window.__Q=window.__Q||{};window.__Q["prev/5/A1"]=[{"q":"A群链球菌引起的超敏反应性疾病是","o":["猩红热","风湿热","波浪热","回归热","产褥热"],"a":1,"e":"A群链球菌的超敏反应性疾病包括风湿热和急性肾小球肾炎，由菌体成分与相应抗体形成免疫复合物或与心肌、肾小球交叉抗原所致。猩红热属毒素性疾病，由致热外毒素引起；波浪热由布鲁菌引起；回归热由螺旋体引起；产褥热为化脓性感染"},{"q":"噬菌体可用于细菌的鉴定和分型是由于","o":["噬菌体专性细胞内寄生","在电子显微镜下多数呈蝌蚪形","有严格的宿主特异性","某些噬菌体的基因组中含有异常碱基","能刺激机体产生特异性的抗体"],"a":2,"e":"噬菌体与宿主菌表面受体结合具有种、甚至型的特异性，只裂解相应细菌，故可用已知噬菌体鉴定未知菌并进行噬菌体分型。蝌蚪形只是形态特征，异常碱基用于噬菌体的检测与分类，噬菌体作为病毒不刺激机体产生抗体"},{"q":"新生隐球菌致病物质主要是","o":["荚膜多糖","芽生孢子","细胞壁","侵袭性酶","假菌丝"],"a":0,"e":"新型隐球菌的荚膜多糖是其主要致病物质，能抑制吞噬细胞吞噬、诱使机体免疫无反应、降低抵抗力，并具抗干燥作用。芽生孢子只是繁殖形式，非致病物质；假菌丝是白念珠菌的侵袭结构；侵袭性酶在隐球菌致病中不占主导地位"},{"q":"对痢疾患者的粪便标本进行分离、培养时应选用","o":["肉汤培养基","血琼脂平板","罗氏培养基","SS选择培养基","柯氏培养基"],"a":3,"e":"SS琼脂含胆盐、枸橼酸钠和煌绿，能抑制革兰阳性菌与大肠埃希菌，利于志贺菌和沙门菌分离，是痢疾粪便标本的常用选择培养基。肉汤培养基用于增菌而无选择性；血琼脂平板不能抑制杂菌；罗氏培养基用于结核分枝杆菌；柯氏培养基用于白喉棒状杆菌"},{"q":"下列不属于动物源性疾病的病原体为","o":["鼠疫耶尔森菌","结核分枝杆菌","布鲁氏菌","斑疹伤寒立克次体","炭疽杆菌"],"a":1,"e":"结核分枝杆菌只感染人，经呼吸道在人间传播，不属动物源性疾病。鼠疫耶尔森菌、布鲁菌、炭疽芽胞杆菌均以动物为传染源，斑疹伤寒立克次体以鼠类为储存宿主、鼠蚤为媒介，均属动物源性或自然疫源性疾病"},{"q":"结核分枝杆菌所致的机体免疫主要是","o":["以T细胞为主的细胞免疫","以产生IgA为主的体液免疫","非特异性免疫","以产生IgG为主的体液免疫","以B细胞为主的细胞免疫"],"a":0,"e":"结核分枝杆菌为兼性胞内寄生菌，抗感染免疫以CD4⁺Th1细胞介导的细胞免疫为主，巨噬细胞活化后杀灭胞内菌，同时形成迟发型超敏反应。IgG、IgA等体液抗体不能进入细胞清除胞内菌；非特异性免疫只起早期辅助作用；B细胞不介导细胞免疫"},{"q":"不属于毒性噬菌体复制周期的阶段是","o":["吸附","脱壳","穿入","生物合成","成熟与释放"],"a":1,"e":"毒性噬菌体复制包括吸附、穿入、生物合成、装配与释放四个阶段，核酸经尾鞘注入菌体，衣壳留在菌外，故无脱壳阶段。装配在菌体内完成，子代噬菌体借裂解酶破坏菌壁而释放。四个阶段连续完成，宿主菌随之裂解死亡"},{"q":"能够使细菌黏附宿主易感细胞的结构是","o":["脂磷壁酸","脂质双层","性菌毛","异染颗粒","鞭毛"],"a":0,"e":"脂磷壁酸即膜磷壁酸，一端锚定于细胞膜糖脂、另一端穿出细胞壁，是革兰阳性菌黏附宿主上皮细胞的重要黏附素，A群链球菌即借其结合纤连蛋白。性菌毛介导细菌间接合，鞭毛为运动器官，异染颗粒为储藏颗粒"},{"q":"蝌蚪形噬菌体负责将头部的核酸注入宿主菌细胞内的器官是","o":["尾髓","尾鞘","尾丝","尾板","尾刺"],"a":0,"e":"蝌蚪形噬菌体尾部由中空的尾髓和外裹的尾鞘组成，尾鞘收缩时将头部核酸经尾髓管道注入菌体。尾丝为吸附器官，尾板内含溶菌酶并固着于菌体表面，尾刺辅助吸附，均不承担核酸注入功能"},{"q":"下列关于干扰素的描述中不正确的一个是","o":["干扰素是一种蛋白质，通过多种途径影响提高宿主的抗病毒能力，其中一种方式是诱导宿主的抗病毒状态","只有病毒感染的细胞能合成干扰素","干扰素的抗病毒谱广，一种病毒感染诱生的干扰素可同时抑制其他病毒感染","干扰素能促进核酸酶合成来降解病毒mRNA","干扰素既能干扰感染细胞内的病毒复制，又能释放到细胞外作用于其他细胞，从而限制病毒扩散"],"a":1,"e":"干扰素并非只由病毒感染的细胞产生，细菌内毒素、人工合成的双链RNA等诱生剂同样可诱导，巨噬细胞、淋巴细胞和体细胞均可合成。它抗病毒谱广，经受体激活下游通路诱导抗病毒蛋白、降解病毒mRNA，既能作用于感染细胞，也能扩散至邻近细胞"},{"q":"TSST-1是金黄色葡萄球菌分泌的一种外毒素，可引起何种疾病","o":["毛囊炎","食物中毒","疖或痈","烫伤样皮肤综合征","中毒性休克综合征"],"a":4,"e":"TSST-1是金黄色葡萄球菌分泌的超抗原，经期女性使用不洁卫生棉条时毒素入血，引起高热、弥漫性红疹、脱屑、低血压及多器官功能紊乱，即中毒性休克综合征。毛囊炎、疖、痈由菌体侵袭与酶类直接引起，食物中毒由肠毒素所致，烫伤样皮肤综合征由表皮剥脱毒素引起"},{"q":"通过普遍性转导转移的基因是","o":["噬菌体的基因","F质粒的基因","R质粒的基因","染色体上的特定基因","染色体上任一段基因"],"a":4,"e":"普遍性转导时噬菌体装配中误将供体菌任何DNA片段装入衣壳，故可转移染色体上任一段基因，毒性噬菌体与温和噬菌体均可介导。局限性转导只转移前噬菌体整合位点两侧的特定基因；F质粒、R质粒经接合转移"},{"q":"前噬菌体是指","o":["亲代噬菌体","尚未整合到宿主菌染色体上的噬菌体","尚未装配好的噬菌体","整合在宿主菌染色体上的噬菌体基因组","游离的、未感染宿主菌的噬菌体"],"a":3,"e":"前噬菌体是温和噬菌体基因组整合于宿主菌染色体后的存在形式，随细菌染色体复制并传给子代，可使宿主发生溶原性转换；携带前噬菌体的细菌即溶原性细菌。尚未整合的游离噬菌体、装配中的噬菌体、亲代噬菌体均不称前噬菌体"},{"q":"机体抗感染的第一道防线是","o":["屏障结构","巨噬细胞","体液免疫","细胞免疫","NK细胞"],"a":0,"e":"屏障结构包括皮肤黏膜及其分泌的杀菌物质、血脑屏障和胎盘屏障，是机体抗感染的第一道防线，可机械阻挡和排除病原体。巨噬细胞、NK细胞属第二道防线，体液免疫和细胞免疫为适应性免疫，发生于感染后期"},{"q":"属于呼肠病毒科的胃肠炎病毒是","o":["星状病毒","诺如病毒","肠道腺病毒","沙波病毒","轮状病毒"],"a":4,"e":"轮状病毒属平滑呼肠病毒科，为双链RNA病毒，是婴幼儿秋季腹泻的主要病原体。诺如病毒与沙波病毒属杯状病毒科；星状病毒属星状病毒科；肠道腺病毒属腺病毒科。四者均引起急性胃肠炎，但只有轮状病毒归呼肠病毒科"},{"q":"关于汉坦病毒生物学性状，错误的是","o":["基因组分三个片段","包膜表面有两种糖蛋白","可凝集鹅红细胞","能在体外多种细胞中增殖","敏感动物是家兔"],"a":4,"e":"汉坦病毒对黑线姬鼠、小白鼠、大白鼠等啮齿动物多呈隐性感染，仅乳鼠与免疫缺陷动物接种后发病，家兔并非其敏感动物。其基因组为分节段单负链RNA，分L、M、S三个片段；包膜表面有G1、G2两种糖蛋白；可凝集鹅红细胞；能在Vero E6等多种细胞中增殖"},{"q":"构成细菌毒力的是","o":["基本结构","菌毛","侵袭力和毒素","代谢产物","侵入机体的途径"],"a":2,"e":"细菌毒力由侵袭力和毒素构成：侵袭力包括黏附、定植、抗吞噬和侵袭性酶类，毒素包括外毒素与内毒素。菌毛只是侵袭力中的黏附因素，不能代表全部毒力；基本结构和一般代谢产物不决定毒力；侵入途径影响感染能否建立，但不属于毒力物质"},{"q":"下列哪种微生物无细胞壁","o":["螺旋体","结核分枝杆菌","肺炎链球菌","肺炎支原体","白喉棒状杆菌"],"a":3,"e":"支原体无细胞壁，仅由细胞膜包被，是天然无细胞壁的微生物，肺炎支原体为其中主要致病种，因无壁故呈高度多形性、可通过滤菌器。螺旋体、结核分枝杆菌、肺炎链球菌、白喉棒状杆菌均有肽聚糖细胞壁，仅染色或结构特殊。L型细菌虽无壁，但属诱导形成的细菌变异型，非独立微生物"},{"q":"以下关于HIV的描述不正确的是","o":["侵犯T淋巴细胞，严重损伤免疫系统","易发生变异，逃避免疫系统攻击","可维持潜伏感染的状态","病毒基因组可整合进宿主基因组","抗gp120 IgG起持续性免疫保护作用"],"a":4,"e":"HIV感染后虽产生抗gp120中和抗体，但env基因高频突变致抗原变异，病毒不断逃逸，抗体不能提供持续免疫保护，故疫苗研制困难。HIV侵犯CD4+T细胞、可整合为前病毒并长期潜伏，此两点描述正确"},{"q":"与HIV-1吸附和进入靶细胞密切相关的蛋白是","o":["p17","p24","gp120","rev","vif"],"a":2,"e":"HIV-1的gp120先与靶细胞CD4分子结合，再与辅助受体结合，随后与gp41分离，gp41构象改变暴露融合肽，介导包膜与细胞膜融合。p17为基质蛋白，p24为衣壳蛋白，均属结构蛋白。rev、vif为调控蛋白，参与基因表达与免疫逃逸，不介导吸附"},{"q":"下列有关菌落的叙述，错误的是","o":["可分为S、R和M型菌落","肉眼可见","由单一细菌形成","一个菌落包含成千上万个细菌","在液体培养基中生长的情况"],"a":4,"e":"菌落是单个细菌在固体培养基上繁殖形成的肉眼可见的细菌集团，含成千上万个细菌，可分为光滑型、粗糙型和黏液型。液体培养基中出现的均匀混浊、沉淀或菌膜属生长现象，不称菌落，故E项错误。A、B、C、D均符合菌落的定义与特征"},{"q":"汉坦病毒感染后，具有早期诊断价值的微生物学检查法是","o":["中和抗体的检测","免疫组化法检测抗原","特异性IgM抗体的检测","血凝抑制抗体的检测","病毒分离"],"a":2,"e":"汉坦病毒感染后特异性IgM抗体于发病1～2天即可检出，早期阳性率可达95%以上，轻型与不典型病例亦然，故具早期诊断价值，常用IgM捕捉ELISA。中和抗体出现晚、维持久，用于回顾性诊断与免疫效果评价。病毒分离需细胞或动物接种，周期长。免疫组化检测抗原阳性率有限，血凝抑制抗体亦属恢复期抗体检测"},{"q":"以下对无芽孢厌氧菌描述正确的是","o":["革兰氏阳性细菌，无芽孢，有鞭毛","条件致病菌，人类和动物肠道或其他部位正常菌群成员","内毒素不是其致病物质","类杆菌是口腔、上呼吸道感染和菌血症的病原体","类杆菌不能分解乳糖"],"a":1,"e":"无芽孢厌氧菌是人和动物肠道、口腔、上呼吸道及泌尿生殖道的正常菌群成员，属条件致病菌，在寄居部位改变、菌群失调或免疫力下降时致病。其革兰染色多为阴性，如类杆菌、梭杆菌，并非均为革兰阳性且有鞭毛。脂多糖内毒素是革兰阴性无芽孢厌氧菌的致病物质。类杆菌以腹腔、盆腔及下消化道感染多见，口腔上呼吸道感染以梭杆菌、消化链球菌为主"},{"q":"可疑肉毒毒素中毒的患者，采集的标本应该是","o":["患者的粪便","患者的血液","患者的脑脊液","伤口的渗出液","患者吃剩的食物"],"a":4,"e":"食源性肉毒中毒由进食含肉毒毒素的食物引起，故应采集剩余食物检测毒素，检出毒素即可确诊，也可采集病人粪便与血清查毒素。血液中毒素含量低且出现短暂；脑脊液无诊断价值；伤口渗出液仅在创伤性肉毒中毒时采集"},{"q":"对病毒衣壳叙述错误的是","o":["由多肽构成的壳微粒组成","表面凸起称刺突","可增加病毒的感染性","呈对称方式排列","可抵抗核酸酶和脂溶剂"],"a":1,"e":"刺突是包膜病毒包膜表面的糖蛋白突起，由包膜蛋白构成，并非衣壳结构，故B项错误。衣壳由壳粒按立体对称或螺旋对称排列组成，可保护核酸、抵抗核酸酶和脂溶剂，并通过吸附介导感染，A、C、D、E均正确"},{"q":"首先成功分离培养出沙眼衣原体的学者是","o":["李斯德","巴斯德","秦纳","郭霍","汤非凡"],"a":4,"e":"1956年我国学者汤飞凡采用鸡胚卵黄囊接种法首次分离出沙眼衣原体，并证实其为沙眼的病原体。郭霍与巴斯德为细菌学奠基人；秦纳（琴纳）发明牛痘接种；李斯特创立消毒法，均与沙眼衣原体的分离无关"},{"q":"下列病原体可经性接触传播的是","o":["沙眼衣原体","鹦鹉热衣原体","普氏立克次体","肺炎衣原体","钩端螺旋体"],"a":0,"e":"沙眼衣原体的生殖生物型和性病淋巴肉芽肿生物型经性接触传播，引起尿道炎、宫颈炎和性病淋巴肉芽肿。鹦鹉热衣原体经呼吸道吸入含菌尘埃感染，肺炎衣原体经飞沫传播，普氏立克次体由人虱传播，钩端螺旋体经疫水接触传播"},{"q":"关于内毒素的说法错误的是","o":["来源于革兰阴性菌","其化学成分是脂多糖","性质稳定，耐热","菌体死亡裂解后释放出来","抗原性强"],"a":4,"e":"内毒素为脂多糖，抗原性弱，刺激机体产生的抗体以IgM为主，且不能经甲醛处理制成类毒素，故“抗原性强”错误。内毒素来源于革兰阴性菌细胞壁，菌体死亡裂解后释放，性质稳定耐热，160℃2～4小时才被破坏，A、B、C、D均正确"},{"q":"下列细菌特性与噬菌体无关的是","o":["细菌L型形成","白喉棒状杆菌产生白喉毒素","肉毒梭菌产生肉毒毒素","金黄色葡萄球菌产生的溶素","伤寒沙门菌分为96个血清型"],"a":0,"e":"细菌L型是细胞壁缺陷型，由溶菌酶、β-内酰胺类抗生素、胆汁或补体等诱导形成，与噬菌体无关。白喉毒素基因由β-噬菌体携带，肉毒毒素C、D型经溶原性转换产生，金黄色葡萄球菌溶素与伤寒沙门菌O-I噬菌体分型均依赖噬菌体"},{"q":"对病毒抵抗力叙述错误的是","o":["大多数病毒60℃ 30分钟可被灭活","大多数病毒在-70℃可存活","紫外线能灭活病毒","甲醛能使病毒灭活，但保留抗原性","所有病毒对脂溶剂都敏感"],"a":4,"e":"病毒对脂溶剂的敏感性取决于有无包膜，有包膜病毒对乙醚、氯仿敏感，无包膜病毒如肠道病毒、腺病毒抵抗力强，故所有病毒均敏感之说错误。60℃ 30分钟可灭活多数病毒，-70℃可长期保存，紫外线损伤核酸，甲醛灭活而保留抗原性"},{"q":"下列微生物都能通过除菌滤器，例外的一种是","o":["放线菌","病毒","衣原体","支原体","L型细菌"],"a":0,"e":"除菌滤器孔径约0.22μm，支原体、衣原体、L型细菌和病毒均可通过。放线菌为革兰阳性丝状菌，菌丝直径约1μm，不能通过滤器，故为例外。支原体无细胞壁、体积最小；L型细菌因细胞壁缺陷呈多形性小体；衣原体原体直径0.2～0.3μm"},{"q":"支原体的基因组为","o":["单股线性DNA","双股环状DNA","单股线性RNA","双股环状RNA","两条相同的单股RNA"],"a":1,"e":"支原体基因组为闭合环状双股DNA，是能独立生活的最小基因组之一，仅约0.6～1.1Mb，故合成代谢能力有限、营养要求高。单股线性DNA见于细小病毒等；RNA不作基因组；双股环状RNA不是任何微生物的基因组形式"},{"q":"HIV的基因最容易发生变异的基因是","o":["tat","env","gag","rev","pol"],"a":1,"e":"HIV的env基因编码gp120和gp41，env基因最易发生突变，gp120表面抗原变异有利于病毒逃避免疫清除，也是疫苗研制困难的原因。gag编码衣壳、核壳与基质蛋白，pol编码逆转录酶、整合酶和蛋白酶，均相对保守。tat、rev属调控基因"},{"q":"除了结核分枝杆菌，以下哪种细菌也可引起人类结核病","o":["牛型结核分枝杆菌","堪萨斯分枝杆菌","瘰疬分枝杆菌","鸟-胞内分枝杆菌","溃疡分枝杆菌"],"a":0,"e":"结核分枝杆菌复合群包括结核分枝杆菌、牛分枝杆菌等，牛分枝杆菌可经未消毒乳品传播，引起人类结核病。堪萨斯、瘰疬、鸟-胞内分枝杆菌属非结核分枝杆菌，多为机会致病；溃疡分枝杆菌引起慢性无痛性皮肤溃疡"},{"q":"包膜病毒所具有的特点不包括","o":["对脂溶剂敏感","出芽增殖","能在肠道黏膜细胞中生长繁殖","含有宿主细胞的化学成分","有包膜病毒电镜下常呈多形态性"],"a":2,"e":"包膜病毒对脂溶剂敏感，以出芽方式释放，包膜含宿主细胞的脂类与糖类成分，电镜下常呈多形态性。包膜对胆盐与胃酸不稳定，故多不经消化道传播，能在肠道黏膜细胞中生长繁殖不属其特点。故包膜病毒多经血行或呼吸道传播"},{"q":"鉴别致病肠道杆菌和其他大部分非致病肠道杆菌的单糖发酵试验，具有辨别意义的单糖是","o":["葡萄糖","麦芽糖","蔗糖","菊糖","乳糖"],"a":4,"e":"致病性肠道杆菌如伤寒沙门菌、志贺菌不发酵乳糖，大多数非致病肠道杆菌发酵乳糖，故乳糖发酵试验是初步鉴别的依据，在SS、麦康凯平板上可直接观察菌落颜色。葡萄糖是所有肠道杆菌都能发酵的糖，蔗糖、麦芽糖、菊糖无此鉴别意义"},{"q":"下列哪项与结核分枝杆菌的致病性无关","o":["多糖","蛋白质","脂质成分","内毒素","免疫损伤"],"a":3,"e":"结核分枝杆菌不产生内毒素和外毒素，也无侵袭性酶，致病靠菌体成分：脂质（索状因子、磷脂、蜡质D）、蛋白质与多糖，以及由此诱发的迟发型超敏反应所致免疫损伤。内毒素是革兰阴性菌细胞壁脂多糖，结核分枝杆菌细胞壁富含脂质而无典型内毒素"},{"q":"细菌侵入血液中大量生长繁殖引起严重的全身中毒症状称为","o":["病毒血症","毒血症","败血症","菌血症","坏血症"],"a":2,"e":"败血症指病原菌侵入血流并大量繁殖、产生毒性产物，引起高热、皮肤黏膜瘀斑、肝脾肿大等全身中毒症状，鼠疫耶尔森菌、炭疽芽胞杆菌即可引起。菌血症仅短暂通过血流，毒血症只有外毒素入血，脓毒血症伴化脓性病灶"},{"q":"哪种细菌可因手术不当引起腹膜炎","o":["大肠埃希菌","痢疾杆菌","伤寒沙门菌","肠炎沙门菌","霍乱弧菌"],"a":0,"e":"大肠埃希菌是肠道正常菌群，肠穿孔、腹部手术或阑尾炎时可移位至腹腔引起腹膜炎，是腹部感染后败血症最常见的革兰阴性菌。痢疾杆菌、伤寒沙门菌、霍乱弧菌主要引起肠道传染病，肠炎沙门菌引起胃肠炎，均非术后腹膜炎常见病原"},{"q":"感染动物后引起母畜流产的病原体是","o":["布鲁氏菌","鼠疫耶氏菌","钩端螺旋体","炭疽芽孢杆菌","鼠伤寒沙门菌"],"a":0,"e":"布鲁菌经消化道、皮肤黏膜侵入后在胎盘绒毛膜大量繁殖并致坏死，故感染家畜引起母畜流产，病畜还见睾丸炎、乳腺炎、子宫炎。鼠疫耶氏菌引起啮齿动物与人的鼠疫，炭疽芽胞杆菌致食草动物败血症样猝死，鼠伤寒沙门菌主要引起胃肠炎"},{"q":"病原菌最适生长温度为","o":["16℃","22℃","37℃","50℃","68℃"],"a":2,"e":"病原菌长期适应人体环境，属嗜温菌，最适生长温度即人体体温37℃，与宿主体温一致有利于其在体内繁殖。16℃、22℃接近室温，适合部分环境菌与真菌；50℃以上仅嗜热菌可生长；68℃已超过多数细菌的耐受上限"},{"q":"关于病毒衣壳的描述不正确的是","o":["裸露病毒的衣壳不能介导病毒感染宿主","衣壳是由一定数量的壳粒组成","衣壳是蛋白质，且具有抗原性","衣壳可保护病毒的核酸","衣壳由病毒基因组编码产生"],"a":0,"e":"裸露病毒无包膜，其衣壳蛋白本身就是吸附受体、介导感染的结构，如腺病毒纤维蛋白与小RNA病毒VP1，故该项错误。衣壳由壳粒组成，保护核酸，具抗原性，其螺旋、二十面体或复合对称型还是病毒分类的依据"},{"q":"注射TAT的目的是","o":["对易感人群进行预防接种","对可疑破伤风患者进行治疗及紧急预防","杀灭伤口中繁殖的破伤风梭菌","主要用于儿童的预防接种","中和与神经细胞结合的毒素"],"a":1,"e":"TAT为马源破伤风抗毒素，能中和游离的破伤风痉挛毒素，用于伤口污染严重又未完成基础免疫者的紧急预防及可疑病人的治疗。它不能杀灭局部繁殖的细菌，也不能中和已与神经细胞结合的毒素。故强调早期足量使用，用药前须做皮试以防过敏"},{"q":"一名旅游者在度假期间出现持续性水样腹泻，无发热。最可能感染的病原体","o":["肠侵袭型大肠埃希菌","伤寒沙门菌","霍乱弧菌","志贺菌","肠集聚型大肠埃希菌"],"a":4,"e":"肠集聚型大肠埃希菌黏附于小肠上皮呈聚集排列，引起旅游者持续性水样腹泻，多无发热和脓血。EIEC与志贺菌侵袭结肠，引起发热、腹痛和脓血便；伤寒沙门菌引起肠热症；霍乱弧菌引起剧烈米泔水样泻并伴重度脱水，与无发热的持续水样泻不符"},{"q":"下列哪种细菌感染可引起化脓性感染","o":["炭疽芽孢杆菌","结核分枝杆菌","金黄色葡萄球菌","白喉棒状杆菌","普氏立克次体"],"a":2,"e":"金黄色葡萄球菌产生血浆凝固酶、α毒素和杀白细胞素，是化脓性感染最常见的病原，引起疖、痈、脓肿、骨髓炎等。炭疽芽胞杆菌引起出血性坏死性炎症，结核分枝杆菌引起肉芽肿与干酪样坏死，白喉棒状杆菌引起假膜，普氏立克次体为胞内寄生，均非化脓性"},{"q":"革兰染色后，革兰阳性菌菌体内的结晶紫不易被脱色的原因是","o":["肽聚糖含量较革兰阴性菌要少","革兰阳性菌带有更多的负电荷","革兰阳性菌相对的表面积较大","革兰阳性菌细胞壁含大量脂质A","95%乙醇很容易穿入菌体内部"],"a":1,"e":"革兰阳性菌磷壁酸含量高、带较多负电荷，等电点低（pH2～3），更易与碱性染料结晶紫结合；加之肽聚糖层厚、交联致密、脂类少，乙醇脱水后网孔缩小，结晶紫-碘复合物不易洗出。A项方向相反，阳性菌肽聚糖实为多于阴性菌；D项脂质A存在于阴性菌外膜脂多糖；E项乙醇易渗入反不利于保留染料"},{"q":"关于转座子的错误描述是","o":["不依赖于同源性重组可自行移动的遗传物质","仅存在于细菌染色体上","伴随转座子移动会出现插入突变","转座子包括插入序列和复合转座子","携带耐药性基因的转座子是多重耐药菌形成和播散的重要原因之一"],"a":1,"e":"转座子是可自行移动的DNA序列，不依赖同源性重组即可插入新位点，除细菌染色体外还存在于质粒和噬菌体基因组中，故“仅存在于染色体上”错误。移动时可造成插入突变；按结构分为插入序列与复合转座子；携带耐药基因的转座子是多重耐药形成和播散的重要原因"},{"q":"关于二重感染的叙述，下列哪项是错误的","o":["是免疫功能缺陷的严重后果","是微生态平衡失调的一种严重后果","是菌群失调症的一种类型","是抗生素治疗原感染性疾病过程中的一种新感染","应重新选用敏感抗生素治疗"],"a":0,"e":"二重感染是长期使用广谱抗菌药物致敏感菌被抑制、耐药菌趁机大量繁殖引起的菌群失调症，属微生态平衡失调的后果，需改用敏感药物。其发生与免疫功能低下有关，但并非免疫功能缺陷的直接后果，原发诱因是抗菌药物的应用"},{"q":"患者，男，33岁，因淋病入院。参与淋病奈瑟菌致病的组分是","o":["溶血素","菌毛","芽孢","鞭毛","肠毒素"],"a":1,"e":"淋病奈瑟菌借菌毛黏附于尿道柱状上皮细胞表面，是其致病的首要组分，丧失菌毛则侵袭力消失。外膜蛋白PⅠ、PⅡ参与黏附并损伤中性粒细胞；该菌无芽胞、无鞭毛，也不产生肠毒素，溶血素并非其主要致病物质"},{"q":"温度敏感突变株在下列哪个条件下可增殖","o":["35～37℃","22～28℃","28～35℃","37～40℃","40℃以上"],"a":2,"e":"温度敏感突变株属条件致死性突变，在28～35℃能增殖，37～40℃则不能增殖，借此可筛选减毒株。野毒株在两种温度下均能增殖；22～28℃温度偏低，40℃以上已超出许可上限，均非其增殖温区"},{"q":"参与HIV-1前体蛋白切割的病毒基因是","o":["nef","rev","gag","tat","pol"],"a":4,"e":"HIV-1的pol基因编码逆转录酶、整合酶和蛋白酶，gag-pol前体蛋白的切割即由pol编码的病毒蛋白酶完成。gag基因编码p55等结构蛋白，env基因编码gp160及gp120、gp41，tat、rev属调控基因，只调节基因表达而不参与切割"},{"q":"葡萄球菌噬菌体分型的意义是","o":["确定其致病性","确定其耐药性","确定葡萄球菌抵抗力","流行病学调查追踪传染源","测定细菌对药物的敏感性"],"a":3,"e":"噬菌体分型依据噬菌体与菌株受体的特异性，同一菌种不同菌株的噬菌体型不同，可用于流行病学调查、追查传染源和医院感染溯源。它与致病性、耐药性、抵抗力及药敏结果无关，这些分别由动物试验和药敏试验判定"},{"q":"下列关于病毒疫苗的描述中，不正确的是","o":["减毒活疫苗具有回复毒力的可能","某些疫苗需要加强免疫","所有抗病毒疫苗只能在感染前接种","灭活疫苗不能诱导sIgA","灭活疫苗也可诱导CTL"],"a":2,"e":"多数病毒疫苗用于预防接种，但并非只能在感染前接种，狂犬病疫苗在暴露后接种仍有效，乙肝治疗性疫苗也已用于慢性感染者，故此项错误。减毒活疫苗有回复毒力的可能，接种后需加强免疫，灭活疫苗不诱导sIgA但可经交叉提呈诱导CTL"},{"q":"下列哪项不是自然疫源性疾病","o":["钩端螺旋体病","莱姆病","黑死病","恙虫病","雅司病"],"a":4,"e":"自然疫源性疾病以野生动物为储存宿主、经媒介在动物间传播并可波及人，钩端螺旋体病、莱姆病、恙虫病均属此类，鼠疫（黑死病）经鼠蚤传播亦属自然疫源性疾病。雅司病由苍白密螺旋体极细亚种引起，经病损皮肤直接接触传播，见于热带儿童，无动物储存宿主与媒介环节"},{"q":"下面哪项不能代表病毒在细胞内增殖","o":["细胞病变效应","红细胞吸附","细胞代谢的改变","干扰现象","细胞培养液混浊"],"a":1,"e":"官方答案为【红细胞吸附】，但依据教材，正确答案为【细胞培养液混浊】。红细胞吸附是带血凝素病毒感染细胞后，细胞膜血凝素吸附红细胞的现象，教材明确列为正黏病毒、副黏病毒增殖的判定指标，属病毒增殖的表现。病毒增殖本身不引起培养液混浊，混浊多因细菌污染或细胞碎片堆积，才是不能代表增殖的指标"},{"q":"某孕妇产前检查时发现有淋病性子宫颈炎。胎儿娩出后应做的处理是","o":["迅速将患儿放人无菌隔离室","1%硝酸银滴眼","给婴儿注射青霉素","给婴儿口服诺氟沙星","0、01%洗必肽清洗婴儿皮肤"],"a":1,"e":"孕妇淋菌性宫颈炎经产道分娩可使新生儿感染淋球菌性结膜炎，出生后立即用1%硝酸银滴眼，或用红霉素、四环素眼膏预防。隔离室、注射青霉素、口服诺氟沙星均非局部预防措施，且喹诺酮类不宜用于新生儿"},{"q":"染色体上整合有F质粒的DNA的细菌，被称为","o":["F＋菌","F－菌","F'菌","Hfr菌","溶源性细菌"],"a":3,"e":"F质粒整合于染色体后与染色体同步复制，能高频转移染色体基因，称Hfr菌。F+菌的F质粒游离存在，F′菌携带整合位点相邻的染色体片段，溶原性细菌是携带前噬菌体者。Hfr菌仍有性菌毛，可作供体但极少使受体转为F+"},{"q":"疥或痈等化脓性病灶比较局限，主要是因为其致病菌产生","o":["凝固酶","酯酶","透明质酸酶","溶血毒素","外毒素"],"a":0,"e":"金黄色葡萄球菌产生的血浆凝固酶使纤维蛋白原变为纤维蛋白，沉积于病灶周围并形成血栓，使疖、痈等化脓灶局限化。透明质酸酶则分解细胞间质、促进病菌扩散，是A群链球菌等侵袭力强的表现。这与链球菌感染易扩散形成丹毒、蜂窝织炎恰成对照"},{"q":"有关志贺菌属叙述正确的是","o":["发酵乳糖","动力试验阳性","硫化氢试验阴性","不分解葡萄糖","具有H抗原"],"a":2,"e":"志贺菌属发酵葡萄糖产酸不产气，除宋内志贺菌迟缓发酵乳糖外均不发酵乳糖；硫化氢试验阴性；无鞭毛、动力阴性；仅有O抗原和K抗原，无H抗原。故A、B、D、E均错，唯硫化氢试验阴性正确"},{"q":"关于获得性耐药描述错误的是","o":["是指在正常情况下，敏感的细菌中出现了对抗菌药物由耐药性的菌株","通常是细菌DNA发生了改变获得了永久的耐药性","可以通过结合、转化等方式获得","获得性耐药可以遗传","获得性耐药稳定性高"],"a":1,"e":"获得性耐药由细菌DNA改变引起，可通过接合、转化、转导获得并遗传，但耐药基因可随质粒丢失而消失，停药后敏感株可重新占优势，故并非永久。敏感菌中出现耐药株、耐药性可遗传且较稳定等表述均正确"},{"q":"病毒垂直传播的正确概念是","o":["在公共场所被病毒感染","通过性接触而发生病毒感染","母亲患病将病毒传给其子女的病毒感染","父亲患病将病毒传给其子女的病毒感染","母亲体内病毒经由胎盘或产道传给胎儿的病毒感染"],"a":4,"e":"垂直传播指病原体由亲代传给子代，包括经胎盘、产道及围产期哺乳等途径，母亲体内病毒经胎盘或产道感染胎儿是其准确表述。公共场所接触与性接触均属水平传播；笼统称传给子女未限定宫内或产道途径，不够确切"},{"q":"诺如病毒的生物学性状描述，错误的是","o":["分节段的双链RNA病毒","球形无包膜","GⅡ4是感染人类最主要型别","对热、乙醚和酸稳定","可感染黑猩猩"],"a":0,"e":"诺如病毒为单正链RNA病毒，基因组不分节段，故“分节段的双链RNA病毒”错误，分节段双链RNA是轮状病毒的特征。该病毒球形无包膜，GⅡ.4型为主要流行型别，耐热、耐酸、耐乙醚，可实验感染黑猩猩"},{"q":"对痢疾病人做微生物学检查，下列哪项是错误的","o":["分离培养细菌，作生化鉴定","采样应挑取粪便的黏液或脓血部分","取黏液性或脓血性便涂片，革兰染色镜检","取标本接种于肠道选择培养基培养","作血清学试验"],"a":2,"e":"痢疾杆菌为革兰阴性杆菌，形态与肠道其他革兰阴性杆菌无从区分，直接涂片革兰染色镜检没有诊断价值，故不作为检查项目。应挑取黏液脓血部分接种SS等肠道选择培养基分离培养，再做生化鉴定；血清学试验须以纯培养物为抗原作菌型鉴定"},{"q":"与汉坦病毒的流行有关的动物是","o":["鼠","猫","狗","猪","牛"],"a":0,"e":"汉坦病毒有严格宿主特异性，主要宿主动物和传染源为黑线姬鼠、褐家鼠等鼠类，鼠粪尿污染形成气溶胶经呼吸道传播。猫、狗、猪、牛不是其自然宿主，与流行无关；灭鼠是控制流行的关键措施。病毒随鼠粪尿排出，形成气溶胶经呼吸道吸入，是该病主要感染方式"},{"q":"以下疾病为动物prion病的是","o":["CJD","CWD","GSS","FFI","vCJD"],"a":1,"e":"鹿慢性消耗病即CWD，是鹿科动物的朊粒病，与羊瘙痒病、牛海绵状脑病同属动物朊粒病。CJD、GSS与FFI均为人类朊粒病，分别表现为克雅病、格斯特曼综合征和致死性家族性失眠。vCJD虽源自牛海绵状脑病，但发生于人，属人类变异型克雅病，不列入动物朊粒病"},{"q":"下列可以体现耐药性程度的是","o":["MIC","LD50","ID50","Ag","Ab"],"a":0,"e":"耐药程度以抗菌药物对细菌的最小抑菌浓度或抑菌圈直径判定，MIC越高耐药越强，并以折点划分敏感、中介与耐药。LD50与ID50表示毒力或感染性大小；Ag与Ab分别指抗原与抗体，均不反映耐药程度"},{"q":"通过性菌毛使供体菌直接接触受体菌而转移和重组DNA的变异现象称为","o":["转化","接合","局限性转导","普遍性转导","溶原性转换"],"a":1,"e":"接合是供体菌通过性菌毛与受体菌直接接触，将质粒DNA转移给受体菌并重组的基因转移方式。转化是受体菌摄取游离DNA，转导经噬菌体介导，溶原性转换是前噬菌体基因表达，均不涉及性菌毛。F质粒与R质粒均属接合性质粒，可在菌间高频转移"},{"q":"确诊细菌性感染最可靠的方法是","o":["观察临床症状","询问病史","用抗生素试探性治疗，根据疗效诊断","根据不同疾病采取不同标本进行细菌的分离与培养鉴定","血清学诊断阳性"],"a":3,"e":"细菌感染的病原学诊断以分离培养与鉴定最可靠，可确定种属并进行药敏试验，是确诊标准。临床症状、病史和试探性治疗均缺乏特异性；血清学抗体阳性只提示感染，且受既往感染和交叉反应影响，不能作为确诊依据"},{"q":"下列关于新型隐球菌致病性的描述，正确的是","o":["多数是内源性感染","主要经皮肤接触传播","鸽子可能是其自然宿主","主要的致病物质为其产生的毒素","不易侵犯中枢神经系统"],"a":2,"e":"新型隐球菌广泛存在于鸽粪和土壤中，鸽子可能是其自然宿主，人经吸入气溶胶感染，多属外源性感染。该菌主要经呼吸道而非皮肤接触传播；荚膜多糖是其主要致病物质，并非毒素；荚膜抗吞噬，极易侵犯中枢神经系统引起慢性脑膜炎，故A、B、D、E均错"},{"q":"均不通过呼吸道感染的病毒组合是","o":["流感病毒、麻疹病毒、埃可病毒","风疹病毒、腺病毒、腮腺炎病毒","乙型脑炎病毒、丙型肝炎病毒","脊髓灰质炎病毒、轮状病毒","冠状病毒、柯萨奇病毒"],"a":2,"e":"乙型脑炎病毒经蚊虫叮咬、丙型肝炎病毒经血液传播，均不经呼吸道。流感病毒、麻疹病毒、腺病毒、风疹病毒、腮腺炎病毒及冠状病毒均经呼吸道飞沫传播；脊髓灰质炎病毒与轮状病毒虽以粪-口为主，但脊灰病毒也可经呼吸道传播，故D项不成立"},{"q":"目前尚不能在常规组织细胞中进行培养的病毒是","o":["HIV","CMV","HPV","HSV","EBV"],"a":2,"e":"HPV的复制依赖皮肤黏膜复层上皮细胞的分化状态，须在角化分化环境中完成生命周期，迄今不能用体外培养细胞增殖，实验室主要靠核酸检测或VLP抗原检测。HIV、CMV、HSV、EBV均可体外培养，分别用淋巴细胞、人成纤维细胞与B淋巴细胞系"},{"q":"在实验室进行病毒相关操作时，规范的管理和操作能够保护操作者不被感染及环境生物安全。下列选项中不合理规范的操作是","o":["使用生物安全柜","操作者穿实验服并佩戴防护眼镜及手套等","不用嘴吹吸溶液","不在实验室进食及饮水","用实验室水槽冲洗实验废弃物"],"a":4,"e":"感染性废弃物须经高压蒸汽灭菌或化学消毒后按医疗废物处理，直接用水槽冲洗会造成气溶胶与下水污染，属严重违规。在生物安全柜内操作、穿实验服并戴护目镜与手套、不用嘴吸吹溶液、不在实验室进食饮水，均为规范要求"},{"q":"下列物质不属于侵袭力的是","o":["Vi抗原","M蛋白","荚膜","肠毒素","普通菌毛"],"a":3,"e":"侵袭力包括荚膜、Vi抗原、M蛋白等抗吞噬物质以及普通菌毛等黏附结构，使细菌能在体内定植、繁殖和扩散。肠毒素属外毒素，作用于肠上皮细胞引起分泌性腹泻，是毒素而非侵袭力，故不属于侵袭力范畴"},{"q":"抗HIV的药物齐多夫定（AZT）的作用靶点是","o":["包膜","P24","逆转录酶","蛋白酶","LTR（long terminal repeat）"],"a":2,"e":"齐多夫定是胸腺嘧啶核苷类似物，磷酸化后与天然底物竞争，抑制HIV逆转录酶，终止前病毒DNA链延伸。其作用于酶而非结构蛋白，包膜、P24衣壳蛋白与LTR均非靶点；蛋白酶抑制剂为另一类药物，作用于gag-pol前体的切割"},{"q":"BCG的获得属于","o":["形态结构变异","抗原性变异","菌落变异","毒力变异","耐药性变异"],"a":3,"e":"卡介苗是牛分枝杆菌在含胆汁、马铃薯等的培养基上连续传230代、历时13年获得的毒力减弱而免疫原性保留的变异株，属毒力变异。形态结构变异、菌落变异、抗原性变异和耐药性变异均不能解释其减毒过程"},{"q":"关于固有耐药描述错误的是","o":["是指细菌对某种抗菌药物的天然耐药性","固有耐药性不是始终如一的，可以丢失","由细菌的种属特征所决定","固有耐药可以稳定遗传","固有耐药稳定性高"],"a":1,"e":"固有耐药由染色体耐药基因或天然缺乏药物靶位决定，具种属特异性，代代相传、始终如一、可预测，不会自行丢失。可丢失、可转移的是获得耐药性，常由质粒与转座子介导，如多数革兰阴性杆菌对万古霉素天然耐药"},{"q":"关于麻风病的病原体以下描述正常的是","o":["抗酸染色阳性","与牛结核分枝杆菌有共同抗原","可以在人工培养基中生长","在结核样型麻风病病变的活检中检出率高","有特异性预防疫苗"],"a":0,"e":"麻风分枝杆菌细胞壁富含分枝菌酸，抗酸染色阳性，取鼻黏膜或皮损刮取物镜检见成束抗酸杆菌有诊断价值。该菌至今不能在人工培养基中生长，需用犰狳或小鼠足垫接种；结核样型病变中菌量少，活检检出率低；目前尚无特异性疫苗"},{"q":"鉴定幽门螺杆菌的主要依据之一是","o":["分解尿素释放氨","分解甘露醇产酸","可以被胆汁溶解","分解含硫氨基酸产生硫化氢","甲基红试验阳性"],"a":0,"e":"幽门螺杆菌生化反应不活泼、不分解糖类，但尿素酶丰富，能迅速分解尿素产氨，中和胃酸利于自身定植，是鉴定该菌的主要依据，也是尿素呼气试验的原理。该菌不分解甘露醇，不被胆汁溶解，不产生硫化氢"},{"q":"引起烫伤样皮肤综合征最常见的致病菌是","o":["表皮葡萄球菌","凝固酶阴性葡萄球菌","金黄色葡萄球菌","腐生性葡萄球菌","人葡萄球菌"],"a":2,"e":"金黄色葡萄球菌产生表皮剥脱毒素，作用于表皮颗粒层使细胞间桥断裂，引起烫伤样皮肤综合征，多见于婴幼儿。表皮葡萄球菌、凝固酶阴性葡萄球菌、腐生葡萄球菌、人葡萄球菌毒力弱，主要引起导管相关感染，不产生该毒素"},{"q":"有关噬菌体应用的错误描述是","o":["噬菌体可用于未知细菌的鉴定与分型","某些噬菌体可作为创口感染的辅助治疗","噬菌体可作为基因工程载体","利用噬菌体测定致癌物质","噬菌体基因可与细菌染色体整合"],"a":3,"e":"噬菌体有严格宿主特异性，可用于未知菌的鉴定与分型，也可作为基因工程载体、用于创口感染辅助治疗，温和噬菌体基因还能整合于细菌染色体。检测致癌物质用的是Ames试验，以鼠伤寒沙门菌组氨酸缺陷株回复突变为指标，与噬菌体无关"},{"q":"最易发生变异的病毒是","o":["流感病毒","呼吸道合胞病毒","麻疹病毒","脊髓灰质炎病毒","腮腺炎病毒"],"a":0,"e":"甲型流感病毒基因组为分节段单负链RNA，RdRp缺乏校对功能，复制中的突变易被保留，节段间又可发生基因重排，故最易出现抗原漂移与抗原转变。麻疹、腮腺炎病毒抗原稳定，各只有一个血清型；脊髓灰质炎病毒虽有3型，抗原变异亦小"},{"q":"关于内毒素主要特性的描述不正确的是","o":["细菌裂解后释出","只有革兰阴性菌能产生","抗原性弱，甲醛液处理不形成类毒素","耐热，160℃，2～4小时被破坏","毒性作用强，对组织器官有选择性毒害作用"],"a":4,"e":"内毒素为革兰阴性菌细胞壁脂多糖，菌体裂解后释出，耐热，160℃ 2～4小时才被破坏，抗原性弱，甲醛处理不形成类毒素。其毒性作用相对较弱且对组织无选择性，各菌引起的发热、休克、DIC大致相同。毒性强并对组织器官有高度选择性的是外毒素"},{"q":"细菌变异机制不包括","o":["突变","转化","转导","接合","重排"],"a":4,"e":"细菌遗传型变异的机制包括基因突变以及转化、接合、转导、溶原性转换等基因转移与重组方式。重排即基因重配，是分节段RNA病毒如流感病毒交换基因组片段产生变异的方式，不属于细菌变异机制"},{"q":"保存病毒最好的方法是","o":["干燥法","组织培养法","甘油保存法","冷冻真空干燥法","低温法"],"a":3,"e":"冷冻真空干燥法在低温下抽去水分，使病毒代谢停止并避免冰晶损伤，可长期保存毒种，取出后复活率高。单纯低温或甘油保存时间有限，普通干燥法易使病毒蛋白变性，组织培养法只能短期维持病毒活性"},{"q":"抗胞内菌感染的主要免疫因素是","o":["抗体","补体","T细胞","NK细胞","巨噬细胞"],"a":2,"e":"胞内菌寄居在巨噬细胞内，抗体和补体难以接触，抗感染主要依靠T细胞，CD4+Th1细胞激活巨噬细胞增强杀菌，CD8+CTL杀伤感染细胞。抗体、补体主要针对胞外菌，NK细胞和巨噬细胞属固有免疫，单独作用有限"},{"q":"不能在无生命培养基中生长的螺旋体是","o":["奋森螺旋体","回归热螺旋体","伯氏疏螺旋体","梅毒螺旋体","钩端螺旋体"],"a":3,"e":"梅毒螺旋体至今不能在无生命人工培养基上生长，需接种家兔睾丸或细胞培养，故实验室诊断依赖暗视野镜检和血清学试验。奋森螺旋体、回归热螺旋体、伯氏疏螺旋体均可人工培养；钩端螺旋体可在柯氏培养基中生长"},{"q":"诊断甲型肝炎最实用的病原学检测方法是","o":["免疫电镜法检测粪便标本中病毒颗粒","取粪便标本作病毒分离培养","粪便标本中特异性抗原的检测","ELISA检测血中抗-HAV IgM","PCR检测血液中HAV RNA"],"a":3,"e":"抗-HAV IgM出现早、消失快，ELISA检测血清抗-HAV IgM是甲型肝炎早期诊断最可靠、最实用的指标。免疫电镜和粪便抗原检测敏感性低，病毒分离培养困难且周期长，RT-PCR多用于研究，抗-HAV IgG只反映既往感染"},{"q":"糖酵解是其唯一产能途径的细菌是","o":["炭疽芽孢梭菌","结核分枝杆菌","百日咳鲍特菌","鼠疫耶尔森菌","产气荚膜梭菌"],"a":4,"e":"产气荚膜梭菌缺乏完整呼吸链与细胞色素系统，能量完全来自糖酵解，故糖酵解是其唯一产能途径，属专性厌氧的化能异养菌，发酵糖类产酸产气显著。炭疽芽胞杆菌、结核分枝杆菌、百日咳鲍特菌、鼠疫耶尔森菌均有氧化磷酸化产能途径"},{"q":"破伤风痉挛毒素与神经肌肉接点处运动神经元细胞膜上结合的受体是","o":["聚唾液酸神经节苷脂和邻近的糖蛋白","聚唾液酸神经节苷脂或邻近的糖蛋白","细胞膜上的蛋白","CD155","SCAR-B2"],"a":0,"e":"破伤风痉挛毒素重链羧基端与神经肌肉接头处运动神经元膜上的受体结合，受体为聚唾液酸神经节苷脂和邻近的糖蛋白，二者共同构成结合位点，故为“和”而非“或”。CD155是脊髓灰质炎病毒的受体，SCAR-B2与此无关"},{"q":"HSV病毒表面的黏附性糖蛋白包括","o":["gB，gD，gH和gK","gB，gC，gD和gH","gG，gH，gI和gM","gE，gG，gI和gJ","gD，gE，gG和gH"],"a":1,"e":"HSV编码的gB、gC、gD和gH均为黏附性糖蛋白，其中gB兼有黏附和融合功能，gD为免疫原性最强的中和抗原。gE、gG、gI、gJ、gK、gL、gM不属黏附性糖蛋白，gE/gI复合物为IgG Fc受体，gG为型特异性抗原"},{"q":"氨基糖苷类抗生素不宜用于","o":["腹腔感染","感染性心内膜炎","革兰阴性菌败血症","孕妇无症状菌尿","脓毒症"],"a":3,"e":"氨基糖苷类可透过胎盘并损害胎儿第Ⅷ对脑神经及肾小管，妊娠期禁用，故孕妇无症状菌尿不宜选用。感染性心内膜炎以青霉素与链霉素等协同杀菌；革兰阴性菌败血症、脓毒症为其适应证；腹腔感染常需联合抗厌氧菌药物"},{"q":"钩端螺旋体血清学诊断最常用的方法是","o":["玻片凝聚试验","显微镜凝聚试验","间接凝聚试验","血凝试验","血凝抑制试验"],"a":1,"e":"显微镜凝集试验以活钩端螺旋体为抗原与病人血清孵育，暗视野下观察凝集成蜘蛛状团块，以50%螺旋体被凝集的最高稀释度为效价，是钩体病血清学诊断最经典、最常用的方法。玻片凝集与间接凝集敏感性低；血凝与血凝抑制试验多用于病毒抗体检测"},{"q":"关于病毒感染类型及其特征的描述中，与其他不同的是","o":["蜱传脑炎病毒感染引起神经功能障碍","单纯疱疹病毒反复引起的口唇疱疹","乙肝患者持续性肝功能异常","麻疹病毒引起亚急性硬化性全脑炎","HIV患者出现典型AIDS期"],"a":0,"e":"蜱传脑炎病毒引起急性中枢神经系统感染，病程短、结局明确，属急性感染。其余均为持续性或潜伏感染：HSV再激活引起复发性口唇疱疹，HBV持续感染致肝功能异常，麻疹病毒引起亚急性硬化性全脑炎（慢发感染），HIV最终进入AIDS期"},{"q":"下列肠道致病菌的特征描述错误的是","o":["均为革兰阴性杆菌","在SS选择培养基上为无色半透明菌落","除少数外均不发酵乳糖","在血琼脂平板培养基上，均不可形成溶血环","营养要求不高，需氧或兼性厌氧"],"a":3,"e":"肠道致病菌并非在血平板上均不溶血，部分大肠埃希菌等菌株可呈β溶血，故该描述错误。这类细菌均为革兰阴性杆菌，营养要求不高、需氧或兼性厌氧，除少数外不发酵乳糖，在SS培养基上形成无色半透明菌落"},{"q":"以下能够产生自溶酶的细菌是","o":["艰难梭菌","变形杆菌","脑膜炎奈瑟菌","结核分枝杆菌","百日咳鲍特菌"],"a":2,"e":"脑膜炎奈瑟菌能产生自溶酶，培养物放置后菌体自溶、培养液变清，故须及时转种。肺炎链球菌亦产自溶酶并可被胆汁激活，但不在选项中。艰难梭菌、变形杆菌、结核分枝杆菌、百日咳鲍特菌均不以此酶为特征"},{"q":"肠道病毒不会引起的疾病是","o":["急性结膜炎","脊髓灰质炎","流行性乙型脑炎","脑炎","心肌炎"],"a":2,"e":"流行性乙型脑炎由乙脑病毒经蚊传播，属虫媒病毒，不属肠道病毒。肠道病毒可引起脊髓灰质炎、无菌性脑膜炎与脑炎、心肌炎及急性出血性结膜炎，柯萨奇A组致疱疹性咽峡炎，B组致心肌炎与心包炎"},{"q":"约90%耐青霉素的球菌是","o":["金黄色葡萄球菌","A群链球菌","肺炎链球菌","脑膜炎奈瑟菌","大肠埃希菌"],"a":0,"e":"金黄色葡萄球菌产酶株比例高，临床分离株约90%对青霉素耐药，主要因产生β-内酰胺酶水解青霉素。A群链球菌对青霉素仍高度敏感，是首选药物；肺炎链球菌耐药率较低且以青霉素中介为主；脑膜炎奈瑟菌、大肠埃希菌不属本题所指的球菌"},{"q":"关于肺炎链球菌的叙述正确的是","o":["产生芽孢和自溶酶","菌体呈矛头状，成对排列","不形成荚膜也有致病性","有鞭毛而有动力","革兰氏染色阴性"],"a":1,"e":"肺炎链球菌革兰染色阳性，菌体呈矛头状，宽端相对、尖端向外成双排列，这是其形态学标志。该菌不产生芽胞，无鞭毛故无动力；荚膜是主要毒力因子，无荚膜株毒力显著减弱；革兰染色阴性属奈瑟菌特征"},{"q":"水痘-带状疱疹病毒侵犯的主要细胞是","o":["上皮细胞","神经细胞","中性粒细胞","巨噬细胞","B细胞"],"a":0,"e":"水痘-带状疱疹病毒经呼吸道侵入，先在呼吸道黏膜上皮细胞和局部淋巴结增殖，再经病毒血症播散至皮肤上皮细胞引起水痘，故侵犯的主要细胞是上皮细胞。神经节是潜伏部位而非复制部位，巨噬细胞、B细胞分别是HIV与EBV的靶细胞"},{"q":"终止细胞内病毒感染的主要免疫因素是","o":["中和抗体","NK细胞","巨噬细胞","CD4＋Th1细胞","CD8＋CTL"],"a":4,"e":"CD8+CTL识别感染细胞表面的病毒抗原与MHCⅠ类分子复合物，通过细胞裂解与诱导凋亡杀伤靶细胞，阻断病毒在细胞内复制，是终止病毒感染的主要机制。中和抗体仅作用于细胞外游离病毒，NK细胞与巨噬细胞属非特异性免疫，CD4+Th1主要起辅助作用"},{"q":"汉坦病毒所致HFRS临床5期过程不包括","o":["发热期","低血压休克期","少尿期","多尿期","败血症期"],"a":4,"e":"肾综合征出血热典型病程分发热期、低血压休克期、少尿期、多尿期和恢复期五期，无败血症期。本病病毒直接损害血管内皮并有免疫病理参与，虽有病毒血症，但不形成细菌性败血症的临床过程，故败血症期不属其分期"},{"q":"与链球菌抗吞噬相关的抗原是","o":["M抗原","T抗原","R抗原","S抗原","X抗原"],"a":0,"e":"M蛋白是A群链球菌表面菌毛样结构中的主要成分，具抗吞噬作用，与致病性密切相关并具型特异性，其与人心肌蛋白的共同抗原还参与风湿热发病。T、R蛋白亦为表面抗原但抗吞噬作用弱，P抗原为无特异性的核蛋白抗原"},{"q":"细菌的转导和溶原性转换的共同特点是","o":["供体菌与受体菌直接接触","需温和噬菌体参与","需毒性噬菌体介导","需性菌毛介导","需质粒参与"],"a":1,"e":"转导以噬菌体为载体转移供体菌DNA，普遍性转导由毒性或温和噬菌体介导；溶原性转换因温和噬菌体前噬菌体基因表达而使细菌获得新性状，两者均需温和噬菌体参与。接合需性菌毛，转化需感受态菌，均不涉及噬菌体"},{"q":"弧菌具有下列哪种结构","o":["鞭毛","芽孢","Vi抗原","M蛋白","异染颗粒"],"a":0,"e":"弧菌为革兰阴性短小弯曲杆菌，菌体一端有单鞭毛，运动活泼，是霍乱弧菌的重要鉴定性状。弧菌不形成芽孢；Vi抗原见于伤寒沙门菌；M蛋白为A群链球菌表面成分；异染颗粒见于白喉棒状杆菌。该菌耐碱不耐酸，可在碱性蛋白胨水中快速增菌，用于霍乱弧菌分离"},{"q":"决定病毒感染后免疫力持久的因素不包括","o":["全身性感染","抗原性稳定","有病毒血症","反复发生感染","抗原性单一"],"a":3,"e":"病毒感染后免疫力是否持久，取决于是否为全身性感染、有无病毒血症、抗原性是否稳定单一以及能否形成潜伏或持续感染。反复发生感染是免疫不牢固的结果，而非原因。麻疹、乙脑等全身感染且抗原稳定者，病后免疫持久"},{"q":"下列关于白假丝酵母菌的描述，正确的是","o":["革兰染色阴性","可产生关节孢子","可用青霉素进行治疗","一般不引起皮肤及黏膜感染","可引起全身脏器感染"],"a":4,"e":"白假丝酵母菌为条件致病菌，在免疫低下、菌群失调时可自黏膜播散至肺、肾、脑等，引起全身脏器感染。该菌革兰染色阳性，形成假菌丝和厚膜孢子而非关节孢子；青霉素对其无效，治疗用氟康唑等；皮肤黏膜感染如鹅口疮极为常见"},{"q":"引起普通感冒最常见的病原体是","o":["流感病毒","副流感病毒","腺病毒","呼吸道合胞病毒","鼻病毒"],"a":4,"e":"鼻病毒是普通感冒最常见的病原体，血清型超过100个，故易反复感染。流感病毒引起流行性感冒，全身中毒症状重；副流感病毒、呼吸道合胞病毒多致婴幼儿下呼吸道感染；腺病毒引起咽结膜热和肺炎"},{"q":"耐药株30S亚基S12蛋白的构型改变，使细菌对哪种抗菌药物发生耐药性","o":["链霉素","青霉素","利福平","红霉素","喹诺酮类药"],"a":0,"e":"链霉素作用于细菌核糖体30S亚基，耐药菌的S12蛋白构型改变后药物不能与之结合而失效。红霉素作用于50S亚基，利福平抑制RNA聚合酶，喹诺酮类抑制DNA旋转酶，青霉素抑制细胞壁合成，机制均不相同"},{"q":"关于转座子，叙述错误的是","o":["是一种转位因子","长度一般超过2kb","不携带结构基因","可能与细菌的多重耐药性有关","是染色体或质粒中能够转移位置的一段DNA序列"],"a":2,"e":"转座子除携带转座相关基因外，还携带耐药基因、抗重金属基因、毒力基因等功能基因，故不携带结构基因的说法错误。它是染色体或质粒中可改变位置的DNA序列，长度约2～25kb，可在质粒与染色体间跳跃，是多重耐药性扩散的重要机制"},{"q":"细菌的F质粒是","o":["前噬菌体成分","细菌的染色体成分","带有毒性基因的可传递DNA","赋予细菌性菌毛的可传递DNA","赋予细菌耐药性的可传递DNA"],"a":3,"e":"F质粒编码性菌毛，含F质粒的细菌为F+菌，接合时作供体，可将质粒或部分染色体基因传给F-菌。R质粒赋予耐药性，Col质粒编码大肠菌素，前噬菌体为整合的噬菌体基因，均非F质粒的功能"},{"q":"急性菌痢患者标本采集时，细菌培养阳性率最高的标本是","o":["尿","血液","胆汁","骨髓","脓血便"],"a":4,"e":"急性菌痢病变在结肠黏膜，患者粪便混有脓血和黏液，含菌量最高，故脓血便培养阳性率最高。菌痢一般不引起菌血症，血液、骨髓、胆汁培养阳性率极低；尿液不含志贺菌，不作标本。血液、骨髓培养在菌痢中极少阳性，胆汁、尿液更不用于该病检查"},{"q":"细菌性肺炎的主要病原菌是","o":["金黄色葡萄球菌","甲型溶血型链球菌","肺炎链球菌","脑膜炎奈瑟菌","流感嗜血杆菌"],"a":2,"e":"肺炎链球菌是细菌性肺炎的主要病原菌，主要引起大叶性肺炎，成人以1、2、3型多见。金黄色葡萄球菌肺炎多为儿童或流感后继发；流感嗜血杆菌与脑膜炎奈瑟菌以脑膜炎、呼吸道感染为主；甲型溶血性链球菌以龋齿、心内膜炎为主"},{"q":"感染宿主细胞能形成包涵体的原核细胞型微生物是","o":["巴通体","立克次体","螺旋体","支原体","衣原体"],"a":4,"e":"衣原体在宿主上皮细胞内形成始体与网状体，胞质内可见含众多原体的包涵体，碘染色呈棕褐色，是诊断沙眼衣原体感染的重要依据。立克次体仅在细胞内增殖，不形成包涵体；支原体、螺旋体与巴通体也无此结构。包涵体另可见于病毒感染，但病毒非原核细胞型"},{"q":"能在人工培养基中生长对人类有致病作用的立克次体属是","o":["巴通体属","东方体属","埃立克体属","柯克斯体属","立克次体属"],"a":0,"e":"巴通体属可在含血琼脂的人工培养基中生长，如汉赛巴通体引起猫抓病。立克次体属、东方体属、埃立克体属为严格细胞内寄生，须用细胞或鸡胚培养；柯克斯体属常规人工培养基亦不生长。故能在人工培养基中生长者仅巴通体属"},{"q":"引起烫伤样皮肤综合征相关的毒素是","o":["TSST-1","表皮剥脱毒素","溶血毒素","杀白细胞素","红疹毒素"],"a":1,"e":"表皮剥脱毒素又称表皮溶解毒素，为金葡菌产生的丝氨酸蛋白酶，裂解桥粒芯糖蛋白1，使表皮与真皮分离，引起烫伤样皮肤综合征。TSST-1引起毒性休克综合征，红疹毒素引起猩红热皮疹，杀白细胞素破坏白细胞，溶血毒素溶解红细胞"},{"q":"梅毒在哪一病程中传染性最强","o":["恢复期","潜伏期","第三期","第二期","第一期"],"a":4,"e":"一期梅毒硬下疳表面渗液含大量梅毒螺旋体，传染性最强；二期梅毒疹与黏膜斑亦含螺旋体，传染性较强；三期梅毒病灶内螺旋体极少，传染性小但破坏性大。潜伏期无皮损，传染性低于一、二期，故病程早期传染性最强"},{"q":"分离培养淋病奈瑟菌，常用的培养基是","o":["精制琼脂肉汤培养基","巧克力血琼脂平板","5%葡萄糖肉汤","半固体培养基","麦芽糖肉汤"],"a":1,"e":"淋病奈瑟菌营养要求高，需含血液、血清的培养基，常用经80℃以上加温的巧克力血琼脂平板，在5%CO₂、35～36℃下培养36～48小时。普通肉汤、半固体培养基及麦芽糖肉汤营养不足，不能支持其生长"},{"q":"白喉计划免疫采用","o":["丙种球蛋白","抗毒素","类毒素","灭活疫苗","减毒活疫苗"],"a":2,"e":"白喉计划免疫用白喉类毒素，与百日咳疫苗、破伤风类毒素组成百白破三联疫苗，婴儿3、4、5月龄各接种1次，2岁、6岁加强。抗毒素仅用于治疗和密切接触者的紧急预防；丙种球蛋白无特异性；灭活疫苗与减毒活疫苗均不用于白喉"},{"q":"与黄曲霉毒素密切相关的恶性肿瘤是","o":["肺癌","肝癌","骨肉瘤","皮肤癌","淋巴瘤"],"a":1,"e":"黄曲霉毒素由黄曲霉、寄生曲霉产生，主要污染花生、玉米，其代谢产物可与肝细胞DNA加合，是肝癌的重要致癌因素，并与HBV感染有协同作用。肺癌与吸烟、氡有关；皮肤癌与紫外线有关；骨肉瘤、淋巴瘤与黄曲霉毒素无明确关联"},{"q":"不能用于检测血清中抗体的试验是","o":["外斐反应","肥达试验","中和试验","间接凝集试验","反向间接凝集试验"],"a":4,"e":"反向间接凝集试验用已知抗体致敏载体，检测标本中的抗原，不能检测抗体。外斐反应、肥达试验检测病人血清中的相应抗体，中和试验检测中和抗体，间接凝集试验用已知抗原致敏载体检测抗体。凝集试验的载体多为乳胶、活性炭或红细胞"},{"q":"立克次体属的致病物质主要是","o":["内毒素和外毒素","多糖和荚膜","多糖和水解酶","脂多糖和磷脂酶A","荚膜和水解酶"],"a":3,"e":"立克次体属细胞壁含脂多糖，具内毒素样毒性；磷脂酶A可溶解宿主细胞膜及吞噬体膜，利于菌体穿入并在小血管内皮细胞内繁殖，二者为主要致病物质。立克次体不产生外毒素。微荚膜黏液层与OmpA、OmpB等表面蛋白主要起黏附与抗吞噬作用，并非毒性物质。水解酶不属其主要致病物质"},{"q":"新型疱疹病毒6、7、8型共同的传播途径是","o":["口腔分泌物唾液","医源性传播","血液","性传播","空气飞沫"],"a":0,"e":"HHV-6、HHV-7主要经唾液传播，HHV-8虽可经性接触和血液传播，但唾液亦是其重要途径，故三者的共同传播途径为口腔分泌物唾液。医源性传播只见于HHV-6和HHV-8，血液传播主要涉及HHV-8，空气飞沫不是其传播方式"},{"q":"常定居于禽类和野鸟肠道的、且最适生长温度为42℃的细菌是","o":["百日咳鲍特菌","空肠弯曲菌","幽门螺杆菌","嗜肺军团菌","流感嗜血杆菌"],"a":1,"e":"空肠弯曲菌为逗点状或S形革兰阴性菌，常定居于家禽和野鸟肠道，最适生长温度42℃，微需氧，是散发性细菌性胃肠炎常见病原。百日咳鲍特菌、流感嗜血杆菌营养要求高且适温37℃；幽门螺杆菌寄居胃黏膜；嗜肺军团菌在人工水体中增殖"},{"q":"严格细胞内寄生的病原体是","o":["普氏立克次体","白假丝酵母菌","结核杆菌","伤寒杆菌","大肠杆菌"],"a":0,"e":"普氏立克次体缺乏完整代谢酶系，须依赖宿主细胞提供能量与营养，为严格细胞内寄生。该菌以二分裂繁殖，每9～12小时一代，最适生长温度34℃。结核分枝杆菌与伤寒沙门菌为兼性胞内寄生，白假丝酵母菌与大肠埃希菌可在人工培养基上生长"},{"q":"致病性与其前噬菌体有关的细菌是","o":["结核分枝杆菌","伤寒沙门菌","破伤风梭菌","白喉棒状杆菌","痢疾志贺杆菌"],"a":3,"e":"β-棒状杆菌噬菌体携带tox基因，感染无毒白喉棒状杆菌后整合于染色体，使其获得产白喉毒素的能力，属溶原性转换。结核分枝杆菌、伤寒沙门菌与痢疾志贺菌的毒力由染色体或质粒基因决定；破伤风梭菌的痉挛毒素基因位于质粒，与噬菌体无关"},{"q":"多种病毒可在实验室培养，以下关于病毒增殖和传播的说法中哪一项是不正确的","o":["某些病毒可用不含活细胞的培养基培养","某些动物病毒可以在鸡胚中培养","宿主范围广的病毒可以在多种细胞中增殖","某些人类病毒能在小鼠体内增殖","不是所有的病毒都可以通过空斑试验测定滴度"],"a":0,"e":"病毒严格细胞内寄生，必须用活细胞（组织细胞、鸡胚或敏感动物）培养，不含活细胞的培养基不能支持其增殖，故A项错误。鸡胚、小鼠可用于特定病毒培养，宿主范围广的病毒可在多种细胞中增殖，空斑试验只适用于能形成空斑的病毒"},{"q":"产生白喉外毒素的白喉棒状杆菌是由于细菌发生了","o":["接合","转化","转导","溶原性转换","原生质体融合"],"a":3,"e":"携带tox基因的β-棒状杆菌噬菌体感染白喉棒状杆菌后，将tox基因整合于宿主染色体，使无毒株变为产毒株，此即溶原性转换。接合经性菌毛传递质粒，转化是摄取裸DNA，转导转移的是供菌DNA片段，原生质体融合为人工方法"},{"q":"非致病性着色真菌与致病性着色真菌的主要区别是","o":["腐生性","37℃生长性","自然界分布性","菌体形态","菌落形态"],"a":1,"e":"致病性着色真菌能在37℃生长，可侵入并适应人体组织；非致病性着色真菌仅能在25℃左右生长，37℃不生长，二者以此鉴别。腐生性、自然界分布及菌体与菌落形态在两类间常有重叠，特异性不足"},{"q":"可用于诊断HCV感染的方法是","o":["PCR检测患者血清HCV DNA","取粪标本做电镜观察病毒颗粒","检测血清抗HCV-IgM","血清接种MDCK细胞","取患者血清接种豚鼠"],"a":2,"e":"HCV为单正链RNA病毒，感染后机体产生结构蛋白与非结构蛋白抗体，用ELISA检测血清抗HCV抗体可辅助诊断并筛选献血员。HCV基因组为RNA，检测HCV DNA的提法错误；病毒不经粪便排出，电镜难查；MDCK细胞用于流感病毒，豚鼠接种不用于HCV"},{"q":"关于汉坦病毒的流行环节，叙述错误的是","o":["汉坦病毒有较严格的宿主特异性","流行状况与宿主动物的分布和活动有关","可经多途径感染人或动物","HFRS的发生和流行具有明显的地区性和季节性","人类对汉坦病毒普遍易感，发病率高"],"a":4,"e":"人类对汉坦病毒普遍易感，但多呈隐性感染，仅少数人发病，故发病率高之说错误。该病毒宿主特异性较强，流行与鼠类分布活动相关，可经呼吸道、消化道等多途径感染，HFRS有明显地区性与季节性"},{"q":"Dane颗粒是","o":["甲型肝炎病毒体","EB病毒体","乙型肝炎病毒体","流感病毒体","脊髓灰质炎病毒体"],"a":2,"e":"Dane颗粒即完整的乙型肝炎病毒体，直径42nm，由HBsAg包膜、HBcAg衣壳、环状双链DNA及DNA聚合酶组成，是HBV的感染性颗粒。甲肝病毒为无包膜单正链RNA病毒，EB病毒属疱疹病毒，流感病毒为分节段负链RNA病毒，均非Dane颗粒"},{"q":"可以产生外毒素的革兰氏阴性菌是","o":["炭疽芽孢杆菌","布氏菌","肉毒梭菌","鼠疫耶尔森菌","破伤风梭菌"],"a":3,"e":"鼠疫耶尔森菌为革兰阴性球杆菌，其鼠毒素具外毒素性质，为可溶性蛋白，对鼠类毒性极强，菌体自溶后释放。炭疽芽胞杆菌、肉毒梭菌与破伤风梭菌均为革兰阳性菌；布氏菌虽为革兰阴性菌，主要致病物质是内毒素，不产生外毒素"},{"q":"机体对HBV的免疫耐受可导致的感染状态是","o":["急性肝炎","重型肝炎","慢性持续性肝炎","原发性肝癌","潜伏感染"],"a":2,"e":"机体对HBV形成免疫耐受时，细胞免疫和体液免疫均处于低水平，既不能清除病毒，也不能杀伤感染细胞，病毒持续复制，表现为无症状携带或慢性持续性肝炎。免疫应答正常者多为急性肝炎，应答过强者为重型肝炎，肝癌是长期感染的结局"},{"q":"以下为人类prion病的是","o":["TME","CWD","BSE","FSE","CJD"],"a":4,"e":"CJD即克-雅病，属人类朊粒病，表现为迅速进展的痴呆、肌阵挛与共济失调。TME为水貂传染性脑病，CWD为鹿慢性消耗病，BSE为牛海绵状脑病，FSE为猫海绵状脑病，四者均为动物朊粒病"},{"q":"肠道正常菌群中主要是","o":["需氧菌","微需氧菌","兼性厌氧菌","厌氧菌","真菌"],"a":3,"e":"肠道微生物群中厌氧菌占99.9%，大肠埃希菌等兼性厌氧菌只占0.1%，故以厌氧菌为主。皮肤、口腔、上呼吸道和泌尿生殖道的微生物群中，80%～90%为无芽胞厌氧菌，需氧菌和真菌只占少数"},{"q":"热原质的生物学特点是","o":["不具有挥发性","加热后容易被破坏","在有水的条件下性能更稳定","能够耐受300℃以上的高温","经消化道吸收后能引起发热反应"],"a":0,"e":"热原质即革兰阴性菌细胞壁脂多糖，耐高温，121℃高压灭菌不被破坏，须250℃干烤才能去除，故加热后容易破坏错误；它不挥发，不能经蒸馏去除，这是制备注射用水须用蒸馏法的原因；口服不引起发热反应"},{"q":"下列能产生内毒素的细菌是","o":["破伤风梭菌","产气荚膜梭菌","肉毒梭菌","结核分枝杆菌","淋病奈瑟菌"],"a":4,"e":"淋病奈瑟菌为革兰阴性球菌，细胞壁含脂多糖，故产生内毒素。破伤风梭菌、产气荚膜梭菌与肉毒梭菌均为革兰阳性菌，只产外毒素；结核分枝杆菌细胞壁富含脂质，不含内毒素。内毒素耐热，须160℃2～4小时才被破坏"},{"q":"霍乱肠毒素能使胞内腺苷环化酶活性增加，促进胞内","o":["cAMP含量升高","ATP含量升高","cAMP含量降低","cGMP含量升高","cGMP含量降低"],"a":0,"e":"霍乱肠毒素A亚基进入细胞后催化G蛋白ADP核糖基化，持续激活腺苷环化酶，使ATP转化为cAMP，胞内cAMP升高，肠黏膜细胞分泌亢进、钠重吸收减少，导致水样泻。cGMP升高见于大肠埃希菌耐热肠毒素；cAMP降低不出现"},{"q":"在我国，流行性乙型脑炎的传染源主要是","o":["病人","病毒携带者","幼猪","蚊","猴"],"a":2,"e":"幼猪是乙脑病毒的主要传染源和扩增宿主，感染后病毒血症持续时间长、滴度高，经蚊叮咬传播给人。蚊是传播媒介而非传染源；病人病毒血症短暂且滴度低，作为传染源意义小；猴仅为次要宿主。三者中只有幼猪能维持高水平病毒血症，构成蚊—猪—蚊的扩增循环"},{"q":"关于病毒核酸，正确的是","o":["可控制病毒的遗传和变异","决定病毒包膜所有成分的形成","RNA不能携带遗传信息","不能决定病毒的感染性","病毒有一种或两种类型核酸"],"a":0,"e":"病毒核酸携带全部遗传信息，决定子代病毒的形态、致病性、抗原性及遗传变异。包膜脂质来自宿主细胞膜，包膜蛋白才由病毒基因编码；RNA同样可携带遗传信息；核酸是感染性的物质基础；每种病毒只含一种核酸"},{"q":"病毒粒子中的一种结构是来自寄主细胞膜的，它是","o":["包膜","刺突","衣壳","核心","核衣壳"],"a":0,"e":"包膜是病毒出芽释放时获得的脂质双层，其脂质和部分多糖来自宿主细胞膜，包膜蛋白由病毒基因编码。刺突是包膜上的糖蛋白突起，决定吸附特异性；衣壳和核心由病毒自身蛋白与核酸构成，与宿主膜无关"},{"q":"与细菌的染色反应、凝集反应有关的是","o":["细菌的光学性质","细菌的表面积","细菌的带电现象","细菌细胞壁的半透性","细菌体内的渗透压"],"a":2,"e":"细菌在溶液中带负电荷，与带正电荷的染料结合而着色，故染色反应与带电现象有关；凝集反应中抗原抗体电荷中和亦基于同一原理。光学性质、表面积、细胞壁半透性、体内渗透压均不直接决定染色和凝集"},{"q":"病毒复制方式是","o":["二分裂","原体、始体","孢子、菌丝","自我复制","有丝分裂"],"a":3,"e":"病毒无细胞结构，以基因组核酸为模板进行自我复制，经复制、装配、释放完成增殖，不进行二分裂或有丝分裂。二分裂为细菌繁殖方式；原体、始体为衣原体发育周期的两个阶段；孢子、菌丝为真菌的繁殖体与营养体"},{"q":"被带有泥土的锈钉刺伤容易引起破伤风是因为","o":["土内含有细菌","土内含有破伤风梭菌芽孢","锐器刺得深","有其他需氧化脓性细菌","有异物"],"a":1,"e":"破伤风梭菌芽胞广泛存在于泥土及人和动物粪便中，带泥土的锈钉刺伤形成深而窄的厌氧伤口，芽胞发芽繁殖并释放痉挛毒素，故根本原因是土内含有破伤风梭菌芽胞。伤口深、有异物和其他化脓菌只是造成厌氧环境，为芽胞发芽提供条件"},{"q":"下列哪种病毒的核酸是分节段的","o":["麻疹病毒","风疹病毒","登革病毒","汉坦病毒","新型肠道病毒"],"a":3,"e":"汉坦病毒属布尼亚病毒目，基因组为分节段的单负链RNA，分L、M、S三个节段。麻疹病毒、风疹病毒为不分节段单负链RNA，登革病毒与新型肠道病毒为不分节段的单正链RNA；分节段是基因重排的物质基础，也是汉坦病毒的标志性特征"},{"q":"乙型肝炎患者血清中通常不能检出的成分是","o":["HBsAg","抗-HBs","HBeAg","抗-HBe","HBcAg"],"a":4,"e":"HBcAg组装于病毒衣壳内并包裹核酸，一般不以游离形式存在于血液，故常规血清学难以检出。HBsAg、HBeAg及抗-HBs、抗-HBe均可在血清中检出，抗-HBc亦为常规检测项目"},{"q":"柯萨奇病毒分为A和B两组的主要依据是","o":["对乳鼠的致病特点","基因组同源性","中和试验","对人的致病特点","血凝试验"],"a":0,"e":"柯萨奇病毒按对乳鼠的致病特点及对细胞培养的敏感性分型：A组引起乳鼠骨骼肌广泛炎症与松弛型麻痹，B组引起灶性肌炎、脂肪坏死与痉挛性麻痹。基因组同源性用于种内分型；中和试验与血凝试验用于血清型鉴定，不用于分组"},{"q":"引起婴幼儿秋冬季腹泻最常见的病原体是","o":["A组轮状病毒","星状病毒","诺如病毒","伤寒沙门菌","痢疾志贺菌"],"a":0,"e":"A组轮状病毒是婴幼儿重症腹泻最常见的病原体，多发于深秋与初冬，故称秋季腹泻，经粪-口传播，侵犯小肠绒毛上皮细胞致吸收障碍。诺如病毒与星状病毒多引起散发或暴发腹泻，季节集中性不强；肠道腺病毒亦可致腹泻但比例低；伤寒沙门菌与痢疾志贺菌引起肠热症与细菌性痢疾"},{"q":"结核分枝杆菌的致病机制多样，与致病作用有关的超敏反应是","o":["体液免疫","Ⅱ型超敏反应","Ⅲ型超敏反应","迟发型超敏反应","ADCC作用"],"a":3,"e":"结核分枝杆菌的菌体蛋白与糖脂可致敏T淋巴细胞，再次接触抗原时释放淋巴因子，引起迟发型超敏反应，与结核结节形成、干酪样坏死及结核菌素试验阳性有关。该反应由T细胞而非抗体介导，不属Ⅱ、Ⅲ型；ADCC以抗体依赖细胞杀伤为特征，与结核的免疫病理无关"},{"q":"包膜DNA病毒释放到细胞外，是通过","o":["出芽方式","宿主细胞破裂","通过细胞间桥在细胞间传播","通过细胞融合在细胞间传播","与宿主细胞整合出现在子代中"],"a":0,"e":"包膜病毒核衣壳穿过细胞膜或核膜、高尔基体膜，以出芽方式获得包膜并释放，一般不直接导致细胞死亡。无包膜病毒多经细胞破裂释放；细胞间桥与细胞融合是病毒在细胞间直接扩散的方式，不属释放途径；病毒基因组整合入宿主DNA是潜伏或转化的机制"},{"q":"测量细菌的单位是","o":["纳米（nm）","微米（μm）","毫米（mm）","厘米（cm）","米（m）"],"a":1,"e":"细菌大小以微米计，需在光学显微镜下用测微尺测量，球菌直径约1μm，杆菌长2～3μm。纳米用于测量病毒与蛋白质等更小结构，如脊髓灰质炎病毒直径仅27～30nm；毫米、厘米与米均远大于细菌，不适用于单个菌体的测量"},{"q":"以下属于活疫苗制剂的是","o":["亚单位疫苗","化学疫苗","DNA重组疫苗","核酸疫苗","减毒疫苗"],"a":4,"e":"减毒活疫苗由减毒或无毒的活病原体制成，接种后可在体内增殖，如卡介苗、麻疹疫苗、口服脊灰疫苗。亚单位疫苗仅含提纯抗原成分；化学疫苗为化学方法提取的抗原；DNA重组疫苗与核酸疫苗导入基因或核酸，均不能在体内增殖，不属活疫苗"},{"q":"无动力的肠道杆菌是","o":["变形杆菌","大肠埃希菌","伤寒沙门菌","肠炎沙门菌","志贺菌"],"a":4,"e":"志贺菌无鞭毛、无动力，在半固体培养基中沿穿刺线生长而不扩散，是肠道杆菌中唯一无动力的菌属。大肠埃希菌、变形杆菌、伤寒沙门菌、肠炎沙门菌均有鞭毛、动力阳性，其中变形杆菌迁徙生长最明显"},{"q":"病毒的分离培养不能采用的方法是","o":["鸡胚培养","动物培养","无生命人工培养基","细胞培养","器官培养"],"a":2,"e":"病毒严格细胞内寄生，缺乏独立代谢的酶系统，须在活细胞或活体组织内才能增殖，无生命人工培养基不能支持其生长。鸡胚接种、动物接种、细胞培养与器官培养均能提供活细胞，是分离病毒的常规方法。无生命培养基如肉汤、琼脂平板只用于细菌和真菌培养，支原体亦可在其中生长，但病毒不能"},{"q":"关于热原质，下列表述错误的是","o":["多由革兰阴性菌产生","本质是细菌细胞壁中的脂多糖","注入人体能引起发热反应","高压蒸汽灭菌处理可破坏其活性","为细菌的合成代谢产物"],"a":3,"e":"热原质即革兰阴性菌细胞壁的脂多糖，耐高温，121℃高压蒸汽灭菌20分钟不被破坏，需250℃干烤才能去除，故此项错误。它由细菌合成代谢产生，注入人体可引起发热反应，是注射用水和生物制品的重要质控指标"},{"q":"与接合作用有关的结构是","o":["鞭毛","轴丝","荚膜","性菌毛","普通菌毛"],"a":3,"e":"接合是供体菌通过性菌毛与受体菌表面受体结合形成通道，将质粒或部分染色体DNA转入受体菌的过程，故性菌毛是关键结构。普通菌毛仅介导黏附；鞭毛与运动有关；轴丝为螺旋体的结构；荚膜抗吞噬，均不参与接合"},{"q":"常用减毒活疫苗预防的疾病是","o":["狂犬病、麻疹","破伤风、百日咳","白喉、乙型肝炎","脊髓灰质炎、结核病","流行性乙型脑炎、腮腺炎"],"a":3,"e":"脊髓灰质炎使用口服减毒活疫苗，结核病使用卡介苗，均为减毒活疫苗。狂犬病疫苗为灭活疫苗；破伤风、白喉用类毒素；乙型肝炎用基因工程亚单位疫苗；乙型脑炎常用灭活疫苗，故A、B、C、E组中均含非活疫苗制品"},{"q":"控制汉坦病毒流行最重要的一般预防措施是","o":["灭鼠","灭蚤","灭蚊","防蜱叮咬","注射HFRS疫苗"],"a":0,"e":"汉坦病毒以鼠类为传染源和贮存宿主，灭鼠、防鼠是切断传播途径最根本的一般预防措施，同时配合灭螨、消毒和个人防护。灭蚤针对斑疹伤寒，灭蚊针对乙脑、登革热，防蜱针对克里米亚-刚果出血热；疫苗属特异性预防"},{"q":"与结核分枝杆菌抗酸性有关的成分是","o":["索状因子","磷脂","分枝菌酸","蜡质D","硫酸脑苷脂"],"a":2,"e":"分枝菌酸与阿拉伯半乳聚糖、肽聚糖构成细胞壁复合物，其长链脂肪酸使苯酚复红着色后难以被盐酸乙醇脱色，是抗酸性的物质基础。索状因子为海藻糖二分枝菌酸，与毒力有关；蜡质D为佐剂，硫酸脑苷脂抑制吞噬体融合"},{"q":"关于非结核分枝杆菌表述正确的是","o":["抗酸染色阴性","多数为致病菌","多通过内毒素致病","多通过产生外毒素致病","流行病学调查数据显示我国鸟分枝杆菌最常见"],"a":4,"e":"我国结核病流行病学调查显示非结核分枝杆菌分离率由2000年11.1%升至2010年22.9%，其中鸟分枝杆菌最常见，其次为偶发分枝杆菌和瘰疬分枝杆菌。非结核分枝杆菌抗酸染色阳性，大多不致病、少数为机会致病菌，不靠内、外毒素致病"},{"q":"下面哪种疾病不属于自然疫源性疾病","o":["流行性斑疹伤寒","地方性斑疹伤寒","肾综合征出血热","恙虫病","莱姆病"],"a":0,"e":"流行性斑疹伤寒由普氏立克次体引起，传染源是病人，人虱为媒介，在人间循环，不属自然疫源性疾病。地方性斑疹伤寒、肾综合征出血热、恙虫病和莱姆病均以鼠类等动物为储存宿主，在动物间循环，属自然疫源性疾病"},{"q":"属于α疱疹病毒亚科的病毒组合是","o":["HSV，CMV","EBV，CMV","VZV，HHV6","HSV，VZV","HHV7，HHV8"],"a":3,"e":"α疱疹病毒亚科包括HSV-1、HSV-2和VZV，均潜伏于神经节。CMV、HHV-6、HHV-7属β亚科，EBV（HHV-4）与HHV-8属γ亚科，故含CMV、EBV、HHV-6、HHV-7、HHV-8的组合均不属α亚科"},{"q":"帮助检测HCMV近期感染最敏感的方法是","o":["从标本中分离培养HCMV","免疫印迹法检测HCMV-IgM","RT-PCR法检测病毒mRNA","ELISA法检测HCMV-IgM","ELISA法检测HCMV-IgG"],"a":3,"e":"HCMV感染后IgM抗体出现早、消失快，且不能经胎盘传给胎儿，ELISA检测HCMV-IgM是辅助诊断近期感染的常用方法，新生儿血清IgM阳性提示宫内感染。IgG阳性仅提示既往感染；病毒分离耗时长，不作首选"},{"q":"关于β-内酰胺酶的叙述，不正确的是","o":["青霉素和头胞菌素类耐药的菌株可产生","革兰阳性菌的β-内酰胺酶位于胞外","只能由细菌染色体编码","1940年首次发现","分为四类"],"a":2,"e":"β-内酰胺酶可由细菌染色体或质粒编码，质粒介导者易在菌间传播，故“只能由染色体编码”错误。该酶由对青霉素、头孢菌素耐药的菌株产生，革兰阳性菌的酶多分泌至胞外，阴性菌的酶位于周浆间隙；1940年首次发现，现分为四类，A、B、D、E均正确"},{"q":"与细菌致病性无关的结构是","o":["荚膜","菌毛","磷壁酸","脂多糖","异染颗粒"],"a":4,"e":"异染颗粒是胞质内由RNA与多偏磷酸盐构成的储藏颗粒，仅用于白喉棒状杆菌等的鉴定，与致病无关。荚膜抗吞噬，菌毛介导黏附，磷壁酸参与黏附与炎症，脂多糖即内毒素，四者均为致病相关结构。荚膜、菌毛、磷壁酸与脂多糖均直接参与侵袭或毒素作用"},{"q":"下列哪一项不适用于病毒感染性疾病的快速诊断","o":["中和试验","免疫荧光试验","电镜检查","酶联免疫吸附试验","血凝抑制试验"],"a":0,"e":"中和试验需细胞培养，观察病毒对细胞的感染性被抗体中和，耗时长，且中和抗体阳性不能区分现症与既往感染，适用于人群免疫调查，不用于快速诊断。免疫荧光、电镜、ELISA、血凝抑制试验均可短时间内出结果"},{"q":"对病毒体叙述最正确的是","o":["有感染性的病毒颗粒","脱壳后仍有感染性的病毒核酸","有刺突的包膜病毒颗粒","可独立存在于细胞外的病毒颗粒","成熟的、完整的、具有感染性的病毒颗粒"],"a":4,"e":"病毒体指结构完整、已成熟并具感染性的病毒颗粒，即核衣壳（有包膜者含包膜）装配完成、发育成熟后的形态。有感染性的病毒颗粒表述过宽，未成熟颗粒也可能具部分感染性；脱壳后游离的病毒核酸虽可具感染性，但已不是病毒体；有刺突的包膜病毒颗粒只概括包膜病毒，无包膜病毒并无刺突"},{"q":"尚无有效疫苗预防的病毒是","o":["脊髓灰质炎病毒","乙型脑炎病毒","埃博拉病毒","汉坦病毒","克里米亚-刚果出血热病毒"],"a":2,"e":"埃博拉病毒发现较晚、流行局限，其疫苗长期停留在研发与临床试验阶段，尚无广泛应用的成熟疫苗，故列为尚无有效疫苗预防的病毒。脊髓灰质炎与乙脑均有成熟的减毒活疫苗和灭活疫苗；汉坦病毒有灭活疫苗在疫区使用；克里米亚-刚果出血热以灭活疫苗试用为主"},{"q":"机体抗外毒素的免疫主要依靠","o":["激活的巨噬细胞分泌的蛋白酶类","IgG、IgM抗体","细胞毒性T细胞","靶细胞表面毒素受体被修饰","辅助T细胞"],"a":1,"e":"外毒素为蛋白质，刺激机体产生抗毒素，主要是IgG和IgM，通过与毒素结合阻断其与靶细胞受体结合而中和毒性。细胞毒性T细胞针对胞内寄生病原，辅助T细胞只起辅助作用，巨噬细胞分泌的蛋白酶为非特异性降解，均非抗毒素主体"},{"q":"溶原性转换是指","o":["供体菌染色体基因与受菌染色体基因的重组","供体菌质粒DNA与受体菌染色体DNA的重组","噬菌体的基因与细菌染色体DNA的重组","细菌染色体的基因发生突变","两种细菌原生质体融合后发生染色体基因的重组"],"a":2,"e":"溶原性转换是温和噬菌体基因整合于细菌染色体后，使宿主菌获得新的生物学性状，本质为噬菌体基因与细菌染色体DNA的重组。供体菌染色体基因与受体菌染色体重组属转化或转导的结果；质粒DNA整合染色体见于Hfr形成；原生质体融合属细胞融合"},{"q":"下列哪种细菌不属于肠道杆菌","o":["甲型副伤寒沙门菌","福氏痢疾杆菌","大肠埃希菌","变形杆菌","炭疽芽孢杆菌"],"a":4,"e":"炭疽芽胞杆菌属芽胞杆菌科芽胞杆菌属，为革兰阳性大杆菌，可形成芽胞，是动物源性细菌。肠杆菌科的共同特征是革兰阴性杆菌、不产生芽胞、多数有周鞭毛。甲型副伤寒沙门菌、福氏志贺菌、大肠埃希菌均属肠杆菌目；变形杆菌属摩根菌科，亦属肠道杆菌范畴"},{"q":"诊断流感病毒最常用的血清学方法是","o":["血凝抑制试验","中和试验","补体结合试验","荧光抗体法","冷凝集试验"],"a":0,"e":"血凝抑制试验利用抗HA抗体阻断病毒凝集红细胞，特异性好、操作简便，是诊断流感病毒感染及鉴定甲型流感病毒亚型最常用的血清学方法。中和试验繁琐，补体结合试验敏感性低，冷凝集试验用于支原体肺炎"},{"q":"鉴定支原体最特异敏感的试验是","o":["ELISA试验","血凝试验","生长抑制试验（GIT）","免疫荧光试验","补体结合试验"],"a":2,"e":"支原体的表面抗原抗体能抑制支原体生长与代谢，生长抑制试验（GIT）与代谢抑制试验特异性、敏感性均高，是鉴定支原体最可靠的方法。ELISA、血凝试验、免疫荧光和补体结合试验均为血清学方法，特异性不及GIT"},{"q":"从我国皮肤癣患者皮肤中分离出的癣菌以下列哪种最为常见","o":["红色毛癣菌","须毛癣菌","许兰毛癣菌","絮状表皮癣菌","白吉利毛孢子菌"],"a":0,"e":"红色毛癣菌是毛癣菌属中侵犯皮肤和甲板最常见的菌种，所致体癣、手足癣、甲癣在我国皮肤癣中居首位。须毛癣菌即石膏样毛癣菌，侵犯皮肤、毛发和甲板，属亲动物性菌。絮状表皮癣菌侵犯皮肤与甲板而不侵犯毛发。许兰毛癣菌是黄癣的病原，白吉利毛孢子菌属毛孢子菌，均非皮肤癣常见分离株"},{"q":"能通过胎盘的螺旋体是","o":["雅司螺旋体","回归热螺旋体","奋森螺旋体","苍白密螺旋体苍白亚种","伯氏疏螺旋体"],"a":3,"e":"苍白密螺旋体苍白亚种即梅毒螺旋体，妊娠期可经胎盘进入胎儿血循环引起先天性梅毒，故孕妇筛查意义重大。雅司螺旋体引起雅司病，回归热螺旋体引起回归热，奋森螺旋体致奋森咽峡炎，伯氏疏螺旋体引起莱姆病，均不经胎盘传播"},{"q":"分离培养后，对细菌具有初步鉴别诊断意义的细菌代谢产物是","o":["vitamin","antibiotics","exotoxin","pigment","endotoxin"],"a":3,"e":"色素是细菌的合成代谢产物，如金黄色葡萄球菌产生金黄色素、铜绿假单胞菌产生绿脓菌素，有助于菌种的初步鉴别。外毒素、内毒素与致病性相关，不用于常规鉴别；抗生素为抗菌物质；维生素虽属合成产物，但鉴别价值很小"},{"q":"常引起以痉挛性咳嗽为特征的呼吸道传染病的是","o":["流感嗜血杆菌","百日咳鲍特菌","空肠弯曲菌","铜绿假单胞菌","幽门螺杆菌"],"a":1,"e":"百日咳鲍特菌经飞沫传播，引起百日咳，典型表现为阵发性痉挛性咳嗽伴鸡鸣样吸气吼声，病程可达2～3个月。流感嗜血杆菌引起会厌炎、脑膜炎；空肠弯曲菌致肠炎；铜绿假单胞菌致烧伤创面感染；幽门螺杆菌致胃炎"},{"q":"白假丝酵母菌在玉米培养基上可形成","o":["厚膜孢子","关节孢子","分生孢子","有性孢子","孢子囊孢子"],"a":0,"e":"白假丝酵母菌在含1%吐温-80的玉米粉琼脂上25℃培养24～48小时，菌丝顶端或侧缘形成厚膜孢子，是鉴定依据。关节孢子见于皮肤癣菌，分生孢子为曲霉、毛癣菌等的繁殖结构，有性孢子与孢子囊孢子非其特点"},{"q":"鉴别甲型溶血性链球菌与肺炎链球菌最可靠的方法是","o":["糖发酵试验","革兰染色镜检","菌落特征","胆汁溶菌试验","血琼脂平板上溶血特征"],"a":3,"e":"肺炎链球菌自溶酶可被胆汁或胆盐激活，胆汁溶菌试验10分钟内菌液变清，甲型溶血性链球菌为阴性，是两者最可靠的鉴别方法。两者均为α溶血、革兰阳性双球菌或短链状，菌落与溶血特征相似；糖发酵试验结果亦不稳定"},{"q":"关于嗜肺军团菌的叙述，错误的是","o":["带菌飞沫、气溶胶被直接吸入下呼吸道造成感染","主要来源是医院中央空调冷却塔污染的循环水气溶胶","亦可通过人与人之间的直接传播而感染","所致疾病有流感样型、肺炎型和肺外感染型","治疗军团病首选红霉素"],"a":2,"e":"嗜肺军团菌存在于天然水体和人工水系统，经带菌飞沫、气溶胶吸入下呼吸道感染，主要来源为中央空调冷却塔、淋浴喷头污染的循环水，无人与人之间直接传播。临床分流感样型、肺炎型和肺外感染型，治疗首选红霉素"},{"q":"主要引起成人腹泻的轮状病毒分组属于","o":["A组","B组","D组","F组","G组"],"a":1,"e":"轮状病毒按结构蛋白VP6的抗原性与基因变异分为A～J十组。A组主要引起婴幼儿重症腹泻，B组主要引起成人腹泻，曾在我国出现暴发流行，C组引起散发性儿童腹泻。D、F、G组主要感染动物，与人腹泻关系不密切"},{"q":"关于葡萄球菌A蛋白叙述错误的是","o":["大多数金黄色葡萄球菌表面的一种糖蛋白","能与IgG1、IgG2和IgG4分子的Fc段发生特异性结合","与协同凝集试验的建立有关","能够阻碍吞噬细胞的吞噬作用","有促细胞分裂、引起超敏反应、损伤血小板等生物活性"],"a":1,"e":"SPA是金黄色葡萄球菌细胞壁表面的蛋白抗原，能与人和多种哺乳动物IgG1、IgG2、IgG4的Fc段非特异性结合，结合后Fab段仍可结合相应抗原，故B项“特异性结合”错误。协同凝集试验正是利用该原理建立，C项正确；SPA与Fc段结合后可阻碍吞噬细胞吞噬，D项正确；其尚有促细胞分裂、损伤血小板等活性，E项正确"},{"q":"表皮癣菌属不能引起哪种癣病","o":["发癣","体癣","甲癣","足癣","手癣"],"a":0,"e":"表皮癣菌属只有絮状表皮癣菌一个种，侵犯皮肤角质层和甲板，引起体癣、股癣、手癣、足癣和甲癣，不侵犯毛发，故不引起发癣。发癣由毛癣菌属和小孢子菌属引起，如许兰毛癣菌、犬小孢子菌。毛癣菌属则同时侵犯皮肤、毛发与甲板"},{"q":"病毒潜伏性感染间歇期的特点是","o":["不能分离出病毒，不能检测出抗体","可以分离出病毒","不产生抗体","不能分离出病毒但能检测出抗体","可以分离出病毒但不能检测出抗体"],"a":3,"e":"潜伏感染间歇期病毒以非复制状态存在于神经节等部位，取材分离不到活病毒，但特异性抗体长期存在，故不能分离出病毒而能检出抗体。显性感染期或慢性感染期可分离出病毒；抗体在潜伏期始终存在，并非不产生"},{"q":"细菌对磺胺耐药是改变体内的哪种酶","o":["二氢叶酸合成酶","DNA旋转酶","拓扑异构酶","转糖基酶","转肽酶"],"a":0,"e":"磺胺类与对氨基苯甲酸结构相似，竞争细菌的二氢叶酸合成酶，使二氢叶酸合成减少，核酸合成受阻。耐药菌通过改变该酶结构或增加PABA产量而耐药；DNA旋转酶是喹诺酮类的靶位，转肽酶是青霉素的靶位"},{"q":"导致食物霉变的主要真菌是","o":["石膏样小孢子菌","毛霉菌","申克孢子丝菌","白假丝酵母菌","曲霉菌"],"a":1,"e":"毛霉属广泛存在于自然界，生长迅速，常引起食物霉变，常见总状毛霉、高大毛霉等。曲霉主要经吸入孢子引起肺曲霉病，在食物霉变中处次要地位。白假丝酵母菌为机会致病菌，多引起黏膜与内脏念珠菌病。申克孢子丝菌属皮下组织感染真菌，石膏样小孢子菌为皮肤癣菌"},{"q":"能够以简单的无机物为原料合成菌体成分的细菌被称为","o":["腐生菌","寄生菌","古细菌","自养菌","专性需氧菌"],"a":3,"e":"自养菌以CO2或碳酸盐为碳源，以N2、NH3、硝酸盐等为氮源，靠无机物氧化或光合作用获取能量合成菌体成分。异养菌（含腐生菌、寄生菌）须以蛋白质、糖类等有机物为原料；古细菌为分类学概念；专性需氧菌按气体需求划分"},{"q":"下列不属于引起假丝酵母菌感染的原因的是","o":["抗菌药物滥用引起的菌群失调","内分泌功能紊乱","长期使用免疫抑制剂","激素的长期使用","与假丝酵母菌感染的病人接触"],"a":4,"e":"念珠菌属为人体正常菌群，感染属内源性机会感染，不通过病人传染，故与病人接触不属诱因。广谱抗生素致菌群失调、内分泌功能紊乱、长期使用免疫抑制剂和糖皮质激素，均使机体抵抗力下降而诱发念珠菌病"},{"q":"关于朊粒的特性描述，错误的是","o":["是一种传染性蛋白质","检出PrP即可诊断为prion病","可引起人和动物感染","为传染性海绵状脑病的病原体","对蛋白酶K具有抗性"],"a":1,"e":"正常细胞同样表达PrPC，故单纯检出PrP不能诊断朊粒病，须证实存在蛋白酶K抗性的异常构象PrPSc。朊粒本质是传染性蛋白，可感染人与多种动物并引起海绵状脑病，对蛋白酶K、紫外线与常规消毒均有很强抗性"},{"q":"细菌内毒素的成分是","o":["肽聚糖","H抗原","O抗原","菌毛","脂多糖"],"a":4,"e":"内毒素化学成分为脂多糖，由脂质A、核心多糖和特异多糖组成，脂质A为毒性中心。O抗原即脂多糖的特异多糖侧链，具型特异性；H抗原为鞭毛蛋白；肽聚糖是细胞壁骨架；菌毛为黏附结构，均非内毒素成分"},{"q":"关于肠产毒型大肠埃希菌的肠毒素的描述，正确的是","o":["抑制蛋白质合成中的延长因子-2","抑制内毒素脱毒","作用于肠壁自主神经","有不耐热和耐热两种","封闭乙酰胆碱的释放"],"a":3,"e":"肠产毒型大肠埃希菌产生不耐热肠毒素LT与耐热肠毒素ST，均由质粒编码。LT由1个A亚单位与5个B亚单位组成，65℃30分钟被破坏，激活腺苷酸环化酶；ST耐热，激活鸟苷酸环化酶。抑制延长因子-2是白喉毒素的作用；封闭乙酰胆碱释放是肉毒毒素的作用"},{"q":"黄曲霉毒素主要损害的器官是","o":["心脏","肝脏","肾脏","肺","脾脏"],"a":1,"e":"黄曲霉毒素以B1毒性最强，经肝细胞色素P450活化后与DNA、蛋白质结合，靶器官是肝脏，引起肝细胞脂肪变性、坏死，并可诱发肝细胞癌。肾脏的靶毒素是赭曲霉毒素A，心脏、肺、脾均非其损伤部位"},{"q":"伤寒病人进行粪便培养致病菌的最佳时间是","o":["潜伏期末","发病1～4天","发病5～10天","发病2～3周","发病4周后"],"a":3,"e":"伤寒病程第1～2周取血培养阳性率最高，第2～3周细菌随胆汁排入肠道，粪便培养阳性率最高，第1～3周骨髓培养阳性率亦高。潜伏期末和发病1～4天菌量少；发病4周后已进入恢复期，检出率明显下降"},{"q":"检查螺旋体最常用的方法是","o":["Gemsa染色法","暗视野显微镜法","抗酸染色法","革兰染色法","悬滴法"],"a":1,"e":"螺旋体体形细长、折光性强，革兰染色不易着色，检查最常用暗视野显微镜直接观察悬滴标本中的活菌及其运动。Giemsa染色、抗酸染色、革兰染色对螺旋体效果差；悬滴法只是制片方式，需配合暗视野显微镜观察"},{"q":"肺炎链球菌能在鼻咽部和支气管黏膜上定居、繁殖和扩散，可能与下列哪种物质有关","o":["荚膜","溶血素","脂磷壁酸","自溶酶","胆汁溶菌素"],"a":0,"e":"荚膜是肺炎链球菌的主要毒力因子，有荚膜的光滑型菌株能抵抗吞噬，在鼻咽部和支气管黏膜定居、繁殖并向周围扩散，荚膜缺失的粗糙型菌株毒力减弱或消失。肺炎链球菌溶素可溶解红细胞、损伤组织；自溶酶与胆汁溶菌现象有关；脂磷壁酸主要参与A群链球菌的黏附"},{"q":"感染可致新型冠状病毒肺炎（COVID-19）的病原体是","o":["SARS-CoV","MERS-CoV","HCoV-HKU1","HCoV-229E","SARS-CoV-2"],"a":4,"e":"SARS-CoV-2属β冠状病毒属SARS相关冠状病毒种，是2019冠状病毒病（COVID-19）的病原体，经飞沫和接触传播。SARS-CoV引起严重急性呼吸综合征，MERS-CoV引起中东呼吸综合征，HCoV-229E与HCoV-HKU1仅致普通感冒"},{"q":"关于新疆出血热的描述，错误的是","o":["1965年首次报道在我国新疆部分地区发生此病","病原体为克里米亚-刚果出血热病毒","除了新疆地区，青海、云南等地亦有该病毒的自然疫源地","黑线姬鼠为主要传染媒介","病后可获得持久免疫力"],"a":3,"e":"新疆出血热即克里米亚-刚果出血热，传播媒介为蜱，通过蜱叮咬或接触病人血液传播。黑线姬鼠是肾综合征出血热汉坦病毒的主要传染源，不是本病的传播媒介，故该项错误。该病1965年在我国新疆首次报道，青海、云南亦有自然疫源地，病后可获持久免疫"},{"q":"在粪便悬滴标本中呈“穿梭样”运动的细菌是","o":["大肠埃希菌","伤寒沙门菌","幽门螺杆菌","霍乱弧菌","变形杆菌"],"a":3,"e":"霍乱弧菌具单鞭毛，运动活泼，在悬滴标本中呈穿梭样或流星状运动，涂片可见鱼群样排列，据此可作初步诊断，再用O1或O139群血清做制动试验定型。大肠埃希菌与伤寒沙门菌虽有周身鞭毛但运动方式不同；变形杆菌呈迁徙生长；幽门螺杆菌鞭毛位于一端而多根"},{"q":"分离培养流感病毒病毒株，常使用的病人标本是","o":["血清","脑脊液","鼻咽拭子","粪便","尿液"],"a":2,"e":"流感病毒增殖于呼吸道上皮，取急性期鼻咽拭子或咽漱液，抗生素处理后接种9～11日龄鸡胚羊膜腔或尿囊腔，35℃培养3～4天，再用血凝试验检测。血清含中和抗体、病毒量少；脑脊液、尿液与粪便不是流感病毒的排出部位，无分离价值"},{"q":"细菌L型所缺乏的结构是","o":["荚膜","鞭毛","芽胞","细胞壁","菌毛"],"a":3,"e":"细菌L型是细胞壁合成受抑或结构被破坏后形成的细胞壁缺陷型，在适宜渗透压下仍能存活繁殖，形态高度多形性，革兰染色多呈阴性。支原体天然无细胞壁，与L型不同。荚膜、鞭毛、芽胞与菌毛并非所有细菌都有，L型缺的是基本结构细胞壁"},{"q":"流行性乙型脑炎的病原体是","o":["脑膜炎奈瑟菌","日本脑炎病毒","森林脑炎病毒","麻疹病毒","结核分枝杆菌"],"a":1,"e":"流行性乙型脑炎由乙脑病毒引起，该病毒1935年自脑炎死亡者脑组织分离，国际上称日本脑炎病毒，属黄病毒科，经蚊传播。森林脑炎病毒经蜱传播，引起森林脑炎，是另一种虫媒病毒。脑膜炎奈瑟菌引起流行性脑脊髓膜炎，属化脓性脑膜炎。麻疹病毒引起麻疹，偶并发脑炎但非乙脑病原"},{"q":"H7N9禽流感病毒最易发生变异的结构是","o":["核蛋白（NP）和核酸","基质蛋白（MP）","非结构蛋白（NS1和NS2）","血凝素（HA）和神经氨酸酶（NA）","RNA依赖的RNA聚合酶"],"a":3,"e":"甲型流感病毒的血凝素和神经氨酸酶为包膜糖蛋白，HA是主要中和抗原，二者均易发生点突变（抗原漂移）和基因重排（抗原转换），H7N9的HA、NA即不断变异。核蛋白、基质蛋白、非结构蛋白和RNA聚合酶相对保守，变异少"},{"q":"病毒复制隐蔽期特点是","o":["电子显微镜能查到病毒颗粒","血清学方法能查到病毒颗粒","查不到病毒颗粒","不同的病毒隐蔽期相同","检测不到抗体"],"a":2,"e":"隐蔽期指病毒脱壳后至子代病毒装配完成之前，细胞内只有核酸与蛋白合成，无完整病毒颗粒，电镜与血清学方法均查不到。各病毒隐蔽期长短不等，取决于基因组大小与复制周期，并不相同。此期长短与能否检出血清抗体无直接关系"},{"q":"目前在传染病的预防接种中，使用减毒活疫苗比使用灭活疫苗普遍，关于其原因，下述不正确的是","o":["减毒活疫苗的免疫效果优于灭活疫苗","减毒活疫苗一般只需要接种一次即可达到免疫效果，而灭活疫苗需要接种多次","减毒活疫苗能在机体内增殖或干扰野毒株的增殖及致病作用，灭活疫苗则不能","减毒活疫苗可诱导机体产生分泌型IgA，故适用于免疫缺陷或免疫功能低下的患者","减毒活疫苗刺激机体产生的特异性免疫的持续时间比灭活疫苗长"],"a":3,"e":"减毒活疫苗可在体内增殖，免疫效果持久、接种次数少，但不能用于免疫缺陷或免疫功能低下者，否则可能引起严重感染，故该项错误。活疫苗可诱导分泌型IgA，免疫效果优于灭活疫苗、免疫维持时间更长则为其优点"},{"q":"关于伤寒沙门菌感染的免疫性，正确的描述是","o":["伤寒沙门菌的H抗体属于IgM类抗体","伤寒沙门菌的O抗体属于IgG类抗体","特异性的体液抗体不辅助杀菌作用","特异性细胞免疫是主要防御机制","特异性体液免疫是主要防御机制"],"a":3,"e":"伤寒沙门菌为胞内寄生菌，彻底杀灭须依赖特异性细胞免疫，故该项正确。伤寒H抗体属IgG类，O抗体属IgM类，A、B两项颠倒；两类抗体在肥达试验中的消长规律不同，可用于病程判断，特异性抗体对胞内菌仅起辅助调理作用"},{"q":"流感病毒的基因组特点是","o":["一条完整的单负链RNA","分节段的单负链RNA","完整的双链DNA","分节段的双链RNA","分节段的单链DNA"],"a":1,"e":"流感病毒基因组为分节段的单负链RNA，甲、乙型各8个节段，丙型7个，节段间易发生基因重配，是抗原转换的结构基础。副流感病毒、腮腺炎病毒同为单负链RNA但不分节段。分节段双链RNA见于呼肠孤病毒属如轮状病毒。完整的双链DNA是疱疹病毒、痘病毒的特点。单链DNA仅见于细小病毒"},{"q":"西尼罗病毒感染后的临床表现不包括","o":["高热","脑炎","皮疹","无尿","淋巴结肿大"],"a":3,"e":"西尼罗病毒感染表现为西尼罗热和西尼罗脑炎两型，前者有高热、头痛、乏力、皮疹及全身淋巴结肿大，后者出现脑炎症状，可留后遗症。无尿为肾衰竭表现，不属该病的临床类型，其余各项均可见于该病"},{"q":"地方性斑疹伤寒传播媒介主要是","o":["蚊子","鼠蚤","鼠","蜱","恙螨"],"a":1,"e":"地方性斑疹伤寒由斑疹伤寒立克次体引起，传染源为鼠，鼠蚤和鼠虱是主要传播媒介，鼠蚤叮咬人时接种立克次体，蚤粪污染也可经口、鼻、眼结膜感染。蚊子传播登革热、乙脑；蜱传播森林脑炎、莱姆病；恙螨传播恙虫病"},{"q":"耐药质粒的组成部分是","o":["RTF（耐药传递因子）与F因子","RTF与r决定因子","r决定因子与gal基因","r决定因子与bio基因","r决定因子与F基因"],"a":1,"e":"R质粒由耐药传递因子与耐药决定子两部分组成，前者编码性菌毛，决定复制、接合与转移，后者携带耐药基因。两部分可整合或单独存在，单独存在时不能接合传递。F因子是致育质粒，gal与bio基因是染色体上的代谢基因，均非R质粒组分"},{"q":"通过噬菌体介导，将供体菌的DNA片段转移到受体菌体内，使后者获得新的生物性状的基因转移方式是","o":["转化","转导","接合","溶原性转换","基因转座"],"a":1,"e":"转导是噬菌体介导的基因转移，供体菌DNA片段被误装入噬菌体衣壳，随感染进入受体菌并发生重组。普遍性转导可传递任何DNA片段，局限性转导只转移前噬菌体整合位点两侧的基因。转化是摄取游离DNA，接合经性菌毛传递质粒，溶原性转换为前噬菌体基因表达"},{"q":"鉴定肠杆菌科的基本条件是","o":["发酵葡萄糖，氧化酶阴性，还原硝酸盐","发酵葡萄糖，氧化酶阳性，还原硝酸盐","发酵葡萄糖，氧化酶阴性，不还原硝酸盐","不发酵葡萄糖，氧化酶阴性，还原硝酸盐","不发酵葡萄糖，氧化酶阴性，不还原硝酸盐"],"a":0,"e":"肠杆菌科的基本生化特征是发酵葡萄糖产酸或产气、氧化酶阴性、能还原硝酸盐为亚硝酸盐，据此可与弧菌科、非发酵菌鉴别。氧化酶阳性见于弧菌属和气单胞菌属；不发酵葡萄糖是非发酵菌如铜绿假单胞菌的特征"},{"q":"引起出血性结肠炎和溶血性尿毒综合征的病原菌是","o":["肠产毒型大肠埃希菌（ETEC）","肠致病型大肠埃希菌（EPEC）","肠出血型大肠埃希菌（EHEC）","肠侵袭型大肠埃希菌（EIEC）","肠聚集型大肠埃希菌（EAEC）"],"a":2,"e":"EHEC产生志贺毒素（Vero毒素），侵犯大肠引起出血性结肠炎，毒素入血损伤肾内皮细胞，导致溶血性尿毒综合征。ETEC产生LT、ST，引起旅行者水样腹泻；EPEC主要致婴儿腹泻；EIEC侵袭结肠上皮，呈痢疾样脓血便；EAEC引起持续性腹泻"},{"q":"O157∶H7血清型是属于下列哪个类型大肠埃希菌","o":["ETEC","EIEC","EPEC","EHEC","EAEC"],"a":3,"e":"O157∶H7属肠出血型大肠埃希菌，产生志贺毒素，引起血性腹泻与溶血性尿毒综合征。ETEC产不耐热与耐热肠毒素致水样腹泻，EIEC侵入结肠上皮，EPEC致婴儿腹泻，EAEC呈聚集性黏附"},{"q":"仅次于流感嗜血杆菌和肺炎链球菌，可引起上呼吸道感染的常见病原菌是","o":["卡他莫拉菌","幽门螺杆菌","嗜肺军团菌","百日咳鲍特菌","结核分枝杆菌"],"a":0,"e":"卡他莫拉菌是上呼吸道感染第3位常见病原菌，仅次于流感嗜血杆菌和肺炎链球菌，致病物质为内毒素。嗜肺军团菌引起军团菌肺炎，属下呼吸道感染；百日咳鲍特菌引起百日咳；幽门螺杆菌寄居胃黏膜，与胃炎、消化性溃疡相关"},{"q":"我国目前应用的乙型肝炎疫苗属于","o":["减毒活疫苗","灭活疫苗","亚单位疫苗","多价疫苗","基因重组疫苗"],"a":4,"e":"我国现用乙型肝炎疫苗为基因重组疫苗，由酵母菌或哺乳动物细胞表达重组HBsAg经纯化制成，是世界上首个基因工程疫苗，按0、1、6个月接种3次。血源疫苗已淘汰，多价疫苗与亚单位疫苗不是其分类名称"},{"q":"细菌的遗传物质包括","o":["核质和质粒","质粒和前噬菌体","核质、质粒和附加体","核质、附加体和前噬菌体","核质、质粒、前噬菌体和转位因子"],"a":4,"e":"细菌遗传物质包括核质即染色体、质粒、前噬菌体以及转位因子，共同构成细菌基因组。仅列核质和质粒不完整；附加体只是质粒的一种存在形式；前噬菌体亦只是温和噬菌体整合后的状态，均不能涵盖全部遗传物质"},{"q":"引起心内膜炎最常见的细菌是","o":["粪链球菌","甲型溶血性链球菌","肺炎链球菌","无乳链球菌","牛链球菌"],"a":1,"e":"甲型溶血性链球菌是亚急性感染性心内膜炎最常见的病原菌，尤其在有瓣膜病变者中，细菌黏附于受损心内膜形成赘生物。肺炎链球菌主要致肺炎、脑膜炎；无乳链球菌致新生儿败血症和脑膜炎；牛链球菌也可致心内膜炎但较少见"},{"q":"能产生溶原状态的噬菌体称为","o":["前噬菌体","毒性噬菌体","温和噬菌体","DNA噬菌体","溶原性噬菌体"],"a":2,"e":"温和噬菌体感染细菌后基因组可整合于宿主染色体成为前噬菌体，随细菌分裂传代而不裂解细菌，即形成溶原状态。毒性噬菌体只有溶菌性周期，增殖后裂解释放子代。前噬菌体指整合状态的噬菌体基因，是溶原状态的结果而非噬菌体名称。DNA噬菌体是按核酸类型划分，与能否形成溶原状态无关"},{"q":"根据感染来源，医院感染主要为","o":["外源性感染","内源性感染","环境感染","交叉感染","致病性微生物感染"],"a":1,"e":"按感染来源，医院感染分为内源性和外源性，我国以来自病人自身菌群的内源性感染为主，病原多为机会致病菌。外源性感染指来自医院环境或他人的病原体；交叉感染属外源性传播方式；环境感染只是外源性感染的一种来源"},{"q":"百白破三联疫苗的组成是","o":["百日咳死菌苗、白喉死菌苗、破伤风类毒素","百日咳死菌苗、白喉类毒素、破伤风类毒素","百日咳类毒素、白喉类毒素、破伤风类毒素","百日咳活菌苗、白喉活菌苗、破伤风死菌苗","百日咳活菌苗、白喉死菌苗、破伤风死菌苗"],"a":1,"e":"百白破三联疫苗由百日咳死菌苗（现用无细胞百日咳疫苗）、白喉类毒素和破伤风类毒素组成，全程接种可使婴儿同时获得三种疾病的免疫力。白喉、破伤风以类毒素免疫，百日咳不用类毒素，亦不用活菌苗"},{"q":"有关结核分枝杆菌的致病性，以下说法正确的是","o":["可经蚊虫叮咬传播","以肠结核最常见","原发感染多见于儿童","继发感染多见于儿童","结核分枝杆菌不能在巨噬细胞中存活"],"a":2,"e":"结核分枝杆菌原发感染多见于儿童，机体初次感染后形成原发综合征；继发感染多见于成年人，多为内源性复发。该菌经呼吸道传播，以肺结核最常见，且能在巨噬细胞内存活繁殖，故其余表述均不成立"},{"q":"EB病毒的主要靶细胞是","o":["中性粒细胞","B淋巴细胞","T淋巴细胞","巨噬细胞","NK细胞"],"a":1,"e":"EBV的靶细胞主要是B淋巴细胞，经唾液感染口咽上皮后侵入局部B细胞，使其转化为淋巴母细胞并潜伏。EBV不感染中性粒细胞、巨噬细胞和NK细胞；T淋巴细胞虽在感染后被激活增殖，但属反应性细胞而非病毒靶细胞"},{"q":"病毒所合成的晚期蛋白功能是","o":["抑制宿主细胞蛋白质的合成","合成包涵体的基质蛋白","构成病毒的衣壳蛋白","抑制宿主细胞核酸的合成","合成子代病毒核酸所需要的DNA多聚酶"],"a":2,"e":"病毒晚期蛋白在病毒DNA复制后合成，主要为衣壳蛋白、包膜糖蛋白等结构蛋白，用于装配子代病毒。早期蛋白才是功能蛋白，包括抑制宿主细胞核酸与蛋白质合成的蛋白、依赖DNA的DNA聚合酶等；包涵体基质蛋白不是晚期蛋白的通用功能表述"},{"q":"细菌的R质粒是","o":["与细菌的致病性有关的毒力因子","编码细菌的性菌毛","赋予细菌耐药性的可传递DNA","带有病毒基因的可传递DNA","细菌胞核中的可传递DNA"],"a":2,"e":"R质粒是接合性耐药质粒，携带耐药基因，可经性菌毛在种内甚至种间细菌间传递，使敏感菌获得耐药性。编码性菌毛是F质粒的功能；毒力因子由毒力质粒或染色体编码；细菌无成形细胞核，不存在胞核中的可传递DNA；病毒基因不构成R质粒"},{"q":"可在无生命培养基中生长繁殖的最小微生物是","o":["细菌","真菌","支原体","衣原体","病毒"],"a":2,"e":"支原体无细胞壁、基因组最小，是能在无生命培养基中生长繁殖的最小微生物，培养需含胆固醇的血清。细菌、真菌可在人工培养基生长但体积大；衣原体为严格细胞内寄生，需细胞培养；病毒无细胞结构，不能人工培养"},{"q":"β-棒状杆菌噬菌体感染了不产生白喉外毒素的白喉杆菌便可使其产生白喉外毒素，发生这种变异的原因是","o":["转化","接合","转导","溶原性转换","原生质融合"],"a":3,"e":"β-棒状杆菌噬菌体感染白喉棒状杆菌后，tox基因随前噬菌体整合于宿主染色体，使无毒株获得产毒能力，属溶原性转换。转导是噬菌体介导的DNA片段转移，不形成稳定溶原状态；转化是摄取游离DNA；接合经性菌毛传递质粒；原生质融合为人工诱导方法"},{"q":"朊粒的致病成分是","o":["DNA","RNA","DNA∶RNA异源二聚体","PrPsc","PrPc"],"a":3,"e":"朊粒的致病成分是PrPSc，其构象以β-折叠为主，不溶于去污剂，抗蛋白酶K，可聚合成淀粉样纤维破坏神经元。PrPc是细胞正常编码的糖蛋白，以α-螺旋为主，可溶且对蛋白酶敏感，无致病性与传染性。朊粒不含核酸，DNA、RNA及DNA∶RNA二聚体均非其致病成分"},{"q":"我国流行的主要布鲁氏菌菌种是","o":["羊布鲁氏菌","牛布鲁氏菌","猪布鲁氏菌","犬布鲁氏菌","森林鼠布鲁氏菌"],"a":0,"e":"我国流行的布鲁菌以羊布鲁菌为主，其次为牛布鲁菌，所致疾病称布鲁菌病，表现为波浪热、多汗、关节痛与肝脾大。羊布鲁菌致病力最强，感染后易转为慢性并反复发作；猪、犬布鲁菌感染少见。三者在含染料培养基中的生长情况与硫化氢产量可用于鉴别"},{"q":"细菌能使丙酮酸脱羧生成中性的乙酰甲基甲醇，可判断为","o":["VP试验阳性","吲哚试验阳性","甲基红试验阳性","硫化氢试验阳性","枸橼酸盐利用试验阳性"],"a":0,"e":"某些细菌使丙酮酸脱羧生成中性乙酰甲基甲醇，后者在碱性条件下被氧化为二乙酰，与含胍基化合物反应生成红色化合物，即VP试验阳性，典型者为产气肠杆菌。吲哚试验检测色氨酸分解产生的吲哚；甲基红试验检测产酸使pH降至4.5以下；硫化氢试验检测含硫氨基酸分解"},{"q":"下列分子生物学实验中，检测病毒蛋白的方法是","o":["原位杂交","点杂交","Southern blot","Western blot","Northern blot"],"a":3,"e":"Western印迹法先将病毒蛋白经SDS-PAGE按分子量分离、转膜，再用特异性抗体显色，直接检测病毒蛋白成分。原位杂交、点杂交、Southern印迹检测DNA，Northern印迹检测RNA，均属核酸检测，不能检出蛋白"},{"q":"关于PCR技术，下列叙述错误的是","o":["是一种DNA扩增技术","是一种有细胞的分子克隆技术","具有快速、灵敏和特异性强等特点","可用于病毒DNA片断的检测","也可用于细菌等微生物DNA片断的检测"],"a":1,"e":"PCR是在体外由DNA聚合酶催化、以引物引导的核酸扩增技术，不需活细胞，故有细胞的分子克隆技术一说不成立。该技术快速、灵敏、特异，可检测病毒、细菌等微生物的特异性DNA片段，RNA病毒需先逆转录"},{"q":"某些耐药菌株对青霉素产生耐药性多由于","o":["耐药菌株产生β-内酰胺酶","耐药菌株产生甲基化酶","直接阻止青霉素的作用","耐药菌株产生腺苷转移酶","耐药菌株产生乙酰转移酶"],"a":0,"e":"耐药菌产生β-内酰胺酶，水解青霉素的β-内酰胺环使其完全失去抗菌活性，是葡萄球菌等对青霉素耐药的主要机制。甲基化酶使16S rRNA甲基化，导致氨基糖苷类耐药；乙酰转移酶、腺苷转移酶钝化氨基糖苷类，均与青霉素耐药无关"},{"q":"疱疹病毒的共同特点不包括","o":["中等大小有包膜的病毒","核酸为双链DNA","衣壳呈二十面体立体对称","除EBV外均可在感染细胞核内形成包涵体","病毒感染的控制主要依赖体液免疫"],"a":4,"e":"疱疹病毒的控制主要依靠细胞免疫，CTL和NK细胞清除病毒，体液免疫作用有限，故主要依赖体液免疫之说错误。疱疹病毒为中等大小有包膜病毒，核酸为双链DNA，衣壳二十面体立体对称，除EBV外均可在感染细胞核内形成包涵体"},{"q":"一种病毒所产生的衣壳或包膜包在另一种病毒基因组外，这种变异称为","o":["基因重组","突变","互补作用","表型混合","交叉复活"],"a":3,"e":"两种病毒混合感染时，子代病毒可含另一方亲代的衣壳或包膜蛋白，而基因组未变，称为表型混合，仅表现抗原性与亲嗜性改变，不稳定、不可遗传。基因重组涉及核酸片段交换；互补作用是缺陷病毒借另一病毒的产物完成复制；交叉复活指灭活病毒间基因重组恢复活性"},{"q":"下列细菌中除哪一种外均能引起败血症","o":["链球菌","大肠杆菌","脑膜炎球菌","破伤风梭菌","肠炎沙门菌"],"a":3,"e":"破伤风梭菌芽胞仅在局部厌氧伤口发芽繁殖，产生痉挛毒素经血流或神经上行作用于中枢，细菌本身不入血，故不引起败血症。链球菌、大肠埃希菌、脑膜炎奈瑟菌与肠炎沙门菌均可侵入血流大量繁殖，引起败血症甚至脓毒血症"},{"q":"可用皮肤变态反应帮助诊断的是","o":["金黄色葡萄球菌感染","霍乱弧菌感染","志贺菌感染","淋病奈瑟菌感染","布鲁菌感染"],"a":4,"e":"布鲁菌感染可用布鲁菌素作皮肤试验，24～48小时观察局部红肿浸润，用于辅助诊断和流行病学调查。金黄色葡萄球菌、霍乱弧菌、志贺菌、淋病奈瑟菌感染均无成熟的皮肤变态反应诊断方法，主要靠培养和血清学检测"},{"q":"含有双链RNA基因组的病毒有","o":["轮状病毒","鼻病毒","腺病毒","流行性乙型脑炎病毒","狂犬病毒"],"a":0,"e":"轮状病毒属呼肠病毒科，基因组为双链RNA，分11个节段，是婴幼儿严重腹泻最常见的病原体。鼻病毒为单正链RNA，腺病毒为双链DNA，乙脑病毒与狂犬病毒均为单负链RNA。杯状病毒、星状病毒虽同致腹泻，核酸为单正链RNA"},{"q":"何种细菌与心肌及肾小球基底膜有共同抗原","o":["金黄色葡萄球菌","A群链球菌","14型肺炎链球菌","脑膜炎奈瑟菌","淋病奈瑟菌"],"a":1,"e":"A群链球菌的M蛋白与人心肌蛋白存在共同抗原，其抗体可交叉反应损伤心肌；菌体抗原与抗体形成的免疫复合物沉积于肾小球基底膜，引起急性肾小球肾炎。金黄色葡萄球菌、肺炎链球菌与奈瑟菌无此交叉抗原"},{"q":"对破伤风梭菌叙述正确的是","o":["通过伤口感染，细菌侵入血而致病","革兰阴性菌，具周鞭毛","不能形成芽孢","芽孢抵抗力强","致病物质主要是内毒素"],"a":3,"e":"破伤风梭菌芽胞对热、干燥、辐射和化学消毒剂抵抗力强，需高压蒸汽灭菌才能杀灭，为其重要生物学特性。该菌为革兰阳性杆菌、有周鞭毛，能形成芽胞；致病物质为痉挛毒素，属外毒素，细菌不入血而毒素入血致病"},{"q":"抗胞内菌感染的主要机制是","o":["补体","细胞免疫","体液免疫","屏障结构","NK细胞"],"a":1,"e":"胞内菌藏于巨噬细胞内，抗体不能进入细胞，故抗胞内菌感染主要依靠细胞免疫，由Th1细胞释放细胞因子激活巨噬细胞、CD8+CTL杀伤感染细胞。补体、体液免疫主要针对胞外菌；屏障结构属固有免疫；NK细胞作用有限"},{"q":"获得耐药性的产生原因不包括","o":["染色体突变","细菌种属特异性决定的耐药性","非接合性R质粒介导","接合性R质粒介导","转座因子介导"],"a":1,"e":"获得耐药性由细菌DNA改变引起，包括染色体突变、接合性或非接合性R质粒转移及转座子介导。种属特异性决定的耐药属固有耐药性，由染色体上天然耐药基因或缺乏药物靶位所致，可代代相传、能预测，不属于获得耐药性"},{"q":"下列接种BCG描述正确的是","o":["推荐在新生儿出生后多次接种巩固免疫效果","规定只在新生儿出生后接种一次","BCG属于灭活疫苗","主要通过诱导合成抗体产生免疫效应","通过结核分枝杆菌毒力变异制备而成"],"a":1,"e":"卡介苗是牛分枝杆菌减毒活疫苗，我国规定新生儿出生后接种一次，不再复种。该疫苗经毒力变异获得，接种后可在体内短暂增殖，主要诱导细胞免疫而非以抗体为主，属减毒活疫苗，故A、C、D、E均错"},{"q":"大多数病原菌的最适生长温度为","o":["25℃","30℃","37℃","40℃","42℃"],"a":2,"e":"绝大多数病原菌长期适应人体环境，最适生长温度为37℃，与人正常体温一致。25～30℃多为真菌和某些环境菌的最适温度，40℃以上仅少数嗜热菌，42℃用于培养空肠弯曲菌等特殊菌。温度过低或过高均使酶活性下降，生长受抑"},{"q":"对于腺病毒的描述错误的是","o":["感染后可获得牢固免疫力而避免再感染","血清型别多","基因组为双链DNA","无包膜，对脂溶剂不敏感","可侵犯人体多种组织和器官"],"a":0,"e":"腺病毒血清型多达50余个，型间无交叉免疫，感染后仅对同型产生免疫，可反复感染，故A项错误。该病毒为双链DNA、无包膜，对脂溶剂不敏感，可侵犯呼吸道、眼结膜、胃肠道和泌尿道等多种组织器官，B、C、D、E均正确"},{"q":"HAV的主要传播途径是","o":["输血","母婴垂直","飞沫传播","粪-口途径","媒介昆虫"],"a":3,"e":"HAV经粪-口途径传播，通过污染水源、食物、海产品及食具引起散发或暴发流行。输血、母婴垂直是HBV、HCV、HIV的主要途径；飞沫传播见于呼吸道病毒；媒介昆虫传播见于虫媒病毒，均非HAV的传播方式"},{"q":"下列病毒中不能通过神经系统向远处传播的是","o":["单纯疱疹病毒Ⅰ型","水痘带状疱疹病毒","狂犬病毒","乙型脑炎病毒","单纯疱疹病毒Ⅱ型"],"a":3,"e":"乙型脑炎病毒经蚊叮咬进入血流，形成病毒血症后突破血脑屏障侵犯中枢神经系统，其扩散依赖血液而非神经通路。HSV-1、HSV-2与VZV可沿感觉神经末梢逆行至神经节潜伏，复发时再沿神经下行；狂犬病病毒沿周围神经向心性移行至脑，均属神经传播"},{"q":"百日咳鲍特菌初次分离培养需用","o":["罗氏培养基","鲍-金培养基","活性炭-酵母浸出液琼脂培养基","血平板","巧克力平板"],"a":1,"e":"百日咳鲍特菌营养要求高、生长缓慢，初次分离需用含甘油、马铃薯和血液的鲍-金培养基。罗氏培养基用于结核分枝杆菌，活性炭-酵母浸出液琼脂用于布鲁菌，血平板与巧克力平板用于其他营养要求高的细菌"},{"q":"乙型脑炎病毒的中间宿主主要是","o":["病人及隐性感染者","蝙蝠","幼猪","蚊","灵长类动物"],"a":2,"e":"猪是乙脑病毒的主要传染源与中间宿主，幼猪感染后病毒血症期长、病毒滴度高，蚊吸血后带毒再叮咬人。蚊为传播媒介，人为终末宿主且病毒血症短暂，蝙蝠与灵长类非主要中间宿主，故对猪群免疫可降低人群发病率"},{"q":"下列选项中能用于描述灭活疫苗优于减毒活疫苗的一项是","o":["灭活疫苗诱发的免疫反应比减毒活疫苗更广泛","灭活疫苗接种比减毒活疫苗更接近病毒自然感染过程","灭活疫苗没有在易感者中传播的风险","因为可以诱生黏膜IgA，所以灭活疫苗在预防呼吸道感染病毒中比减毒活疫苗更有效","灭活疫苗不需要冷链运输和保存"],"a":2,"e":"灭活疫苗中病毒已失去复制能力，接种后不在体内增殖，也不会排毒传播给易感接触者，对免疫缺陷者更安全。减毒活疫苗免疫应答广、接近自然感染并诱生黏膜IgA，但可排毒并可能回复突变；两类疫苗均需冷链，灭活疫苗并不因此占优"},{"q":"能够抑制病毒逆转录酶活性的是","o":["阿昔洛韦（ACV）","丙氧鸟苷（GCV）","齐多夫定（AZT）","干扰素","金刚烷胺"],"a":2,"e":"齐多夫定是胸腺嘧啶核苷类似物，在细胞内磷酸化后竞争性抑制HIV逆转录酶，阻断前病毒DNA合成，对病毒逆转录酶的敏感性比细胞DNA聚合酶高100倍以上。阿昔洛韦、丙氧鸟苷抑制疱疹病毒DNA聚合酶；金刚烷胺阻断M2蛋白脱壳；干扰素通过诱导抗病毒蛋白发挥作用"},{"q":"用于估计病毒感染性强弱和毒力的实验方法是","o":["TCID50测定","蚀斑形成试验","ELISA","PCR","EIA"],"a":0,"e":"TCID50即50%组织细胞感染量，以感染50%细胞的最高稀释度计算，数值越小感染力越强，用于估计病毒的感染性与毒力。蚀斑形成试验用于计算有感染性的病毒颗粒数，ELISA与PCR分别检测抗原和核酸，不反映感染力"},{"q":"可阻断HSV感染易感细胞的因素是","o":["干扰素","NK细胞","CTL","单核细胞","抗gD抗体"],"a":4,"e":"gD是HSV包膜上免疫原性最强的中和抗原，抗gD抗体可封闭病毒与细胞受体的结合，阻断吸附和穿入。干扰素通过诱导抗病毒蛋白抑制复制，NK细胞和CTL杀伤已感染细胞，单核细胞起吞噬调理作用，均不能在吸附阶段阻断感染"},{"q":"伤寒沙门菌的鞭毛为","o":["单鞭毛","双鞭毛","周身鞭毛","单端丛生鞭毛","两端丛生鞭毛"],"a":2,"e":"伤寒沙门菌为革兰阴性杆菌，菌体四周有周身鞭毛，能运动，鞭毛抗原即H抗原，与O抗原共同用于血清学分型。单鞭毛见于霍乱弧菌；单端丛生或两端丛生鞭毛见于假单胞菌等，沙门菌不属此类。鞭毛需特殊染色或半固体培养基观察动力"},{"q":"预防立克次体病最重要的措施是","o":["注射疫苗","服用抗生素","控制和消灭传播媒介和储存宿主","灭蚊、灭蝇，防止蚊蝇叮咬","避免与患者接触"],"a":2,"e":"立克次体为严格胞内寄生，须经蜱、螨、虱、蚤等节肢动物媒介传播，媒介还可经卵传代成为储存宿主，故灭鼠、灭虱、防蜱螨叮咬，控制和消灭媒介与储存宿主最为重要。灭活疫苗免疫效果有限、使用面窄。多西环素等抗生素用于治疗，仅可短期预防给药。灭蚊、灭蝇针对乙脑、疟疾的媒介"},{"q":"有关霍乱弧菌叙述正确的是","o":["霍乱弧菌具有单鞭毛","霍乱弧菌具有周身鞭毛","霍乱弧菌具有嗜酸性","霍乱弧菌具有嗜盐性","霍乱弧菌是革兰染色阳性细菌"],"a":0,"e":"霍乱弧菌菌体一端有一根粗长的鞭毛，运动活泼，在液体中呈流星状穿梭运动，故为单鞭毛菌。周身鞭毛见于大肠埃希菌、变形杆菌等。霍乱弧菌耐碱不耐酸，无嗜盐性，嗜盐性见于副溶血性弧菌，革兰染色阴性"},{"q":"属于慢发病毒感染类型的疾病是","o":["慢性乙型肝炎","带状疱疹","登革热","牛海绵状脑病","埃博拉出血热"],"a":3,"e":"慢发病毒感染指潜伏期长达数年至数十年、一旦发病即进行性加重并必然致死的感染，牛海绵状脑病由朊粒引起，潜伏期4～5年，属此类。慢性乙型肝炎属慢性感染，病毒持续存在并可复制。带状疱疹是潜伏的水痘-带状疱疹病毒再激活。登革热与埃博拉出血热均为急性感染，病程短，无长潜伏期"},{"q":"可以作为mRNA翻译蛋白质的病毒核酸类型是","o":["dsDNA","dsRNA","ss（－）RNA","ss（＋）RNA","ss（＋）DNA"],"a":3,"e":"单正链RNA病毒的基因组结构与真核mRNA相似，本身即可作为mRNA直接翻译病毒蛋白，故具有感染性。双链DNA、双链RNA、单负链RNA均须先转录出mRNA；单正链DNA不是病毒基因组的常见类型"},{"q":"可用抗毒素进行紧急预防的疾病是","o":["斑疹伤寒","破伤风","百日咳","结核病","非典型肺炎"],"a":1,"e":"破伤风梭菌以外毒素致病，对伤口污染严重又未经基础免疫者，立即注射破伤风抗毒素可即刻中和游离毒素，起到紧急预防作用。斑疹伤寒、百日咳、结核病、非典型肺炎均以抗菌药物为主，无对应抗毒素可用"},{"q":"下列属于非细胞型微生物的是","o":["衣原体","立克次体","病毒","细菌","真菌"],"a":2,"e":"病毒无细胞结构，仅由核酸与蛋白质衣壳（有的尚有包膜）构成，基因组只含一种核酸，以复制方式增殖，属非细胞型微生物。衣原体、立克次体有细胞壁和核糖体，属原核细胞型；细菌为原核单细胞生物；真菌为真核细胞型微生物"},{"q":"目前能在体外培养的肝炎病毒是","o":["HAV","HBV","HCV","HDV","HEV"],"a":0,"e":"HAV于1979年由Provost等实现细胞培养，是目前唯一能常规体外培养的肝炎病毒，为疫苗研制奠定基础。HBV在体外细胞中难以常规培养，HCV、HDV、HEV亦均缺乏稳定的体外培养系统"},{"q":"病毒复制过程中，哪种机制是错误的","o":["以宿主细胞获得能量","只在活细胞内复制","不能在无生命培养基中培养","宿主细胞始终保持完整结构","利用宿主细胞的合成机制来合成"],"a":3,"e":"病毒为严格细胞内寄生，复制中抑制宿主细胞生物合成、改变细胞膜通透性，最终导致细胞病变、融合或死亡，故宿主细胞不能始终保持完整结构。病毒利用宿主能量与合成机制、只在活细胞内复制、不能在无生命培养基生长均正确"},{"q":"在结核病的诊断检查中，常采用浓缩集菌的方法提高标本的检出率，其中对痰液、支气管灌洗液及尿液等污染标本常需经下列哪种试剂预先处理","o":["3%盐酸酒精","95%乙醇","4%NaOH","70%乙醇","稀盐酸"],"a":2,"e":"结核分枝杆菌对酸、碱有较强抵抗力，痰液、支气管灌洗液、尿液等污染标本先用4%NaOH或3%HCl、6%H2SO4处理，杀灭杂菌并液化黏稠物，再离心集菌涂片。3%盐酸酒精用于抗酸染色脱色，乙醇用于消毒，不作标本前处理"},{"q":"朊病毒可引起的典型疾病是","o":["克罗伊茨费尔特-雅各布病","艾滋病","恙虫病","莱姆病","狂犬病"],"a":0,"e":"朊粒引起传染性海绵状脑病，人类典型疾病为克-雅病，表现为迅速进展的痴呆、肌阵挛，病理见脑组织海绵状改变。艾滋病由HIV引起，恙虫病由恙虫病东方体引起，莱姆病由伯氏疏螺旋体引起，狂犬病由狂犬病病毒引起"},{"q":"关于医院感染的描述不正确的是","o":["多为外源性感染","医院感染指患者或医务人员在医院环境内发生的感染","多由耐药菌引起","引起医院感染的微生物的种类常发生变迁","医院感染的预防和控制措施包括消毒灭菌、隔离预防、合理使用抗菌药物等"],"a":0,"e":"医院感染以内源性感染为主，病原体多为患者自身的条件致病菌，在免疫力下降、菌群失调或寄居部位改变时致病，故“多为外源性感染”错误。其余各项正确：发生在医院环境内，多由耐药菌引起，病原谱随抗生素使用而变迁，防控靠消毒灭菌、隔离与合理用药"},{"q":"G＋与G－细菌的细胞壁共同成分是","o":["五肽交联桥","外毒素","内毒素","肽聚糖","外膜"],"a":3,"e":"肽聚糖是革兰阳性菌与革兰阴性菌细胞壁的共同组分，前者含五肽交联桥，后者仅聚糖骨架与四肽侧链。磷壁酸为阳性菌特有，外膜与脂多糖即内毒素为阴性菌特有，五肽交联桥亦仅见于阳性菌。肽聚糖含量与结构的差异是革兰染色结果不同的物质基础"},{"q":"关于病毒隐性感染者免疫力的描述中不正确的是","o":["部分患者可获得免疫力而终止感染","非特异性免疫有助于病毒隐性感染终止","患者可成为无症状携带者","隐性病毒感染既可诱导体液免疫也可诱导细胞免疫反应","干扰素对隐性感染病毒无抑制作用"],"a":4,"e":"干扰素在感染早期即可抑制多数病毒增殖，是隐性感染得以终止的重要因素，称其无抑制作用错误。隐性感染同样可诱导体液与细胞免疫，部分人获免疫力清除病毒，也可成为无症状携带者，其血清抗体阳性是流行病学调查的重要线索"},{"q":"人类嗜T细胞病毒不含有的酶类是","o":["逆转录酶","胰蛋白酶","蛋白水解酶","DNA多聚酶","核酸内切酶"],"a":4,"e":"HTLV属逆转录病毒，病毒颗粒内含有逆转录酶、整合酶和蛋白酶（蛋白水解酶），逆转录酶兼具RNA依赖的DNA聚合酶和DNA依赖的DNA聚合酶活性。核酸内切酶不属其病毒体酶类，帽依赖核酸内切酶见于流感病毒"},{"q":"属于嗜肝DNA病毒科的病毒是","o":["甲型肝炎病毒","乙型肝炎病毒","丙型肝炎病毒","丁型肝炎病毒","戊型肝炎病毒"],"a":1,"e":"HBV属嗜肝DNA病毒科正嗜肝DNA病毒属，基因组为部分双链环状DNA（3.2kbp）。HAV属小RNA病毒科，HCV属黄病毒科，HDV属三角病毒科，三者均为RNA病毒；HEV属戊型肝炎病毒科，亦为单正链RNA病毒。故该科成员仅HBV"},{"q":"革兰阳性菌的生物学特点是","o":["细胞壁不含磷壁酸","肽聚糖层外有外膜包绕","等电点（pI）为2～3","因菌体微小，其相对表面积也小","菌体内渗透压为5～6个大气压"],"a":2,"e":"革兰阳性菌磷壁酸含量高，带较多负电荷，等电点为pH2～3，低于革兰阴性菌的pH4～5，故与结晶紫结合更牢固。其细胞壁含磷壁酸而无外膜；菌体微小则相对表面积大，代谢旺盛；菌体内渗透压高，可达20～25个大气压，并非5～6个"},{"q":"对于被狂犬咬伤的伤口处理方法，错误的是","o":["涂抹大量抗生素","用70%乙醇及碘酒涂擦伤口","立即用20%肥皂水清洗伤口","注射狂犬病疫苗","注射高效价抗狂犬病病毒血清"],"a":0,"e":"狂犬咬伤后应立即用大量清水和肥皂水冲洗伤口，再用75%乙醇或碘伏消毒，并接种疫苗、注射抗狂犬病免疫球蛋白。伤口不宜涂抹大量抗生素，也不宜缝合包扎，以免病毒滞留。抗生素仅用于继发细菌感染的防治"},{"q":"控制登革热暴发流行的最重要的有效措施是","o":["灭鼠","灭蚤","灭蚊","灭虱","防蜱叮咬"],"a":2,"e":"登革病毒经埃及伊蚊和白纹伊蚊传播，防蚊、灭蚊是控制暴发流行的最重要措施，目前无特效疫苗与药物。灭鼠针对鼠疫、肾综合征出血热；灭蚤针对地方性斑疹伤寒；灭虱针对流行性斑疹伤寒；防蜱针对森林脑炎和莱姆病"},{"q":"难以分离出HIV的艾滋病患者标本是","o":["精液","外周血","唾液","粪便","脑脊液"],"a":3,"e":"HIV存在于血液、精液、阴道分泌物、脑脊液、乳汁和唾液中，故可自外周血、精液、脑脊液分离病毒。粪便不含HIV，且含大量杂菌，病毒易失活，最难分离出病毒。唾液病毒滴度低，但仍存在检出可能"},{"q":"下列细菌不属于胞内菌的是","o":["结核分枝杆菌","霍乱弧菌","伤寒沙门菌","布鲁氏菌","肺炎军团菌"],"a":1,"e":"霍乱弧菌黏附于小肠黏膜表面繁殖，不侵入肠上皮细胞和肠腺，属胞外菌。结核分枝杆菌、伤寒沙门菌、布鲁氏菌和肺炎军团菌均能在巨噬细胞内生存繁殖，属胞内菌，其抗感染免疫以细胞免疫为主"},{"q":"副溶血性弧菌所致疾病是","o":["霍乱","食物中毒","肺炎","败血症","胃十二指肠溃疡"],"a":1,"e":"副溶血性弧菌存在于海水及鱼、贝类等海产品中，经污染食物引起食物中毒，是我国沿海地区细菌性食物中毒的首要病因。霍乱由霍乱弧菌引起，肺炎、败血症、胃十二指肠溃疡与幽门螺杆菌相关，均非本菌所致"},{"q":"多细胞真菌形成的菌落是","o":["酵母型菌落","类酵母型菌落","丝状型菌落","光滑型菌落","类似细菌菌落"],"a":2,"e":"多细胞真菌的菌丝体形成丝状型菌落，呈毛状、棉絮状或粉末状，并产生各种色素。酵母型菌落为单细胞真菌的菌落，类酵母型菌落镜下可见假菌丝，光滑型菌落是细菌的菌落特征，与真菌菌落不同。菌落表面可呈绒毛状、粉末状或颗粒状，并产生色素"},{"q":"能耐受酸、蛋白酶和胆汁的病毒为","o":["流感病毒","风疹病毒","脊髓灰质炎病毒","呼吸道合胞病毒","麻疹病毒"],"a":2,"e":"脊髓灰质炎病毒属肠道病毒，耐酸，在胃肠道中能耐受胃酸、蛋白酶和胆汁作用，故经粪-口途径传播。流感病毒、麻疹病毒、风疹病毒、呼吸道合胞病毒均对酸和脂溶剂敏感，经呼吸道传播，不能耐受胃肠道环境"},{"q":"关于VZV的生物学性状，错误的是","o":["无动物储存宿主","CPE出现缓慢","能形成嗜酸性包涵体","潜伏于骶神经节","皮肤损伤以水疱为特征"],"a":3,"e":"VZV潜伏于脊髓后根神经节与脑神经感觉神经节，骶神经节是HSV-2的潜伏部位。VZV无动物储存宿主，细胞病变出现缓慢，可形成嗜酸性核内包涵体，皮肤损害以水疱为特征。潜伏部位不同是鉴别两种疱疹病毒的重要依据之一"},{"q":"化脓性细菌侵入血流后，大量繁殖并扩散到其他器官组织，产生新的化脓性病灶，引起严重临床症状称为","o":["败血症","毒血症","内毒素血症","脓毒血症","菌血症"],"a":3,"e":"脓毒血症指化脓性细菌侵入血流并大量繁殖，经血流扩散至其他器官，形成新的化脓性病灶，如金葡菌引起多发性肝、肾、皮下脓肿。败血症是细菌入血繁殖但无迁移化脓灶，菌血症仅为短暂过血，毒血症是外毒素入血，内毒素血症为内毒素入血"},{"q":"将脊髓灰质炎病毒排出体外的主要排泄物是","o":["飞沫","鼻分泌物","眼分泌物","尿液","粪便"],"a":4,"e":"脊髓灰质炎病毒经粪-口途径传播，在咽部与肠道增殖，随粪便排出可持续数周，污染水源与食物造成传播。发病早期咽部也可排毒1～2周，但粪便排毒量大、时间长，是主要排出途径。尿液、眼分泌物与鼻分泌物不排出该病毒"},{"q":"给流行区的幼猪进行特异性疫苗接种可以降低人群发病率的疾病是","o":["森林脑炎","黄热病","乙型脑炎","登革热","肾综合征出血热"],"a":2,"e":"猪是乙脑病毒的主要传染源和中间宿主，病毒在猪群增殖后经蚊传播给人，对流行区幼猪接种疫苗可降低猪群带毒率，从而降低人群发病率。森林脑炎、黄热病、登革热、肾综合征出血热的传染源与猪无关，分别为蜱、蚊、鼠等"},{"q":"以下不属于狂犬病的临床表现的是","o":["恐水症","角弓反张","吞咽或饮水困难","循环衰竭","昏迷、呼吸衰竭"],"a":1,"e":"角弓反张是破伤风痉挛毒素引起的表现，不属狂犬病。狂犬病典型表现为恐水、吞咽与饮水困难、咽喉肌痉挛，继而肢体麻痹、昏迷，最终死于呼吸与循环衰竭，病死率几乎100%，暴露后须立即接种疫苗与免疫血清"},{"q":"有关质粒叙述不正确的是","o":["质粒是细菌染色体外的遗传物质","质粒是闭合环状的双链DNA","两种质粒不可存在于同一宿主菌内","具有自主复制的能力","可自行丢失或人工处理消除"],"a":2,"e":"结构不同的质粒可相容共存于同一菌细胞，只有结构相似、密切相关的质粒才表现不相容而不能稳定共存，故该项错误。质粒为染色体外闭合环状双链DNA，能自主复制，也可自行丢失或经吖啶橙等处理消除"},{"q":"可引起亚急性硬化性全脑炎（SSPE）的病原体是","o":["埃可病毒","轮状病毒","麻疹病毒","流感病毒","风疹病毒"],"a":2,"e":"麻疹病愈后5～15年，约百万分之一病人发生亚急性硬化性全脑炎，脑组织中麻疹病毒M基因变异致M蛋白合成障碍，形成缺陷病毒，不能正常装配释放，属慢发病毒感染。埃可病毒致无菌性脑膜炎与皮疹；轮状病毒致腹泻；流感病毒与风疹病毒不引起SSPE"},{"q":"引起牙周脓肿最常见的病原菌是","o":["甲型溶血性链球菌","类白喉杆菌","无芽孢厌氧菌","铜绿假单胞菌","白念珠菌（白假丝酵母菌）"],"a":0,"e":"甲型溶血性链球菌是口腔常住菌，为龋齿与牙周脓肿的常见病原菌，亦可致亚急性感染性心内膜炎。无芽孢厌氧菌多引起深部脓肿与败血症；铜绿假单胞菌多见于烧伤与医院感染；白念珠菌引起鹅口疮；类白喉杆菌多为黏膜正常菌群"},{"q":"产气荚膜梭菌可引起","o":["食物中毒","猩红热","烫伤样皮肤综合征","大叶性肺炎","肠热症"],"a":0,"e":"产气荚膜梭菌A型产生肠毒素，在芽胞形成时释放，作用于肠黏膜上皮引起食物中毒，表现为腹痛腹泻。猩红热由A群链球菌致热外毒素引起，烫伤样皮肤综合征由金葡菌表皮剥脱毒素引起，大叶性肺炎由肺炎链球菌引起，肠热症由伤寒沙门菌引起"},{"q":"下列病毒感染不能引起细胞转化的是","o":["HSV","CMV","HAV","HPV","EBV"],"a":2,"e":"HAV在肝细胞内增殖缓慢，不整合宿主基因组，不引起细胞转化，只造成免疫病理损伤。HSV、CMV、EBV、HPV均可整合或部分整合宿主DNA使细胞转化，其中HPV的E6、E7与宫颈癌相关，EBV与鼻咽癌相关"},{"q":"下列各项对病毒感染性疾病的描述中正确的是","o":["一种病毒引起一种疾病","很多病毒感染不能产生临床症状","可以根据病毒的形态预测所致疾病的类型","一种疾病由一种病毒引起","病毒感染的临床表现完全与其他病原体不同"],"a":1,"e":"病毒隐性感染常见，病毒未到达靶细胞或机体迅速产生免疫，可无任何临床症状，但仍获得免疫力，部分转为病毒携带者。一种病毒可引起多种疾病，一种疾病也可由多种病毒引起；病毒形态与疾病类型无对应关系；临床表现与细菌等感染常有重叠，不能据以区分"},{"q":"溶菌酶杀灭细菌的作用机理是","o":["裂解肽聚糖骨架的β-1,4糖苷键","竞争肽聚糖合成中所需的转肽酶","抑制核蛋白体的小亚基结合作用","竞争性抑制叶酸的合成代谢","破坏细胞膜的呼吸作用"],"a":0,"e":"溶菌酶水解肽聚糖中N-乙酰葡萄糖胺与N-乙酰胞壁酸之间的β-1,4糖苷键，破坏聚糖骨架，使细菌在低渗环境中裂解。青霉素与转肽酶结合、阻断四肽侧链交联，抑制的是肽聚糖合成而非水解。磺胺类竞争二氢蝶酸合成酶而抑制叶酸合成。氨基糖苷类作用于核糖体30S亚基"},{"q":"肥达试验可诊断下列哪种疾病","o":["斑疹伤寒","肠热症","风湿病","急性痢疾","波浪热"],"a":1,"e":"肥达试验用伤寒沙门菌O、H抗原及甲、乙、丙型副伤寒沙门菌H抗原与病人血清作凝集，测定抗体效价，辅助诊断肠热症。斑疹伤寒用外斐反应，风湿病用抗O试验，急性痢疾取粪便培养或镜检，波浪热用布鲁菌血清凝集试验"},{"q":"逆转录病毒增殖的突出特点","o":["需要RNA酶","需逆转录酶","病毒RNA复制时要通过DNA复制中间型","病毒核酸整合到细胞基因组中","以出芽方式释放到细胞外"],"a":1,"e":"逆转录病毒颗粒内含逆转录酶，复制时先以病毒RNA为模板合成双链DNA，再整合入细胞染色体形成前病毒，故需逆转录酶是其突出特点。整合是逆转录后的步骤；出芽释放为多数包膜病毒共有；RNA复制经DNA中间型只是该过程的表现"},{"q":"下列方法中不是病毒快速诊断方法的是","o":["检测标本中病毒形态、包涵体及CPE（电镜、免疫电镜及光镜）","病毒抗原检测（免疫荧光、酶联免疫及放射免疫等）","病毒抗体检测","病毒核酸检测","病毒分离培养"],"a":4,"e":"病毒分离培养需接种易感细胞、鸡胚或动物，培养数天至数周才能判定，不能快速出结果。电镜与免疫电镜观察形态和包涵体、免疫荧光或ELISA检测抗原、PCR检测核酸、检测特异性IgM抗体，均可在数小时内完成，属快速诊断"},{"q":"关于R质粒的描述，下列哪项是错误的","o":["R质粒是耐药性质粒","R质粒可通过接合方式传递","R质粒在肠道菌中更为常见","R质粒在呼吸道感染细菌中更为常见","R质粒由RIF和 r决定子组成"],"a":3,"e":"R质粒即接合性耐药质粒，由耐药传递因子和耐药决定子组成，经接合在菌株间传递，在革兰阴性肠道菌中分布最广、最突出。呼吸道感染病原以革兰阳性菌为主，R质粒远不如肠道菌常见，故该说法错误"},{"q":"机体对外毒素免疫作用是依靠抗毒素的","o":["杀灭作用","调理作用","吞噬作用","中和作用","清除作用"],"a":3,"e":"抗毒素是抗体，只能与游离外毒素结合，阻止其与靶细胞受体结合，发挥中和作用，对已结合的毒素无效。抗体不能直接杀灭细菌，调理与吞噬作用于菌体，清除作用表述笼统，均非抗毒素抗外毒素的机制"},{"q":"不属于细菌致病物质的组分是","o":["脂质A","肠毒素","荚膜多糖","核蛋白体","细菌分泌系统"],"a":3,"e":"细菌致病物质包括侵袭力与毒素：荚膜多糖抗吞噬，脂质A为内毒素毒性组分，肠毒素为外毒素，分泌系统参与毒素与效应蛋白的转运。核蛋白体是细菌蛋白质合成场所，属细胞结构而非致病物质，与致病性无关"},{"q":"百日咳鲍特菌Ⅰ相菌的共同抗原为","o":["凝集因子1","凝集因子2","凝集因子3","凝集因子4","凝集因子5"],"a":0,"e":"百日咳鲍特菌Ⅰ相菌为光滑型有毒株，各菌株均含凝集因子1，故其为共同抗原；凝集因子2、3等随菌株不同而分布有差异，用于血清型分型。Ⅰ相菌有荚膜、毒力强，经连续传代可变为无毒力的Ⅳ相菌"},{"q":"病毒的复制周期中，除哪项外均正确","o":["吸附","穿入","脱壳","二分裂","成熟和释放"],"a":3,"e":"病毒复制周期为吸附、穿入、脱壳、生物合成、装配成熟与释放五个步骤，不含二分裂。二分裂是细菌、立克次体、衣原体网状体等原核细胞的繁殖方式。其余四项均为病毒复制周期的正确环节。葡萄糖、半乳糖等糖类不与B亚单位结合"},{"q":"处于低渗环境中的L型细菌，可发生","o":["菌落中心凹陷","菌体变形","荚膜肿胀","鞭毛丢失","代时延长"],"a":1,"e":"L型细菌缺失细胞壁，仅存一层细胞膜，对渗透压敏感，处于低渗环境时水分内渗，菌体膨胀变形甚至裂解。其菌落呈“油煎蛋”样，中心致密、周边薄；荚膜肿胀为抗原抗体反应的表现；鞭毛丢失、代时延长均非低渗所致"},{"q":"新型隐球菌与白假丝酵母菌的主要区别在于后者","o":["以出芽方式繁殖","形成假菌丝","只能在37℃生长","菌体呈卵圆形","对抗生素不敏感"],"a":1,"e":"白念珠菌在组织内可形成芽生孢子与假菌丝，假菌丝是细胞延长后相互连接成藕节状的链，为与新型隐球菌鉴别的要点。两者均以出芽方式繁殖，菌体均呈卵圆形；新型隐球菌有肥厚荚膜，墨汁负染可见，且不形成假菌丝；培养温度与抗生素敏感性不构成鉴别依据"},{"q":"花斑癣，俗称汗斑，为浅表真菌病。引起该病的病原体主要是","o":["石膏样毛癣菌","犬小孢子菌","絮状表皮癣菌","甄氏外瓶霉","秕糠马拉色菌"],"a":4,"e":"花斑癣由秕糠马拉色菌引起，该菌寄居皮肤角质层，在高温潮湿、多汗时致病，表现为黄褐或灰白色斑片。石膏样毛癣菌、犬小孢子菌、絮状表皮癣菌引起体癣、头癣等皮肤癣菌病，甄氏外瓶霉引起暗色丝孢霉病"},{"q":"被称为卡波西（Kaposi）肉瘤相关疱疹病毒的是","o":["HSV-1","HSV-2","HHV-6","HHV-7","HHV-8"],"a":4,"e":"HHV-8由Yuan Chang等于1994年从艾滋病病人卡波西肉瘤活检组织中发现，故又称卡波西肉瘤相关疱疹病毒，还与原发性渗出性淋巴瘤、多中心Castleman病相关。HSV-1、HSV-2引起黏膜皮肤疱疹与脑炎，HHV-6、HHV-7与幼儿急疹相关"},{"q":"常用于检查血液和组织中的梅毒螺旋体的染色方法是","o":["抗酸染色法","镀银染色法","墨汁染色法","鞭毛染色法","革兰染色法"],"a":1,"e":"梅毒螺旋体革兰染色不易着色，常用Fontana镀银染色，菌体染成棕褐色，也可用暗视野显微镜直接观察悬滴标本中的螺旋体及其运动。抗酸染色用于分枝杆菌；墨汁负染用于观察新型隐球菌荚膜；鞭毛染色用于观察细菌鞭毛；革兰染色对螺旋体无鉴别价值"},{"q":"灭活病毒无效的因素是","o":["干扰素","乙醚","青霉素","乙醇","紫外线"],"a":2,"e":"青霉素抑制肽聚糖交联，作用于细菌细胞壁，病毒无细胞壁和肽聚糖，故对病毒无效。乙醚溶解包膜脂质，乙醇使蛋白变性，紫外线破坏核酸，干扰素诱导抗病毒蛋白，均可灭活或抑制病毒。灭活病毒以破坏核酸或包膜为目标，与抗菌机制不同"},{"q":"细菌耐药性产生的机制不包括","o":["钝化酶的产生","药物作用靶位的改变","细菌毒力改变","细菌对药物的主动外排","细菌细胞壁通透性的改变"],"a":2,"e":"细菌耐药机制包括产生钝化酶、药物作用靶位改变、细胞壁通透性降低、主动外排和形成生物膜，也可因代谢状态改变而耐药。毒力改变只影响致病性，与药物能否到达靶位并发挥作用无关，不属耐药机制"},{"q":"抗菌药物对细菌能够起作用的首位条件是","o":["抗菌药物与细菌接触","抗菌药物进入细菌细胞内","抗菌药物在细菌细胞内分解","细菌不携带耐药基因","细菌具有抗菌药物的靶点"],"a":4,"e":"抗菌药物通过药靶发挥作用，药靶是药物作用的特定靶位，细菌具备相应靶点是药物起效的前提，缺靶位即呈固有耐药。与细菌接触、进入菌体只是到达作用部位的过程；药物不在菌体内分解；是否携带耐药基因影响敏感性，而非起效前提"},{"q":"肠出血型大肠埃希菌（EHEC）主要血清型是","o":["O6","O25","O111","O157:H7","O158"],"a":3,"e":"EHEC即产志贺毒素大肠埃希菌，引起人类疾病的主要血清型为O157:H7，美国、日本流行株均为此型。O111:H11见于意大利，O26等其他O抗原型亦可致感染但非主要。该菌经污染食物传播，引起血性腹泻并可并发溶血性尿毒综合征"},{"q":"百日咳鲍特菌检测，标本采集主要是","o":["鼻腔洗液","含漱液","痰液","血液","尿液"],"a":0,"e":"百日咳鲍特菌定植于鼻咽部黏膜，检测取鼻咽拭子或鼻腔洗液，直接接种鲍-金培养基分离，现临床以PCR为首选。痰液来自下呼吸道，分离价值低；血液、尿液无意义。含漱液被唾液稀释并混杂口腔菌群，不作首选"},{"q":"抗结核治疗的原则是","o":["早期、联合用药","早期、规范、足量用药","早期、联合、规范用药","早期、联合、足量、规范、全程用药","联合、足量、规范、全程用药"],"a":3,"e":"抗结核化疗强调早期、联合、规律、全程，并保证足够剂量以维持有效血药浓度，故D项最完整。早期用药可杀灭繁殖旺盛菌，联合用药防止耐药，全程用药清除持留菌。B、C两项缺少全程，E项缺少早期，均难以防止复发和耐药"},{"q":"志贺菌感染防治原则不包括","o":["隔离病人","消毒排泄物","主要防御机制是肠黏膜表面的sIgA","容易出现多重耐药","应用灭活疫苗进行预防"],"a":4,"e":"志贺菌感染防治以隔离病人、消毒排泄物、切断粪-口传播为主，治疗须注意多重耐药问题，黏膜局部sIgA是主要防御机制。目前尚无成熟疫苗用于预防，以灭活疫苗预防之说与防治原则不符，故不列为其防治措施"},{"q":"测量病毒大小通常是用","o":["m","cm","mm","μm","nm"],"a":4,"e":"病毒大小测量单位为纳米，1nm等于1/1000μm，病毒体直径多在20～300nm，需电镜放大数千至数万倍才能观察。微米用于细菌与真菌，毫米、厘米、米用于更大生物，光学显微镜下仅痘病毒等大病毒可见"},{"q":"关于细菌磷壁酸，下列说法正确的是","o":["革兰阴性菌内毒素的化学成分","细菌外毒素主要的化学成分","细菌荚膜中主要的化学成分","革兰阳性菌细胞壁中的组成成分","革兰阴性菌细胞壁中的组成成分"],"a":3,"e":"磷壁酸是革兰阳性菌细胞壁的特有组分，约占细胞壁干重的50%，与黏附、抗吞噬及诱发炎症有关。内毒素是革兰阴性菌细胞壁的脂多糖；外毒素为细菌分泌的蛋白质；荚膜主要成分为多糖或多肽，均不含磷壁酸"},{"q":"克里米亚-刚果出血热病毒的传播媒介是","o":["蚊","蚤","虱","蜱","螨"],"a":3,"e":"克里米亚-刚果出血热病毒经硬蜱叮咬传播，蜱既是传播媒介又是储存宿主，发病具明显蜱活动季节性。蚊传播乙型脑炎与登革热，蚤传播鼠疫及斑疹伤寒立克次体，虱传播普氏立克次体，恙螨传播恙虫病东方体"},{"q":"关于在微生物学发展史上作出重要贡献的科学家及其所作出的贡献，下列哪项叙述是错误的","o":["巴斯德首次研制出狂犬疫苗","郭霍先后分离出炭疽杆菌、结核杆菌和霍乱弧菌","伊凡诺夫斯基发现烟草花叶病毒","琴纳分离出天花病毒","弗莱明发现青霉菌产物抑制金黄色葡萄球菌的生长"],"a":3,"e":"琴纳观察到挤奶女工感染牛痘后不患天花，遂用牛痘接种预防天花，并未分离出天花病毒。巴斯德研制出狂犬病疫苗；郭霍先后分离出炭疽芽胞杆菌、结核分枝杆菌与霍乱弧菌；伊凡诺夫斯基发现烟草花叶病的滤过性因子；弗莱明发现青霉菌产物抑制金黄色葡萄球菌"},{"q":"儿童患流行性腮腺炎时常见的并发症是","o":["睾丸炎或卵巢炎","肝炎","胃肠炎","肾炎","肺炎"],"a":0,"e":"腮腺炎病毒嗜腺体和神经组织，青春期及成人感染后易并发睾丸炎或卵巢炎，睾丸炎可致不育。肝炎、肾炎、肺炎、胃肠炎均非其常见并发症；病后可获牢固免疫，6个月内婴儿因母体抗体很少发病。腮腺肿大以耳垂为中心、边缘不清，腮腺管口红肿但无脓性分泌物"},{"q":"关于脑膜炎奈瑟菌的生物学性状，下列错误的是","o":["革兰阴性球菌","新分离菌株多具有荚膜","对寒冷抵抗力强","初分离时需要5%～10%CO2","常用巧克力血琼脂平板分离培养"],"a":2,"e":"脑膜炎奈瑟菌对理化因素抵抗力很弱，对干燥、热力、寒冷和消毒剂均敏感，标本需保暖保湿并及时接种。该菌为革兰阴性双球菌，新分离株有荚膜，初分离需5%～10%CO2，常用巧克力血琼脂平板"},{"q":"针对HSV的微生物学检查，下列标本不合适的是","o":["水疱液","唾液","角膜拭子","脑脊液","粪标本"],"a":4,"e":"HSV原发感染后潜伏于感觉神经节，复发时沿神经至皮肤黏膜形成水疱，故水疱液、唾液、角膜拭子及脑脊液均可检出病毒。粪标本不含HSV，粪便中排出的是肠道病毒，故不适合作为HSV检查标本"},{"q":"病毒的感染性核酸指的是","o":["双股DNA","单股RNA","单股DNA","去除衣壳的病毒核酸","去除包膜的病毒核酸"],"a":3,"e":"感染性核酸指去除衣壳（及包膜）后仍能进入细胞并直接作为mRNA翻译、产生子代病毒的核酸，如小RNA病毒、黄病毒的正链RNA。双股DNA、单股DNA、单股RNA本身不必然具感染性；仅去除包膜而保留衣壳者仍属核衣壳，并非游离核酸"},{"q":"破伤风是破伤风梭菌所致的","o":["菌血症","败血症","脓血症","毒血症","脓毒败血症"],"a":3,"e":"破伤风梭菌仅在伤口局部厌氧环境中繁殖，不入血，其外毒素即痉挛毒素入血并作用于中枢神经，引起全身肌肉强直痉挛，故属毒血症。菌血症指细菌入血但不繁殖；败血症为细菌入血大量繁殖并产生毒素；脓毒血症尚有迁徙性化脓灶"},{"q":"用DPT三联疫苗预防的是","o":["流感嗜血杆菌","百日咳鲍特菌","嗜肺军团菌","铜绿假单胞菌","炭疽芽孢杆菌"],"a":1,"e":"DPT三联疫苗由白喉类毒素、百日咳菌苗和破伤风类毒素组成，用于预防白喉、百日咳和破伤风，其中百日咳成分来自百日咳鲍特菌。流感嗜血杆菌用Hib荚膜多糖结合疫苗；军团菌、铜绿假单胞菌、炭疽芽孢杆菌均无DPT接种"},{"q":"原核细胞型微生物与真核细胞型微生物的根本区别是","o":["单细胞","二分裂方式繁殖","有细胞壁","前者仅有原始核结构，无核膜和核仁等","对抗生素敏感"],"a":3,"e":"原核细胞型微生物的细胞核分化程度低，仅为裸露DNA团块，无核膜、核仁，这是与真核细胞型微生物的根本区别。单细胞、二分裂繁殖、有细胞壁在真菌等真核微生物中同样存在；对抗生素敏感只是多数细菌的特点，不构成分类学根本界限"},{"q":"百日咳鲍特菌的传播主要通过","o":["飞沫","粪便","尿液","血液","眼结膜分泌物"],"a":0,"e":"百日咳鲍特菌经咳嗽、打喷嚏产生的飞沫传播，人类是唯一宿主，传染源为早期病人和带菌者，潜伏期约2周。粪便、尿液、血液和眼结膜分泌物均非其传播途径；该菌主要侵犯呼吸道纤毛上皮，在咽部增殖致病"},{"q":"不属于衣原体引起的疾病的是","o":["回归热","性病淋巴肉芽肿","沙眼","包涵体结膜炎","婴幼儿肺炎"],"a":0,"e":"回归热由回归热疏螺旋体引起，经虱或软蜱叮咬传播，属螺旋体病。沙眼、包涵体结膜炎、性病淋巴肉芽肿及婴幼儿肺炎均由衣原体所致：沙眼衣原体A～C型致沙眼，D～K型致包涵体结膜炎和婴儿肺炎，L型致性病淋巴肉芽肿。故回归热不属衣原体疾病"},{"q":"用于立克次体的染色方法是","o":["墨汁染色法","棉蓝染色法","抗酸染色法","革兰染色法","Giemsa染色法"],"a":4,"e":"立克次体革兰染色阴性但着色浅，需用Giemsa染色、Gimenez染色或Macchiavello染色观察，Giemsa染色呈紫色或蓝色。墨汁负染用于观察隐球菌荚膜，棉蓝染色用于真菌，抗酸染色用于分枝杆菌，革兰染色对立克次体不易着色"},{"q":"脊髓灰质炎患者多见的人群是","o":["儿童","老人","农民","青壮年","制革工人"],"a":0,"e":"脊髓灰质炎病毒经粪-口传播，主要侵犯脊髓前角运动神经元，引起急性弛缓性肢体麻痹，病人以儿童多见，故称小儿麻痹症。成人感染后病情往往更重，但发病率低；农民与制革工人是炭疽、布鲁氏菌病等职业相关感染的高发人群，与本病无关"},{"q":"可通过蚊子叮咬传播的病原体是","o":["麻疹病毒","水痘带状疱疹病毒","流行性乙型脑炎病毒","甲型肝炎病毒","脊髓灰质炎病毒"],"a":2,"e":"流行性乙型脑炎病毒经蚊叮咬传播，属虫媒病毒。麻疹病毒与水痘-带状疱疹病毒经呼吸道飞沫及接触传播，甲型肝炎病毒与脊髓灰质炎病毒经粪-口途径传播。登革病毒与寨卡病毒亦经伊蚊传播，属同一传播模式"},{"q":"编码HBsAg的基因是","o":["C基因","Pre-C基因","S基因","P基因","X基因"],"a":2,"e":"S基因编码HBsAg，与preS1、preS2共同构成表面蛋白。C基因编码HBcAg，pre-C与C基因共同编码HBeAg，P基因编码病毒聚合酶，X基因编码X蛋白。前S区与S基因突变可致HBsAg抗原性改变而出现诊断逃逸"},{"q":"有关副溶血性弧菌叙述错误的是","o":["革兰染色阴性细菌","有鞭毛","可引起食物中毒","嗜盐性","嗜酸性"],"a":4,"e":"副溶血性弧菌为革兰阴性杆菌，具单端鞭毛，嗜盐，在含3%～3.5%NaCl的培养基中生长良好，无盐则不生长，是沿海地区食物中毒的常见病原菌，主要污染海产品。其为嗜盐而非嗜酸，且不耐酸，故“嗜酸性”错误"},{"q":"细菌的染色体外遗传物质是指","o":["质粒","mRNA","性菌毛","异染颗粒","核蛋白体"],"a":0,"e":"质粒是细菌染色体外具有独立复制能力的遗传物质，多为闭合环状双链DNA，可携带耐药、毒力等基因。mRNA为转录产物，性菌毛为表面结构，异染颗粒为胞质内含物，核蛋白体为蛋白质合成场所，均在染色体基因控制下"},{"q":"具有黏附作用的革兰氏阳性菌组分是","o":["鞭毛","芽孢","荚膜","性菌毛","膜磷壁酸"],"a":4,"e":"革兰阳性菌的膜磷壁酸又称脂磷壁酸，一端连于细胞膜糖脂，另一端穿过肽聚糖伸出菌表，是重要黏附素，可与宿主细胞受体结合。壁磷壁酸主要维持细胞壁电荷与坚韧性，荚膜抗吞噬，鞭毛管运动，性菌毛参与接合传递质粒"},{"q":"下列对于产气荚膜梭菌的描述哪项是正确的","o":["肠道内正常菌群","血平板上可出现双溶血环","亚碲酸钾培养基中菌落变黑","产生β-内酰胺酶","卫星现象阳性"],"a":1,"e":"产气荚膜梭菌在血平板上形成双溶血环，内环为θ毒素所致完全溶血，外环为α毒素所致不完全溶血，是重要的鉴定特征。它不是肠道正常菌群，亚碲酸钾培养基上菌落变黑是白喉棒状杆菌，产生β-内酰胺酶是脆弱拟杆菌，卫星现象见于流感嗜血杆菌"},{"q":"均可通过粪-口途径传播的病毒是","o":["HAV、诺如病毒、轮状病毒","HEV、狂犬病病毒、prion","HCV、柯萨奇病毒、肠道腺病毒","HDV、星状病毒、风疹病毒","HBV、脊髓灰质炎病毒、埃可病毒"],"a":0,"e":"HAV、诺如病毒、轮状病毒均经粪-口途径传播，分别引起甲型肝炎和病毒性胃肠炎。HEV虽亦经粪-口传播，但狂犬病病毒经咬伤、朊粒经接触传播；HCV、HBV、HDV主要经血液传播；风疹病毒经呼吸道传播，故B、C、D、E组合均不成立"},{"q":"以下不属于外源性朊粒感染导致的疾病是","o":["库鲁病","家族性克-雅病","医源性克-雅病","牛海绵状脑病","羊瘙痒症"],"a":1,"e":"家族性克-雅病由PRNP基因突变使朊蛋白结构失稳变构而发病，属遗传性朊粒病，不是外源性感染。库鲁病经食人习俗传播，医源性克-雅病经污染的器械或移植物传播，牛海绵状脑病和羊瘙痒症分别由病牛、病羊朊粒传播，均属获得性即外源性感染"},{"q":"以下哪种不属于病毒非遗传性变异","o":["互补作用","核壳转移","加强作用","表型混合","基因重组"],"a":4,"e":"基因重组是两种病毒核酸片段互换，改变了基因组结构，可遗传，属遗传性变异。互补作用指两株病毒的基因产物相互补充，表型混合（核壳转移）只是衣壳与核酸错配，加强作用指一株病毒增强另一株复制，三者基因组均未改变"},{"q":"分离培养淋球菌时，下列方法不能采用的是","o":["标本要保湿保暖","标本要立即送检","标本要接种预温的巧克力血琼脂平板上","在厌氧环境中培养","在含5%～10% CO2的大气中培养"],"a":3,"e":"淋病奈瑟菌为专性需氧菌，初次分离须在5%～10%CO2环境、预温的巧克力血琼脂平板上生长，故不能置厌氧环境培养。标本须保湿保暖并立即送检，因其对干燥与低温极敏感。该菌氧化酶阳性、分解葡萄糖产酸不产气，可与其他奈瑟菌鉴别"},{"q":"最易形成慢发病毒感染的病毒是","o":["HIV","HBV","HAV","EBV","HPV"],"a":0,"e":"HIV感染后经数年甚至十余年缓慢进展，CD4+T细胞进行性减少，最终进入AIDS期，属慢发病毒感染；麻疹病毒引起亚急性硬化性全脑炎也属此类。HBV、EBV以潜伏感染和持续感染为特点，HAV只引起急性自限性肝炎，均不属慢发感染"},{"q":"伤寒沙门菌O抗原的成分为","o":["鞭毛抗原","菌毛蛋白","荚膜多糖","细胞壁脂多糖中特异性多糖部分","肽聚糖"],"a":3,"e":"O抗原即菌体抗原，位于革兰阴性菌细胞壁脂多糖的最外层，由特异性多糖的重复寡糖单位构成，决定种特异性，耐热，100℃不被破坏，是沙门菌分群的依据。鞭毛抗原为H抗原，菌毛蛋白与荚膜多糖分别为菌毛抗原和Vi抗原，肽聚糖不具抗原特异性"},{"q":"检测病毒抗体的三种方法是","o":["中和试验、补体结合试验、血凝抑制试验","中和试验、补体结合试验、血凝试验","酶联免疫吸附试验、PCR、血凝抑制试验","中和试验、血凝试验、免疫电泳技术","酶联免疫吸附试验、凝胶免疫扩散试验、PCR"],"a":0,"e":"检测病毒抗体常用中和试验、补体结合试验与血凝抑制试验，分别检测中和抗体、补体结合抗体与血凝抑制抗体。血凝试验检测的是病毒颗粒凝集红细胞的能力，PCR检测病毒核酸，均非抗体检测。三者针对不同抗原成分，敏感性各异"},{"q":"志贺菌在消化道黏膜表面主要的抗体类型是","o":["IgM","IgG","IgD","分泌型IgA","IgE"],"a":3,"e":"志贺菌经粪-口传播，侵入结肠黏膜，局部黏膜免疫以分泌型IgA为主，sIgA可阻止细菌黏附与侵袭。血清中可出现IgM、IgG，但黏膜表面起主要作用的是sIgA；IgD、IgE不参与抗菌黏膜免疫"},{"q":"不能中和病毒感染性的抗体是","o":["血凝抑制抗体","补体结合抗体","中和抗体","抗神经氨酸酶抗体","包膜病毒抗体"],"a":1,"e":"补体结合抗体由病毒内部抗原或表面非中和抗原诱生，不能中和病毒感染性，仅可用于血清学诊断。血凝抑制抗体、抗神经氨酸酶抗体与包膜糖蛋白抗体均针对病毒表面成分，能阻断吸附或释放，具中和作用"},{"q":"关于外毒素主要特性的描述不正确的是","o":["从活菌分泌出","只有革兰阳性菌能产生","抗原性强，甲醛液处理可形成类毒素","绝大多数外毒素不耐热","毒性作用强，对组织器官有选择性毒害作用"],"a":1,"e":"外毒素可由部分革兰阳性菌和部分革兰阴性菌产生，如痢疾志贺菌、霍乱弧菌、肠产毒素型大肠埃希菌、铜绿假单胞菌、鼠疫耶尔森菌均产生外毒素，故B项错误。外毒素由活菌分泌、毒性强且对组织有选择性、不耐热、抗原性强可经甲醛处理成类毒素，A、C、D、E均正确"},{"q":"伤寒沙门菌死亡崩解后释出内毒素使人","o":["体温升高，外周血白细胞升高","体温不变，外周血白细胞升高","体温不变，外周血白细胞下降","体温升高，外周血白细胞下降","体温升高，外周血白细胞不变"],"a":3,"e":"伤寒沙门菌死亡崩解后释放内毒素，作用于体温调节中枢引起发热，并使外周血白细胞降低（肠热症时白细胞减少或正常）。这与一般细菌感染白细胞升高相反，机制是内毒素促使白细胞黏附于血管壁并抑制骨髓释放"},{"q":"真菌的繁殖“器官”是","o":["芽孢","孢子","芽管","菌丝","菌丝体"],"a":1,"e":"孢子是真菌的繁殖器官，分无性孢子（芽生孢子、分生孢子、孢子囊孢子）与有性孢子（接合孢子、子囊孢子、担孢子）。芽孢是细菌的休眠体，不是真菌结构；芽管是孢子发芽形成的管状突起；菌丝与菌丝体是营养体，由菌丝构成，并非繁殖器官"},{"q":"具有包膜，但不具有包膜蛋白基因的病毒是","o":["HAV","HBV","HCV","HDV","HEV"],"a":3,"e":"HDV为缺陷病毒，有包膜，但包膜蛋白是HBV提供的HBsAg，其自身基因组仅编码HDAg，不含包膜蛋白基因。HBV的包膜蛋白由自身S基因编码；HCV的E1、E2亦由自身基因组编码；HAV与HEV均无包膜。故符合条件者为HDV"},{"q":"乙型脑炎病毒的传播媒介是","o":["蜱","蚊","白蛉","幼猪","鼠"],"a":1,"e":"乙型脑炎病毒以三带喙库蚊为主要传播媒介，蚊吸血后病毒在唾液腺增殖，叮咬猪等家畜和禽类造成扩增。蜱传播森林脑炎和克里米亚-刚果出血热，白蛉传播白蛉热，幼猪是扩增宿主而非媒介，鼠是汉坦病毒宿主"},{"q":"关于病毒，下列哪项说法是正确的","o":["病毒能侵害动植物","病毒可产生类毒素","病毒对抗生素敏感","病毒不具有免疫原性","抗病毒药物种类多，效果好，副作用小，价格低"],"a":0,"e":"病毒宿主范围广泛，可感染细菌、真菌、植物、动物和人，A项正确。类毒素由细菌外毒素经甲醛处理制成，病毒不产生外毒素，B项错；抗生素主要作用于细菌细胞壁、核糖体等靶点，对病毒无效，C项错；病毒感染可诱生抗体和细胞免疫，具免疫原性，D项错；抗病毒药物种类有限、副作用较大，E项错"},{"q":"常用墨汁负染色法进行形态学检查的病原体是","o":["钩端螺旋体","新型隐球菌","白假丝酵母菌","脑膜炎奈瑟菌","白喉棒状杆菌"],"a":1,"e":"新型隐球菌荚膜厚而折光，墨汁负染色后背景呈黑色，菌体周围有一圈不着色的荚膜，是经典的形态学检查法。白假丝酵母、脑膜炎奈瑟菌用革兰染色，钩端螺旋体用Fontana镀银染色或暗视野显微镜，白喉棒状杆菌用亚甲蓝或Albert染色"},{"q":"以下最易引起胎儿先天性畸形的病毒是","o":["EB病毒","人疱疹病毒7型","水痘带状疱疹","单纯疱疹病毒","人巨细胞病毒"],"a":4,"e":"人巨细胞病毒经胎盘垂直传播，抑制细胞有丝分裂，引起小头畸形、智力低下、耳聋及肝脾肿大，是最易致胎儿先天性畸形的病毒。HSV-2主要引起新生儿疱疹，VZV与HHV-7致畸少见，EBV致畸作用不明确"},{"q":"在正常胃酸条件下，需大量霍乱弧菌才能引起感染的原因是","o":["该菌不耐酸","胃内有乳酸杆菌等拮抗该菌","人体对其有较强的天然免疫力","该菌致病力弱","该菌繁殖能力弱"],"a":0,"e":"霍乱弧菌不耐酸，在正常胃酸中仅存活约4分钟，故需摄入10⁸个以上细菌方能通过胃屏障。胃内乳酸杆菌的拮抗和天然免疫力均非主要因素；该菌致病力强，霍乱毒素为已知最强的致泻毒素；在碱性蛋白胨水中代时仅8～12分钟，繁殖迅速，“繁殖能力弱”不成立"},{"q":"肉毒梭菌引起的食物中毒是以","o":["消化系统症状为主","呼吸系统症状为主","神经系统症状为主","泌尿系统症状为主","循环系统症状为主"],"a":2,"e":"肉毒毒素经血流作用于外周胆碱能神经末梢，阻断乙酰胆碱释放，表现为眼睑下垂、复视、吞咽及呼吸困难等，属典型神经中毒症状，胃肠症状轻微。金黄色葡萄球菌肠毒素刺激呕吐中枢，以呕吐、腹泻等消化系统症状为主；产气荚膜梭菌食物中毒以腹痛、水样腹泻为主，均不出现弛缓性麻痹"},{"q":"引起感染性心内膜炎最常见的致病菌","o":["甲型溶血性链球菌","肺炎链球菌","金黄色葡萄球菌","淋球菌","脑膜炎奈瑟菌"],"a":0,"e":"亚急性感染性心内膜炎多由甲型溶血性链球菌即草绿色链球菌群中的牛链球菌等引起，细菌黏附于受损心瓣膜形成赘生物。金黄色葡萄球菌引起急性心内膜炎；肺炎链球菌主要致大叶性肺炎；淋球菌与脑膜炎奈瑟菌分别致淋病和流行性脑脊髓膜炎"},{"q":"结核菌素实验结果强阳性则表明","o":["可能未感染过结核分枝杆菌","可能未接种过卡介苗","可能有活动性结核病","可能处于原发感染早期，超敏反应尚未产生","可能为恶性肿瘤患者"],"a":2,"e":"结核菌素试验强阳性，即硬结直径≥20mm或伴水疱坏死，提示体内有活动性结核病灶，应进一步检查。阴性可能未感染或处于原发感染早期、超敏反应尚未形成；阳性仅表示曾感染或接种过卡介苗；恶性肿瘤病人常呈阴性"},{"q":"HIV疫苗研究，目前遇到的最大问题是","o":["病毒型别多","无可用的动物模型","HIV的敏感细胞特殊","病毒突变引起抗原性改变","病毒不易培养"],"a":3,"e":"HIV的env基因最易突变，gp120表面抗原不断改变，使中和抗体难以持续有效，加之型别多、可整合潜伏，疫苗研制极为困难，其中抗原性改变是核心障碍。HIV可在PBMC及传代细胞中培养，并非无模型、不易培养"},{"q":"下列有关一些致病菌所致疾病与采集标本送检的部位描述错误的是","o":["伤寒患者应在病程1～2周内取粪便，一般2～3周时取血液","菌痢患者应取其沾有脓血或黏液的粪便","肺结核患者取其干酪样痰液","流行性脑膜炎患者可取其脑脊液、血液或出血淤斑","钩端螺旋体感染应在发病7～10天取外周血，2周后取尿液"],"a":0,"e":"肠热症病程第1～2周应取外周血，第2～3周取粪便和尿液，故该描述把采血与采便时间颠倒。菌痢取脓血黏液便，肺结核取干酪样痰，流脑取脑脊液、血液或淤斑，钩体病7～10天取血、2周后取尿，均符合各自病原体在体内的消长规律"},{"q":"HIV对以下理化因素具有较强抵抗力的是","o":["70%乙醇","漂白水","高压蒸汽灭菌","0.5%次氯酸钠","紫外线"],"a":4,"e":"HIV对紫外线有较强抵抗力，紫外线不能有效灭活；但其包膜含脂质，对70%乙醇、漂白粉、0.5%次氯酸钠等脂溶剂与消毒剂敏感，56℃30分钟或高压蒸汽121℃20分钟即可灭活。冷冻血制品需68℃加热72小时才能保证灭活病毒"},{"q":"用于治疗钩端螺旋体病的抗生素主要是","o":["金霉素","磺胺类","青霉素","链霉素","氯霉素"],"a":2,"e":"钩端螺旋体对青霉素高度敏感，青霉素是治疗钩体病的首选药物，中重度病例静脉给药，首剂后须警惕赫氏反应。磺胺类对钩端螺旋体无效，不能选用。链霉素主要用于鼠疫、布鲁菌病。氯霉素用于伤寒与立克次体病。轻症可口服多西环素、氨苄西林或阿莫西林"},{"q":"下列哪一个可以作为检测病毒滴度的方法","o":["空斑形成试验","电子显微镜","血凝试验","聚合酶链反应","酶联免疫试验"],"a":0,"e":"空斑形成试验将系列稀释病毒液接种单层细胞，一个空斑由一个感染性病毒颗粒增殖形成，计数空斑可推算活病毒量，以PFU/ml表示，是测定病毒滴度的经典方法。电镜观察形态，血凝试验半定量病毒颗粒，PCR测核酸，ELISA测抗原抗体"},{"q":"关于巴斯德菌属叙述错误的是","o":["可引起低等动物败血症","革兰阳性球杆菌","致病物质为荚膜和内毒素","可用青霉素G治疗","人感染可引起脑膜炎、脓肿等"],"a":1,"e":"巴斯德菌属为革兰阴性球杆菌，常两极浓染，有荚膜、无鞭毛；多杀巴斯德菌经猫狗咬伤传播，引起伤口感染、脓肿、脑膜炎等，治疗首选青霉素G。故“革兰阳性球杆菌”错误，其余各项描述正确。鼠疫耶尔森菌亦为革兰阴性球杆菌，但两极浓染更明显"},{"q":"以下虫媒病毒中，感染后可引起发热、白细胞减少、血小板减少和多器官功能损害的是","o":["黄热病病毒","发热伴血小板减少综合征病毒","登革病毒","西尼罗病毒","寨卡病毒"],"a":1,"e":"大别班达病毒旧称发热伴血小板减少综合征病毒，经蜱传播，引起发热伴血小板减少综合征，表现为发热、白细胞与血小板减少及多器官功能损害。登革病毒以发热、皮疹、出血为主，黄热病有黄疸，寨卡病毒致皮疹与胎儿畸形"},{"q":"对星状病毒致病性的描述，错误的是","o":["能引起哺乳动物和禽类的急性胃肠炎","引起的疾病一般持续1～2周","侵犯十二指肠黏膜细胞","临床表现类似于轮状病毒胃肠炎","主要引起婴幼儿腹泻"],"a":1,"e":"星状病毒引起婴幼儿及老年人腹泻，临床表现类似轮状病毒胃肠炎，但症状较轻，病程短，一般仅2～5天，故持续1～2周的描述错误。该病毒侵犯十二指肠黏膜细胞，可感染哺乳动物和禽类，引起急性胃肠炎"},{"q":"下列哪种毒素分解细胞膜卵磷脂","o":["产气荚膜梭菌α毒素","产气荚膜梭菌β毒素","破伤风痉挛毒素","破伤风溶血素","肉毒毒素"],"a":0,"e":"产气荚膜梭菌α毒素即磷脂酶C，分解宿主细胞膜卵磷脂，破坏膜完整性致细胞坏死，因卵磷脂普遍存在故作用无选择性。β毒素为成孔毒素，在细胞膜上形成孔道。破伤风痉挛毒素属神经毒素，阻止抑制性神经递质释放而引起痉挛。肉毒毒素作用于神经肌肉接头，抑制乙酰胆碱释放致弛缓性麻痹"},{"q":"我国规定的水、食品等卫生细菌学检查的指标菌是","o":["沙门菌","大肠埃希菌","志贺菌","克雷伯菌","变形杆菌"],"a":1,"e":"大肠埃希菌主要来源于人与温血动物粪便，在环境中存活时间与肠道致病菌相近，检测方便，故作为饮水、食品被粪便污染的指标菌，我国规定100mL饮用水中不得检出总大肠菌群和大肠埃希菌。沙门菌、志贺菌为致病菌，检出即须处理；克雷伯菌与变形杆菌不作指标菌"},{"q":"卡介苗是结核分枝杆菌的下列哪种变异所致","o":["耐药性变异","形态结构变异","菌落变异","毒力变异","基因变异"],"a":3,"e":"卡介苗是牛结核分枝杆菌在含蛋黄、胆汁、甘油、马铃薯的培养基上连续传230代、历时13年获得的减毒株，属毒力变异，保留免疫原性而失去致病力。耐药性变异、形态结构变异、菌落变异均不产生疫苗，基因变异过于笼统"},{"q":"下列药物对病毒感染治疗无效的是","o":["阿昔洛韦","拉米夫定","齐多夫定（AZT）","蛋白酶抑制剂","两性霉素"],"a":4,"e":"两性霉素B与真菌细胞膜的麦角甾醇结合，形成孔道致真菌死亡，是抗真菌药，对病毒无作用。阿昔洛韦抑制疱疹病毒DNA聚合酶，拉米夫定、齐多夫定抑制逆转录酶，蛋白酶抑制剂阻断HIV前体蛋白切割，均用于抗病毒治疗"},{"q":"最常见的深部感染真菌病是","o":["念珠菌病","隐球菌病","曲霉病","毛霉病","PCP"],"a":0,"e":"念珠菌病是白念珠菌引起的皮肤、黏膜及内脏感染，为最常见的深部真菌病，多见于免疫功能低下者。隐球菌病多引起脑膜炎，曲霉病以肺曲霉病为主，毛霉病见于重症糖尿病与免疫抑制者，肺孢子菌肺炎见于艾滋病病人，发病率均低于念珠菌病"},{"q":"肠道病毒的共同特性不包括","o":["为无包膜的小RNA病毒","基因组为单正链RNA","耐酸、耐乙醚","寄生于肠道，主要引起胃肠炎","可侵犯肠道外组织，临床症状多样化"],"a":3,"e":"肠道病毒经消化道传播并在肠道初步增殖，但主要引起肠道外感染，如脊髓灰质炎、无菌性脑膜炎、心肌炎、疱疹性咽峡炎，胃肠炎并非其致病特点，急性胃肠炎主要由轮状病毒、诺如病毒引起。肠道病毒为无包膜的小RNA病毒，基因组为单正链RNA，耐酸、耐乙醚，这些均属其共同特性"},{"q":"目前尚未广泛用于预防病毒感染性疾病的疫苗是","o":["类毒素","减毒活疫苗","灭活疫苗","核酸疫苗","基因工程疫苗"],"a":3,"e":"类毒素是用甲醛处理外毒素使其脱毒并保留抗原性制成的生物制品，针对的是细菌外毒素病（破伤风、白喉），病毒不产生外毒素，故不用于病毒性疾病的预防。减毒活疫苗、灭活疫苗与基因工程疫苗均已广泛使用；核酸疫苗中的mRNA疫苗已获批用于新冠预防"},{"q":"下列哪种细菌有鞭毛结构","o":["志贺菌","葡萄球菌","链球菌","变形杆菌","结核分枝杆菌"],"a":3,"e":"变形杆菌为革兰阴性杆菌，具周鞭毛，运动活泼，在固体培养基上呈迁徙性生长，可作初步鉴定依据。志贺菌无鞭毛无动力，葡萄球菌、链球菌为革兰阳性球菌无鞭毛，结核分枝杆菌亦无鞭毛。鞭毛的数量与位置也是分类依据，如单毛菌与周毛菌"},{"q":"培养支原体最必需的成分是","o":["蛋白质","胆固醇","葡萄糖","磷脂","维生素B1"],"a":1,"e":"支原体无细胞壁，细胞膜含胆固醇，多数种类需胆固醇维持膜结构与稳定，培养基中须加血清提供胆固醇与脂肪酸，故胆固醇为最必需成分。蛋白质、葡萄糖、磷脂与维生素可支持生长但非特有需求；皂素、两性霉素B作用于胆固醇即可杀灭支原体"},{"q":"淋病奈瑟菌的主要传播途径是","o":["伤口传播","消化道传播","性接触传播","呼吸道传播","节肢动物叮咬"],"a":2,"e":"淋病奈瑟菌主要经性接触直接传播，引起泌尿生殖道化脓性炎症；新生儿可经产道感染致淋菌性眼炎。消化道、呼吸道不是其传播途径，节肢动物叮咬与伤口传播亦无关，该菌在外界抵抗力弱，间接接触传播少见"},{"q":"关于恙虫病东方体的叙述下面哪项是错误的","o":["细胞壁不含肽聚糖、脂多糖和微荚膜样黏液层","与普通变形杆菌OXk株有共同的多糖抗原","在感染细胞内密集分布于细胞质内靠近细胞核","恙螨是主要的寄生宿主、储存宿主和传播媒介","主要在单核细胞内繁殖，以出芽方式释放"],"a":4,"e":"恙虫病东方体主要在小血管内皮细胞内繁殖，以出芽方式释放且一般不破坏细胞，故在单核细胞内繁殖之说错误。该菌细胞壁无肽聚糖与脂多糖，与变形杆菌OXk株有共同多糖抗原可做外斐试验，恙螨为储存宿主与媒介"},{"q":"关于革兰阳性菌错误的叙述是","o":["细胞壁主要成分为肽聚糖","细胞壁主要成分为脂多糖","与结晶紫牢固结合","不能形成内毒素","对青霉素敏感"],"a":1,"e":"革兰阳性菌细胞壁由厚层肽聚糖（可达50层）和磷壁酸构成，脂多糖是革兰阴性菌外膜的成分，故该项错误。革兰阳性菌等电点低（pH2～3），与结晶紫结合牢固，乙醇脱色不易褪去而染成紫色；无外膜即无内毒素；肽聚糖含量高，对青霉素敏感"},{"q":"人乳头瘤病毒的基因组是","o":["两条单股负链RNA","双股环状DNA","单股负链分节段的RNA","单股负链不分节段的RNA","双股环状RNA"],"a":1,"e":"人乳头瘤病毒属乳头瘤病毒科，无包膜，衣壳呈二十面体立体对称，基因组为双股环状DNA，约8kb，含早期区、晚期区和长控制区。分节段单负链RNA是流感病毒；不分节段单负链RNA是副黏病毒；双股环状RNA不符合已知病毒基因组类型"},{"q":"内基小体具有诊断意义的疾病是","o":["狂犬病","乙型脑炎","鼠疫","登革热","出血热"],"a":0,"e":"内基小体是狂犬病病毒在神经细胞胞质内形成的嗜酸性包涵体，多见于海马回锥体细胞，检出即可诊断狂犬病。乙型脑炎病毒不形成内基小体，鼠疫为细菌感染，登革热与出血热亦无此包涵体。该包涵体需取脑组织检查，生前诊断价值有限"},{"q":"狂犬病病毒具有高度亲和力的细胞是","o":["淋巴结","神经细胞","巨噬细胞","皮肤黏膜","肾上腺"],"a":1,"e":"狂犬病病毒对神经组织有高度亲和力，经神经肌肉接头进入外周神经，沿轴索向心性移行至中枢神经系统，在神经细胞内增殖并形成内基小体。该病毒不入血形成明显病毒血症，淋巴结、巨噬细胞、皮肤黏膜和肾上腺均非其主要靶细胞"},{"q":"对人类致病性最强的葡萄球菌是","o":["金黄色葡萄球菌","腐生性葡萄球菌","表皮葡萄球菌","凝固酶阴性葡萄球菌","人葡萄球菌"],"a":0,"e":"金黄色葡萄球菌是葡萄球菌属中毒力最强者，致病物质分表面结构、毒素与酶三类，具荚膜、SPA、凝固酶及多种外毒素，可引起化脓性感染与中毒性疾病。表皮、腐生、人葡萄球菌等凝固酶阴性菌毒力弱，多为机会致病菌"},{"q":"决定病毒体感染细胞的关键物质是","o":["衣壳","包膜","核酸","刺突","核蛋白"],"a":2,"e":"病毒核酸携带全部遗传信息，决定子代病毒的形态结构、致病性、抗原性与增殖特性，是病毒感染的物质基础，提取的核酸亦具感染性。衣壳保护核酸并决定对称结构，包膜与刺突中的吸附蛋白介导与受体结合，核蛋白为核衣壳组分，均不能独立决定感染"},{"q":"病毒和衣原体的不同点是","o":["传染性颗粒的可滤过性","严格的细胞内寄生性","在感染细胞内可形成包涵体","对抗生素的敏感性","对紫外线的敏感性"],"a":3,"e":"衣原体有细胞壁、核糖体和多种酶，对抗生素敏感；病毒无细胞结构，对抗生素不敏感。两者均严格细胞内寄生，均可滤过，均可在感染细胞内形成包涵体，对紫外线也均敏感，故这些不能作为鉴别点。衣原体有独特发育周期，可见原体和始体"},{"q":"对外毒素特性叙述不正确的是","o":["由细菌合成分泌","主要成分是脂多糖","毒性强","抗原性强","性质不稳定"],"a":1,"e":"外毒素是细菌合成并分泌的毒性蛋白质，毒性强、抗原性强，不耐热，性质不稳定，经甲醛处理可脱毒制成类毒素。脂多糖是内毒素的化学本质，存在于革兰阴性菌细胞壁，菌体裂解后才释放。外毒素主要由革兰阳性菌及部分革兰阴性菌产生"},{"q":"HCMV是导致艾滋病患者最常见的机会感染病原体之一。其最常引起的是","o":["视网膜炎","肝炎","脑炎","肺炎","肾炎"],"a":0,"e":"HCMV在艾滋病病人中主要引起视网膜炎，是CD4⁺T细胞严重低下时的标志性机会感染，可致视力下降甚至失明。肺炎多由卡氏肺孢子菌等引起；脑炎常见病原为弓形虫、HSV及JC病毒。肝炎、肾炎不是其典型表现"},{"q":"下列物质中不能诱生干扰素的是","o":["病毒","人工合成双链RNA","衣原体","细菌脂多糖","头孢菌素"],"a":4,"e":"干扰素诱生剂包括病毒、人工合成双链RNA如polyI:C、衣原体、细菌脂多糖等，均可诱导细胞产生干扰素。头孢菌素属β-内酰胺类抗生素，作用是抑制细菌细胞壁合成，无诱生干扰素的能力"},{"q":"引起猩红热感染最可能的细菌是","o":["A群链球菌","表皮葡萄球菌","金黄色葡萄球菌","肺炎链球菌","甲型溶血性链球菌"],"a":0,"e":"猩红热由A群β溶血性链球菌产生致热外毒素引起，表现为发热、咽峡炎和全身弥漫性红斑。表皮葡萄球菌、金黄色葡萄球菌引起化脓性感染或食物中毒；肺炎链球菌致肺炎；甲型溶血性链球菌致龋齿和心内膜炎，均不引起猩红热"},{"q":"有正常微生物群存在的部位是","o":["胃、肠道、腹腔","鼻咽腔、眼结膜、脑脊液","胆囊、肝脏、十二指肠","尿道、口腔、外耳道","皮肤、黏膜、淋巴液"],"a":3,"e":"正常微生物群寄居在与外界相通的体表和腔道，如皮肤、口腔、鼻咽腔、肠道、尿道、外耳道和阴道。腹腔、脑脊液、胆囊、肝脏、淋巴液及血液属无菌部位，正常时不应检出细菌，一旦出现提示感染。故仅D项所列部位均有正常菌群"},{"q":"细菌仅仅是一时性或间断性侵入血流，但未在血中繁殖，称为","o":["菌血症","毒血症","败血症","脓毒血症","病毒血症"],"a":0,"e":"菌血症指致病菌由局部短暂或间断侵入血流但不在血中繁殖，如伤寒早期。毒血症为细菌在局部繁殖、仅外毒素入血；败血症为细菌入血大量繁殖并产生毒性产物；脓毒血症尚有化脓性病灶；内毒素血症为革兰阴性菌释放内毒素入血"},{"q":"关于EBV感染的描述，错误的是","o":["人群感染普遍","儿童初次感染多无明显症状","主要经呼吸道传播","可引起多种疾病","与肿瘤发生相关"],"a":2,"e":"EBV主要经唾液传播，通过密切接触如接吻传播，故又称接吻病，亦可经输血传播。人群中感染普遍，儿童原发感染多无明显症状，可致传染性单核细胞增多症、Burkitt淋巴瘤、鼻咽癌。呼吸道飞沫非其主要途径"},{"q":"口服脊髓灰质炎糖丸疫苗后，机体可产生","o":["血清IgG，IgM","血清IgG，肠黏膜局部sIgA","血清IgG，咽部黏膜局部sIgA","血清IgA，IgG","肠黏膜局部sIgA"],"a":1,"e":"口服脊髓灰质炎减毒活疫苗类似自然感染，病毒在肠道增殖，刺激肠道黏膜产生sIgA，同时诱生血清中和抗体IgG、IgM，既阻止病毒在肠道增殖，又防止其侵入中枢神经系统。仅局部sIgA或仅血清抗体均不全面，IgM非主要保护抗体"},{"q":"发酵乳糖的肠道杆菌是","o":["非致病大肠埃希菌","痢疾志贺菌","伤寒沙门菌","肖氏沙门菌","甲型副伤寒沙门菌"],"a":0,"e":"大肠埃希菌能发酵乳糖产酸产气，非致病性大肠埃希菌为肠道正常菌群，故发酵乳糖。痢疾志贺菌、伤寒沙门菌与甲型副伤寒沙门菌均不发酵乳糖；宋内志贺菌仅迟缓发酵，故乳糖发酵须观察24小时以上"},{"q":"巨细胞病毒常引起","o":["唇疱疹","带状疱疹","病毒性脑炎","先天性畸形","传染性单核细胞增多症"],"a":3,"e":"HCMV是引起先天性畸形最常见的病原体之一，妊娠早期经胎盘感染胎儿，可致小头畸形、智力低下与先天性耳聋。唇疱疹由HSV-1引起；带状疱疹由VZV再激活引起；病毒性脑炎以乙脑与HSV脑炎多见；传染性单核细胞增多症由EBV引起"},{"q":"动物试验常用于检测细菌的","o":["质粒","型别","毒力","基因变异","能量代谢"],"a":2,"e":"动物实验主要用于测定细菌毒力、制备免疫血清、建立感染模型及评价药物与疫苗，如用豚鼠或地鼠测定结核分枝杆菌毒力。质粒检测靠核酸电泳；型别鉴定用血清学与分子方法；基因变异靠测序；能量代谢靠生化反应，均不以动物试验为主要手段"},{"q":"禁忌接种风疹减毒活疫苗的人群是","o":["育龄期女青年","婚前女青年（未孕）","注射过抗风疹人血清免疫球蛋白的非孕妇","妊娠期妇女","1岁以上儿童、少年"],"a":3,"e":"风疹减毒活疫苗可通过胎盘感染胎儿，妊娠期妇女禁用，育龄期女青年接种后应避孕3个月。免疫缺陷者与使用免疫抑制剂者亦属禁忌；婚前未孕女青年、1岁以上儿童均可接种，接种后2～3周产生抗体，保护期可达10年以上"},{"q":"金刚烷胺抗病毒作用主要机制","o":["抑制病毒蛋白质合成","抑制病毒脱衣壳","促进感染细胞溶酶体释放","干扰病毒核酸的合成","抑制病毒组装、成熟和释放"],"a":1,"e":"金刚烷胺为M2蛋白抑制剂，阻断M2离子通道的质子转运，使病毒不能完成脱壳，从而抑制甲型流感病毒早期复制。该药不抑制病毒核酸合成、蛋白质翻译或装配释放；促进溶酶体释放、干扰核酸合成均非其作用机制"},{"q":"与细菌致病性相关的结构是","o":["异染颗粒","细胞膜","中介体","芽孢","菌毛"],"a":4,"e":"菌毛是细菌的黏附结构，能与宿主细胞表面糖蛋白或糖脂受体结合，是感染的第一步，与致病性直接相关。芽胞与抵抗力及外源性感染来源有关，中介体与呼吸和分裂有关，异染颗粒是鉴定依据，细胞膜参与物质转运"},{"q":"细菌核酸检测的常用方法不包括","o":["PCR","基因芯片","16S rRNA基因序列分析","ELISA","核酸杂交"],"a":3,"e":"细菌核酸检测针对特异基因序列，包括PCR、基因芯片、16S rRNA基因序列分析和核酸杂交。ELISA属免疫学方法，以抗原抗体反应检测细菌抗原或血清抗体，不检测核酸，是本题要排除的方法"},{"q":"对于大批量朊粒病样品的筛查，最适用的微生物学检查方法是","o":["PrPsc的ELISA检测","PMCA法","PrPsc的免疫印迹杂交","生物标记物14-3-3蛋白的免疫印迹杂交","PrPsc的免疫组化检测"],"a":0,"e":"PrPSc的ELISA检测可批量操作、快速出结果，适用于大批量样品的初步筛查。PMCA与RT-QuIC敏感性最高，但技术要求高、成本大，用于微量标本的确诊；免疫印迹和免疫组化通量低，14-3-3蛋白为脑脊液非特异性标志物"},{"q":"肝炎病毒的传播途径不包括","o":["消化道传播","血液或血制品传播","接触传播","呼吸道传播","母婴垂直传播"],"a":3,"e":"肝炎病毒经粪-口途径（HAV、HEV）、血液与血制品（HBV、HCV、HDV）、性接触及母婴垂直传播，均不经常规呼吸道传播，故呼吸道传播不属其途径。呼吸道传播是流感病毒、麻疹病毒、腺病毒等的传播方式"},{"q":"参与流感病毒成熟释放有关的组分是","o":["血凝素（HA）","神经氨酸酶（NA）","核蛋白（NP）","外层脂蛋白","基质蛋白（MP）"],"a":1,"e":"神经氨酸酶水解感染细胞表面糖蛋白末端的N-乙酰神经氨酸，破坏受体，促使成熟病毒体出芽释放，是释放的关键组分。血凝素介导吸附与膜融合，核蛋白构成核衣壳，基质蛋白参与包装出芽，外层脂蛋白非流感病毒组分"},{"q":"与细菌侵袭力有关的致病因子不包括","o":["菌毛","荚膜","刺突","侵袭性酶","细菌生物被膜"],"a":2,"e":"细菌侵袭力包括菌毛等黏附素、荚膜、侵袭性酶和生物被膜，分别介导黏附定植、抗吞噬、扩散和抵抗药物。刺突是病毒包膜表面的糖蛋白结构，属病毒成分，不属细菌侵袭力因子。细菌侵袭力以黏附、抗吞噬和扩散为核心，与病毒表面结构无关"},{"q":"检测梅毒的不加热血清反应（USR）使用的抗原是","o":["非致病性螺旋体","变形杆菌0Xk株","梅毒螺旋体","绵羊红细胞","牛心肌类脂质"],"a":4,"e":"USR属非梅毒螺旋体抗原试验，以正常牛心肌心脂质为抗原，检测病人血清中的反应素即抗脂质抗体，操作简便但特异性较低。梅毒螺旋体抗原试验才用螺旋体作抗原；变形杆菌OXk株用于外斐反应；绵羊红细胞用于血凝试验"},{"q":"不分解乳糖、分解葡萄糖不产气、可产生H2S、有动力的肠道杆菌可能是","o":["大肠埃希菌","伤寒沙门菌","宋内志贺菌","福氏志贺菌","霍乱弧菌"],"a":1,"e":"伤寒沙门菌有周身鞭毛故动力阳性，发酵葡萄糖产酸不产气，不发酵乳糖，硫化氢弱阳性，符合题干全部条件。大肠埃希菌发酵乳糖且产酸产气；志贺菌无动力、不产生硫化氢；霍乱弧菌属弧菌科，非肠杆菌科"},{"q":"支原体与病毒的相同点是","o":["对抗生素敏感","有两种核酸","能在无生命培养基上生长繁殖","个体微小，能通过滤菌器","具有含有大量胆固醇的细胞膜"],"a":3,"e":"支原体是能在无生命培养基中生长繁殖的最小原核细胞型微生物，缺乏细胞壁、高度多形性，直径0.2～0.3μm，可通过滤菌器，病毒同样能通过滤菌器，此为二者共同点。支原体含DNA与RNA两种核酸，有含胆固醇的细胞膜，对四环素、红霉素敏感。病毒只含一种核酸，无细胞结构，须在活细胞内增殖"},{"q":"下列描述中，不属于病毒免疫逃逸机制的是","o":["病毒抗原的变异","病毒抗原高表达","子代病毒通过细胞融合方式释放","细胞内寄生","病毒抗原型别多"],"a":1,"e":"病毒抗原高表达可增强抗原提呈，有利于免疫识别与清除，不属逃逸机制。逃逸机制包括严格细胞内寄生、抗原变异与型别众多、损伤免疫细胞、抑制干扰素产生及下调MHC表达，细胞融合直接扩散亦为其逃避抗体的一种方式"},{"q":"关于铜绿假单胞菌的生物学特性描述错误的是","o":["可利用硝酸盐在厌氧条件下生长","分解蛋白质能力强","碱性环境中有自溶现象","对常用化学消毒剂有一定的抵抗力","产生脂溶性色素"],"a":4,"e":"铜绿假单胞菌产生水溶性色素（绿脓素、荧光素），可弥散至培养基和脓汁使其呈绿色，而非脂溶性色素。该菌可利用硝酸盐在厌氧条件下生长，分解蛋白质能力强，碱性环境中有自溶现象，对常用化学消毒剂抵抗力较强"},{"q":"以下关于狂犬病病毒的特性描述正确的是","o":["形态呈杆状","核酸为双链RNA","抵抗力极强","可在胞质中形成嗜酸性包涵体","动物宿主范围狭窄"],"a":3,"e":"狂犬病病毒在人或动物中枢神经细胞胞质内形成圆形或椭圆形、直径20～30nm的嗜酸性包涵体，称内氏小体，可作辅助诊断指标。病毒形态呈子弹状而非杆状，核酸为单负链RNA，对热和脂溶剂敏感、抵抗力弱，宿主范围广"},{"q":"具有抵抗吞噬细胞清除作用的细菌特殊结构是","o":["荚膜","鞭毛","芽胞","细胞壁","菌毛"],"a":0,"e":"荚膜多糖亲水并带负电荷，与吞噬细胞膜产生静电排斥，能抵抗吞噬细胞的吞噬与消化，是细菌重要的毒力因子，如肺炎链球菌、炭疽芽胞杆菌。鞭毛与运动有关；芽胞是休眠体，增强抵抗力；菌毛介导黏附；细胞壁为基本结构，无抗吞噬作用"},{"q":"IMViC试验中，字母C代表","o":["甲基红试验","硫化氢试验","尿素酶试验","乳糖分解试验","枸橼酸盐利用试验"],"a":4,"e":"IMViC由吲哚、甲基红、VP和枸橼酸盐利用四个试验组成，C即枸橼酸盐利用试验，阳性时细菌以枸橼酸盐为唯一碳源、铵盐为唯一氮源，使培养基变碱。M为甲基红，V为VP，I为吲哚；硫化氢、尿素酶、乳糖发酵均不属该组合"},{"q":"测定SLO抗体，可协助下列哪种疾病的诊断","o":["风湿热","肠热症","类风湿关节炎","猩红热","红斑性狼疮"],"a":0,"e":"SLO即链球菌溶素O，具免疫原性，感染后血清抗SLO抗体即ASO升高，活动性风湿热病人常超过400单位，故ASO试验用于风湿热的辅助诊断。肠热症用肥达试验，类风湿关节炎与红斑狼疮属自身免疫病，猩红热靠临床表现和咽拭子培养"},{"q":"下列哪一种是医院感染最常见的致病性葡萄球菌","o":["人葡萄球菌","表皮葡萄球菌","腐生葡萄球菌","耐甲氧西林金黄色葡萄球菌","溶血葡萄球菌"],"a":3,"e":"耐甲氧西林金黄色葡萄球菌携带mecA基因，编码PBP2a，对所有β-内酰胺类亲和力低，是医院感染的重要病原菌，常引起肺炎、伤口与血流感染。人葡萄球菌、表皮葡萄球菌、溶血葡萄球菌多为皮肤正常菌群，属凝固酶阴性葡萄球菌，致病力弱；腐生葡萄球菌主要引起尿路感染"},{"q":"HBV包膜上的S蛋白为","o":["HBsAg","HBsAg＋HBcAg","PreS1Ag","PreS2Ag","HBsAg＋PreS1Ag＋PreS2Ag"],"a":0,"e":"HBV包膜由S基因编码的三种蛋白构成，其中S蛋白即HBsAg，是包膜的主要成分和诊断标志。M蛋白为PreS2+HBsAg，L蛋白为PreS1+PreS2+HBsAg，PreS1Ag和PreS2Ag只是大、中蛋白的组成部分，不能单独代表S蛋白"},{"q":"符合逆转录病毒复制特点的描述是","o":["以RNA为模板，先转录互补DNA","以RNA为模板，先转录早期mRNA","以RNA直接作为mRNA","以亲代DNA为模板，产生复制中间型","以DNA为模板直接转录子代DNA"],"a":0,"e":"逆转录病毒以病毒RNA为模板，在逆转录酶催化下合成互补DNA，再形成双链DNA并整合于宿主染色体。以RNA直接作mRNA见于单正链RNA病毒，先转录早期mRNA则为DNA病毒的复制特点"},{"q":"耐药性的程度可以表示为","o":["该药物的治疗浓度","该药物对细菌的最小抑菌浓度","该药物对细菌的最大抑菌浓度","该药物的治疗剂量","该药常用量在血清中的浓度"],"a":1,"e":"耐药程度以抗菌药物对细菌的最小抑菌浓度（MIC）判定，MIC越高耐药性越强，并以折点区分敏感、中介与耐药。治疗浓度、治疗剂量、最大抑菌浓度和血清药物浓度均不能定量反映耐药水平。纸片扩散法的抑菌圈直径可辅助判定"},{"q":"性菌毛的功能是","o":["具有抗吞噬作用","与细菌趋化性运动有关","参与细菌分裂","黏附于宿主细胞","与传递遗传物质有关"],"a":4,"e":"性菌毛由质粒编码，供体菌与受体菌经性菌毛连接形成接合管，将质粒DNA传递至受体菌，故其功能与传递遗传物质有关。抗吞噬由荚膜承担，趋化性运动与鞭毛有关，黏附宿主细胞靠普通菌毛，细菌分裂为二分裂，不依赖性菌毛"},{"q":"关于垂直感染的相关描述中正确的是","o":["在公共场所被病毒感染","通过性接触而发生病毒感染","父亲患病毒病传给子女","母亲患病毒病传给其子女","母亲体内病毒经胎盘或产道传给胎儿的病毒感染"],"a":4,"e":"垂直感染指病原体由亲代经胎盘、产道或哺乳传给子代，母亲体内病毒经胎盘或产道传给胎儿最为典型。公共场所感染属水平传播；性接触传播亦为水平传播；父亲传给子女不经胎盘产道；D项未限定传播方式，表述笼统"},{"q":"可以用于沙眼的辅助诊断是","o":["墨汁负染色","冷凝集试验","包涵体检查","显微镜凝集试验","外斐反应"],"a":2,"e":"沙眼衣原体在结膜上皮细胞胞质内形成包涵体，取结膜刮片经Giemsa或碘液染色查找包涵体是沙眼的辅助诊断方法。墨汁负染用于新型隐球菌，冷凝集试验辅助支原体肺炎诊断，外斐反应用于立克次体病，显微镜凝集试验用于钩端螺旋体"},{"q":"肠杆菌科细菌对理化因素的抵抗力不强，不耐干燥，加热60℃、30分钟即被杀死，原因是缺乏","o":["荚膜","芽胞","细胞壁","鞭毛","菌毛"],"a":1,"e":"芽胞含水量低并富含吡啶二羧酸钙，对热、干燥和化学消毒剂抵抗力极强，肠杆菌科细菌不形成芽胞，故60℃30分钟即被杀灭。荚膜只抗吞噬，鞭毛管运动，菌毛管黏附，细胞壁仅提供渗透屏障，均不赋予耐热性"},{"q":"关于质粒的叙述错误的是","o":["为遗传物质","可自行丢失","可在细菌间转移","存在于细胞质中","是细菌生命活动所必需物质"],"a":4,"e":"质粒是染色体外的遗传物质，并非细菌生命活动所必需，丢失后细菌仍能正常存活，故E项错误。质粒可游离于细胞质或整合于染色体，能自行丢失或被消除，并可通过接合、转化、转导在细菌间转移，A、B、C、D均正确"},{"q":"霍乱肠毒素相应的受体是","o":["糖蛋白","黏蛋白","岩藻糖","D-甘露糖","GM1神经节苷脂"],"a":4,"e":"霍乱肠毒素B亚单位有5个，与小肠黏膜上皮细胞膜的GM1神经节苷脂特异性结合，介导A亚单位进入细胞，激活腺苷酸环化酶使cAMP升高，导致水、氯和碳酸氢钾大量分泌。D-甘露糖、岩藻糖是其他凝集素或血型抗原的配体，黏蛋白为呼吸道分泌成分，均非该毒素受体"},{"q":"以下属于细菌生长因子的是","o":["糖类","维生素","蛋白质","无机盐","微量元素"],"a":1,"e":"生长因子是细菌自身不能合成、必须从外界摄取的有机物，包括维生素、某些氨基酸、嘌呤和嘧啶，故维生素属生长因子。糖类、蛋白质为碳氮源，无机盐和微量元素属无机营养物，均不属生长因子。有些细菌还需X因子、V因子等特定生长因子"},{"q":"细菌通过性菌毛介导，F＋菌与F－菌之间的遗传物质转移过程是","o":["接合","转化","转导","溶原性转换","原生质融合"],"a":0,"e":"F+菌带F质粒、表面有性菌毛，与F-菌接合时经性菌毛形成接合桥，将F质粒的一条单链DNA导入受体菌，使受体菌转为F+菌。转化是摄取游离DNA，转导经噬菌体介导，溶原性转换为前噬菌体基因表达，原生质融合为实验室手段"},{"q":"衣原体细胞外的感染型是","o":["革兰阴性圆形体","始体","内基小体","原体","革兰阳性圆形体"],"a":3,"e":"原体是衣原体细胞外的感染型，呈球形，壁厚致密，代谢不活跃，具有传染性，经黏膜微小创面吸附侵入细胞后始转变为始体。始体为细胞内繁殖型，壁薄、体积大、二分裂增殖；内基小体是狂犬病病毒的胞质包涵体"},{"q":"以下不是结核分枝杆菌侵入机体途径的是","o":["破损的皮肤黏膜","消化道","呼吸道","泌尿道","节肢动物叮咬"],"a":4,"e":"结核分枝杆菌主要经呼吸道飞沫核传播，亦可经消化道（饮用带菌牛奶）和破损皮肤黏膜侵入。经泌尿道侵入少见，多为血行播散后的排出途径，故非主要入侵门户。节肢动物叮咬是鼠疫耶尔森菌、立克次体等的传播方式，与结核无关"},{"q":"丙种球蛋白的优点是","o":["来源广","易制备","免疫效果好","含多种微生物抗体","易保存"],"a":3,"e":"丙种球蛋白由正常人血浆提取，含针对多种常见病原体的抗体，可对麻疹、甲型肝炎等提供紧急被动免疫，无需制备特异抗血清即可使用。其来源受限、难以大量制备，免疫效果不如特异性免疫球蛋白，且抗体非自身产生，维持仅2～3周，需冷藏保存"},{"q":"耐药性是指","o":["药物对细菌所具有的杀伤力","细菌对药物所具有的敏感性","药物诱导细菌产生耐药性突变","细菌对药物所具有的相对抵抗性","细菌对药物所具有的破坏力"],"a":3,"e":"耐药性指细菌对某种抗菌药物由敏感变为不敏感的现象，即细菌对药物具有相对抵抗性，由遗传机制决定。药物对细菌的杀伤力称抗菌活性；敏感性是耐药的反面；药物只能选择已存在的突变株，不能诱导细菌定向突变"},{"q":"在室温中动力活泼，但在37℃时动力缓慢，具有此特征的细菌是","o":["百日咳鲍特菌","单核细胞性李斯特菌","幽门螺杆菌","流感嗜血杆菌","空肠弯曲菌"],"a":1,"e":"单核细胞增生李斯特菌有鞭毛，室温下动力活泼，37℃时鞭毛蛋白表达减少、动力缓慢，此温度依赖的动力特征可作初步判定。空肠弯曲菌42℃生长、动力阳性；幽门螺杆菌尿素酶丰富；流感嗜血杆菌与百日咳鲍特菌均无鞭毛"},{"q":"不属于细菌基本结构的选项是","o":["芽孢","细胞质","细胞膜","核质（拟核）","细胞壁"],"a":0,"e":"细菌的基本结构包括细胞壁、细胞膜、细胞质和核质，为所有细菌共有，缺一即难以存活。芽胞仅某些细菌在营养缺乏时形成，与荚膜、鞭毛、菌毛同属特殊结构，故不属基本结构。特殊结构只在特定条件下出现，并非所有细菌都有"},{"q":"乙型脑炎病毒的主要传染源不包括","o":["羊","鸟类","病人","马","幼猪"],"a":2,"e":"乙脑的主要传染源是带毒幼猪，其次为马、牛、羊等家畜及鸟类，猪感染后病毒血症滴度高、持续时间长。病人病毒血症短暂且滴度低，不构成主要传染源，故列为不包括者。传播媒介为三带喙库蚊，蚊可带毒越冬并垂直传代"},{"q":"支原体与衣原体的不同点是","o":["有DNA和RNA两种核酸","能在无生命的培养基中生长繁殖","属于原核细胞微生物","以二分裂法繁殖","对抗生素敏感"],"a":1,"e":"支原体是能在无生命培养基中生长繁殖的最小原核细胞型微生物，而衣原体为严格细胞内寄生，须用鸡胚、细胞或动物接种培养。两者均有DNA和RNA两种核酸，均属原核细胞型，以二分裂繁殖，均对四环素类与大环内酯类抗生素敏感"},{"q":"金黄色葡萄球菌引起的化脓性感染疖或痈，病灶比较局限，其主要原因是该菌释放","o":["凝固酶","TSST-1","外毒素","葡萄球菌溶素","耐热核酸酶"],"a":0,"e":"金黄色葡萄球菌产生血浆凝固酶，使纤维蛋白原转变为纤维蛋白沉积于菌体表面和病灶周围，形成纤维蛋白屏障，阻碍吞噬细胞和药物进入，故疖、痈病灶局限、脓汁黏稠。TSST-1引起毒性休克，溶素溶解细胞，耐热核酸酶用于鉴定，均不造成病灶局限"},{"q":"脑膜炎奈瑟菌引起下列哪种疾病","o":["乙脑","流脑","亚急性硬化性全脑炎（SSPE）","结核性脑膜炎","森林脑炎"],"a":1,"e":"脑膜炎奈瑟菌是流行性脑脊髓膜炎即流脑的病原菌，经呼吸道飞沫传播，自鼻咽部入血后侵犯脑膜。乙脑由乙脑病毒经蚊传播；亚急性硬化性全脑炎由麻疹病毒缺陷株引起；结核性脑膜炎由结核分枝杆菌所致；森林脑炎由蜱传黄病毒引起"},{"q":"卡介苗的接种对象主要是","o":["结核性脑膜炎患者","结核菌素试验阳性者","严重结核病人，结核菌素试验阴性患者","新生儿和结核菌素试验阴性的儿童","肿瘤患者"],"a":3,"e":"卡介苗为减毒活疫苗，接种对象是新生儿及结核菌素试验阴性的儿童，可诱导细胞免疫，降低粟粒性结核和结核性脑膜炎的发生。结素试验阳性者已受感染，无需接种；活动性结核病人、肿瘤患者及免疫缺陷者不宜接种活疫苗"},{"q":"属于L型细菌的特性是","o":["无致病性","常规培养形成油煎蛋菌落","形成不可逆性变异","细菌菌落为光滑型","形态可改变"],"a":4,"e":"L型细菌是细胞壁缺陷型，失去细胞壁后形态呈多形性、可改变，在低渗环境中易裂解。其变异可逆，去除诱导因素后可回复；需在高渗低琼脂含血清培养基上才形成油煎蛋样菌落，普通培养不出现；部分L型仍具致病性"},{"q":"水痘的特异性预防方法是","o":["易感儿童接种VZV减毒活疫苗","成人接种VZV减毒活疫苗","注射干扰素","注射含特异性病毒抗体的人免疫球蛋白","注射抗病毒血清"],"a":0,"e":"水痘的特异性预防是对1岁以上健康易感儿童接种VZV减毒活疫苗，可显著降低发病率。带状疱疹疫苗用于60岁以上老年人或慢性病病人；免疫球蛋白仅用于暴露后紧急预防；干扰素与抗病毒血清不作常规特异性预防"},{"q":"可用于灭活乙型肝炎病毒的方法是","o":["100℃加热5分钟","紫外线照射1.5 W/m3，1小时","75%消毒酒精处理","60℃加热1小时","高压蒸汽灭菌121.3℃，20分钟"],"a":4,"e":"乙型肝炎病毒对理化因素抵抗力强，100℃需10分钟才可灭活，故100℃ 5分钟不足；紫外线、75%乙醇、60℃ 1小时均不能可靠灭活。高压蒸汽灭菌121.3℃维持15～20分钟可破坏其感染性，是可靠的灭活方法"},{"q":"艾滋病患者的淋巴细胞不可能出现的是","o":["CD4＋T细胞减少","CD4＋T细胞增加","CD4＋T细胞/CD8＋T细胞比例倒置","CD4＋T细胞相对减少，CD8＋T细胞相对增加","CD8＋T细胞增加"],"a":1,"e":"HIV以CD4+T细胞为主要靶细胞，感染后CD4+T细胞数量减少、功能下降，CD8+T细胞相对增多，出现CD4/CD8比例倒置。故CD4+T细胞增加不会出现。其减少机制包括病毒直接杀伤、合胞体形成、凋亡增加及骨髓与胸腺生成受抑"},{"q":"副溶血性弧菌具有","o":["耐碱性","耐酸性","嗜盐性","耐高渗性","嗜温性"],"a":2,"e":"副溶血性弧菌为嗜盐菌，在含35g/L NaCl的培养基中生长最佳，无盐不能生长，NaCl高于80g/L亦不能生长。耐碱性是霍乱弧菌的特点，可在pH8.8～9.0碱性蛋白胨水中增殖；该菌不耐酸；嗜温是多数致病菌的共性，不具鉴别意义"},{"q":"不含有核酸的微生物是","o":["亚病毒","类病毒","拟病毒","朊粒","微小病毒"],"a":3,"e":"朊粒本质为构象异常的朊蛋白，不含核酸，仅由蛋白质构成。类病毒为环状单链RNA分子，无衣壳；拟病毒为包裹在类病毒样衣壳中的环状RNA；亚病毒是类病毒、拟病毒和朊粒的统称；微小病毒为细小DNA病毒，含单链DNA。故不含核酸者仅朊粒"},{"q":"鉴别肠道致病菌与非致病菌，经常选用","o":["吲哚试验","菊糖发酵试验","乳糖发酵试验","葡萄糖发酵试验","甘露醇发酵试验"],"a":2,"e":"肠道致病菌如志贺菌、沙门菌不发酵乳糖，非致病的大肠埃希菌等发酵乳糖，故乳糖发酵试验是初步鉴别的常用生化反应，并用于麦康凯、SS等选择鉴别培养基。吲哚试验用于鉴别大肠埃希菌与产气杆菌。菊糖发酵试验用于鉴别肺炎链球菌与甲型溶血性链球菌。葡萄糖发酵试验不能区分，因两类菌多能发酵葡萄糖"},{"q":"R质粒是","o":["细菌的异染颗粒","编码细菌的性菌毛","带有毒性基因的可传递物质","具有耐药性因子的可传递遗传物质","胞质中染色体外的可传递营养物质"],"a":3,"e":"R质粒是携带耐药性基因、可通过接合在细菌间传递的染色体外遗传物质，使受体菌获得耐药性，亦称传染性耐药因子。性菌毛由F质粒或染色体基因编码，异染颗粒为储藏颗粒，营养物质不能传递耐药性"},{"q":"溶菌酶的作用靶点是","o":["磷壁酸","细菌细胞膜","脂多糖","抑制肽聚糖合成的转肽酶","聚糖骨架的β-1,4糖苷键"],"a":4,"e":"溶菌酶作用于肽聚糖的聚糖骨架，水解N-乙酰葡萄糖胺与N-乙酰胞壁酸间的β-1,4糖苷键，使骨架断裂、细菌裂解。青霉素与转肽酶结合，阻断四肽侧链交联，抑制肽聚糖合成。磷壁酸为革兰阳性菌特有成分，与黏附致病相关。脂多糖是革兰阴性菌外膜成分即内毒素。细胞膜含磷脂与蛋白，并非溶菌酶底物"},{"q":"质粒核酸是","o":["双链RNA","单链RNA","单股DNA","闭合环状DNA","不完整的DNA"],"a":3,"e":"质粒是细菌染色体外的遗传物质，多为闭合环状双链DNA，可自主复制，携带耐药、毒力等基因，并能通过接合转移。少数质粒为线性DNA，但不存在单链或RNA形式；不完整的DNA也不是质粒的存在形式"},{"q":"有完整细胞核的微生物是","o":["真菌","放线菌","衣原体","立克次体","细菌"],"a":0,"e":"真菌属真核细胞型微生物，细胞核分化程度高，有核膜、核仁和染色体，胞质内有完整细胞器，故有完整细胞核。放线菌、衣原体、立克次体、细菌均为原核细胞型微生物，只有核质，无核膜与核仁；病毒为非细胞型微生物，无细胞结构"},{"q":"预防伤寒用","o":["活疫苗","死疫苗","类毒素","抗毒素","细胞因子"],"a":1,"e":"伤寒疫苗为灭活疫苗即死疫苗，用加热或化学方法杀死菌体而保留抗原性，需多次接种，免疫维持时间较短。类毒素用于白喉、破伤风，抗毒素为被动免疫，活疫苗用于卡介苗、炭疽等，细胞因子不属疫苗"},{"q":"以噬菌体为媒介把供体菌的DNA片段转移到受体菌，使受体菌获得新的遗传性状称为","o":["转化","转导","接合","溶原性转换","原生质体融合"],"a":1,"e":"转导是以噬菌体为媒介，将供体菌DNA片段转入受体菌并重组，使受体菌获得新性状。转化为受体菌直接摄取游离DNA；接合经性菌毛传递质粒或染色体；溶原性转换是噬菌体基因整合使宿主获得新性状；原生质体融合为细胞间融合"},{"q":"血清学诊断病毒感染时，应在急性期和恢复期各取一份标本，以比较两份标本的抗体效价，恢复期血清的抗体效价较急性期血清的抗体效价高（ ）有诊断意义","o":["2倍","3倍","4倍以上","10倍以上","20倍以上"],"a":2,"e":"血清学诊断须取急性期与恢复期双份血清，恢复期IgG抗体效价比急性期升高4倍或4倍以上方有诊断意义。2～3倍升高可能属个体波动，10倍、20倍并非判定阈值；单份血清抗体阳性不能判定近期感染"},{"q":"在感染和流行过程中与老鼠无关的疾病是","o":["钩端螺旋体病","出血热","地方性斑疹伤寒","流行性斑疹伤寒","恙虫病"],"a":3,"e":"流行性斑疹伤寒由普氏立克次体引起，传染源是病人，人虱为传播媒介，鼠类不参与其流行环节。钩端螺旋体病以鼠和猪为主要储存宿主，经污染水源传播。肾综合征出血热由汉坦病毒引起，鼠类是传染源。恙虫病储存宿主为鼠类，经恙螨幼虫叮咬传播。地方性斑疹伤寒的传染源亦为鼠类"},{"q":"大部分细菌的代时一般为","o":["10～19分钟","20～30分钟","40～60分钟","18～24小时","48～72小时"],"a":1,"e":"细菌以二分裂方式繁殖，数量倍增所需时间为代时，多数细菌为20～30分钟，如大肠埃希菌。结核分枝杆菌代时长达18～24小时，属慢生长菌；10～19分钟仅见于少数繁殖极快的细菌，40～60分钟及以上者亦少见"},{"q":"性病淋巴肉芽肿的病原体是","o":["肺炎衣原体","鹦鹉热衣原体","脲原体","沙眼衣原体","兽类衣原体"],"a":3,"e":"性病淋巴肉芽肿由沙眼衣原体LGV生物型L1～L3血清型引起，经性接触传播，侵犯腹股沟淋巴结，形成化脓性淋巴结炎和慢性淋巴肉芽肿。肺炎衣原体引起肺炎，鹦鹉热衣原体经鸟类传播，脲原体引起非淋菌性尿道炎，兽类衣原体不感染人"},{"q":"可以产生自溶酶的细菌","o":["A群链球菌","肺炎链球菌","甲型溶血性链球菌","凝固酶阴性葡萄球菌","金黄色葡萄球菌"],"a":1,"e":"肺炎链球菌产生自溶酶，培养48小时后菌落中央下陷呈脐状，培养液渐变澄清，胆汁或胆盐可激活该酶，故有胆汁溶菌试验。A群链球菌、甲型溶血性链球菌与葡萄球菌均不产生此酶。该酶为肺炎链球菌的鉴定要点之一"},{"q":"辅助诊断立克次体病的交叉凝集试验是","o":["锡克试验","血凝试验","冷凝集试验","外斐反应","肥达试验"],"a":3,"e":"立克次体与变形杆菌OX19、OX2、OXK菌株有共同抗原，用后者菌体抗原代替立克次体抗原检测病人血清抗体，此交叉凝集试验即外斐反应。肥达试验是用伤寒沙门菌O、H抗原诊断伤寒；冷凝集试验用于辅助诊断支原体肺炎；锡克试验测机体对白喉的免疫力；血凝试验多用于病毒检测"},{"q":"可引起自然疫源性疾病的病毒是","o":["登革病毒","单纯疱疹病毒","戊型肝炎病毒","脊髓灰质炎病毒","轮状病毒"],"a":0,"e":"登革病毒在丛林中的猴-蚊-猴循环中持续存在，属自然疫源性疾病，人进入疫源地经伊蚊叮咬而感染。单纯疱疹病毒、戊型肝炎病毒、脊髓灰质炎病毒和轮状病毒均只在人间传播，无动物储存宿主。人-蚊-人循环只在流行期出现，疫源地则长期存在"},{"q":"诊断钩端螺旋体病的血清学检查方法为","o":["显微镜凝集溶解试验","外斐反应","肥达试验","红细胞溶解试验","补体结合试验"],"a":0,"e":"钩端螺旋体病血清学诊断以显微镜凝集试验最经典常用，用活标准株与病人血清作用，暗视野下观察凝集，以50%凝集的最大稀释度为效价。外斐反应用于立克次体病，肥达试验用于肠热症，补体结合试验敏感性低，红细胞溶解试验不用于此"},{"q":"以下关于博尔纳病病毒的描述，错误的是","o":["有包膜病毒","通过密切接触传播","已有有效的疫苗","病毒核酸为单负链RNA","引起中枢神经系统疾病"],"a":2,"e":"博尔纳病病毒为有包膜的单负链RNA病毒，引起马、羊等家畜及人的中枢神经系统疾病，主要经密切接触传播。目前尚无有效疫苗和特异性治疗方法，故已有有效疫苗的说法错误。该病最早在德国博尔纳镇流行，人感染后以精神行为异常和脑炎为主要表现"},{"q":"伤寒沙门菌Vi抗原","o":["存在于菌毛蛋白","存在于鞭毛蛋白","可用于沙门菌分组","可用于沙门菌分型","刺激机体产生的抗体效价低"],"a":4,"e":"Vi抗原位于伤寒沙门菌O抗原外围，能阻止O抗原凝集，其免疫原性弱，刺激机体产生的抗体效价低，故不作为常规血清学诊断指标。Vi抗原具有型特异性，用于伤寒沙门菌的鉴定而非分组；它不是菌毛蛋白或鞭毛蛋白成分"},{"q":"立克次体病患者不能使用的药物是","o":["青霉素","红霉素","四环素","磺胺","氯霉素"],"a":3,"e":"磺胺类药物对立克次体不仅无抑制作用，反而可为其提供对氨基苯甲酸而促进生长，故立克次体病禁用磺胺。四环素、氯霉素、红霉素均有效，其中多西环素为首选；青霉素对缺乏典型肽聚糖的立克次体无效"},{"q":"关于水痘带状疱疹病毒致病性的叙述，正确的是","o":["VZV可经动物传染给人","带状疱疹患者不是儿童水痘的传染源","水痘性脑炎可致永久后遗症","原发感染后，VZV潜伏于淋巴细胞","带状疱疹疼痛不明显"],"a":2,"e":"VZV可引起水痘性脑炎，重症者遗留永久性神经系统后遗症，故该叙述正确。人是VZV唯一宿主，不经动物传人；带状疱疹患者水疱液含病毒，是儿童水痘的重要传染源；原发感染后病毒潜伏于脊髓后根神经节；带状疱疹常伴明显神经痛"},{"q":"HSV-1的主要潜伏部位是","o":["上皮细胞","唾液腺","B淋巴细胞","三叉神经节","骶神经节"],"a":3,"e":"HSV-1原发感染后沿感觉神经轴突上行，以非复制状态终身潜伏于三叉神经节与颈上神经节，受激惹时沿神经下行至口唇引起唇疱疹。HSV-2潜伏于骶神经节，VZV潜伏于脊髓后根神经节；上皮细胞是原发增殖部位而非潜伏部位"},{"q":"肠杆菌科细菌的菌体抗原是","o":["O抗原","H抗原","Vi抗原","K抗原","Vi抗原和K抗原"],"a":0,"e":"菌体抗原即O抗原，位于革兰阴性菌细胞壁脂多糖最外层，由O特异性多糖决定，具种特异性。O抗原耐热，100℃不被破坏，与不耐热的H抗原可资区别。H抗原为鞭毛抗原，K抗原为荚膜或菌毛抗原，Vi抗原是伤寒沙门菌的荚膜抗原"},{"q":"下列选项中，关于病毒形成持续性感染的原因不正确的是","o":["机体免疫功能低下，不能完全清除病毒","病毒存在于受保护部位","病毒发生抗原性突变或抗原性较弱","病毒基因整合在宿主染色体基因中，长期与宿主细胞共存","病毒有与宿主相似的抗原成分"],"a":4,"e":"持续性感染的原因包括机体免疫功能低下、病毒藏匿于受保护部位、抗原变异或抗原性弱、产生缺陷干扰颗粒及病毒基因整合于宿主基因组。与宿主相似的抗原成分易致免疫耐受，并非持续感染的成因。缺陷干扰颗粒的干扰作用亦改变了感染的自然进程"},{"q":"关于着色真菌的特点，下列叙述不正确的是","o":["产生孢子囊孢子","一般由外伤侵入人体","主要侵犯肢体皮肤及皮下组织","在机体免疫力低下时可发生颅内感染","在沙保培养基上生长缓慢"],"a":0,"e":"着色真菌属暗色真菌，菌丝与孢子呈暗褐色，靠分生孢子繁殖，不形成孢子囊孢子；孢子囊孢子是毛霉、根霉等接合菌的繁殖结构。该菌多经外伤植入皮下，侵犯肢体皮肤及皮下组织，免疫力低下者可入颅内，在沙保培养基上生长缓慢"},{"q":"普氏立克次体的主要传播途径是","o":["消化道","呼吸道","生殖道感染","虱叮咬后经破损皮肤进入体内","蚤叮咬后入血"],"a":3,"e":"普氏立克次体以人虱为传播媒介，虱叮咬时立克次体随粪便排于皮肤，经搔抓造成的破损处侵入人体，并非由虱唾液直接接种。虱感染后7～10天死亡且不经卵传代，仅为媒介；蚤传播的是斑疹伤寒立克次体"},{"q":"以噬菌体为载体，将供体菌的部分遗传物质转移给受体菌的过程，称为","o":["转化","接合","溶原性转换","原生质体融合","转导"],"a":4,"e":"以噬菌体为载体将供体菌DNA片段转入受体菌并使其获得新性状，称转导，分普遍性与局限性两类。转化为受体菌直接摄取游离DNA，接合经性菌毛传递质粒，溶原性转换为前噬菌体基因表达而非片段转移"},{"q":"首先分离培养出结核分枝杆菌的是","o":["伊凡诺夫斯基","列文虎克","巴斯德","利斯特","郭霍"],"a":4,"e":"1882年郭霍首次分离培养出结核分枝杆菌，并据此提出郭霍法则。伊凡诺夫斯基发现烟草花叶病毒，列文虎克首次观察细菌，巴斯德创立巴氏消毒法并研制疫苗，利斯特开创外科消毒法，均与结核分枝杆菌的分离无关"},{"q":"肠道病毒基因组中能编码结构蛋白的基因是","o":["P1区和P2区","P2区和P3区","P3区和P1区","P1区和Vpg","poly（A）"],"a":1,"e":"官方答案为【P2区和P3区】，但依据教材，正确答案为【P1区】。肠道病毒基因组只有一个ORF，分为P1、P2、P3三区；P1区依次编码VP4、VP2、VP3、VP1，其中VP1～VP3构成衣壳主要成分，属结构蛋白；P2、P3区编码蛋白酶、RNA依赖的RNA聚合酶及VPg等非结构蛋白。选项中无单项P1区，题干选项设置亦有误"},{"q":"作为食品受粪便污染指标的菌属","o":["志贺菌属","埃希菌属","变形杆菌属","克雷伯菌属","沙门菌属"],"a":1,"e":"埃希菌属中的大肠埃希菌主要来源于人与温血动物粪便，在食品与饮水中检出即提示粪便污染，故用作卫生学指标。志贺菌、沙门菌属致病菌，检出即具诊断意义；变形杆菌与克雷伯菌分布广泛，特异性差"},{"q":"可迟缓发酵乳糖的细菌是","o":["宋内志贺菌个别菌株","福氏志贺菌个别菌株","鲍氏志贺菌个别菌株","痢疾志贺菌个别菌株","伤寒沙门菌个别菌株"],"a":0,"e":"志贺菌属除宋内志贺菌迟缓发酵乳糖（一般需3～4天）外均不发酵乳糖，个别宋内菌株呈迟缓发酵。福氏、鲍氏、痢疾志贺菌均不发酵乳糖，伤寒沙门菌亦不发酵乳糖，故乳糖迟缓发酵是宋内志贺菌的鉴别点"},{"q":"可使感染细胞发生融合的病毒是","o":["流感病毒","腺病毒","麻疹病毒","鼻病毒","埃可病毒"],"a":2,"e":"麻疹病毒HL蛋白介导感染细胞融合，形成多核巨细胞与合胞体，是包膜病毒扩散方式之一。腺病毒无包膜，不引起细胞融合；鼻病毒、埃可病毒多致细胞圆缩、坏死；流感病毒虽属包膜病毒，但融合现象不典型，实验室多以红细胞吸附判断增殖"},{"q":"病毒引起的细胞病变机制中，与免疫病理损伤有关的是","o":["病毒衣壳蛋白对细胞的毒性","病毒的酶抑制细胞的代谢","病毒释放造成细胞膜损伤","病毒改变细胞膜抗原引起的细胞损伤","病毒包涵体对细胞的损伤"],"a":3,"e":"病毒改变感染细胞膜表面抗原，使细胞成为免疫应答攻击的靶细胞，CTL杀伤与抗体介导的ADCC造成免疫病理损伤。衣壳蛋白毒性、病毒酶抑制细胞代谢、病毒释放损伤细胞膜、包涵体损伤均属病毒直接致细胞病变，不经免疫机制"},{"q":"放线菌与龋齿和牙周炎有关，能产生一种黏性很强的物质，这种物质是","o":["鞭毛","荚膜","顶端结构","6-去氧太洛糖","普通菌毛"],"a":3,"e":"内氏放线菌与黏液放线菌产生多糖6-去氧太洛糖，黏性强，可将口腔中的放线菌及其他细菌黏附于牙釉质形成菌斑，与龋齿和牙周炎有关。荚膜虽与黏附有关，但此处所指并非荚膜；鞭毛、普通菌毛与顶端结构分别与运动、黏附和支原体滑行有关，均非该物质"},{"q":"关于百日咳鲍特菌特性的叙述，错误的是","o":["革兰阴性短小杆菌","专性需氧菌","营养要求高，分离培养需选用鲍-金培养基","菌落常发生S型到R型变异","抵抗力较强，耐干燥，日光照射数小时才死亡"],"a":4,"e":"百日咳鲍特菌抵抗力弱，日光直射1小时、56℃30分钟即被杀死，故“耐干燥、照射数小时才死亡”错误。该菌为革兰阴性短小杆菌，专性需氧，营养要求高，初次分离需鲍-金培养基；菌落常由Ⅰ相光滑型向Ⅳ相粗糙型变异，毒力随之减弱，A、B、C、D均正确"},{"q":"肺炎链球菌荚膜多糖疫苗属于","o":["活疫苗","亚单位疫苗","基因工程疫苗","重组载体疫苗","核酸疫苗"],"a":1,"e":"肺炎链球菌荚膜多糖疫苗由提取纯化的荚膜多糖制成，不含核酸，属亚单位疫苗。活疫苗含减毒病原体，基因工程疫苗为重组表达的抗原，重组载体疫苗与核酸疫苗分别经载体递送基因和注射DNA或RNA"},{"q":"常用于制备病毒灭活疫苗的是","o":["氯仿","乙醚","酚类","甲醛","过氧化氢"],"a":3,"e":"甲醛能使病毒蛋白变性、破坏核酸而灭活病毒，同时保留抗原性，是制备灭活疫苗最常用的灭活剂，如乙肝血源疫苗、脊髓灰质炎灭活疫苗。氯仿、乙醚用于溶解包膜脂质，酚类和过氧化氢为消毒剂，均不用于疫苗制备"},{"q":"引起胃肠炎的病原体是","o":["甲型副伤寒沙门菌","肖氏沙门菌","希氏沙门菌","猪霍乱沙门菌","伤寒沙门菌"],"a":3,"e":"猪霍乱沙门菌属动物源性菌，可引起人类胃肠炎，也可致败血症及迁徙性化脓灶。伤寒沙门菌、甲型副伤寒沙门菌、乙型（肖氏）和丙型（希氏）副伤寒沙门菌主要引起肠热症，表现为持续高热、玫瑰疹、相对缓脉和白细胞减少，而非胃肠炎"},{"q":"下列病毒的基因组可直接作为mRNA的一组病毒是","o":["脊髓灰质炎病毒、柯萨奇病毒、流感病毒","脊髓灰质炎病毒、HIV、麻疹病毒","脊髓灰质炎病毒、甲型肝炎病毒、埃可（ECHO）病毒","脊髓灰质炎病毒、乙型肝炎病毒、轮状病毒","脊髓灰质炎病毒、麻疹病毒、甲型肝炎病毒"],"a":2,"e":"单正链RNA病毒的基因组本身具有mRNA功能，可直接翻译出病毒蛋白，脊髓灰质炎病毒、甲型肝炎病毒和埃可病毒均属此类。流感病毒为分节段负链RNA，麻疹病毒为负链RNA，轮状病毒为双链RNA，HBV为DNA，HIV经逆转录，基因组均不能直接作mRNA"},{"q":"能够增强细菌毒力的质粒是","o":["F质粒","R质粒","Col质粒","Vi质粒","代谢质粒"],"a":3,"e":"Vi质粒编码Vi抗原，可抗御吞噬细胞吞噬，并阻挡抗体、补体对菌体的破坏，属毒力质粒。F质粒编码性菌毛，与接合传递有关；R质粒编码耐药性；Col质粒编码大肠菌素；代谢质粒编码糖、尿素等代谢酶，均不直接增强毒力"},{"q":"下列理化因素中，不可灭活肠道病毒的是","o":["紫外线","脂溶剂","氧化剂","56℃ 30min","0.3%甲醛"],"a":1,"e":"肠道病毒无包膜，不含脂质，乙醚、氯仿等脂溶剂不能将其灭活。紫外线可损伤病毒核酸，氧化剂和0.3%甲醛可使其蛋白变性，56℃30分钟可灭活多数肠道病毒，故这些因素均有效。肠道病毒对酸和乙醚均耐受，这正是其能经消化道传播的结构基础"},{"q":"衣氏放线菌感染的最常见部位是","o":["胸膜","肠道","中枢神经系统","面颈部软组织","泌尿道"],"a":3,"e":"衣氏放线菌是口腔正常菌群，多致内源性混合感染，以面颈部放线菌病最常见，约占60%，常有口腔炎、拔牙或下颌骨骨折史，形成多发性脓肿与瘘管。胸部放线菌病多继发于肺部感染。腹部放线菌病常与阑尾穿孔、肠穿孔有关。盆腔与中枢神经系统放线菌病少见"},{"q":"吲哚试验阳性说明细菌代谢产物中有","o":["H2S","靛基质","丙酮酸","二乙酰","CO2和H2"],"a":1,"e":"吲哚试验检测细菌分解色氨酸生成吲哚（靛基质）的能力，吲哚与对二甲基氨基苯甲醛试剂反应生成玫瑰吲哚而呈红色，为阳性，大肠埃希菌、变形杆菌、霍乱弧菌均为阳性。H2S由含硫氨基酸分解产生，丙酮酸、二乙酰为其他代谢产物"},{"q":"下列关于抗病毒细胞免疫的描述中不正确的是","o":["细胞免疫在抗病毒中具有重要作用","细胞免疫缺陷者不适于接种减毒活疫苗","辅助性Th1细胞能直接杀伤病毒感染细胞","成熟CD8＋CTL能直接特异性杀伤病毒感染细胞","活化的Th1细胞释放多种细胞因子可增强NK细胞和巨噬细胞的功能"],"a":2,"e":"Th1细胞属CD4+辅助性T细胞，通过释放IFN-γ、TNF等细胞因子激活巨噬细胞和NK细胞、促进CTL增殖分化，不能直接杀伤靶细胞。直接特异性杀伤病毒感染细胞的是CD8+CTL。细胞免疫缺陷者接种减毒活疫苗可致严重感染"},{"q":"不属于人工被动免疫方式的是","o":["注射抗菌血清","注射类毒素","注射胎盘丙种球蛋白","注射人血清丙种球蛋白","注射抗毒素"],"a":1,"e":"类毒素属人工主动免疫，接种后2～4周才产生抗体，用于预防。抗毒素、抗菌血清、人血清丙种球蛋白与胎盘丙种球蛋白均含现成抗体，注射后立即生效，属人工被动免疫，多用于治疗或紧急预防；异种抗毒素须警惕Ⅰ型超敏反应"},{"q":"下列关于汉坦病毒的特性描述，错误的是","o":["有包膜的DNA病毒","可直接损伤全身毛细血管和小血管","感染流行状况与鼠类的分布活动有关","可引起免疫复合物性疾病","特异性IgM有助于早期诊断其感染"],"a":0,"e":"汉坦病毒属布尼亚病毒目，基因组为分节段单负链RNA并有包膜，故有包膜的DNA病毒之说错误。该病毒可直接损伤全身毛细血管与小血管，流行与鼠类分布活动相关，可形成免疫复合物致病，特异性IgM有助早期诊断"},{"q":"容易引发流感世界性大流行的病原体是","o":["甲型流感病毒","乙型流感病毒","丙型流感病毒","副流感病毒","流感嗜血杆菌"],"a":0,"e":"甲型流感病毒基因组为分节段单负链RNA，血凝素与神经氨酸酶抗原易发生漂移和基因重排，可产生新亚型，故易引起世界性大流行。乙型变异小，多为局部流行，丙型只引起散发轻型感染；副流感病毒与流感嗜血杆菌不是流感大流行的病原"},{"q":"能使致病性大肠杆菌产生肠毒素的质粒是","o":["F质粒","R质粒","ST质粒","LT质粒","Col质粒"],"a":4,"e":"官方答案为【Col质粒】，但依据教材，正确答案为【ST质粒】。Col质粒编码大肠埃希菌的大肠菌素，属细菌素质粒，与肠毒素无关；ETEC的耐热肠毒素ST和不耐热肠毒素LT均由质粒基因编码，故ST质粒（或LT质粒）才能使致病性大肠杆菌产生肠毒素。F质粒编码性菌毛，R质粒编码耐药性"},{"q":"关于VZV的特点，错误的是","o":["感染症状典型，一般不需做微生物学检查即可诊断","引起新生儿疱疹","属于α疱疹病毒","能在胚胎组织细胞中增殖","人类是VZV的唯一宿主"],"a":1,"e":"新生儿疱疹由HSV-2经产道感染引起，与VZV无关，故该项错误。VZV属α疱疹病毒亚科，人类是唯一宿主，可在胚胎组织细胞中增殖；临床表现典型，水痘与带状疱疹依皮损分布即可诊断，一般不需微生物学检查"},{"q":"人体对结核分枝杆菌的免疫特点是","o":["可引起Ⅲ型超敏反应","以体液免疫为主","为有菌免疫","不能通过人工主动免疫获得","可引起Ⅰ型超敏反应"],"a":2,"e":"结核分枝杆菌感染后，机体免疫力随体内活菌存在而维持，属有菌免疫（传染性免疫），细菌被清除后免疫逐渐消失。该免疫以细胞免疫为主，并伴Ⅳ型迟发型超敏反应；卡介苗可提供人工主动免疫，故B、D、E均错"},{"q":"存在于人体的微生物量最多的部位是","o":["口腔","肠道","皮肤","阴道","呼吸道"],"a":1,"e":"人体肠道尤其是结肠内含大量细菌，占人体微生物总量的绝大部分，种类达数百种，以厌氧菌为主。口腔、皮肤、阴道与呼吸道虽也有菌群定植，但数量和种类均远少于肠道；胃内因胃酸作用菌量很少"},{"q":"R质粒在哪类细菌中最常见","o":["幽门螺杆菌","需氧菌","肠杆菌科菌","葡萄球菌","厌氧菌"],"a":2,"e":"R质粒在肠杆菌科细菌中最为常见，尤以大肠埃希菌、志贺菌与沙门菌间的传播突出，接合传递使耐药性在肠道菌群中迅速扩散。幽门螺杆菌、葡萄球菌与厌氧菌虽也可携带耐药质粒，但远不如肠杆菌科普遍"},{"q":"下列与疱疹病毒有关的疾病，不包括","o":["龈口炎","鼻咽癌","卡波西肉瘤","脑炎","皮肤疣"],"a":4,"e":"疱疹病毒所致疾病包括HSV-1的龈口炎、角膜炎，EBV的鼻咽癌、Burkitt淋巴瘤，HHV-8的卡波西肉瘤，以及疱疹病毒性脑炎。皮肤疣由人乳头瘤病毒引起，属乳头瘤病毒科，与疱疹病毒无关"},{"q":"黄曲霉毒素主要由下列哪类微生物产生","o":["细菌","立克次体","放线菌","真菌","螺旋体"],"a":3,"e":"黄曲霉毒素由黄曲霉产生，属真菌毒素，耐热，主要污染花生与玉米，长期摄入与肝癌发生相关。烟曲霉、黑曲霉、棕曲霉等亦可产生类似致癌物质。细菌产生外毒素与内毒素，放线菌主要产生抗生素。毒素经口摄入即可中毒，与真菌本身感染无关"},{"q":"类毒素是","o":["抗毒素经甲醛处理后的物质","细菌素经甲醛处理后的物质","外毒素经甲醛处理后脱毒而保持抗原性的物质","内毒素经甲醛处理后脱毒而保持抗原性的物质","外毒素经甲醛处理后脱毒并改变了抗原性的物质"],"a":2,"e":"外毒素经0.3%～0.4%甲醛处理后失去毒性而保留免疫原性，即为类毒素，可刺激机体产生抗毒素用于人工主动免疫。抗毒素是免疫动物血清中的抗体，属人工被动免疫；内毒素为脂多糖，甲醛处理不能脱毒制成类毒素"},{"q":"下列情况中最不易发生机会性感染的是","o":["艾滋病晚期","正常菌群寄居部位改变","使用大量免疫抑制剂","经常服用维生素","长期使用广谱抗生素"],"a":3,"e":"机会性感染发生于免疫功能低下、菌群失调或正常菌群寄居部位改变时，如艾滋病晚期、大量使用免疫抑制剂、长期广谱抗生素。经常服用维生素只补充营养，既不抑制免疫也不破坏菌群平衡，不增加机会性感染的风险"},{"q":"细菌的核糖体由下列亚基组成","o":["50S","50S或30S","50S和30S","30S或60S","40S和60S"],"a":2,"e":"细菌核糖体沉降系数为70S，由50S和30S两个亚基组成，50S含23S与5S rRNA，30S含16S rRNA，是链霉素、红霉素等抗生素的作用靶位。真核细胞核糖体为80S，由60S和40S组成，故40S与60S的组合错误"},{"q":"下列哪种病毒感染人体后可获得持久免疫力","o":["流感病毒","单纯疱疹病毒","腺病毒","脊髓灰质炎病毒","人乳头瘤病毒"],"a":3,"e":"脊髓灰质炎病毒感染后可诱生型特异性中和抗体，免疫力长期而牢固，且血清型仅3个，故极少再感染。流感病毒抗原易变异，HSV潜伏并反复复发，腺病毒型别多，HPV型别多且免疫逃逸，均不能获得持久免疫"},{"q":"关于病毒概念错误的是","o":["病毒在细胞外不能产生能量","病毒在细胞外不能合成蛋白质","病毒在细胞外不能合成自身代谢所需要的酶","包膜病毒需要宿主的细胞膜作为包膜成分","病毒需降解宿主细胞DNA以获得核苷酸"],"a":4,"e":"病毒无产能酶系与核糖体，细胞外不能产生能量、不能合成蛋白质与自身所需酶类，必须寄生活细胞。包膜病毒的包膜脂质取自宿主细胞膜或核膜。病毒复制所需核苷酸来自宿主细胞代谢池，并不降解宿主DNA，此说与病毒增殖机制不符"},{"q":"关于脊髓灰质炎病毒的特点叙述正确的是","o":["病后不能获得持久免疫力","是有包膜的RNA病毒","临床类型以麻痹型多见","只有1个血清型","主要以粪-口途径传播"],"a":4,"e":"脊髓灰质炎病毒无包膜，主要经粪-口途径传播，隐性感染远多于显性感染，麻痹型仅占1%左右。病后可获得对同型病毒的持久免疫；病毒有3个血清型；临床以隐性感染和轻型为多，麻痹型少见。病毒在肠道增殖后仅少数入血，极少数累及脊髓前角运动神经元"},{"q":"不以虫媒为主要传播媒介的病毒是","o":["登革病毒","黄热病病毒","克里米亚-刚果出血热病毒","乙型脑炎病毒","汉坦病毒"],"a":4,"e":"汉坦病毒主要经鼠类粪尿污染的气溶胶、食物及伤口传播，螨媒仅为可能的次要途径，不以虫媒为主要传播方式。登革病毒、黄热病病毒、乙型脑炎病毒均以蚊为媒介，克里米亚-刚果出血热病毒以蜱为媒介"},{"q":"预防真菌感染性疾病，目前的最佳方法是","o":["预防性使用抗真菌药物","接种疫苗","注意清洁卫生，提高机体免疫力","多与患者或患病动物接触，使机体产生特异性免疫力","使用抗菌药物"],"a":2,"e":"真菌感染尚无有效疫苗，预防以注意清洁卫生、保持皮肤与鞋袜干燥、避免接触病人和带菌动物为主，深部真菌病应去除诱因、提高机体免疫力。预防性用抗真菌药易致耐药，抗菌药物可诱发菌群失调，接触患者不能产生有效免疫"},{"q":"对病毒生物学性状的描述，不正确的是","o":["测量大小的单位为纳米（nm）","含有DNA和RNA两种核酸","以复制方式增殖","必须寄生于活细胞内","属于非细胞型微生物"],"a":1,"e":"病毒只含一种核酸，DNA或RNA，不同时含两种，这是病毒区别于其他微生物的重要特征。病毒大小以nm计，以自我复制方式增殖，严格细胞内寄生，属非细胞型微生物。同时含两种核酸的是细菌、真菌等细胞型微生物"},{"q":"下列除哪种细菌外，一般都不入血","o":["白喉棒状杆菌","伤寒沙门菌","霍乱弧菌","痢疾志贺菌","破伤风梭菌"],"a":1,"e":"伤寒沙门菌为胞内寄生菌，可经淋巴入血形成两次菌血症，是选项中唯一常规入血者。白喉棒状杆菌、霍乱弧菌与痢疾志贺菌均局限于局部黏膜，仅外毒素入血致病；破伤风梭菌停留于厌氧创口，痉挛毒素入血而细菌不入血繁殖"},{"q":"对鼻咽癌有辅助诊断意义的血清学指标是","o":["VCA-IgM和VCA-IgG","EA-IgA和VCA-IgA","EBNA-IgG和VCA-IgG","EA-IgG和EA-IgA","MA-IgM和EBNA-IgG"],"a":1,"e":"EB病毒EA-IgA与VCA-IgA效价持续升高对鼻咽癌有辅助诊断价值，可用于高危人群筛查和早期诊断。VCA-IgM升高提示原发感染，VCA-IgG与EBNA-IgG阳性提示既往感染，不能用于鼻咽癌诊断"},{"q":"引起食物中毒最常见的葡萄球菌是","o":["表皮葡萄球菌","凝固酶阴性葡萄球菌","金黄色葡萄球菌","腐生性葡萄球菌","人葡萄球菌"],"a":2,"e":"金黄色葡萄球菌产生肠毒素，耐热100℃30分钟仍保持活性，是葡萄球菌食物中毒的病原。表皮葡萄球菌、人葡萄球菌与腐生葡萄球菌均属凝固酶阴性葡萄球菌，毒力弱，主要引起导管相关感染。其肠毒素属外毒素，与化脓性感染的致病物质不同"},{"q":"由HSV-1引起的感染类型一般不包括","o":["龈口炎","唇疱疹","疱疹性角膜结膜炎","脑炎","新生儿疱疹"],"a":4,"e":"新生儿疱疹由HSV-2经产道感染引起，不属HSV-1所致。HSV-1主要引起疱疹性龈口炎、唇疱疹、疱疹性角膜结膜炎和散发性脑炎，均经接触传播，原发感染后潜伏于三叉神经节。两型HSV的潜伏部位与传播途径亦不相同"},{"q":"耐药性质粒是指","o":["F质粒","R质粒","Col质粒","毒力质粒","代谢质粒"],"a":1,"e":"R质粒即耐药性质粒，携带耐药基因并可通过接合在细菌间传递，是耐药性扩散的主要载体。F质粒编码性菌毛、介导接合；Col质粒编码大肠菌素；毒力质粒编码黏附素、毒素等毒力因子；代谢质粒编码特殊代谢酶"},{"q":"有关衣原体的描述正确的是","o":["原体是发育周期中的繁殖型","细胞质包围原体形成空泡","原体在细胞外不稳定","在空泡内始体增大而发育成原体","原体以吞饮方式进入细胞"],"a":4,"e":"衣原体原体为感染型，通过吞饮方式进入宿主细胞，在空泡内发育为始体，始体二分裂繁殖后再浓缩成原体，完成发育周期。原体在细胞外较稳定，具感染性；始体为繁殖型，无感染性，故原体在细胞外不稳定之说错误"},{"q":"H-O变异属于","o":["形态结构变异","抗原性变异","菌落变异","毒力变异","耐药性变异"],"a":0,"e":"H-O变异指有鞭毛的细菌失去鞭毛，菌落由H型（薄而蔓延）变为O型（光滑型），动力试验转阴，属鞭毛的形态结构变异，其抗原性随之改变。菌落变异指菌落形态改变，毒力变异与耐药性变异涉及致病力和药物敏感性，均非本题所指"},{"q":"甲型流感病毒易发生变异的原因是","o":["HA、NA和相应抗体结合导致灭活","脂溶剂裂解脂质包膜发生L型变异","RNA分节段而易于发生基因重组","基质蛋白受干扰素影响合成受阻","基质蛋白易受理化因素影响而变构"],"a":2,"e":"甲型流感病毒基因组为分节段的单负链RNA，不同毒株混合感染时各节段可发生基因重排，产生新亚型；同时RdRp缺乏校对功能，复制中易出现点突变。抗体结合导致灭活、脂溶剂裂解包膜、基质蛋白变构均非变异原因"},{"q":"霍乱弧菌产生的主要致病物质是","o":["霍乱毒素","鞭毛","菌毛","内毒素","荚膜"],"a":0,"e":"霍乱弧菌黏附于小肠黏膜后繁殖并释放霍乱毒素，A亚基使Gs蛋白持续活化、cAMP升高，肠上皮细胞大量分泌水和电解质，引起剧烈水样泻。鞭毛、菌毛仅与穿过黏液层和定植有关；内毒素毒性较弱，不引起主要症状；荚膜非该菌致病物质。故主要致病物质为霍乱毒素"},{"q":"可阻止白假丝酵母由单细胞相转变为菌丝相的因素是","o":["抗白假丝酵母黏附素抗体","机体正常微生物群的拮抗作用","吞噬细胞的吞噬作用","适应性细胞免疫应答","正常体液中的抗真菌物质"],"a":0,"e":"抗白念珠菌黏附素抗体可封闭菌体表面黏附素，抑制其黏附于宿主细胞，从而阻断酵母相向菌丝相的转变与侵袭。B项正常微生物群拮抗属菌群屏障，C项吞噬细胞属固有免疫清除，D项适应性细胞免疫针对已入侵真菌，E项正常体液中的抗真菌物质亦为杀伤作用而非阻断相变"},{"q":"使相应细菌裂解的噬菌体称为","o":["前噬菌体","毒性噬菌体","温和噬菌体","溶原性细菌","L型细菌"],"a":1,"e":"毒性噬菌体能在宿主菌内复制增殖、产生子代并最终裂解细菌，只有溶菌性周期。温和噬菌体基因组可整合于宿主菌染色体成为前噬菌体，随细菌分裂传代，不引起裂解。溶原性细菌是携带前噬菌体的宿主菌；L型细菌为细胞壁缺陷的细菌变异型，与噬菌体无关"},{"q":"下列哪种微生物与龋齿的发病关系密切","o":["放线菌","人型支原体","奋森螺旋体","巴西诺卡菌","星型诺卡菌"],"a":0,"e":"龋齿放线菌、内氏放线菌和黏液放线菌能产生6-去氧太洛糖等多糖，将口腔细菌黏附于牙釉质形成菌斑，与龋齿和牙周炎密切相关。人型支原体寄居泌尿生殖道，奋森螺旋体与口腔机会感染有关，巴西诺卡菌和星形诺卡菌引起诺卡菌病"},{"q":"关于皮肤癣菌的致病特点，错误的是","o":["一种皮肤癣菌可引起不同部位感染","同一部位感染也可由不同皮肤癣菌引起","是一种条件致病性真菌","引起的真菌病最多","常侵犯角质蛋白丰富的部位"],"a":2,"e":"皮肤癣菌是嗜角质蛋白的致病性真菌，侵犯皮肤角质层、毛发和甲板，引起浅部真菌病，在真菌病中发病最多，一种菌可致多个部位感染，同一部位也可由不同菌种引起。其不属条件致病性真菌，健康人接触后即可感染"},{"q":"链球菌群特异性的抗原是","o":["蛋白质抗原","P抗原","A抗原","B抗原","C抗原"],"a":4,"e":"C抗原即细胞壁多糖抗原，位于细胞壁内侧，为群特异性抗原，是链球菌分群的依据。M蛋白等表面蛋白质抗原具型特异性，是分型依据；P抗原为核蛋白抗原，各群链球菌相同，无特异性。分群用于流行病学调查与疫苗制备，分型用于追溯传染源"},{"q":"有包膜的病毒侵入细胞的方式是","o":["胞饮","直接穿入","吞噬","膜融合","裂解细胞膜"],"a":3,"e":"包膜病毒依靠包膜表面的融合蛋白介导包膜与细胞膜或胞质囊泡膜融合，核衣壳进入胞质，如流感病毒HA2、HIV gp41。胞饮与吞噬是细胞摄入大分子或颗粒的方式，多数无包膜病毒经此穿入；直接穿入指无包膜病毒改变细胞膜通透性；裂解细胞膜并非生理性侵入方式"},{"q":"下列哪种现象属于病毒基因突变","o":["温度敏感性变异","交叉复活","表型混合","多重复活","表型交换"],"a":0,"e":"温度敏感性变异属病毒基因突变，突变株在低温可增殖而高温不能增殖，是减毒活疫苗选育的常用表型。交叉复活、多重复活为两株病毒基因组间的重组；表型混合与表型交换指病毒结构蛋白的混合装配，属基因产物互补而非核酸序列改变"},{"q":"关于幽门螺杆菌的特性正确的是","o":["归属于弯曲菌属","革兰阴性杆菌，无鞭毛","专性需氧生长，营养要求高","耐干燥","与B型胃炎、消化道溃疡及胃癌有关"],"a":4,"e":"幽门螺杆菌定植于胃黏膜，产生尿素酶、空泡毒素与黏附素，与慢性胃炎、消化性溃疡、胃黏膜相关淋巴瘤和胃癌密切相关。其自成一属，不归弯曲菌属；革兰阴性，一端有数根鞭毛；微需氧而非专性需氧；不耐干燥，经口-口或粪-口途径传播"},{"q":"伤寒可出现的并发症是","o":["肝炎","胆囊炎","DIC","肠出血及肠穿孔","骨髓炎"],"a":3,"e":"伤寒第2～3周胆囊内细菌经胆汁再入肠道，使已致敏的肠壁淋巴组织发生超敏反应，形成坏死溃疡，可并发出血和穿孔，是最严重的并发症。胆囊炎多为带菌状态而非急性并发症；肝炎、DIC、骨髓炎不是伤寒的典型并发症"},{"q":"细菌对两性霉素B的耐药性属于","o":["固有耐药性","染色体突变引起的耐药性","获得耐药性","质粒介导的耐药性","转座因子介导的耐药性"],"a":0,"e":"两性霉素B与真菌细胞膜上的麦角固醇结合，细菌细胞膜不含固醇，故所有细菌对其天然不敏感，属固有耐药性。获得耐药性指细菌DNA改变后由敏感转为耐药，可由染色体突变、R质粒接合转移或转座子介导，与种属天然不敏感性质不同"},{"q":"关于噬菌体的叙述，错误的选项是","o":["侵袭细菌等的病毒","有严格的宿主特异性","主要由核酸和蛋白质组成","对理化因素的抵抗力比一般细菌强","每种噬菌体都含有DNA和RNA两种形式的核酸"],"a":4,"e":"每种噬菌体只含一种核酸，或DNA或RNA，据此分为DNA噬菌体和RNA噬菌体，故该项错误。噬菌体是侵袭细菌的病毒，有严格宿主特异性，由核酸和蛋白质组成，对理化因素的抵抗力比一般细菌强"},{"q":"下列关于HSV的特性叙述，错误的是","o":["较宽的宿主范围，能在多种细胞中增殖","可在淋巴细胞建立潜伏感染，复发常见","两型HSV的传播途径不同","至少有11种包膜糖蛋白","在多数细胞中表现为溶细胞感染"],"a":1,"e":"HSV原发感染后在感觉神经节建立潜伏感染，HSV-1潜伏于三叉神经节，HSV-2潜伏于骶神经节，复发常见，而非在淋巴细胞潜伏；淋巴细胞潜伏是EBV的特点。其余各项正确：宿主范围广、两型传播途径不同、有11种以上包膜糖蛋白、多表现为溶细胞感染"},{"q":"与长期使用抗生素引起的假膜性肠炎有关的细菌是","o":["金黄色葡萄球菌","大肠杆菌","艰难梭菌","肺炎链球菌","耶尔森氏菌"],"a":2,"e":"长期使用抗生素后肠道正常菌群被抑制，艰难梭菌趁机大量繁殖并产生肠毒素和细胞毒素，引起假膜性肠炎，是典型的二重感染。金黄色葡萄球菌也可致二重感染，但以化脓性感染为主；大肠埃希菌、肺炎链球菌、耶尔森菌不引起抗生素相关假膜性肠炎"},{"q":"新生隐球菌的主要传播方式是","o":["病人-咳痰-飞沫传播","鸽子-粪便-呼吸道传播","病人-粪便-消化道传播","病人-粪便-呼吸道传播","人虱-粪便-破损皮肤传播"],"a":1,"e":"新生隐球菌主要经吸入鸽粪污染的尘埃而感染，鸽粪为其自然贮存宿主，故传播方式为鸽子—粪便—呼吸道。该菌不通过人与人之间飞沫或粪-口传播，人虱叮咬亦非其途径，皮肤破损接种仅偶见。其荚膜多糖是主要毒力因子，中枢神经系统感染多见于免疫功能缺陷者"},{"q":"金黄色葡萄球菌重要的抗原是","o":["葡萄球菌A蛋白","O抗原","H抗原","多糖抗原","荚膜抗原"],"a":0,"e":"金黄色葡萄球菌抗原30种以上，以葡萄球菌A蛋白最为重要，SPA可与IgG的Fc段结合，封闭调理吞噬，是金葡菌的标志性抗原。O抗原、H抗原分别是革兰阴性肠道菌的菌体抗原与鞭毛抗原，荚膜抗原和多糖抗原虽存在但不具此鉴别意义"},{"q":"革兰阳性菌和革兰阴性菌细胞壁共有成分是","o":["磷脂","磷壁酸","肽聚糖","吡啶二羧酸","二氨基庚二酸"],"a":2,"e":"肽聚糖为细菌细胞壁的基本组分，革兰阳性菌由聚糖骨架、四肽侧链与五肽交联桥构成，革兰阴性菌仅具聚糖骨架与四肽侧链，但两者共有肽聚糖。磷壁酸为革兰阳性菌特有，外膜与脂多糖为革兰阴性菌特有，二氨基庚二酸见于阴性菌四肽侧链"},{"q":"皮肤癣菌侵犯部位仅限于表皮、毛发及指（趾）甲，这是因为引起这些真菌病的病原体具有以下哪种特性","o":["嗜油脂性","嗜角质蛋白","嗜干燥","嗜糖","喜低温"],"a":1,"e":"皮肤癣菌的共同特点是亲角蛋白，其角蛋白酶可分解角质，故只能侵犯皮肤角质层、毛发和甲板，不侵入皮下及内脏。嗜油脂性是马拉色菌的特点；嗜干燥、嗜糖、喜低温均不能解释其严格的部位选择性"},{"q":"下列物质中，具有感染性的是","o":["Dane颗粒","小球形颗粒","管形颗粒","HBeAg","HBcAg"],"a":0,"e":"Dane颗粒为完整HBV颗粒，含环状双链DNA和DNA聚合酶，表面有HBsAg，具有感染性。小球形颗粒和管形颗粒仅由HBsAg组成，不含核酸，无感染性；HBeAg、HBcAg为可溶性抗原成分，本身不能引起感染"},{"q":"鉴定幽门螺杆菌的重要特征性依据是","o":["定居在胃肠道内","运动活泼、生化反应活泼","产生大量尿素酶，分解尿素为氨","革兰阴性无芽孢菌","弯曲状或S形细菌"],"a":2,"e":"幽门螺杆菌产生大量尿素酶，分解尿素为氨和二氧化碳，中和胃酸以利定植，尿素呼气试验即据此诊断，是鉴定的重要特征性依据。弯曲状、革兰阴性无芽孢、定居胃肠道、运动活泼等性状其他弯曲菌也可具备，缺乏特异性"},{"q":"关于汉坦病毒的致病性，错误的是","o":["主要的靶细胞是血管内皮细胞","主要的感染类型是隐性感染","诱导的机体免疫具有双重作用","所致疾病以发热、出血和肾脏损害为特征","一年四季均有流行，无明显季节性"],"a":4,"e":"肾综合征出血热有明显季节性，姬鼠型以春夏季及秋冬交界为高峰，家鼠型多在春季，与鼠类活动和人类接触机会相关。汉坦病毒主要攻击血管内皮细胞，致病以发热、出血、肾损害为特征，免疫应答既清除病毒又参与损伤，隐性感染亦常见"},{"q":"有关菌毛的描述不正确的是","o":["多见于革兰阴性菌","细菌的运动器官","性菌毛可传递遗传物质","普通菌毛与细菌黏附有关","比鞭毛短、直、细且数量多"],"a":1,"e":"菌毛不是运动器官，鞭毛才是细菌的运动器官。菌毛短、直、细、数量多，多见于革兰阴性菌；普通菌毛数量多而介导黏附，性菌毛仅1～4根，在接合时传递质粒。两者均为细菌表面附属物，但功能截然不同"},{"q":"关于克里米亚-刚果出血热病毒的叙述，正确的是","o":["是无包膜的RNA病毒","对酸和脂溶剂抵抗力弱","与其他出血热病毒有共同抗原","所致疾病无明显的季节性","尚无疫苗可用于特异性预防"],"a":1,"e":"克里米亚-刚果出血热病毒为有包膜的RNA病毒，对酸、脂溶剂与去污剂敏感，故该项正确。A项误为无包膜；该病毒与其他出血热病毒无共同抗原；发病与蜱活动一致而有明显季节性；我国已研制灭活疫苗"},{"q":"HSV-2常潜伏的部位是","o":["三叉神经节","颈上神经节","骶神经节","肋间神经","腰神经节"],"a":2,"e":"HSV-2主要经性接触传播，原发感染后沿感觉神经上行，潜伏于骶神经节，复发时引起生殖器疱疹。HSV-1潜伏于三叉神经节和颈上神经节；VZV潜伏于脊髓后根神经节和脑神经感觉神经节；肋间神经、腰神经节不是其潜伏部位"},{"q":"1976年在美国费城一次退伍军人会议期间发生肺炎流行，次年分离出","o":["军团菌","肺炎衣原体","螺杆菌","莱姆病螺旋体","肺炎球菌"],"a":0,"e":"1976年美国费城退伍军人会议期间暴发的肺炎由嗜肺军团菌引起，次年从死亡者肺组织分离出该菌，军团病由此得名。肺炎衣原体、肺炎链球菌引起社区肺炎，螺杆菌寄居胃黏膜，莱姆病螺旋体由蜱传播，均与此次流行无关"},{"q":"新生儿诊断为子宫内感染时血液中检测出的有诊断意义的抗体为","o":["IgG","IgA","IgM","IgE","IgD"],"a":2,"e":"IgM分子量大，不能通过胎盘，新生儿血中检出特异性IgM说明抗体由胎儿自身产生，是宫内感染的可靠指标。IgG可经胎盘由母体被动输入，阳性无法区分宫内感染与母体抗体转移；IgA、IgE、IgD均不适用于此判断"},{"q":"对外界抵抗力最强的细菌结构是","o":["荚膜","鞭毛","芽胞","细胞壁","菌毛"],"a":2,"e":"芽胞含水量低、含大量吡啶二羧酸钙，核心外有多层膜结构，故对热、干燥、辐射和化学消毒剂抵抗力最强，可耐煮沸数小时。荚膜只抗吞噬，鞭毛、菌毛为表面附属物，细胞壁的抵抗力远不及芽胞。正因如此，灭菌效果以能否杀死芽胞为判定标准"},{"q":"人类嗜T淋巴细胞病毒所致的疾病是","o":["血友病","人类免疫缺陷综合征","红斑狼疮","淋巴瘤","人毛细胞白血病"],"a":4,"e":"HTLV-1引起成人T细胞白血病，HTLV-2则与毛细胞白血病样疾病相关，故人毛细胞白血病为其所致疾病。血友病是遗传性凝血因子缺陷，艾滋病由HIV引起，红斑狼疮属自身免疫病，均与HTLV无关"},{"q":"根据病毒感染的发展进程，下列病毒中与其他病毒不同的是","o":["HBV","HCV","CMV","EBV","HIV"],"a":4,"e":"HIV属逆转录病毒科慢病毒属，感染后经漫长潜伏期进行性破坏CD4+T细胞，呈慢发病毒感染过程。HBV、HCV以慢性感染为主，CMV、EBV以潜伏感染为主，均可在体内长期存留而无慢病毒样的进行性致死病程"},{"q":"RPR试验测定病人血清反应素所用的抗原是","o":["同种异型抗原","钩体类属抗原","梅毒特异性抗原","半抗原","异嗜性抗原"],"a":4,"e":"RPR属非梅毒螺旋体抗原试验，以正常牛心肌心脂质作抗原，该脂质与梅毒螺旋体脂质成分有共同抗原性，是存在于不同种属间的异嗜性抗原，用于测定血清中的反应素。梅毒特异性抗原用于荧光螺旋体抗体吸收试验、TPPA等确证试验。半抗原指仅有反应原性、无免疫原性的小分子脂质，需与载体蛋白结合才具抗原性"},{"q":"内毒素的主要毒性物质是","o":["核酸","多糖","蛋白质","氨基酸","脂质A"],"a":4,"e":"内毒素即脂多糖，由脂质A、核心多糖和特异多糖组成，脂质A是毒性与生物学活性的主要组分，无种属特异性。多糖为菌体抗原成分，决定血清型；蛋白质为外毒素的主要成分。氨基酸不构成内毒素的毒性基团"},{"q":"引起莱姆病的主要病原体是","o":["伯氏疏螺旋体","钩端螺旋体","回归热疏螺旋体","梅毒螺旋体","雅司螺旋体"],"a":0,"e":"莱姆病由伯氏疏螺旋体引起，硬蜱为传播媒介，鼠类为储存宿主，表现为慢性游走性红斑、关节炎和神经系统损害。钩端螺旋体引起钩体病，回归热疏螺旋体引起回归热，梅毒螺旋体引起梅毒，雅司螺旋体引起雅司"},{"q":"下列选项中，不属于慢发病毒感染特征的是","o":["潜伏期长","发病后症状持续性加重","潜伏期不能检测到病毒或病毒抗原","可在隐性感染后进入长潜伏期","可在显性感染后进入长潜伏期"],"a":2,"e":"慢发病毒感染潜伏期长，可达数月至数年，发病后症状进行性加重，病程呈亚急性且结局多为死亡；感染可发生在隐性感染或显性感染之后，病原体在潜伏期内持续存在，并非不能检出。潜伏期检测不到病毒或抗原是潜伏感染的特点，病毒以潜伏状态长期存留，激活后才增殖致病"},{"q":"脊髓灰质炎病毒感染的最常见的临床表现是","o":["无菌性脑膜炎","隐性感染","非麻痹型脊髓灰质炎","延髓麻痹","永久性迟缓性肢体麻痹"],"a":1,"e":"脊髓灰质炎病毒感染后至少90%表现为隐性感染，仅少数病毒侵入中枢神经系统。无菌性脑膜炎、非麻痹型脊髓灰质炎均属显性感染；延髓麻痹和永久性迟缓性肢体麻痹为严重麻痹型，发生率不足1%"},{"q":"下列病毒感染中不能引起病毒血症的是","o":["流感病毒","流行性乙型脑炎病毒","脊髓灰质炎病毒","腮腺炎病毒","ECHO病毒"],"a":0,"e":"流感病毒局限在呼吸道上皮细胞增殖，一般不侵入血流，故不形成病毒血症，全身症状由细胞因子引起。乙脑病毒、脊髓灰质炎病毒、腮腺炎病毒与ECHO病毒均可入血形成病毒血症，再播散至中枢神经系统、唾液腺等靶器官"},{"q":"感染后不能获得牢固免疫的病毒是","o":["甲型肝炎病毒","脊髓灰质炎病毒","麻疹病毒","流感病毒","乙型脑炎病毒"],"a":3,"e":"流感病毒表面HA和NA抗原易发生漂移与转换，每遇新亚型人群普遍易感，病后免疫仅对同型同株有效且短暂，故不能获得牢固免疫。麻疹病毒、乙型脑炎病毒、脊髓灰质炎病毒、甲型肝炎病毒感染后均可产生持久甚至终生免疫"},{"q":"革兰染色时，决定细菌被染成蓝紫色或红色的细菌物理性状是","o":["光学性质","表面积大小","带电现象","细胞壁和细胞膜的半透性","细菌体内的渗透压大小"],"a":2,"e":"革兰阳性菌等电点为pH2～3，革兰阴性菌为pH4～5，在近中性环境中均带负电荷，前者带电荷更多，与带正电的结晶紫结合更牢固，乙醇脱色时不易洗脱而呈紫色。光学性质、表面积大小与体内渗透压不决定染色反应；细胞壁通透性影响脱色速度，但根本差异仍在带电"},{"q":"革兰阳性粗短杆菌，有鞭毛，无荚膜。芽胞呈椭圆形，直径大于菌体，位于菌体次极端，呈网球拍状。该细菌是","o":["破伤风梭菌","产气荚膜梭菌","肉毒梭菌","艰难梭菌","炭疽杆菌"],"a":2,"e":"肉毒梭菌为革兰阳性粗短杆菌，有鞭毛、无荚膜，芽胞椭圆形、直径大于菌体、位于次极端，使菌体呈网球拍状。破伤风梭菌芽胞正圆位于顶端，呈鼓槌状。产气荚膜梭菌芽胞位于中央或次极端，不使菌体膨大，有荚膜。炭疽芽胞杆菌呈竹节状排列，芽胞居中"},{"q":"整合有前噬菌体的细菌，获得新的遗传性状的过程，称为","o":["转化","接合","转导","溶原性转换","原生质融合"],"a":3,"e":"温和噬菌体感染细菌后，其基因组整合于宿主染色体成为前噬菌体，使细菌获得新的生物学性状，称溶原性转换，如白喉棒状杆菌获得产毒能力。转化是摄取游离DNA，接合经性菌毛传递质粒，转导是噬菌体介导的基因转移，原生质体融合为实验手段"},{"q":"布鲁氏菌的主要致病物质是","o":["内毒素","微荚膜","侵袭性酶","鞭毛","外毒素"],"a":0,"e":"布鲁氏菌为革兰阴性小杆菌，内毒素是其主要致病物质，可引起发热、乏力、关节痛等，并能在单核巨噬细胞内寄生，形成菌血症与反复发作。其微荚膜与透明质酸酶等参与侵袭，但致病以内毒素为主；该菌无外毒素与鞭毛"},{"q":"病毒灭活是指在理化因素作用下使病毒失去","o":["抗原性","感染性","血凝特性","诱生干扰素的能力","融合细胞特性"],"a":1,"e":"灭活是理化因素破坏病毒核酸或衣壳，使其失去感染性，但仍保留抗原性，这正是制备灭活疫苗的基础。血凝特性、诱生干扰素能力和融合细胞特性在灭活后常可部分保留，不能作为灭活指标；抗原性属灭活后应予保留的性状。故灭活指失去感染性"},{"q":"细菌的耐药性突变特点是","o":["抗菌药物的使用与细菌耐药性突变无关","细菌的耐药性基因突变不可发生回复突变","基因突变所导致的耐药是抗生素诱导的","耐药菌的大量产生与抗生素的使用无关","合理使用抗生素可以避免耐药菌产生"],"a":0,"e":"耐药性突变属自发突变，细菌在接触药物前即已存在耐药突变株，抗菌药物只起选择作用而非诱导作用，故耐药突变的发生与用药无关。E项合理使用抗生素只是防控措施，可延缓而不能杜绝耐药菌出现；C项把耐药突变说成由抗生素诱导，混淆了选择与诱导；B项亦错，耐药突变可发生回复突变"},{"q":"EB病毒的原发感染中，约半数表现的疾病是","o":["传染性单核细胞增多症","恶性淋巴瘤","鼻咽癌","唇疱疹","生殖器疱疹"],"a":0,"e":"EBV在人群中感染普遍，原发感染多无明显症状，约50%感染者表现为传染性单核细胞增多症，故该病是EBV原发感染的代表性疾病。Burkitt淋巴瘤、鼻咽癌与EBV潜伏感染及癌基因激活相关；唇疱疹、生殖器疱疹由HSV-1、HSV-2引起"},{"q":"关于立克次体，下列叙述哪项不正确","o":["大多是专性细胞内寄生","对抗生素不敏感","大多是人畜共患病原体","节肢动物常为传播媒介","含有DNA和RNA两类核酸"],"a":1,"e":"立克次体对四环素类、氯霉素敏感，磺胺类不敏感且能促进其生长，故“对抗生素不敏感”错误。立克次体多为专性细胞内寄生，多为人畜共患病原体，节肢动物为传播媒介，同时含DNA和RNA两类核酸"},{"q":"引起人类梅毒的病原体是","o":["雅司螺旋体","回归热疏螺旋体","伯氏疏螺旋体","苍白密螺旋体","钩端螺旋体"],"a":3,"e":"梅毒由苍白密螺旋体苍白亚种引起，俗称梅毒螺旋体，螺旋致密规则、两端尖直，运动活泼。雅司螺旋体引起雅司病，属地方性密螺旋体病。伯氏疏螺旋体引起莱姆病，回归热疏螺旋体引起回归热。钩端螺旋体引起钩端螺旋体病，经疫水接触传播"},{"q":"培养真菌的最适pH值是","o":["1","4","7","9","10"],"a":1,"e":"真菌嗜酸性，最适pH为4.0～6.0，故在pH4左右生长最好，培养基常不加缓冲剂以利于其产酸。细菌最适pH为7.2～7.6，霍乱弧菌偏碱、结核分枝杆菌偏酸，均与真菌不同。故真菌培养基多偏酸，细菌培养基多为中性"},{"q":"关于荚膜组织胞浆菌的特点，下列叙述正确的是","o":["可形成肢体象皮肿","产生酵母型菌落","吸入带菌尘埃可引起急性肺部感染","根据荚膜多糖抗原分4个血清型","为一种条件致病性真菌"],"a":2,"e":"荚膜组织胞浆菌为双相真菌，吸入带菌尘埃后先在肺部引起急性感染，多数自愈，免疫低下者可播散至全身。象皮肿由丝虫引起；荚膜多糖分A、B、C、D四型的是新型隐球菌；该菌属致病性真菌，在正常宿主亦可致病，并非典型条件致病菌"},{"q":"禽流感病毒的病毒类型是","o":["丙型流感病毒","乙型流感病毒","甲型流感病毒","副流感病毒","鼻病毒"],"a":2,"e":"禽流感病毒属甲型流感病毒，其HA和NA抗原易发生变异和基因重排，某些亚型如H5N1、H7N9可跨种传播感染人。乙型流感病毒仅感染人、无亚型；丙型流感病毒亦无亚型；副流感病毒和鼻病毒与禽流感无关"},{"q":"下列试验中不属于血清学诊断方法的是","o":["肥达试验","外斐反应","ELISA","糖发酵试验","抗O试验"],"a":3,"e":"糖发酵试验属细菌生化反应，用于鉴别细菌分解糖类的能力，不依赖抗原抗体反应，不属血清学诊断。肥达试验、外斐反应、抗O试验均为凝集试验，ELISA为酶免疫测定，均以抗原抗体结合为基础"},{"q":"固有耐药性的产生是","o":["染色体突变","接合性R质粒介导","非接合性R质粒介导","转座因子介导","细菌种属特异性所决定"],"a":4,"e":"固有耐药性又称天然耐药性，由细菌染色体上的耐药基因或天然缺乏药物靶位决定，具种属特异性，可预测、可代代相传。染色体突变、接合性或非接合性R质粒介导、转座因子介导均属获得耐药性的来源"},{"q":"关于耐药质粒叙述错误的有","o":["几乎所有致病菌均有耐药质粒","R质粒在肠道菌中最常见","R质粒分为接合性和非接合性质粒","R质粒只决定对一种抗菌药物有耐药性","R质粒可决定细菌的耐药性"],"a":3,"e":"R质粒常携带多个耐药基因，可同时对多种抗菌药物耐药，故只决定对一种药物耐药的说法错误。R质粒在肠道菌中最为常见，分接合性与非接合性，接合性R质粒还可带动非接合性质粒共同转移。耐药质粒还可经转座子与整合子加速扩散"},{"q":"肠热症的无症状带菌者体内可有哪种病原体","o":["猪霍乱沙门菌","肠炎沙门菌","破伤风梭菌","伤寒沙门菌","鼠伤寒沙门菌"],"a":3,"e":"肠热症由伤寒沙门菌及甲、乙、丙型副伤寒沙门菌引起，胆囊带菌者可长期排菌成为无症状带菌者，是重要传染源。猪霍乱沙门菌、肠炎沙门菌、鼠伤寒沙门菌主要引起胃肠炎。破伤风梭菌经伤口感染，与肠道带菌无关"},{"q":"下列细菌当中，可以引起人畜共患病的是","o":["结核分枝杆菌","麻风分枝杆菌","淋病奈瑟菌","炭疽芽孢杆菌","霍乱弧菌"],"a":3,"e":"炭疽芽胞杆菌主要感染牛、羊等食草动物，人通过接触病畜及畜产品、摄食或吸入而感染，属人畜共患病。结核分枝杆菌、麻风分枝杆菌、淋病奈瑟菌、霍乱弧菌均只在人间传播，无动物传染源。其芽胞在土壤中可存活数十年，形成持久疫源地"},{"q":"属于真核细胞型微生物的是","o":["螺旋体","放线菌","真菌","细菌","病毒"],"a":2,"e":"真菌有完整细胞核、核膜核仁及线粒体、内质网等细胞器，属真核细胞型微生物。细菌、放线菌、螺旋体均有原核结构，病毒无细胞结构。真菌细胞壁含几丁质与葡聚糖而不含肽聚糖，故对青霉素不敏感"},{"q":"可用作快速诊断的血清学方法是","o":["中和试验","取双份血清，在二次血清抗体升高4倍以上有诊断意义","血凝抑制试验","用ELISA法检测特异性IgM","PCR"],"a":3,"e":"ELISA检测血清或脑脊液中的特异性IgM，可在感染后4～5天检出，阳性率达90%以上，属快速诊断的血清学方法。中和试验、血凝抑制试验需双份血清抗体4倍以上升高，只能作回顾性诊断；PCR检测病毒核酸虽快速，但不属血清学方法"},{"q":"可致疱疹性咽峡炎的肠道病毒主要是","o":["柯萨奇病毒A组","脊髓灰质炎病毒","埃可病毒","轮状病毒","柯萨奇病毒B组"],"a":0,"e":"疱疹性咽峡炎主要由柯萨奇病毒A组引起，在咽腭弓、软腭、悬雍垂周围出现疱疹和溃疡。脊髓灰质炎病毒侵犯脊髓前角致弛缓性麻痹，埃可病毒多引起出疹和无菌性脑膜炎，柯萨奇B组与心肌炎相关，轮状病毒引起腹泻"},{"q":"流脑的病原体是","o":["淋病奈瑟菌","肺炎链球菌","乙脑病毒","脑膜炎奈瑟菌","链球菌"],"a":3,"e":"流行性脑脊髓膜炎由脑膜炎奈瑟菌引起，该菌为革兰阴性双球菌，有荚膜与菌毛，经飞沫传播，内毒素为主要致病物质。淋病奈瑟菌引起淋病；肺炎链球菌致肺炎与中耳炎；乙脑病毒引起流行性乙型脑炎，经蚊传播；链球菌多见于化脓性感染"},{"q":"下列关于血清学诊断正确的是","o":["一般适用于抗原性较弱，以及病程较长的传染病诊断","是感染性疾病最重要的诊断依据","不能用于调查人群对某病原体的免疫水平及检测预防接种效果","在血清学诊断中，通常取双份血清","如果抗体效价低，即可否定感染"],"a":3,"e":"血清学诊断常采集急性期和恢复期双份血清，恢复期IgG抗体阳转或效价升高4倍以上才有诊断价值，单份血清只能作参考。它适用于抗原性较强、病程较长的感染，不是最重要的诊断依据，也可用于人群免疫水平和接种效果调查，抗体效价低不能排除感染"},{"q":"以下描述正确的是","o":["人工被动免疫接种的物质是抗原性物质","人工被动免疫不能用于治疗","人工主动免疫接种的物质是丙种球蛋白","人工主动免疫主要用于治疗","人工被动免疫主要用于紧急预防"],"a":4,"e":"人工被动免疫输入的是抗体或细胞因子，注射后立即生效，但维持仅2～3周，故主要用于治疗或紧急预防，如接触麻疹后注射丙种球蛋白。其接种物为抗体，不是抗原；人工主动免疫接种疫苗或类毒素，出现慢、维持久，以预防为主，一般不用于治疗"},{"q":"下列哪种细菌可以代替立克次体作为抗原与患者血清进行交叉凝集反应，用于诊断立克次体病","o":["产气肠杆菌","变形杆菌","沙雷菌","枸橼酸杆菌","摩根杆菌"],"a":1,"e":"普通变形杆菌OX19、OX2、OXK菌株的O抗原与斑疹伤寒立克次体、恙虫病东方体有共同抗原，可代替立克次体作抗原与病人血清凝集，即外斐试验。产气肠杆菌、沙雷菌、枸橼酸杆菌与摩根杆菌均无此共同抗原，不用于该试验"},{"q":"下列关于真菌抵抗力的描述正确的是","o":["对干燥、阳光及紫外线的抵抗力不强","对10%甲醛不敏感","对青霉素敏感","较耐热，70℃1小时菌丝和孢子不能被杀灭","制霉菌素可抑制真菌的生长"],"a":4,"e":"制霉菌素属多烯大环内酯类，与真菌细胞膜麦角固醇结合形成孔道，抑制真菌生长，故该描述正确。真菌对干燥、阳光和紫外线抵抗力较强，对甲醛等消毒剂敏感；青霉素对真菌无效；菌丝和孢子在70℃1小时可被杀灭"},{"q":"R质粒的最常见的转移途径是","o":["转化","接合","转导","溶原性转换","原生质融合"],"a":1,"e":"R质粒为接合性耐药质粒，通过性菌毛在细菌间传递，是质粒最常见的转移方式，在革兰阴性菌中尤为突出。接合还可传递毒力质粒与代谢质粒；转化需感受态菌，转导需噬菌体，均非其主要途径。接合频率受菌体密度与药物选择压力影响"},{"q":"登革热的流行病学特征不包括","o":["人是病毒传播的主要储存宿主","主要流行于热带和亚热带地区","曾经在中国广东省引起大规模流行","其媒介通常在夜间叮咬人体","可通过释放携带沃尔巴克氏体的蚊子作防控"],"a":3,"e":"登革热媒介为埃及伊蚊和白纹伊蚊，主要在白天叮咬人，故“夜间叮咬”错误。人和灵长类动物是主要储存宿主，该病流行于热带和亚热带，我国广东、海南等地曾多次暴发；释放携带沃尔巴克氏体的蚊虫可降低媒介种群，是新型防控策略"},{"q":"甲型流感病毒容易引起世界性大流行的原因是","o":["病毒抗原性弱","病毒型别较多","病毒发生抗原转变","多个亚型同时流行","病毒发生抗原漂移"],"a":2,"e":"甲型流感病毒分节段RNA在人与禽流感病毒混合感染时可发生基因重排，产生HA或NA全新的亚型即抗原转变，人群普遍缺乏免疫，故引起世界性大流行。抗原漂移仅为点突变造成的亚型内变异，引起季节性流行"},{"q":"核酸类型为DNA的呼吸道病毒是","o":["流感病毒","副流感病毒","呼吸道合胞病毒","腺病毒","麻疹病毒"],"a":3,"e":"腺病毒为双链DNA病毒，无包膜，可引起咽结膜热、肺炎和胃肠炎。流感病毒、副流感病毒、呼吸道合胞病毒、麻疹病毒均为单负链RNA病毒，故D项是所列病毒中唯一的DNA病毒，其余四种核酸类型均为RNA"},{"q":"患病后可获得终身牢固免疫力的病毒是","o":["冠状病毒","鼻病毒","流感病毒","腮腺炎病毒","呼吸道合胞病毒"],"a":3,"e":"腮腺炎病毒只有一个血清型，感染后机体产生持久而牢固的免疫，婴儿可自母体获得被动免疫，故6个月内婴儿很少患病。流感病毒抗原易变异，病后免疫短暂且亚型间无交叉保护；鼻病毒型别众多，可反复感染；冠状病毒与呼吸道合胞病毒的免疫也不持久，常发生再感染"},{"q":"在全球广泛引起AIDS的病原体是","o":["HPV","HTLV-1","HIV-1","HTLV-2","HIV-2"],"a":2,"e":"HIV-1是全球艾滋病流行的主要病原体，呈世界性分布；HIV-2主要局限于西非，致病性较弱。HPV引起生殖道疣与宫颈癌，HTLV-1引起成人T细胞白血病，HTLV-2与AIDS无关"},{"q":"感染后不易形成病毒血症的病毒是","o":["轮状病毒","麻疹病毒","腮腺炎病毒","风疹病毒","脊髓灰质炎病毒"],"a":0,"e":"轮状病毒局限在小肠黏膜绒毛上皮细胞内增殖，引起吸收障碍与腹泻，一般不侵入血流，故不易形成病毒血症。麻疹病毒、腮腺炎病毒、风疹病毒与脊髓灰质炎病毒均可入血形成病毒血症，并借此播散至皮肤、唾液腺、胎儿或中枢神经系统"},{"q":"长期储存HIV的宿主细胞是","o":["CD4＋T细胞","CD8＋T细胞","NK细胞","巨噬细胞","B细胞"],"a":0,"e":"HIV感染后部分CD4+T细胞存活并分化为记忆CD4+T细胞，其内病毒基因表达极低，成为长期潜伏的主要储存库。巨噬细胞可携带病毒，但长期储存库以记忆CD4+T细胞为主；CD8+T细胞、B细胞与NK细胞非其靶细胞"},{"q":"脊髓灰质炎病毒最主要的感染类型是","o":["隐性感染","慢发病毒感染","急性感染","慢性感染","潜伏感染"],"a":0,"e":"脊髓灰质炎病毒感染后至少90%为隐性感染，仅少数发生无菌性脑膜炎，约1%出现弛缓性麻痹。隐性感染比例高且可获型特异免疫，故为主要感染类型。潜伏感染见于HSV等疱疹病毒，慢发病毒感染见于朊粒病和HIV感染"},{"q":"风湿热辅助诊断试验是","o":["协同凝集试验","肥达反应","外斐反应","溶菌试验","ASO试验"],"a":4,"e":"A群链球菌感染后机体产生抗链球菌溶血素O抗体，风湿热病人血清ASO显著升高，活动期常超过400单位，故ASO试验用于辅助诊断。肥达反应针对伤寒沙门菌，外斐反应针对立克次体，协同凝集试验利用葡萄球菌A蛋白检测抗原，溶菌试验观察细菌裂解，均与风湿热无关"},{"q":"在1.05kg/cm2 121℃ 20分钟条件下，高压蒸汽灭菌法不能去除热原质的原因是","o":["压力不足","加热时间不够","热原质具有耐高温特点","加热温度没有达到200℃","有水的情况下热原质不易被破坏"],"a":2,"e":"热原质即革兰阴性菌细胞壁脂多糖，耐高温，121℃ 20分钟高压蒸汽灭菌亦不能破坏，需250℃干烤30分钟以上才能破坏其致热活性。压力与时间并非不足，121.3℃已是标准灭菌条件，温度亦已达标；其原因是热原质本身耐热，而非有水保护"},{"q":"钩端螺旋体的主要致病物质是","o":["内毒素","外毒素","溶血素","鞭毛","荚膜"],"a":0,"e":"内毒素是钩端螺旋体的主要致病物质，其脂质A结构与典型内毒素有差异、毒性较弱，但可引起发热、炎症和微循环障碍。黏附素、溶血素和侵袭性酶起辅助作用；该菌不产生外毒素；鞭毛与荚膜并非其主要致病物质"},{"q":"抗流感病毒再感染的主要免疫因素是","o":["干扰素","细胞免疫","抗神经氨酸酶抗体","黏膜免疫","血清中抗血凝素抗体"],"a":4,"e":"体液免疫以抗HA抗体为主，能中和病毒、阻止其吸附穿入，对同亚型变异株的保护可持续数月至数年，是抗再感染的主要因素。抗NA抗体可限制病毒释放与扩散，作用次之；细胞免疫主要促进恢复；干扰素与黏膜免疫参与早期非特异防御，不能提供持久保护"},{"q":"下列病毒复制周期中，不正确的一个环节是","o":["吸附","穿入","脱壳","生物合成","孢子形成与释放"],"a":4,"e":"病毒复制周期为吸附、穿入、脱壳、生物合成、装配与释放五个阶段，不含“孢子形成”。孢子（芽胞）是芽胞杆菌等原核生物的休眠结构，与病毒增殖无关。A～D均为复制周期的正确环节，故E项错误"},{"q":"不属于新现或再现传染病的是","o":["AIDS","SARS","新型冠状病毒肺炎","结核","狂犬病"],"a":4,"e":"新现与再现传染病指近数十年新识别的病原体所致疾病或发病率回升的旧病，艾滋病、SARS、新冠均属新现，结核因耐药与免疫抑制人群增多而再现。狂犬病是已知古老的人兽共患病，流行格局与防控手段长期稳定，未列入新现或再现传染病"},{"q":"皮肤是重要的防御屏障，下列哪个病毒可以通过皮肤损伤进入机体","o":["副流感病毒","呼吸道合胞病毒","鼻病毒","乳头瘤病毒","流感病毒"],"a":3,"e":"人乳头瘤病毒经皮肤黏膜微小破损侵入基底层上皮细胞，在分化细胞中完成复制，故皮肤损伤是其侵入门户。副流感病毒、呼吸道合胞病毒、鼻病毒与流感病毒均经呼吸道黏膜或眼结膜侵入，不经皮肤破损感染"},{"q":"龋齿与下列何种细菌关系最密切","o":["乙型溶血型链球菌","肠球菌","B群链球菌","变异链球菌","唾液链球菌"],"a":3,"e":"变异链球菌产生葡萄糖基转移酶，分解蔗糖生成黏性不溶性葡聚糖，构成牙菌斑基质，使细菌黏附于牙面，发酵产酸使pH降至4.5，导致牙釉质脱钙形成龋损。唾液链球菌为口腔正常菌群；B群链球菌引起新生儿败血症与脑膜炎；肠球菌多致泌尿道感染与心内膜炎"},{"q":"不是由A群溶血性链球菌引起的疾病是","o":["亚急性细菌性心内膜炎","急性肾小球肾炎","风湿热","猩红热","败血症"],"a":0,"e":"A群链球菌引起化脓性感染（咽峡炎、丹毒、脓疱疮）、毒素性疾病（猩红热）与超敏反应性疾病（风湿热、急性肾小球肾炎），严重时可致败血症。亚急性细菌性心内膜炎多由甲型溶血性链球菌（如咽峡炎链球菌）在原有心瓣膜病变基础上引起，不属A群链球菌所致"},{"q":"寄生菌的生物学特点是","o":["专性活细胞内寄生","以复制的方式进行繁殖","遇氧后可迅速形成芽孢","可利用N2、NH3、NO2－、NO3－等作为氮源合成菌体成分","必须以多种有机物为原料才能合成菌体成分并获得能量"],"a":4,"e":"寄生菌属异养菌，必须以蛋白质、糖类等多种有机物为原料才能合成菌体成分并获得能量，不能利用无机物自养。专性活细胞内寄生与复制繁殖是病毒特点；遇氧形成芽孢无依据；以N2、NH3、硝酸盐为氮源是自养菌特点"},{"q":"在进行病毒分离培养时，病毒感染细胞的形态变化被称为“细胞病变效应”。下列关于细胞病变效应的描述中最为准确的是","o":["不引起感染细胞死亡的病毒感染通常症状较轻","细胞病变效应很少引起细胞死亡","形成多核巨细胞是细胞病变效应的一种","细胞病变效应只能用电子显微镜观察","细胞病变效应不能用光学显微镜观察"],"a":2,"e":"细胞病变效应包括细胞变圆、融合形成多核巨细胞、出现包涵体、脱落死亡等，故形成多核巨细胞属其一种。CPE常导致细胞死亡，且可用光学显微镜观察，并非仅电镜可见；不引起细胞死亡的病毒亦可致病"},{"q":"衣原体与病毒的不同点是","o":["对抗生素敏感","专性活真核细胞内寄生","可用鸡胚接种进行培养","可在感染细胞中形成包涵体","可通过细菌滤器"],"a":0,"e":"衣原体有细胞壁、含DNA和RNA、有核糖体，对四环素类和大环内酯类敏感，故与病毒的根本区别在于对抗生素敏感。与病毒相同之处是专性活细胞内寄生、可用鸡胚接种、形成包涵体、能通过细菌滤器"},{"q":"以白纹伊蚊为传播媒介的病毒是","o":["乙型脑炎病毒","森林脑炎病毒","汉坦病毒","登革病毒","东方马脑炎病毒"],"a":3,"e":"白纹伊蚊与埃及伊蚊是登革病毒的主要传播媒介，病毒在蚊体内增殖后经叮咬传播，也可经蚊卵垂直传递。乙型脑炎病毒主要由三带喙库蚊传播；森林脑炎病毒由硬蜱传播；汉坦病毒经鼠类排泄物形成气溶胶传播；东方马脑炎病毒亦由蚊传播，但媒介非白纹伊蚊"},{"q":"狂犬病病毒的基因组为","o":["双链RNA","分节段的单负链RNA","分节段的单正链RNA","不分节段的单正链RNA","不分节段的单负链RNA"],"a":4,"e":"狂犬病病毒属弹状病毒科，基因组为不分节段的单负链RNA，全长约12kb，依次编码N、P、M、G、L五种蛋白，核衣壳螺旋对称。分节段的单负链RNA见于流感病毒，其八个节段易发生基因重排。单正链RNA见于鼻病毒、乙脑病毒。双链RNA见于轮状病毒"},{"q":"关于机会致病菌的叙述，下列正确的是","o":["机体免疫功能低下时才被感染","由正常菌群在特定条件下转化而成","引起感染的原因是细菌发生了耐药性变异","引起感染的条件是细菌的毒力增强","引起感染的诱因是滥用抗生素"],"a":1,"e":"机会致病菌即条件致病菌，多为正常菌群成员，在寄居部位改变、机体免疫力下降或菌群失调时致病。A项只强调免疫低下，遗漏部位改变和菌群失调；C、D项把耐药或毒力增强当作致病条件；E项滥用抗生素仅为诱发菌群失调的因素之一"},{"q":"噬菌体具有抗原性，能够刺激机体产生特异性抗体，该抗体","o":["能抑制相应噬菌体侵袭宿主菌","能抑制已进入宿主菌噬菌体的生物合成","能抑制宿主菌内噬菌体的成熟释放","能抑制噬菌体的脱壳","能抑制噬菌体基因组的整合"],"a":0,"e":"噬菌体抗体能中和游离噬菌体、抑制其侵袭宿主菌，但对已吸附或已进入菌体的噬菌体无效，也不能阻止其生物合成、成熟释放与基因组整合。这与其抗原表位位于衣壳表面、抗体不能进入菌体有关。故可用于噬菌体分型与细菌鉴定的中和试验"},{"q":"金黄色葡萄球菌特殊的表面结构蛋白是","o":["SPA","荚膜","黏附素","胞壁肽聚糖","脂多糖"],"a":0,"e":"SPA是金黄色葡萄球菌细胞壁的表面蛋白，可与IgG的Fc段结合，封闭调理吞噬，是金葡菌重要的抗原和鉴别指标。荚膜、黏附素、肽聚糖虽为表面结构成分，但不具此特异性；脂多糖是革兰阴性菌外膜成分"},{"q":"感染人类引起波浪热的病原体是","o":["斑疹伤寒立克次体","肺炎链球菌","布鲁氏菌","肠炎沙门菌","白喉棒状杆菌"],"a":2,"e":"布鲁氏菌为动物源性胞内菌，人接触病畜或食入污染乳制品后感染，表现为发热2～3周、间歇数日再起的波浪热，伴多汗、关节痛和肝脾大。斑疹伤寒立克次体引起斑疹伤寒，肺炎链球菌引起肺炎，肠炎沙门菌引起胃肠炎，白喉棒状杆菌引起白喉"},{"q":"下列处理方法不能有效预防真菌性食物中毒的是","o":["严禁销售霉变食物","严禁食用霉变食物","霉变食物一定要洗干净并加热后才能食用","加强市场管理","加强食品卫生宣传"],"a":2,"e":"真菌毒素如黄曲霉毒素B1耐热，一般烹调加热不能将其破坏，霉变食物清洗加热后仍可致中毒，故C项错误。预防关键在于严禁销售和食用霉变食品，加强市场管理与卫生宣传，做好防霉去毒"},{"q":"关于耐药性质粒的描述错误的是","o":["由耐药传递因子和耐药决定因子组成","耐药传递因子和F质粒的功能相似","R质粒的转移是造成细菌间耐药性传播的主要原因","细菌耐药性的产生是由于R质粒基因突变所致","耐药决定因子可编码细菌多重耐药性"],"a":3,"e":"R质粒由耐药传递因子和耐药决定因子组成，前者与F质粒功能相似，可经接合传递；耐药决定因子常携带多个转座子，编码多重耐药，故R质粒转移是细菌间耐药性扩散的主要原因。细菌耐药性主要来自外源耐药基因的获得，而非R质粒基因突变，此项错误"},{"q":"下列关于病毒的描述，哪项是错误的","o":["病毒的最基本结构是由核酸和蛋白质组成的","病毒不能在无生命的人工培养基中生长增殖","病毒体内只含有一种核酸类型","某些动物病毒常引起人类致死性感染","病毒以分裂的方式进行增值"],"a":4,"e":"病毒以基因组核酸为模板进行自我复制，无细胞分裂过程，故E项错误。病毒基本结构为核酸加衣壳，只含一种核酸；因无核糖体与产能系统，不能在无生命培养基中增殖；狂犬病病毒、HIV等可致人类致死性感染，A、B、C、D均正确"},{"q":"绝大多数病原菌生长最适pH为","o":["2.2～2.8","3","5.1～5.8","6.6～6.8","7.2～7.6"],"a":4,"e":"绝大多数病原菌最适生长pH为7.2～7.6，与人体内环境相近。霍乱弧菌耐碱，最适pH8.4～9.2；结核分枝杆菌偏酸，最适pH6.5～6.8。pH2.2～2.8、5.1～5.8多见于嗜酸微生物或真菌"},{"q":"可通过聚丙烯酰胺凝胶电泳进行分型和快速鉴定的病毒是","o":["杯状病毒","轮状病毒","星状病毒","肠道腺病毒","柯萨奇病毒"],"a":1,"e":"轮状病毒基因组为11个节段的双链RNA，聚丙烯酰胺凝胶电泳呈特征性4-2-2-3分布图，可据此快速分型与鉴定。杯状病毒、星状病毒、肠道腺病毒、柯萨奇病毒无此节段图谱，不用该法分型"},{"q":"关于多重耐药描述错误的是","o":["有些菌株能同时耐受多种抗菌药物的现象","通常由于质粒决定的耐药性发生传播容易引起多重耐药性","外排泵是导致细菌多重耐药的重要原因","生化因素不会导致多重耐药","多重耐药菌日益增加"],"a":3,"e":"多重耐药的机制包括产生多种钝化酶、外排泵主动泵出药物、靶位改变和膜通透性下降，均属生化因素，故“生化因素不会导致多重耐药”错误。R质粒可经接合在菌间传递，是多重耐药迅速播散的重要原因，B项正确；外排泵过度表达确为重要机制，C项正确"},{"q":"细菌耐药性形成的主要方式是","o":["转化","转导","转换","接合","原生质体融合"],"a":3,"e":"接合是供体菌经性菌毛与受体菌沟通，将R质粒等接合性质粒传递过去，是细菌获得耐药性最主要的方式，革兰阴性菌中尤为突出。转化是摄取游离DNA，转导经噬菌体介导，“转换”非规范术语，原生质体融合为实验手段"},{"q":"艰难梭菌的传播途径为","o":["呼吸道","接触传播","血液传播","粪-口途径","垂直传播"],"a":3,"e":"艰难拟梭菌经粪-口途径传播，芽胞被吞食后在肠道发芽繁殖，释放毒素A和毒素B引起假膜性结肠炎，是医院内抗生素相关性腹泻的主要病原。该病不经呼吸道、血液或垂直传播；接触被芽胞污染的手和物品属粪-口传播的具体环节"},{"q":"HIV的分类属于","o":["泡沫病毒属","慢病毒属","α逆转录病毒属","γ逆转录病毒属","ε逆转录病毒属"],"a":1,"e":"HIV属逆转录病毒科正逆转录病毒亚科慢病毒属，为单正链RNA病毒，具包膜，经逆转录整合于宿主基因组。泡沫病毒属与α、γ、ε逆转录病毒属均不含HIV；HTLV-1属δ逆转录病毒属，与HIV同科不同属"},{"q":"以下哪种情况属于耐药","o":["药物对细菌的治疗浓度小于其最小抑菌浓度","药物对细菌的治疗浓度大于其最小抑菌浓度","药物对细菌的治疗浓度小于其最大抑菌浓度","药物对细菌的治疗浓度大于其最大抑菌浓度","药物对细菌的治疗浓度等于其最小抑菌浓度"],"a":1,"e":"官方答案为【药物对细菌的治疗浓度大于其最小抑菌浓度】，但依据教材，正确答案为【药物对细菌的治疗浓度小于其最小抑菌浓度】。耐药的本质是治疗剂量下所能达到的血药浓度低于MIC，药物不能抑制细菌；治疗浓度大于MIC才判为敏感。最大抑菌浓度不是药敏判定指标，等于MIC只属临界状态"},{"q":"染色体上整合有F因子的细菌称为","o":["F－菌","F＋菌","F＇菌","附加体","Hfr（高频重组株）"],"a":4,"e":"F质粒整合到细菌染色体上，与染色体同步复制，能高频率转移染色体基因，称为高频重组株。F+菌的F质粒游离存在；F-菌无F质粒；F′菌的F质粒携有相邻染色体片段但仍游离；附加体是能游离又能整合的质粒的统称，不是菌株名称"},{"q":"来源于质粒的β-内酰胺酶有","o":["头孢菌素酶","羧苄西林酶","金属酶","头孢菌素类","非金属碳青霉烯酶"],"a":1,"e":"质粒介导的β-内酰胺酶主要有羧苄西林酶和AmpC酶等，可随质粒在菌间迅速传播。头孢菌素酶多由染色体编码，金属酶与非金属碳青霉烯酶属碳青霉烯酶类，头孢菌素类则是药物而非酶，均不符合题意"},{"q":"使形成原生质体的细菌发生融合，获得多种类型重组融合体，称为","o":["转化","接合","转导","溶原性转换","原生质融合"],"a":4,"e":"去除细胞壁形成原生质体后，在聚乙二醇等作用下可使两个原生质体融合，获得兼具双方遗传性状的重组融合体，称原生质体融合。转化是摄取裸DNA，接合经性菌毛传递质粒，转导由噬菌体介导，溶原性转换是噬菌体基因整合"},{"q":"与麻疹患者密切接触后的易感者应尽早采取的措施是","o":["注射抗毒素","接种麻疹疫苗","服用抗生素","注射丙种球蛋白","服用中草药"],"a":3,"e":"与麻疹病人密切接触的易感者应尽早注射人丙种球蛋白作紧急被动免疫，可阻止发病或减轻症状，因抗体立即生效而疫苗需2～4周才产生保护。抗毒素只中和外毒素，对病毒无效；抗生素对病毒无效；接种麻疹疫苗用于常规免疫，暴露后单用来不及"},{"q":"婴幼儿麻疹病毒感染最常见的并发症是","o":["脑膜炎","结膜炎","肺炎","脑脊髓炎","亚急性硬化性全脑炎"],"a":2,"e":"麻疹患儿抵抗力低下、呼吸道黏膜受损，最常见并发症为细菌性肺炎，其次为中耳炎与支气管炎，多由肺炎链球菌、金黄色葡萄球菌继发感染引起。脑炎是最严重并发症，SSPE为病愈后5～15年的迟发并发症，均非常见"},{"q":"下列细菌中均能引起食物中毒，但临床不表现为急性胃肠炎症状的是","o":["金黄色葡萄球菌","肉毒梭菌","肠炎沙门菌","副溶血弧菌","产气荚膜梭菌"],"a":1,"e":"肉毒梭菌在厌氧条件下产生肉毒毒素，毒素吸收入血后作用于胆碱能神经末梢，阻断乙酰胆碱释放，表现为眼睑下垂、复视、吞咽困难、呼吸肌麻痹，胃肠道症状轻或缺如。金葡菌、沙门菌、副溶血弧菌、产气荚膜梭菌的食物中毒均以恶心、呕吐、腹泻为主"},{"q":"目前已知的最小DNA病毒是","o":["人类博卡病毒","丁型肝炎病毒","鼻病毒","人乳头瘤病毒","EB病毒"],"a":0,"e":"人类博卡病毒属细小病毒科，为无包膜的单链DNA病毒，基因组约5kb，是目前已知最小的DNA病毒。丁型肝炎病毒是最小的RNA病毒；鼻病毒为RNA病毒；HPV与EBV虽为DNA病毒，基因组均远大于博卡病毒"},{"q":"支原体与细菌的不同点是","o":["含有核糖体","含有两种核酸","能在人工培养基上生长","无细胞壁","细胞核无核膜及核仁，仅有核质"],"a":3,"e":"支原体是自然界中唯一无细胞壁而能独立生活的原核细胞型微生物，故无固定形态、呈多形性，对β-内酰胺类天然耐药。含核糖体、含DNA和RNA两种核酸、可在人工培养基上生长、核质无核膜核仁，这些均与细菌相同"},{"q":"启动HIV转录的基因是","o":["vif","tat","rev","nef","vpu"],"a":1,"e":"tat基因编码Tat蛋白，与LTR中的TAR序列结合，反式激活病毒基因组转录，是启动HIV转录的关键调控基因。rev促进病毒mRNA核输出，nef下调CD4与MHC表达，vif、vpu参与病毒颗粒感染性与释放，均不启动转录"},{"q":"以下用于治疗HIV感染的药物不包括","o":["PI","AZT","NRTI","Amoxicillin","INSTI"],"a":3,"e":"Amoxicillin为氨基青霉素，作用于细菌细胞壁，对HIV无抑制作用。PI为蛋白酶抑制剂，AZT为核苷类逆转录酶抑制剂，NRTI为非核苷类逆转录酶抑制剂，INSTI为整合酶抑制剂，均属抗HIV药物"},{"q":"机体获得人工主动免疫的方式是","o":["注射类毒素","注射抗毒素","注射细胞因子","注射胎盘球蛋白","通过胎盘从母体获得"],"a":0,"e":"人工主动免疫是接种抗原性生物制品，使机体自身产生抗体，注射类毒素属此类，免疫力出现慢但可维持数年。抗毒素、胎盘球蛋白、细胞因子均为人工被动免疫制剂，直接输入现成抗体或因子；经胎盘从母体获得属自然被动免疫"},{"q":"下列病毒感染后不会透过血脑屏障","o":["乙脑病毒","麻疹病毒","登革病毒","乳头瘤病毒","柯萨奇病毒"],"a":3,"e":"人乳头瘤病毒嗜上皮性，感染皮肤与黏膜上皮细胞，不进入血流，也不侵犯中枢神经系统，故不透过血脑屏障。乙脑病毒经血流突破血脑屏障；麻疹病毒可致SSPE；登革病毒与柯萨奇病毒均可入血并累及中枢神经系统"},{"q":"用灭活疫苗预防的疾病有","o":["麻疹","狂犬病","登革热","风疹","腮腺炎"],"a":1,"e":"狂犬病疫苗为灭活疫苗，用理化方法灭活病毒而保留抗原性，暴露后接种可诱导主动免疫。麻疹、风疹、腮腺炎均使用减毒活疫苗，登革热疫苗亦以减毒活疫苗为主，故均不属灭活疫苗。减毒活疫苗能在体内复制，免疫效果更持久"},{"q":"可辅助HDV复制的病毒是","o":["HAV","HBV","HCV","HEV","HSV"],"a":1,"e":"HDV是缺陷病毒，基因组仅1.7kb，只编码HDAg，其包膜HBsAg及复制所必需的辅助功能均由HBV提供，须与HBV共同感染才能产生具感染性的颗粒。HAV、HEV为独立复制的小RNA病毒；HCV属黄病毒科，可自主复制；HSV为双链DNA病毒，与HDV无关"},{"q":"关于噬菌体可用于细菌性感染治疗的叙述错误的是","o":["特定的噬菌体只可用于相应敏感细菌感染的治疗","治疗具有广谱性","不易造成菌群失调","不易造成耐药","对某些易产生耐药性的细菌治疗有较大的应用价值"],"a":1,"e":"噬菌体与宿主菌受体结合具有种和型的特异性，只裂解相应细菌，治疗谱窄，故“治疗具有广谱性”错误。正因窄谱，它不易破坏正常菌群，细菌对其产生耐受也较少，对金黄色葡萄球菌、铜绿假单胞菌等易耐药菌感染有较大应用价值"},{"q":"关于R质粒决定的耐药性，下列说法错误的是","o":["所有致病菌都有耐药质粒","以多重耐药性常见","容易因质粒丢失成为敏感株","可从宿主菌检出R质粒","耐药性可经转导、转化方式进行转移"],"a":0,"e":"R质粒只存在于部分耐药菌株，并非所有致病菌都携带耐药质粒，故此项错误。R质粒常携带多个耐药基因，以多重耐药常见，可从宿主菌中检出，也可经接合、转导、转化在菌间转移；质粒可自行丢失，菌株随之恢复敏感"},{"q":"细胞壁缺陷的微生物是","o":["金黄色葡萄球菌","肺炎支原体","普氏立克次体","沙眼衣原体","L型细菌"],"a":1,"e":"支原体无细胞壁、仅具细胞膜，是天然细胞壁缺陷的原核细胞型微生物。L型细菌是细菌在青霉素、溶菌酶等诱导下失去细胞壁形成的变异型，去除诱因后部分可回复，不属独立菌种。螺旋体、立克次体、衣原体均有细胞壁，仅结构特殊"},{"q":"目前我国引起细菌性痢疾病原菌排第一位的是","o":["痢疾志贺菌1型","宋氏志贺菌","福氏志贺菌","痢疾志贺菌2型","鲍氏志贺菌"],"a":2,"e":"我国志贺菌感染以福氏志贺菌与宋内志贺菌为主，其中福氏志贺菌居首位，且感染易转为慢性、病程迁延。宋内志贺菌多引起轻型感染，痢疾志贺菌1型产志贺毒素、病情最重但少见，鲍氏志贺菌仅见局部散发"},{"q":"下列疾病出现皮肤慢性移行性红斑的是","o":["莱姆病","梅毒","品他病","雅司","足菌肿"],"a":0,"e":"慢性移行性红斑是莱姆病的特征性早期皮损，由伯氏疏螺旋体经蜱叮咬传播，初为红色斑疹，扩大成边缘鲜红、中央退行的环状损害。梅毒的特征皮损为硬下疳与梅毒疹；雅司病与品他病均属地方性密螺旋体病，表现为皮肤斑疹、丘疹与色素改变；足菌肿为真菌或放线菌所致足部肿胀与窦道"},{"q":"急性病毒感染引起的炎症反应中，炎性细胞主要是","o":["中性粒细胞","淋巴细胞","嗜酸性粒细胞","嗜碱性粒细胞","NK细胞"],"a":1,"e":"急性病毒感染时，病毒在细胞内复制并诱生干扰素和趋化因子，浸润的炎性细胞以淋巴细胞和单核细胞为主。中性粒细胞是急性细菌性炎症的主要细胞；嗜酸性粒细胞见于寄生虫感染和超敏反应；NK细胞属固有免疫细胞，不构成主要浸润细胞"},{"q":"口服脊髓灰质炎减毒活疫苗的优点不包括","o":["口服方便，儿童易于接受","易保存不需冷藏","可刺激机体产生血清中和抗体IgG","疫苗病毒随粪便排出，扩大了免疫范围","疫苗病毒在肠道增殖，产生局部sIgA可以阻断野毒株的感染"],"a":1,"e":"口服脊灰减毒活疫苗稳定性差，需冷藏保存，4℃仅存活2周，故“易保存不需冷藏”不属于其优点。该疫苗口服方便，可在肠道增殖产生sIgA阻断野毒株，同时诱生血清中和抗体IgG，疫苗病毒随粪便排出还可扩大免疫范围，A、C、D、E均为其优点"},{"q":"通过疫苗接种目前已经被消灭的传染病是","o":["小儿麻痹症","麻疹","天花","乙型脑炎","白喉"],"a":2,"e":"天花病毒经全球疫苗接种计划已于1980年被彻底消灭。脊髓灰质炎野毒株仅在少数地区流行，尚未全球消灭；麻疹、乙型脑炎、白喉仍有流行，疫苗接种只能控制发病。故目前已被消灭的仅天花"},{"q":"当血循环中钩体被清除后，下列哪个器官或组织中仍可能存在致病性钩端螺旋体","o":["肌肉","心脏","肾脏","脑","肝"],"a":2,"e":"特异性抗体能调理、凝集、溶解血中钩端螺旋体，但对肾脏内的菌体作用不明显，故血循环清除后肾脏仍带菌，尿中可长期甚至终身排菌。肝、脑、肌肉的损害发生于菌血症期，随血中菌体清除而消退，肾脏是唯一持续存菌的器官"},{"q":"目前有特异性疫苗可供预防的病毒性疾病组合是","o":["甲型肝炎、戊型肝炎、丙型肝炎、狂犬病","甲型肝炎、乙型肝炎、丁型肝炎、乙型脑炎","丙型肝炎、丁型肝炎、乙型脑炎、狂犬病","丁型肝炎、脊髓灰质炎、艾滋病、水痘","乙型肝炎、戊型肝炎、脊髓灰质炎、登革热"],"a":1,"e":"甲肝、乙肝、乙脑均有特异性疫苗，丁肝无独立疫苗，但HDV为缺陷病毒、需HBV辅助复制，接种乙肝疫苗即可阻断其感染，故该组合成立。丙肝、戊肝、艾滋病、登革热目前均无上市的特异性疫苗，含这些病种的组合不成立"},{"q":"质粒是细菌的","o":["核质DNA","胞质中的rRNA","胞质中的cDNA","染色体外的DNA","胞质颗粒"],"a":3,"e":"质粒是细菌染色体以外、能独立复制的遗传物质，多为闭合环状双链DNA，存在于胞质中，可携带耐药、毒力等基因。核质DNA即细菌染色体；rRNA、cDNA均非质粒本质；胞质颗粒多为营养贮存物，无遗传功能"},{"q":"青霉素导致革兰阳性菌死亡的机制是","o":["裂解磷壁酸","损伤细胞膜","抑制菌体蛋白质的合成","裂解肽聚糖的聚糖骨架","抑制肽聚糖中五肽交联桥与四肽侧链的连接"],"a":4,"e":"青霉素与青霉素结合蛋白结合，抑制转肽酶，阻碍四肽侧链与五肽交联桥的连接，使肽聚糖交联受阻、细胞壁缺损，细菌在低渗环境肿胀裂解。损伤细胞膜者是多黏菌素，抑制菌体蛋白质合成者是氨基糖苷类与氯霉素，裂解磷壁酸并无相应药物机制"},{"q":"一期梅毒患者，检查病原体应取的标本是","o":["梅毒疹渗出液","下疳渗出液","脑脊液","血液","尿液"],"a":1,"e":"一期梅毒的特征性损害是硬下疳，其渗出液含梅毒螺旋体最多，是病原学检查的最适标本，可用暗视野显微镜直接观察。梅毒疹渗出液属二期损害，脑脊液用于神经梅毒，血液和尿液含菌量低，不作直接镜检标本"},{"q":"下列哪种病毒形成的持续性感染与其他病毒不同","o":["乙肝病毒","麻疹病毒","丙肝病毒","巨细胞病毒","EB病毒"],"a":1,"e":"麻疹病毒所致的SSPE属慢发病毒感染，病毒在体内长期潜伏，数年后才发病，病程进行性加重直至死亡，与其他病毒的持续感染形式不同。HBV、HCV引起慢性持续性感染；CMV、EBV感染后病毒基因组潜伏于细胞，属潜伏感染，激活后引起再发"},{"q":"在EBV血清学诊断中，异嗜性抗体主要用于诊断的疾病是","o":["非洲儿童恶性淋巴瘤","鼻咽癌","舌毛状白斑病","传染性单核细胞增多症","霍奇金淋巴瘤"],"a":3,"e":"EBV感染后非特异性活化B淋巴细胞，产生异嗜性抗体，可凝集绵羊红细胞，用于传染性单核细胞增多症的辅助诊断。鼻咽癌诊断依靠EA-IgA和VCA-IgA，非洲儿童恶性淋巴瘤和霍奇金淋巴瘤靠病理与EBV核酸检测，舌毛状白斑见于艾滋病"},{"q":"有关细菌芽胞正确的描述是","o":["是细菌的繁殖方式","染色时易着色","维持生命的必须结构","一个细菌可形成多个芽胞","对不良环境有强抵抗力"],"a":4,"e":"芽胞含水量少、核心含吡啶二羧酸钙、有多层致密芽胞壳，对热、干燥、辐射和化学消毒剂均有强大抵抗力，是灭菌是否彻底的标志。芽胞不是繁殖方式，一个细菌只形成一个芽胞，也不是维持生命的必需结构；芽胞壁厚致密，普通染色不易着色，需芽胞染色法"},{"q":"口服脊髓灰质炎减毒活疫苗的首次服用和加强免疫年龄分别为","o":["新生儿，4岁","2月龄，4岁","2月龄，6岁","4月龄，4岁","6月龄，4岁"],"a":1,"e":"口服脊髓灰质炎减毒活疫苗首剂于2月龄服用，4岁时加强免疫一次。该疫苗口服后类似自然感染，既诱生血清中和抗体，又刺激肠道产生sIgA。新生儿免疫系统未成熟且有母体抗体干扰，6月龄已过首次接种时机"},{"q":"链球菌可分为20个群，分群的根据是","o":["P抗原不同","C多糖抗原不同","对氧的需要不同","M蛋白不同","溶血素不同"],"a":1,"e":"链球菌按细胞壁中C多糖抗原的不同分为A～H、K～V共20群，对人致病的约90%属A群。M蛋白用于同群内分血清型，P抗原为无特异性的核蛋白抗原，溶血素和对氧需要不是分群依据。群特异抗原位于细胞壁多糖，型特异抗原则为M蛋白"},{"q":"关于人巨细胞病毒的描述，正确的是","o":["有多个血清型","人类是其唯一宿主","有敏感的动物模型","体外培养尚未成功","对脂溶剂不敏感"],"a":1,"e":"人巨细胞病毒种属特异性高，只感染人，人类是其唯一宿主，实验动物不敏感，也无理想动物模型。该病毒只有一个血清型，体外可在人成纤维细胞中培养成功，且具包膜，对乙醚等脂溶剂敏感，故其余描述均错"},{"q":"与HIV-1逆转录过程密切相关的病毒基因是","o":["env","pol","rev","gag","vpu"],"a":1,"e":"pol基因编码逆转录酶、整合酶和蛋白酶，HIV-1基因组RNA逆转录为双链DNA即由逆转录酶完成。env编码gp120与gp41，gag编码衣壳、核壳和基质蛋白，rev、vpu、vif为调控基因，均不参与逆转录"},{"q":"吡啶二羧酸主要存在于","o":["细菌细胞壁","细菌细胞膜","细菌荚膜","细菌菌毛","细菌芽孢"],"a":4,"e":"吡啶二羧酸存在于芽胞的核心与皮质中，与钙结合成盐，可提高芽胞内酶的热稳定性，是芽胞耐热的物质基础之一，为芽胞特有的成分。细菌细胞壁含肽聚糖与磷壁酸，细胞膜含磷脂与蛋白，荚膜为多糖，菌毛为蛋白，均不含吡啶二羧酸"},{"q":"质粒在细菌间的转移方式主要是","o":["转化","接合","转导","溶原性转换","原生质融合"],"a":1,"e":"质粒可通过接合、转化、转导等方式在细菌间转移，其中经性菌毛接合传递最为常见，R质粒即借此迅速播散。转化是摄取游离DNA，转导由噬菌体介导，溶原性转换是前噬菌体基因表达，原生质融合为实验手段，均非质粒自然转移的主要方式"},{"q":"革兰阴性菌的性菌毛的特点是","o":["化学成分为多糖","与细菌的运动有关","介导细菌遗传物质交换","是细菌转化时必要结构","吸附易感细胞的细菌结构"],"a":2,"e":"性菌毛由质粒基因编码，比普通菌毛粗长，末端有受体，可在供、受菌间形成接合管传递质粒DNA，介导遗传物质交换。运动器官是鞭毛；吸附易感细胞的是普通菌毛；转化只需感受态，不依赖性菌毛"},{"q":"对人致病的链球菌主要是","o":["A群链球菌","B群链球菌","C群链球菌","D群链球菌","E群链球菌"],"a":0,"e":"链球菌中A群即化脓性链球菌对人毒力最强，引起咽炎、猩红热、丹毒及风湿热、急性肾小球肾炎等超敏反应性疾病。B群主要致新生儿败血症和脑膜炎；D群肠球菌致尿路感染和心内膜炎；C、E群很少对人致病"},{"q":"与细菌致育性有关的质粒是","o":["F质粒","R质粒","Col质粒","毒力质粒","代谢质粒"],"a":0,"e":"F质粒即致育质粒，编码性菌毛，介导细菌间质粒的接合传递，含F质粒者为F+菌，接合时作供体。R质粒编码耐药性；Col质粒编码大肠菌素；毒力质粒编码毒力因子；代谢质粒编码特殊代谢酶，均不决定致育性"},{"q":"对脂溶剂不敏感的病毒是","o":["HAV","HBV","HCV","HDV","HSV"],"a":0,"e":"HAV为无包膜的小RNA病毒，不含脂质，对乙醚、氯仿等脂溶剂耐受。HBV、HCV、HDV均有包膜，HSV为有包膜的双链DNA病毒，脂溶剂可溶解其包膜脂质而使之灭活，故均对脂溶剂敏感"},{"q":"对神经细胞具有高度亲和力的病毒是","o":["人类免疫缺陷病毒","乙型肝炎病毒","EB病毒","甲型肝炎病毒","狂犬病病毒"],"a":4,"e":"狂犬病病毒属弹状病毒科，是嗜神经性病毒，经咬伤部位横纹肌增殖后沿神经轴索向中枢逆行扩散，在神经细胞内增殖致病。HIV攻击CD4⁺T细胞，HBV嗜肝细胞，EBV嗜B淋巴细胞，HAV嗜肝细胞，均不以神经细胞为主要靶细胞"},{"q":"下列病毒中不能经垂直传播的是","o":["巨细胞病毒","风疹病毒","乙型肝炎病毒","脊髓灰质炎病毒","单纯疱疹病毒"],"a":3,"e":"脊髓灰质炎病毒主要经粪-口和呼吸道传播，不通过胎盘或产道传播。巨细胞病毒、风疹病毒、乙型肝炎病毒、单纯疱疹病毒均可经胎盘、产道或哺乳引起宫内感染和围产期感染，故不能垂直传播者为脊髓灰质炎病毒"},{"q":"整合在细菌染色体上的噬菌体核酸是","o":["前噬菌体","毒性噬菌体","温和噬菌体","子代噬菌体","溶原性噬菌体"],"a":0,"e":"温和噬菌体基因组整合于宿主菌染色体，整合状态下的噬菌体基因称为前噬菌体，随细菌染色体复制传给子代。毒性噬菌体只进行溶菌性增殖。子代噬菌体是复制后装配的颗粒。溶原性噬菌体指具溶原周期的噬菌体本身，而非整合状态的核酸"},{"q":"下列用于培养病毒的方法中最常用的是","o":["家兔接种","小白鼠接种","鸡胚","组织细胞","灵长类动物"],"a":3,"e":"病毒培养有组织细胞培养、鸡胚接种和动物接种三种，其中组织细胞培养最常用，可观察细胞病变、做空斑计数和中和试验。鸡胚多用于流感病毒初次分离；小鼠、家兔等动物接种仅用于特定病毒，已逐步被细胞培养替代"},{"q":"卫星现象可用于鉴别","o":["百日咳鲍特菌","流感嗜血杆菌","白喉棒状杆菌","金黄色葡萄球菌","甲型链球菌"],"a":1,"e":"金黄色葡萄球菌能合成并释放Ⅴ因子，在血平板上使周围的流感嗜血杆菌菌落增大，离金葡菌越远菌落越小，即卫星现象，用于鉴定流感嗜血杆菌。百日咳鲍特菌、白喉棒状杆菌、甲型链球菌无此现象；金葡菌本身不需Ⅴ因子"},{"q":"新生儿“脓漏眼”的病原体是","o":["脑膜炎奈瑟菌","淋病奈瑟菌","肺炎链球菌","衣原体","支原体"],"a":1,"e":"新生儿脓漏眼由淋病奈瑟菌引起，分娩时经患淋病母亲的产道感染，表现为结膜大量脓性分泌物，可致角膜溃疡穿孔。脑膜炎奈瑟菌引起流脑，肺炎链球菌引起肺炎，衣原体可引起包涵体结膜炎但分泌物较少，支原体不引起化脓性结膜炎"},{"q":"结核菌素试验的应用价值不包括","o":["选择卡介苗接种对象","检测卡介苗接种的免疫效果","成人结核病的诊断依据","肿瘤患者的细胞免疫功能测定","对未接种卡介苗的人群进行结核病流行病学调查"],"a":2,"e":"结核菌素试验用于选择卡介苗接种对象、检测接种后的细胞免疫效果、对未接种儿童作流行病学调查，也可评价肿瘤等患者的细胞免疫功能。成人多已感染，结核菌素试验阳性只说明曾感染或接种，不能作为成人结核病的诊断依据"},{"q":"HCMV的潜伏部位不包括","o":["唾液腺","乳腺","骶神经节","肾脏","淋巴细胞"],"a":2,"e":"HCMV潜伏于髓系前体细胞、分泌性腺体、肾脏和白细胞等，故唾液腺、乳腺、肾脏、淋巴细胞均可为其潜伏部位。骶神经节是HSV-2的潜伏部位，HSV-1潜伏于三叉神经节和颈上神经节，故C项不属于HCMV潜伏部位"},{"q":"无须接受HBIG被动免疫的人群是","o":["HBsAg阳性母亲所生的新生儿","输入了HBsAg阳性血液者","接受了HBsAg阳性器官的移植者","体表破损处沾染了HBsAg阳性血清者","无症状HBsAg携带者"],"a":4,"e":"无症状HBsAg携带者已处于感染状态，注射乙肝免疫球蛋白无预防意义。HBsAg阳性母亲所生新生儿、输入HBsAg阳性血液者、接受阳性器官移植者以及破损皮肤沾染阳性血清者，均属暴露后高危人群，应尽早注射HBIG并全程接种乙肝疫苗"},{"q":"ETEC产生的不耐热肠毒素的致病机制是","o":["吸附","A亚单位穿越细胞膜与腺苷酸环化酶作用","聚集性黏附","引起核糖体功能障碍","激活鸟苷酸环化酶"],"a":1,"e":"ETEC不耐热肠毒素由1个A亚单位与5个B亚单位组成，B亚单位结合肠上皮细胞GM1神经节苷脂，介导A亚单位穿膜并激活腺苷酸环化酶，使cAMP升高、肠黏膜分泌亢进致水样腹泻。耐热肠毒素则激活鸟苷酸环化酶"},{"q":"下列细菌中生长繁殖速度最慢的细菌是","o":["肺炎链球菌","A群链球菌","大肠埃希菌","结核分枝杆菌","脑膜炎奈瑟菌"],"a":3,"e":"结核分枝杆菌含大量脂质，营养要求高，专性需氧，增殖缓慢，代时约18～24小时，培养需2～4周才见菌落，故为最慢者。肺炎链球菌、A群链球菌、大肠埃希菌与脑膜炎奈瑟菌代时均约20～60分钟，18～24小时即可形成菌落"},{"q":"编码抗菌药物耐药性的是","o":["F质粒","R质粒","Col质粒","Vi质粒","代谢质粒"],"a":1,"e":"R质粒为接合性耐药质粒，携带耐药基因，可经接合在细菌间传递，是耐药性播散的主要载体。F质粒编码性菌毛，决定致育性；Col质粒编码大肠菌素；Vi质粒编码沙门菌Vi抗原；代谢质粒编码特殊代谢酶，均不决定耐药性"},{"q":"轮状病毒的核酸类型是","o":["分节段的双链RNA","分节段的单负链RNA","单正链RNA","单链DNA","双链DNA"],"a":0,"e":"轮状病毒属呼肠孤病毒科，基因组为11个节段的双链RNA，分节段的特点使其易发生基因重排。流感病毒为分节段单负链RNA，冠状病毒与脊髓灰质炎病毒为单正链RNA，乙肝病毒为部分双链DNA"},{"q":"可致严重急性呼吸综合征的病原体是","o":["冠状病毒229E","SARS冠状病毒","MERS冠状病毒","鼻病毒","3型腺病毒"],"a":1,"e":"SARS冠状病毒是严重急性呼吸综合征的病原体，属β冠状病毒属，经飞沫和接触传播，引起弥漫性肺损伤。HCoV-229E、HCoV-HKU1仅致普通感冒；MERS冠状病毒引起中东呼吸综合征；鼻病毒致普通感冒；3型腺病毒致咽结膜热及呼吸道感染"},{"q":"下列说法错误的是","o":["病毒对抗生素不敏感","病毒对干扰素敏感","病毒体由核酸和核糖体构成","病毒只能在活细胞内增殖","病毒是一类非细胞形态的微生物"],"a":2,"e":"病毒体由核酸和蛋白质衣壳构成，有的外包脂质包膜，不含核糖体、线粒体等细胞器，故此项错误。病毒无细胞结构，只能在活细胞内增殖，对抗生素不敏感而对干扰素敏感，其余各项均正确。裸露病毒仅有核衣壳，同样不含核糖体"},{"q":"细菌对糖的分解能力不同，主要是因为","o":["酶系统不同","营养型不同","糖的种类不同","氧气存在与否","细胞膜通透性不同"],"a":0,"e":"不同细菌含有的酶系统不同，对糖的酵解途径与终产物各异，故发酵能力与产酸产气表现不同，是生化反应鉴别细菌的基础。营养型不同决定营养需求；糖的种类与氧气条件影响结果但不决定细菌固有的分解能力；细胞膜通透性只影响底物进入速度"},{"q":"引发亚急性硬化性全脑炎（SSPE）的病因是","o":["麻疹病毒引起的持续性感染","疱疹病毒引起的潜伏感染","脊髓灰质炎病毒引起的慢性感染","流行性乙型脑炎病毒引起的急性感染","狂犬病病毒引起的慢发感染"],"a":0,"e":"SSPE是麻疹病毒在脑组织长期存留引起的慢发病毒感染，发生于麻疹痊愈后5～15年，表现为进行性大脑衰退。疱疹病毒引起潜伏感染，脊髓灰质炎病毒与乙脑病毒为急性感染，狂犬病为急性脑脊髓炎"},{"q":"在病毒复制的隐蔽期","o":["能查到病毒颗粒","能测到病毒抗原","既能查到病毒颗粒又能测到病毒抗原","既查不到病毒颗粒又测不到病毒抗原","能查到病毒颗粒但测不到病毒抗原"],"a":3,"e":"隐蔽期指病毒脱壳后至子代病毒装配释放前的阶段，此时病毒核酸和蛋白在细胞内合成，但尚无完整病毒颗粒，抗原尚未组装成可检测形式，故两者均查不到。该期是病毒复制最活跃的阶段，持续数小时至数十小时"},{"q":"预防脊髓灰质炎进行人工自动免疫的主要对象是","o":["野外工作者","青壮年","林区工人","老年人","5岁以内的儿童"],"a":4,"e":"脊髓灰质炎主要侵犯儿童，5岁以内小儿易感，故人工主动免疫对象为5岁以内儿童，常规于2、3、4月龄基础免疫。青壮年、老年人、野外工作者和林区工人多已通过隐性感染获得免疫，不是重点接种对象"},{"q":"孕妇感染风疹病毒引起胎儿患先天性风疹综合征的发病率最高的时期是","o":["怀孕中期","孕期最初20周","孕期最后3个月","孕期最后1个月","分娩前后"],"a":1,"e":"风疹病毒经胎盘感染胎儿，孕20周内尤其妊娠3个月内胎盘屏障尚不完善，感染危害最大、致畸率最高，可致先天性心脏病、耳聋、白内障。孕晚期感染时胎儿器官已分化完成，畸形少见，多为迟发性损害"},{"q":"G－细胞壁特有成分是","o":["磷壁酸","肽聚糖","多聚糖","外膜","中介体"],"a":3,"e":"外膜是革兰阴性菌细胞壁特有的结构，由脂蛋白、脂质双层和脂多糖组成，约占细胞壁干重80%。磷壁酸为革兰阳性菌特有；肽聚糖为两类细菌共有；中介体是细胞膜内陷形成的结构，与呼吸和分裂有关"},{"q":"关于顿挫感染，正确的是","o":["因宿主细胞内有相应抑制物","因宿主细胞DNA有关基因激活","因宿主细胞缺乏有关酶","因感染病毒有核酸缺失","因感染病毒抗原性转变"],"a":2,"e":"顿挫感染发生于非容纳细胞，因细胞缺乏病毒复制所需的酶、能量和原料，病毒不能完成复制，产生不了完整病毒体。缺陷病毒因基因组缺失需辅助病毒相助；抗原性转变属抗原变异；细胞抑制物、细胞DNA基因激活均非其机制"},{"q":"外毒素的化学性质是","o":["脂类","多糖","蛋白质","氨基酸","脂多糖"],"a":2,"e":"外毒素是细菌合成并分泌的蛋白质，多为A-B型结构，不耐热，65℃30分钟即被破坏，抗原性强，经甲醛处理可制成类毒素。内毒素的化学本质是脂多糖，属细胞壁成分；多糖、脂类、氨基酸均不构成外毒素"},{"q":"支原体的主要繁殖方式是","o":["二分裂","出芽","核酸复制","断裂","细胞融合"],"a":0,"e":"支原体以二分裂为主要繁殖方式，另有断裂、出芽与分枝等方式，因无细胞壁而呈多形性。核酸复制是病毒的增殖方式，出芽为包膜病毒的释放方式，细胞融合为病毒扩散及细胞病变的形式，均非支原体的繁殖方式"},{"q":"分枝杆菌属细菌最主要的特点是","o":["胞壁含大量脂质","无特殊结构","有分枝生长趋势","一般不易着色","抵抗酸性酒精脱色"],"a":0,"e":"分枝杆菌属细胞壁脂质占干重60%以上，与阿拉伯半乳聚糖、分枝菌酸构成复合物，导致抗酸染色阳性、生长缓慢、抵抗力强及致病与超敏反应相关，故含脂质丰富是其主要特点。抗酸染色阳性仅为该特点的表现之一"},{"q":"下列病毒中能引起全身感染的是","o":["流感病毒","副流感病毒","鼻病毒","麻疹病毒","呼吸道合胞病毒"],"a":3,"e":"麻疹病毒经呼吸道侵入后先在局部淋巴结增殖，继而入血形成两次病毒血症，播散至皮肤、结膜、呼吸道及中枢神经系统，属典型全身感染。流感病毒、副流感病毒、鼻病毒、呼吸道合胞病毒多局限于呼吸道上皮，一般不形成病毒血症，故为局部感染"},{"q":"病毒复制过程中可产生RNA-DNA杂交体的是","o":["（＋）ssRNA病毒","dsRNA病毒","dsDNA病毒","逆转录病毒","（－）ssRNA病毒"],"a":3,"e":"逆转录病毒以基因组RNA为模板，在逆转录酶作用下合成cDNA，形成RNA-DNA杂交体，随后降解RNA链、合成双链DNA并整合为前病毒。正单链RNA病毒直接翻译或经复制酶合成负链，双链RNA病毒以RNA为模板复制，双链DNA病毒按DNA→RNA→蛋白质转录翻译，均不产生RNA-DNA杂交体"},{"q":"细菌培养物中，能代表纯种菌的是","o":["菌膜","菌苔","菌落","凝集物","沉淀物"],"a":2,"e":"一个菌落由单个细菌繁殖而成，挑取一个菌落移种可获纯种细菌，故菌落代表纯种菌。菌膜为液体表面生长的菌体，菌苔为固体表面密集生长的菌体群体，凝集物与沉淀物为抗原抗体反应或菌体沉淀，均不能代表纯种"},{"q":"与致病性相关的细菌结构是","o":["中介体","细胞膜","异染颗粒","芽孢","荚膜"],"a":4,"e":"荚膜位于细胞壁外，富含多糖或多肽，具有抗吞噬、抗杀菌物质的作用，是肺炎链球菌、炭疽芽孢杆菌的重要毒力因子，失去荚膜则致病力显著下降。中介体是细胞膜内陷折叠形成的结构，与呼吸酶活性和细胞分裂有关。异染颗粒是白喉棒状杆菌胞质内的储藏物，用于形态学鉴定。芽孢与抵抗力及鉴别相关，不属侵袭力结构"},{"q":"微生物学的奠基人是","o":["Edward Jenner","Louis Pasteur","Lister","Walter Reed","Antonyvan Leeuwenhoek"],"a":1,"e":"巴斯德用曲颈瓶实验否定自然发生说，并研制减毒疫苗，是微生物学的奠基人。郭霍发现结核分枝杆菌和霍乱弧菌并提出柯霍法则；秦纳发明牛痘接种预防天花；李斯特创用石炭酸消毒；列文虎克首次观察并描述细菌"},{"q":"下列哪项不属于机体正常组织和体液中的抗菌物质","o":["补体","溶菌酶","防御素","抗毒素","乙型溶素"],"a":4,"e":"官方答案为【乙型溶素】，但依据教材，正确答案为【抗毒素】。补体、溶菌酶、防御素与乙型溶素均属正常组织和体液中固有的抗菌物质，乙型溶素即正常体液中的β-溶素，教材明确列为体液杀菌分子。抗毒素是类毒素免疫马后提取的免疫球蛋白，属特异性抗体，须人工制备，不属于机体正常组织与体液中的抗菌物质"},{"q":"A组轮状病毒感染最常见的类型是","o":["隐性感染","潜伏感染","急性感染","慢性感染","慢发病毒感染"],"a":2,"e":"A组轮状病毒引起婴幼儿急性胃肠炎，多为急性感染，起病急、病程短，以水样泻和呕吐为主，易致脱水。潜伏感染见于HSV、VZV；慢性感染见于HCV、HBV；慢发病毒感染见于朊粒病和HIV感染"},{"q":"白喉棒状杆菌的主要传播途径是","o":["粪-口途径","飞沫传播","创伤感染","接触感染","垂直传播"],"a":1,"e":"白喉棒状杆菌存在于病人和带菌者的鼻咽分泌物中，经飞沫传播，最常侵犯咽、喉、气管和鼻腔黏膜，局部形成灰白色假膜。粪-口途径、创伤感染、接触感染和垂直传播均非其主要传播方式，人群普遍易感"},{"q":"不属于条件致病性真菌的是","o":["白假丝酵母菌","曲霉菌","毛霉菌","皮肤癣菌","新生隐球菌"],"a":3,"e":"皮肤癣菌亲角蛋白，侵犯皮肤角质层、毛发和甲板，引起浅部真菌病，属原发性致病真菌，而非机会致病性真菌。白念珠菌、曲霉、毛霉、新生隐球菌均在机体免疫力下降或菌群失调时致病，属条件致病性真菌"},{"q":"下列病毒中不能通过性接触传播的是","o":["HIV","HCV","HBV","HSV-2","HPV"],"a":1,"e":"HCV主要经输血和血制品传播，性接触和家庭密切接触虽可传播但非主要途径，母婴传播罕见，故在所列病毒中最不符合性接触传播。HIV、HBV、HSV-2、HPV均以性接触为重要甚至主要传播途径"},{"q":"以下关于朊粒病的防治原则，描述错误的是","o":["牛海绵状脑病的骨肉粉不可作为饲料使用","缺乏有效药物","对染病动物的体液需用漂白粉溶液处理2小时以上","高危人群可接种朊粒疫苗","朊粒病患者的器官不可用于器官移植"],"a":3,"e":"朊粒病目前既无有效药物，也无疫苗可供免疫预防，故高危人群接种朊粒疫苗错误。防制依靠切断传播途径：禁止用牛海绵状脑病动物的骨肉粉作饲料，病人器官不用于移植，污染物用次氯酸钠或氢氧化钠浸泡并高压灭菌"},{"q":"与立克次体有共同抗原的细菌","o":["变形杆菌","大肠埃希菌","伤寒沙门菌","布氏杆菌","绿脓杆菌"],"a":0,"e":"变形杆菌X19、X2、XK菌株的O抗原与普氏立克次体、斑疹伤寒立克次体及恙虫病东方体有共同多糖抗原，可用外斐试验代替立克次体抗原检测病人血清抗体。大肠埃希菌、伤寒沙门菌、布氏杆菌、铜绿假单胞菌均无此交叉抗原"},{"q":"支原体感染选择哪类药物最敏感","o":["影响胞膜蛋白和胞浆蛋白合成的抗生素","阻断肽聚糖合成的抗生素","使细胞壁通透性增加的抗生素","抑制磷壁酸合成的抗生素","破坏细胞壁的抗生素"],"a":0,"e":"支原体无细胞壁，对作用于细胞壁的β-内酰胺类天然耐药，故应选干扰蛋白质合成的四环素类、大环内酯类及抑制DNA旋转酶的喹诺酮类。阻断肽聚糖合成、破坏细胞壁或增加胞壁通透性的药物对其无效"},{"q":"下列有关病毒感染的描述中，正确的是","o":["病毒在人群个体间的相互传播为水平传播","母亲将病毒传给其子女的感染为垂直传播","病毒感染细胞造成的免疫病理损伤仅限于Ⅳ型超敏反应","病毒的慢性感染指的是慢发病毒感染","病毒感染后的无症状携带者不能产生任何抗病毒免疫反应"],"a":0,"e":"病原体在人群个体间经人-人、动物-人及媒介环境的传播称水平传播，流感即属此类。垂直传播专指孕妇经胎盘、产道或哺乳将病毒传给胎儿、新生儿，出生后经日常接触传播仍属水平传播。病毒所致免疫病理损伤可涉Ⅱ、Ⅲ、Ⅳ型超敏反应。慢性感染与慢发病毒感染是不同概念。无症状携带者同样产生抗病毒免疫应答"},{"q":"以鼠蚤为传播媒介的立克次体是","o":["普氏立克次体","斑疹伤寒立克次体","恙虫病立克次体","嗜吞噬细胞无形体","查菲埃立克体"],"a":1,"e":"斑疹伤寒立克次体又称莫氏立克次体，以鼠蚤为传播媒介，鼠蚤叮咬时把含菌粪便排于皮肤，经抓痕侵入，鼠蚤兼作储存宿主。普氏立克次体经人虱传播，引起流行性斑疹伤寒。恙虫病东方体由恙螨幼虫传播。嗜吞噬细胞无形体与查菲埃立克体均经蜱传播，分别引起人粒细胞无形体病与埃立克体病"},{"q":"产生致热外毒素的A群链球菌是由于细菌发生了","o":["接合","转化","转导","溶原性转换","原生质体融合"],"a":3,"e":"致热外毒素即红疹毒素，由携带噬菌体的A群链球菌产生，毒素基因随前噬菌体整合入宿主染色体，属溶原性转换。接合需质粒经性菌毛传递；转化是摄取裸DNA；转导转移的是供菌基因；原生质体融合为人工手段"},{"q":"肠热症患者并发症肠出血和肠穿孔的机理是","o":["第二次菌血症","细菌再次侵入肠壁淋巴组织，使组织发生超敏反应，导致局部的坏死和溃疡","沙门菌释放的内毒素","沙门菌释出的肠毒素","沙门菌具有的侵袭力"],"a":1,"e":"伤寒病程第2～3周，胆囊中的细菌随胆汁再次进入肠道，侵入已致敏的肠壁淋巴组织，引起迟发型超敏反应，导致局部坏死和溃疡，侵蚀血管则肠出血，穿透浆膜则肠穿孔。第二次菌血症是病程早期表现，内毒素、肠毒素和侵袭力不造成此类免疫性溃疡"},{"q":"基因工程疫苗是","o":["将编码保护性抗原的基因重组到质粒表达载体上，导入宿主体内","是提取病原体保护性抗原表位制成的疫苗","是将编码某一蛋白抗原的基因转入减毒的病毒或细菌制成的疫苗","将编码病原体保护性抗原表位的目的基因导入原核或真核表达系统中表达、纯化制成的疫苗","通过毒力变异或者自然选择制成的疫苗"],"a":3,"e":"基因工程疫苗是将编码保护性抗原的目的基因导入原核或真核表达系统，表达后纯化制成，重组HBsAg即属此类。将抗原基因插入质粒直接导入体内的是核酸疫苗；转入减毒病毒或细菌载体的是重组载体疫苗；提取抗原表位制成的是亚单位疫苗；经毒力变异选育的是减毒活疫苗"},{"q":"噬菌体在分类上属于","o":["细菌","病毒","真菌","支原体","衣原体"],"a":1,"e":"噬菌体是感染细菌、真菌等微生物的病毒，具备病毒的全部基本特性：只含一种核酸、无细胞结构、严格细胞内寄生、以复制方式增殖。故分类上属病毒，不属细菌、真菌、支原体或衣原体，其形态结构与复制方式与动物病毒一致"},{"q":"下列细菌毒素中毒性最强的是","o":["破伤风痉挛毒素","炭疽毒素","白喉外毒素","霍乱肠毒素","肉毒毒素"],"a":4,"e":"肉毒毒素是已知最剧烈的毒物，毒性比氰化钾强1万倍，纯结晶1mg可杀死2亿只小鼠，对人致死量约0.1μg，属神经毒素，抑制乙酰胆碱释放。破伤风痉挛毒素毒性亦强但次之；白喉外毒素抑制蛋白合成；霍乱肠毒素激活腺苷酸环化酶致分泌性腹泻；炭疽毒素毒性相对低"},{"q":"乙型肝炎病毒的主要传播途径是","o":["呼吸道","血液、血制品","消化道","蚊虫叮咬","共用毛巾"],"a":1,"e":"HBV主要经血液、血制品及医源性途径传播，感染者血液中病毒载量高，微量污染血即可致感染，性接触和母婴传播亦常见。消化道传播是HAV、HEV的主要途径；蚊虫叮咬、共用毛巾不传播HBV。故血液、血制品为最主要途径"},{"q":"流感病毒分亚型的依据是","o":["核蛋白（NP）和基质蛋白（MP）","神经氨酸酶（NA）和血凝素（HA）","RNA依赖的RNA聚合酶","基质蛋白（MP）","所致疾病的临床特征"],"a":1,"e":"流感病毒按核蛋白和基质蛋白抗原性分为甲、乙、丙三型，型内再依表面血凝素和神经氨酸酶抗原性划分亚型，故HA和NA是分亚型依据。NP和MP用于分型；RNA聚合酶和临床特征不用于分型。HA和NA的抗原变异是流感大流行的基础"},{"q":"朊粒病的特点主要有","o":["可通过破损的皮肤而感染","可发生潜伏感染","潜伏期很短","可注射疫苗进行预防","朊粒的免疫原性很强"],"a":0,"e":"朊粒可经破损皮肤黏膜、角膜移植、污染的手术器械或生长激素注射传播，属医源性感染。其潜伏期极长，可达数年至数十年；机体对朊粒不发生免疫应答，免疫原性极弱，也无疫苗可用，故其余各项均错"},{"q":"除携带与转座有关的基因外，常带有耐药基因的遗传物质是","o":["噬菌体","R质粒","转座子","插入序列","细菌染色体"],"a":2,"e":"转座子除携带转座酶等与转座有关的基因外，常整合耐药基因、抗重金属基因和毒力基因，随转座在质粒与染色体间扩散。插入序列最短、只编码转座酶；噬菌体携带的是自身基因；细菌染色体为耐药基因的最终所在地，不是本题所指的转移元件"},{"q":"皮肤癣菌侵犯部位仅限于表皮、毛发和指甲，是因为皮肤癣菌","o":["嗜油脂","嗜角质蛋白","缺乏正常菌群的保护","其受体存在于这些组织上","这些部位易通过接触传染"],"a":1,"e":"皮肤癣菌共同特点是亲角蛋白，可侵犯皮肤角质层、毛发和甲板，故病变限于表皮、毛发与指甲，不侵入深部组织，也不引起全身感染。嗜油脂见于马拉色菌等嗜脂性酵母；受体学说不能解释其限定部位；局部无正常菌群保护并非原因"},{"q":"无细胞壁结构的原核细胞型微生物是","o":["螺旋体","衣原体","支原体","真菌","立克次体"],"a":2,"e":"支原体无细胞壁，仅具含胆固醇的细胞膜，是原核细胞型微生物中唯一无细胞壁者，故呈多形性、可通过滤菌器。螺旋体、衣原体、立克次体均有细胞壁；真菌属真核细胞型微生物，不属原核细胞型，其细胞壁含几丁质与葡聚糖"},{"q":"对青霉素类和头孢菌素类耐药的菌株，作用于药物的主要是","o":["甲基化酶","氨基糖苷类钝化酶","氯霉素乙酰转移酶","β-内酰胺酶","乳酸合成酶"],"a":3,"e":"β-内酰胺酶特异性地水解青霉素与头孢菌素的β-内酰胺环，使药物失去抗菌活性，是此类耐药的主要机制。氨基糖苷类钝化酶修饰氨基糖苷类，氯霉素乙酰转移酶灭活氯霉素，甲基化酶修饰药物靶位"},{"q":"确证HIV感染的检测方法是","o":["RIA","ELISA","WB实验","IFA","对流免疫电泳"],"a":2,"e":"HIV初筛用ELISA检测抗-HIV抗体，阳性者须以Western blot检测gag、pol、env等结构蛋白条带加以确证，故WB为确证试验。RIA、IFA、对流免疫电泳敏感性或特异性不足，只能作辅助；ELISA用于筛查而非确证"},{"q":"关于沙眼衣原体的致病物质正确的是","o":["外毒素","磷脂酶A","主要外膜蛋白","胶原酶","P1蛋白"],"a":2,"e":"沙眼衣原体的主要外膜蛋白MOMP既是型特异性抗原，又介导黏附、抗吞噬并参与致病，是重要致病物质。衣原体不产生外毒素。磷脂酶A是立克次体的致病物质，用于溶解宿主细胞膜。P1蛋白是淋病奈瑟菌的主要外膜蛋白。胶原酶见于产气荚膜梭菌等，与衣原体致病无关"},{"q":"与原发性肝细胞癌密切相关的病毒是","o":["HAV","HBV","HIV","HSV","HPV"],"a":1,"e":"HBV与原发性肝细胞癌密切相关，我国约80%的肝癌病人曾慢性感染HBV，HBsAg携带者发生肝癌的危险性较常人高200倍。HAV不引起慢性感染，HIV、HSV、HPV分别与艾滋病、疱疹及宫颈癌相关"},{"q":"可灭活肠道病毒的物质是","o":["脂溶剂","氧化剂","蛋白酶","胆盐","胃酸"],"a":1,"e":"肠道病毒无包膜，对脂溶剂、胆盐、胃酸与蛋白酶均有抵抗力，故能抵抗胃酸与胆汁顺利通过消化道传播，仅强氧化剂、紫外线及高温可将其灭活。脂溶剂用于鉴别病毒有无包膜，对肠道病毒几乎无作用"},{"q":"计划地将抗菌药物分期分批交替使用，其原因是","o":["节约抗菌药物","可将细菌彻底杀灭","按照病程要求","使疗效最好","使耐药基因发生回复突变"],"a":4,"e":"抗菌药物分期分批交替使用可使原先占优势的耐药突变株失去选择压力，敏感株重新占优势，耐药基因发生回复突变而回复为敏感表型，从而延缓耐药性发展。节约药物、按病程要求、追求最佳疗效均非交替用药的目的；彻底杀灭细菌在现实中难以实现，也不是该策略的依据"},{"q":"下列哪一项不是肠杆菌科的共同特性","o":["革兰阴性杆菌","兼性厌氧或需氧","少数有荚膜","多数有周鞭毛","多数有芽胞"],"a":4,"e":"肠杆菌科细菌均不产生芽胞，故“多数有芽胞”不属其共同特性。该科为中等大小革兰阴性杆菌，兼性厌氧或需氧，多数有周鞭毛，大多有菌毛，少数有荚膜或微荚膜，A、B、C、D均正确"},{"q":"受体菌直接摄取供体菌游离DNA而获得新的生物学性状的过程称为","o":["转化","接合","转导","溶原性转换","原生质融合"],"a":0,"e":"转化是受体菌处于感受态时直接摄取供体菌游离DNA片段，并整合于染色体而获得新性状。接合经性菌毛传递质粒，转导由噬菌体介导，溶原性转换为前噬菌体基因表达，原生质融合是人工诱导的细胞融合，均与题干描述不符"},{"q":"与prion的感染不相关的疾病是","o":["羊瘙痒病","库鲁病","牛海绵状脑病","口蹄疫","克罗伊茨费尔特-雅各布病"],"a":3,"e":"朊粒引起的是传染性海绵状脑病，包括羊瘙痒病、牛海绵状脑病、库鲁病与克罗伊茨费尔特-雅各布病，均为中枢神经系统退行性病变。口蹄疫由口蹄疫病毒引起，属小RNA病毒科，是偶蹄动物的急性传染病，与朊粒无关"},{"q":"可引起化脓性炎症的革兰阴性球菌是","o":["淋病奈瑟菌和金黄色葡萄球菌","链球菌和淋病奈瑟菌","脑膜炎奈瑟菌和淋病奈瑟菌","金黄色葡萄球菌和链球菌","肠球菌和链球菌"],"a":2,"e":"脑膜炎奈瑟菌和淋病奈瑟菌均为革兰阴性双球菌，可致化脓性炎症，前者引起流行性脑脊髓膜炎，后者引起淋病。金黄色葡萄球菌、链球菌、肠球菌均为革兰阳性球菌，故D、E项组合不成立，A、B项亦含阳性球菌"},{"q":"治疗链球菌感染的首选药物是","o":["链霉素","红霉素","青霉素","四环素","磺胺药物"],"a":2,"e":"A群链球菌对青霉素高度敏感，至今未发现耐药株，青霉素为首选药物，可有效治疗咽峡炎并预防风湿热与急性肾小球肾炎。红霉素用于青霉素过敏者；链霉素、四环素与磺胺药对链球菌作用弱或耐药率高，不作首选"},{"q":"关于疱疹病毒的叙述，正确的是","o":["均为无包膜的双链DNA病毒","β疱疹病毒亚科可感染并潜伏在多种组织中","疱疹病毒都不能引起先天性感染","病毒感染的控制主要依赖于体液免疫","疱疹病毒在潜伏感染时，也能翻译蛋白"],"a":1,"e":"β疱疹病毒亚科包括HCMV、HHV-6、HHV-7，可感染并潜伏于腺体、肾、淋巴细胞等多种组织。疱疹病毒均为有包膜的双链DNA病毒；HCMV、HSV均可引起先天性感染；机体控制感染主要依靠细胞免疫；潜伏期仅表达少量基因，不进行完整复制"},{"q":"大多数细菌分裂一代所需的时间是","o":["10～20秒","30～60秒","5～10分钟","20～30分钟","60分钟"],"a":3,"e":"细菌以二分裂方式繁殖，多数细菌代时为20～30分钟，即每20～30分钟增殖一代，故培养18～24小时可形成肉眼可见菌落。结核分枝杆菌代时长达18～24小时；10～20秒与30～60秒过短，不符合细菌增殖规律；60分钟仅见于个别生长缓慢的细菌"},{"q":"布鲁菌与结核分枝杆菌的不同点是","o":["可在巨噬细胞内生长","致病性与超敏反应有关","可通过血流播散","主要通过内毒素致病","感染后形成带菌免疫"],"a":3,"e":"布鲁菌为革兰阴性菌，内毒素是其重要致病物质；结核分枝杆菌细胞壁无脂多糖、不含内毒素，致病依靠脂质、索状因子与超敏反应。两者均可巨噬细胞内生长、经血流播散并形成带菌免疫，故其余各项为共同点"},{"q":"外毒素的特点之一是","o":["多由革兰阴性菌产生","多为细菌裂解后释放","化学成分是脂多糖","可制成类毒素","毒性较弱"],"a":3,"e":"外毒素化学成分为蛋白质，毒性强、对热不稳定，多由革兰阳性菌合成后分泌释放，经甲醛处理可脱毒制成类毒素用于人工主动免疫。内毒素为革兰阴性菌细胞壁脂多糖，菌体裂解后释放，毒性较弱且耐热，不能制成类毒素。故多由革兰阴性菌产生、裂解后释放、化学成分为脂多糖、毒性较弱均为内毒素特点"},{"q":"在液体培养基中呈菌膜生长的下列细菌是","o":["肉毒梭菌","变形杆菌","产气荚膜梭菌","布鲁菌","结核分枝杆菌"],"a":4,"e":"结核分枝杆菌为专性需氧菌，在液体培养基表面生长形成菌膜，加入水溶性脂肪酸后疏水性降低才呈均匀生长。肉毒梭菌、产气荚膜梭菌为厌氧菌，布鲁菌为微需氧菌，均不形成菌膜。变形杆菌在固体培养基呈迁徙生长，液体中呈均匀混浊"},{"q":"观察细菌动力最常使用的培养基是","o":["液体培养基","半固体培养基","血琼脂平板培养基","选择培养基","巧克力色琼脂平板培养基"],"a":1,"e":"半固体培养基含3～5g/L琼脂，黏度低，有鞭毛细菌沿穿刺线向四周扩散呈羽毛状或云雾状生长，无鞭毛菌仅沿穿刺线呈线状生长，故最常用于观察动力。液体培养基用于增菌，固体培养基用于分离纯化，选择培养基用于筛选目的菌"},{"q":"霍乱弧菌在下列哪种培养基上生长良好","o":["血琼脂平板","肉汤培养基","碱性蛋白胨水","葡萄糖蛋白胨水","SS琼脂平板"],"a":2,"e":"霍乱弧菌耐碱不耐酸，在pH8.8～9.0的碱性蛋白胨水中生长良好，其他细菌在此pH下受抑，故用作初次分离的增菌培养基。血琼脂平板与肉汤无选择作用；SS琼脂含胆盐与煌绿，用于分离沙门菌与志贺菌；葡萄糖蛋白胨水用于VP、甲基红等生化反应"},{"q":"引起婴儿玫瑰疹的疱疹病毒是","o":["单纯疱疹病毒","水痘带状疱疹病毒","人疱疹病毒6型","人疱疹病毒7型","人疱疹病毒8型"],"a":2,"e":"婴儿玫瑰疹即幼儿急疹，由人疱疹病毒6型（主要为HHV-6B）引起，表现为高热3～5天后热退疹出。单纯疱疹病毒引起龈口炎和生殖器疱疹，水痘-带状疱疹病毒引起水痘和带状疱疹，HHV-7偶可引起类似疾病但非主要病原，HHV-8与Kaposi肉瘤相关"},{"q":"食入未消毒的羊奶，最可能引起的疾病是","o":["破伤风","伤寒","结核病","波浪热","肉毒中毒"],"a":3,"e":"羊布鲁菌是主要传染源，食入未消毒的羊奶或接触病畜可经消化道、皮肤黏膜感染，引起波浪热，表现为反复波浪状发热、多汗、关节痛和肝脾大。破伤风经伤口感染；伤寒经污染食物水传播；结核病多经呼吸道；肉毒中毒由罐头食品中肉毒毒素引起"},{"q":"关于药物敏感性试验，下列说法正确的是","o":["药敏试验的结果是指导临床用药的唯一依据","根据药敏试验的结果，应采用抑菌环最大的药物","抑菌环直径为2.5cm属于高度敏感药物","纸片法是根据抑菌环的有无和大小来判定试验菌对该抗菌药物耐药或敏感的","同一种细菌的不同菌株对同一药物的敏感性一样"],"a":3,"e":"纸片法将含药纸片贴于已接种细菌的琼脂平板，药物扩散形成浓度梯度，据抑菌环有无及直径判定敏感、中介或耐药。A项“唯一依据”错误，尚须结合感染部位、药物代谢和病情；B项不能只凭环大小选药；C项2.5cm须与折点比较才能定级；E项不同菌株敏感性差异很大"},{"q":"参与流感病毒吸附宿主细胞的蛋白是","o":["神经氨酸酶（NA）","基质蛋白（MP）","外层脂蛋白","核蛋白（NP）","血凝素（HA）"],"a":4,"e":"血凝素HA1亚单位与宿主细胞表面唾液酸受体结合，介导病毒吸附，HA2参与膜融合，故HA是吸附的关键蛋白。神经氨酸酶NA作用于子代病毒的释放与扩散；基质蛋白M1构成包膜内层；核蛋白NP包裹RNA；外层脂蛋白非流感病毒结构，均不参与吸附"},{"q":"能发生接合的细菌具有","o":["耐药决定因子","Col质粒","F质粒","前噬菌体","Vi质粒"],"a":2,"e":"F质粒编码性菌毛，含F质粒的细菌为F+菌，可与F-菌形成接合桥传递DNA，故能发生接合。耐药决定因子、Col质粒、Vi质粒虽可为质粒成分，但本身不编码性菌毛；前噬菌体为整合的噬菌体基因，与接合无关"},{"q":"病毒的糖蛋白具有下列特征，但例外的是","o":["通常来源于宿主细胞","参与病毒的感染过程","可以促进感染靶细胞的融合","是一种重要的病毒抗原","可以刺激机体产生中和性抗体"],"a":0,"e":"病毒糖蛋白由病毒基因组编码，位于包膜或衣壳表面，参与吸附与膜融合，构成重要抗原并诱生中和抗体。包膜的脂质双层才主要来源于宿主细胞膜或核膜，糖类亦来自宿主，故糖蛋白通常来源于宿主细胞之说不能成立"},{"q":"下列病毒中能形成潜伏感染的是","o":["HSV","HIV","HBV","HCV","CMV"],"a":0,"e":"HSV原发感染后，残余病毒沿感觉神经轴突上行，以非复制状态潜伏于三叉神经节、颈上神经节或骶神经节，持续终生，遇诱因激活复发，是潜伏感染的典型代表。HIV以前病毒整合形式长期存在；HBV、HCV多致慢性感染；CMV潜伏于髓系前体细胞，但教科书所举潜伏感染代表为HSV"},{"q":"HSV-1感染引起的疾病一般不包括","o":["龈口炎","唇疱疹","角膜结膜炎","生殖器疱疹","脑炎"],"a":3,"e":"HSV-1主要引起疱疹性龈口炎、唇疱疹、疱疹性角膜结膜炎和疱疹性脑炎，潜伏于三叉神经节。生殖器疱疹主要由HSV-2引起，属性传播疾病。新生儿疱疹多经产道感染HSV-2，故生殖器疱疹不属HSV-1的代表性疾病"},{"q":"麻疹应急预防最常用的措施是","o":["接种麻疹活疫苗","注射青链霉素","注射丙种球蛋白","接种麻疹死疫苗","注射干扰素"],"a":2,"e":"麻疹暴露后的应急预防以注射丙种球蛋白为主，可提供现成抗体，阻断发病或减轻症状，属人工被动免疫。麻疹活疫苗用于常规计划免疫，暴露后接种产生抗体需时较长；青霉素、链霉素对病毒无效；麻疹无死疫苗；干扰素不作应急预防"},{"q":"细菌基因的转移和重组方式不包括","o":["转化","接合","转导","突变","溶原性转换"],"a":3,"e":"细菌基因转移与重组的方式包括转化、接合、转导和溶原性转换，均涉及外源DNA进入受体菌并重组。突变是细菌自身DNA碱基序列的改变，属变异的来源而非基因转移方式，故不包括突变。突变只改变自身基因序列，不涉及外源DNA进入与整合，故属变异来源而非转移方式"},{"q":"引起肺部条件性感染的病原体是","o":["霍乱弧菌","破伤风梭菌","结核分枝杆菌","肺炎克雷伯菌","伤寒沙门菌"],"a":3,"e":"肺炎克雷伯菌广泛存在于土壤、水和人呼吸道、肠道，荚膜厚、抵抗力强，属典型机会致病菌，在免疫力低下、气管插管或广谱抗生素使用后引起肺炎等感染。霍乱弧菌、破伤风梭菌、结核分枝杆菌、伤寒沙门菌均为专性致病菌，健康人感染即可发病"},{"q":"基因突变导致的耐药性，为主的是","o":["单一耐药性","多重耐药性","对药物依赖性","不可遗传的耐药性","不稳定的耐药性"],"a":0,"e":"染色体基因突变只改变一个基因的产物，通常仅导致对单一药物耐药；R质粒携带多个耐药基因才产生多重耐药。药物依赖性、不稳定性和不可遗传性均不是基因突变所致耐药的特点，突变产生的耐药可以遗传"},{"q":"构成EB病毒包膜蛋白的成分是","o":["EBV早期抗原","EBV晚期抗原","EBV核抗原","潜伏膜蛋白-1","潜伏膜蛋白-2"],"a":1,"e":"EBV晚期抗原包括衣壳抗原VCA与膜抗原MA，MA位于病毒包膜及感染细胞表面，如gp350/gp220，故构成包膜蛋白的成分属晚期抗原。早期抗原为非结构蛋白，具DNA聚合酶活性；核抗原位于感染B细胞核内；潜伏膜蛋白LMP-1、LMP-2位于细胞膜，属潜伏期蛋白"},{"q":"伤寒的并发症肠穿孔和肠出血常发生在病程的哪个时间段","o":["第1周","第2周","第2～3周","第3周","第4周"],"a":2,"e":"伤寒第2～3周，回肠末段集合淋巴结的坏死组织脱落形成溃疡，累及血管与肌层，故易发生肠出血与肠穿孔。第1周为菌血症期，第3～4周后病变修复、病情好转；出血量大者可致休克。肠穿孔多发生于回肠末段，是伤寒最严重的并发症之一"},{"q":"部分诺卡菌具有弱抗酸性，是因为细菌中含有","o":["K抗原","索状因子","诺卡菌酸","脂质","磷脂酶C"],"a":2,"e":"诺卡菌属细胞壁含诺卡菌酸，与分枝菌酸结构相近，故具弱抗酸性，用1%盐酸乙醇延长脱色即可脱色，可与结核分枝杆菌鉴别。索状因子是结核分枝杆菌的毒力成分；K抗原为细菌表面抗原；磷脂酶C是产气荚膜梭菌的毒力因子"},{"q":"结核菌素试验结果为阴性，一般不属于下列哪种情况","o":["未感染过结核分枝杆菌","未接种过卡介苗","原发感染早期","已感染过结核分枝杆菌","正患有严重结核病"],"a":3,"e":"已感染过结核分枝杆菌者，结核菌素试验应为阳性，故阴性不属于此情况。阴性见于未感染、未接种卡介苗、原发感染早期（4～8周内超敏反应尚未建立）、严重结核病致无反应性以及免疫抑制者。故阴性结果不能一概排除结核，须结合临床判断"},{"q":"关于噬菌体特性的叙述，错误的是","o":["不能通过细菌滤器","具有抗原性","主要成分是核酸和蛋白质","形态多呈蝌蚪状","具有严格的宿主特异性"],"a":0,"e":"噬菌体是感染细菌的病毒，个体微小，能通过细菌滤器，该项叙述错误。其结构简单，仅由蛋白质衣壳和核酸组成，形态多呈蝌蚪状，具有抗原性，感染具有严格的宿主特异性，只能在活菌内增殖。按与宿主的关系可分毒性噬菌体与温和噬菌体，后者可整合于染色体成为前噬菌体"},{"q":"某患者大面积烧伤，伤口坏死组织多，首先应采取以下哪种方法给予处理","o":["清创，扩创，注射TAT","清创，扩创，注射DPT","清创，扩创，注射OT","简单处理伤口以便减少患者的疼痛","立即注射大剂量链霉素"],"a":0,"e":"大面积烧伤、坏死组织多易形成局部厌氧环境，利于破伤风梭菌芽孢发芽繁殖，故应及早清创、扩创、以过氧化氢冲洗并注射破伤风抗毒素中和游离毒素。DPT为白喉-百日咳-破伤风主动免疫制剂，起效慢；OT为结核菌素；链霉素对厌氧芽孢菌无效"},{"q":"HCV最主要的传播途径是","o":["消化道传播","血液和血制品","日常生活接触","母婴传播","性接触传播"],"a":1,"e":"HCV主要经输血和血制品传播，性接触及家庭密切接触也可传播，母婴传播罕见。消化道传播是HAV、HEV的主要途径；日常生活接触并非HCV的主要传播方式。故血液和血制品为最主要途径"},{"q":"下列病毒中，不能寄生在免疫细胞中的是","o":["麻疹病毒","EB病毒","乙肝病毒","HIV","登革病毒"],"a":2,"e":"乙型肝炎病毒嗜肝细胞，其受体位于肝细胞膜，主要在肝细胞内复制，不在免疫细胞内寄生。麻疹病毒可感染淋巴细胞和巨噬细胞，EB病毒以B淋巴细胞为靶细胞，HIV侵犯CD4+T细胞和巨噬细胞，登革病毒可在单核细胞中增殖"},{"q":"黑死病的病原体是","o":["布鲁菌","幽门螺杆菌","炭疽芽孢杆菌","鼠疫耶尔森菌","霍乱弧菌"],"a":3,"e":"鼠疫耶尔森菌是鼠疫的病原体，14世纪欧洲的黑死病即鼠疫大流行，经鼠蚤叮咬或接触染疫动物传播，分为腺鼠疫、肺鼠疫和败血症型。布鲁菌引起布鲁菌病，炭疽芽胞杆菌引起炭疽，幽门螺杆菌致胃炎，霍乱弧菌致霍乱"},{"q":"可能引发超敏反应的免疫制剂是","o":["丙种球蛋白","白细胞介素","抗毒素","干扰素","类毒素"],"a":2,"e":"抗毒素为马血清制备的异种蛋白，注入人体可诱导IgE，引起Ⅰ型超敏反应，使用前必须做皮肤试验，必要时脱敏注射。类毒素为主动免疫制剂，丙种球蛋白虽属异体蛋白但反应少见，白细胞介素与干扰素为细胞因子制剂，均不是超敏反应的主要来源"},{"q":"用作EBV感染早期诊断的指标是","o":["EA-IgG","EA-IgM","MA-IgM","MA-IgG","VCA-IgG"],"a":2,"e":"EBV感染后最早出现的是IgM类抗体，针对膜抗原的IgM抗体在感染早期即可检出、持续时间短，故可作早期诊断指标。VCA-IgG、EA-IgG阳性多提示既往感染或持续感染；EA-IgA、VCA-IgA效价持续升高对鼻咽癌有辅助诊断价值，不用于早期诊断"},{"q":"对内毒素叙述不正确的是","o":["细胞壁中的脂多糖","耐热","毒性作用较弱","具有较强的抗原性","产生的中和性抗体作用较弱"],"a":3,"e":"内毒素为革兰阴性菌细胞壁脂多糖，抗原性弱，刺激机体产生的中和抗体作用也弱，不能经甲醛处理制成类毒素。其化学本质是脂多糖，耐热，需160℃ 2～4小时才破坏；毒性作用相对较弱，且只在菌体死亡崩解后释放"},{"q":"以下预防狂犬病的主要措施，描述错误的是","o":["规范对家犬、军警犬类的管理","捕杀野犬","对高危人群进行狂犬疫苗接种","对高危人群使用干扰素","给家犬注射犬用狂犬疫苗"],"a":3,"e":"狂犬病预防以管理传染源和接种疫苗为主：规范家犬与军警犬管理、捕杀野犬、给家犬注射犬用疫苗均属传染源控制。对高危人群接种狂犬病疫苗属暴露前预防，效果确切。干扰素仅用于个别病毒病辅助治疗，毒副作用限制其应用，不用于狂犬病预防"},{"q":"伤寒病人发病第一周内，分离病原菌应采取的标本是","o":["血液","尿液","粪便","脑脊液","呕吐物"],"a":0,"e":"伤寒发病第1～2周为菌血症期，血中菌量高，取血液增菌培养阳性率最高；第2～3周菌随胆汁排入肠道，粪便与尿液培养阳性率上升。脑脊液用于脑膜炎，呕吐物不作常规标本。骨髓培养阳性率亦高，可作补充"},{"q":"以下哪种疾病属有菌免疫","o":["风湿热","急性肾小球肾炎","白喉","肺结核","肠热症"],"a":3,"e":"有菌免疫指机体免疫力随体内病原体存在而维持，病原体被清除后免疫随之消失，结核分枝杆菌感染最为典型。白喉属抗毒素免疫，肠热症病后可获牢固免疫，风湿热与急性肾小球肾炎属免疫复合物介导的超敏反应性疾病"},{"q":"伤寒沙门菌致病特点是","o":["不引起持续高热","可在肠道淋巴组织内繁殖","没有第二次菌血症","不侵犯肝、脾、肾等器官","可引起内脏化脓性感染"],"a":1,"e":"伤寒沙门菌经口入肠，经M细胞被吞噬细胞吞噬，在肠系膜淋巴结内繁殖后经胸导管入血形成第一次菌血症，故肠道淋巴组织是其繁殖部位。C项错在伤寒可有两次菌血症；E项内脏化脓性感染是金黄色葡萄球菌等化脓菌的表现，伤寒为单核巨噬细胞内的肉芽肿性病变"},{"q":"肠杆菌科细菌最常见的变异是","o":["耐药性变异","毒力变异","抗原变异","形态结构变异","菌落变异"],"a":0,"e":"肠杆菌科细菌最易发生耐药性变异，可由染色体突变或获得R质粒引起，后者更为常见，可经质粒、转座子与噬菌体介导形成多重耐药甚至泛耐药。毒力变异、抗原变异、形态结构与菌落变异亦可发生，但频度低得多"},{"q":"目前已知致泻毒素中毒性最强的是","o":["大肠埃希菌肠毒素","金黄色葡萄球菌肠毒素","霍乱肠毒素","伤寒沙门菌肠毒素","志贺毒素"],"a":2,"e":"霍乱肠毒素由A亚基和5个B亚基组成，是目前已知最强烈的致泻毒素，B亚基结合GM1神经节苷脂，A亚基激活腺苷环化酶使cAMP升高，引起剧烈水样泻。金葡菌肠毒素作用于呕吐中枢，志贺毒素有细胞毒和神经毒，致泻毒性均较弱"},{"q":"HIV的传播方式最常见的是","o":["吸毒","医源性","性接触","接吻","共用碗筷"],"a":2,"e":"性接触是HIV最主要的传播方式，占感染者绝大多数，病毒经黏膜微小破损进入。血液及血制品、母婴垂直传播次之；接吻、共用餐具与蚊虫叮咬均不传播。我国经输血传播已明显减少，性传播构成比上升"},{"q":"不属于正常菌群生理作用的是","o":["生物拮抗","营养作用","免疫作用","抗肿瘤作用","一定条件下，可转化为致病菌"],"a":4,"e":"正常菌群的生理作用包括生物拮抗、营养作用、免疫作用及抗肿瘤作用，其中营养作用指合成维生素K与B族维生素，生物拮抗靠占位与产细菌素抑制外来菌。一定条件下转化为机会致病菌属其条件致病性，是潜在致病风险而非生理作用"},{"q":"不是抗病毒药物的是","o":["金刚烷胺","阿糖腺苷","干扰素","3＇-氮唑核苷","万古霉素"],"a":4,"e":"万古霉素为糖肽类抗菌药物，作用于细菌细胞壁肽聚糖合成，对病毒无效。金刚烷胺阻断流感病毒M2蛋白通道，阿糖腺苷抑制病毒DNA聚合酶，利巴韦林即3′-氮唑核苷广谱抗RNA病毒，干扰素为广谱抗病毒生物制剂"},{"q":"以下不属于痘病毒的病毒是","o":["天花病毒","水痘-带状疱疹病毒","牛痘病毒","传染性软疣病毒","猴痘病毒"],"a":1,"e":"水痘-带状疱疹病毒属疱疹病毒科α疱疹病毒亚科，即人疱疹病毒3型，原发感染引起水痘，再激活引起带状疱疹，不属痘病毒。天花病毒、牛痘病毒、猴痘病毒与传染性软疣病毒均属痘病毒科，是体积最大的DNA病毒，呈砖形或卵圆形，在细胞质内复制"},{"q":"下列属于真核细胞性微生物的是","o":["甲型流感病毒","卡氏肺孢子菌","问号状钩端螺旋体","沙眼衣原体","空肠弯曲菌"],"a":1,"e":"真菌有完整细胞核、核膜核仁及线粒体、内质网等细胞器，属真核细胞型微生物；卡氏肺孢子菌现归真菌，故为真核细胞型。甲型流感病毒属非细胞型；问号状钩端螺旋体、沙眼衣原体、空肠弯曲菌均有原核结构，属原核细胞型"},{"q":"用于证明DNA是遗传物质的经典试验是","o":["中断杂交试验","荚膜肿胀试验","耐药突变株筛选试验","肺炎链球菌转化试验","细菌生长曲线测定试验"],"a":3,"e":"格里菲斯发现肺炎链球菌荚膜转化现象，艾弗里等进一步提取各组分，证实只有DNA才能使受体菌发生转化，从而证明DNA是遗传物质。中断杂交试验用于染色体基因定位；荚膜肿胀试验用于快速诊断；耐药突变株筛选和生长曲线测定均不涉及遗传物质本质"},{"q":"结构最简单的病毒体为","o":["核酸","衣壳","核衣壳","核衣壳和包膜","原生小体"],"a":2,"e":"核衣壳由核心（核酸）与衣壳构成，是病毒体的基本结构，无包膜病毒即以此形式存在，结构最简单。核酸或衣壳单独均不构成完整病毒体；核衣壳加包膜是包膜病毒的结构，更为复杂；原生小体指衣原体的原体，不是病毒结构"},{"q":"下列抗生素，衣原体不敏感的是","o":["链霉素","红霉素","四环素","强力霉素","螺旋霉素"],"a":0,"e":"衣原体对四环素、强力霉素、红霉素等大环内酯类及螺旋霉素敏感，这些药物能渗入细胞内作用于原体。链霉素属氨基糖苷类，不易进入真核宿主细胞，对胞内寄生的衣原体无效，故为不敏感者。治疗首选四环素类，孕妇与儿童可用红霉素"},{"q":"关于机会致病菌感染，下列叙述哪项是不正确的","o":["为内源性感染","多发生医院感染","发生于免疫功能低下者","常发生二重感染","近年来感染率呈下降趋势"],"a":4,"e":"机会致病菌多属内源性感染，常发生于免疫低下、菌群失调的住院病人，可表现为二重感染。随着免疫抑制剂、侵入性诊疗和器官移植的广泛开展，其感染率呈上升趋势，故近年来感染率呈下降趋势的说法错误"},{"q":"不同病毒的减毒活疫苗一般不宜同时接种，原因是","o":["疫苗易回复为有毒力病毒","病毒量太多，易产生免疫麻痹","病毒间发生干扰现象，导致免疫失败","病毒间相互作用，致免疫原性改变","病毒易被灭活"],"a":2,"e":"两种以上减毒活疫苗同时接种时，先进入的疫苗株可诱导干扰素、破坏细胞受体或改变细胞代谢，干扰后一疫苗株复制，导致免疫失败，故应错开接种。毒力回升、免疫麻痹、免疫原性改变和疫苗被灭活均非同时接种的主要顾虑"},{"q":"属于气单胞菌属的细菌是","o":["嗜水气单胞菌","卡他莫拉菌","铜绿假单胞菌","嗜麦芽窄食单胞菌","荧光假单胞菌"],"a":0,"e":"嗜水气单胞菌属气单胞菌属，为水中常居菌，可经污染的水与食物引起胃肠炎、食物中毒、败血症和创伤感染。卡他莫拉菌属莫拉菌属；铜绿假单胞菌与荧光假单胞菌属假单胞菌属；嗜麦芽窄食单胞菌属窄食单胞菌属，均为非发酵革兰阴性菌"},{"q":"下列说法不正确的是","o":["耐药性菌株在药物使用之前就出现了","耐药性菌株可以回复成敏感性菌株","药物的使用是敏感性菌株变成耐药性菌株的决定因素","药物的筛选使耐药性菌株比例增加","基因突变产生的耐药性可以保持很多代"],"a":2,"e":"耐药突变在接触药物之前即自发随机产生，抗菌药物只起选择作用，淘汰敏感株使耐药株比例升高，并非诱导敏感株定向变为耐药株，故C项错误。A项符合突变自发、药物选择的规律；B项停用药物后耐药株失去竞争优势，可回复敏感；E项突变所致耐药可遗传多代"},{"q":"决定病毒传染主要在于","o":["衣壳","核酸","包膜","神经氨酸酶","蛋白"],"a":1,"e":"病毒核酸携带全部遗传信息，决定子代病毒的致病性、抗原性与增殖能力，是感染与遗传变异的物质基础。衣壳、包膜及刺突蛋白仅决定吸附与亲嗜性，属结构蛋白功能；神经氨酸酶参与成熟释放。蛋白表述笼统，不能替代核酸"},{"q":"BCG属于哪种疫苗","o":["死疫苗","活疫苗","亚单位疫苗","基因工程疫苗","核酸疫苗"],"a":1,"e":"卡介苗是牛结核分枝杆菌减毒活疫苗，接种后可在体内有限增殖，诱导体液和细胞免疫，免疫持久，属活疫苗。死疫苗如伤寒疫苗、百日咳疫苗，亚单位疫苗、基因工程疫苗和核酸疫苗均非完整的活菌制剂"},{"q":"病毒感染后出现多核巨细胞的是","o":["麻疹病毒","风疹病毒","脊髓灰质炎病毒","流感病毒","乙型肝炎病毒"],"a":0,"e":"麻疹病毒包膜HL蛋白兼具溶血与融合活性，使感染细胞融合形成华新多核巨细胞，为其特征性细胞病变。风疹病毒致先天性风疹综合征；流感病毒CPE轻微，需红细胞吸附判定增殖；脊髓灰质炎病毒致细胞圆缩坏死；HBV难以在普通细胞培养中观察CPE"},{"q":"下列选项中型别最多的病毒是","o":["腺病毒","麻疹病毒","冠状病毒","鼻病毒","风疹病毒"],"a":3,"e":"鼻病毒血清型已超过100个，型别之多居常见呼吸道病毒之首，型间无交叉免疫，故再感染极为常见。腺病毒、冠状病毒的型别较少，麻疹病毒与风疹病毒各只有单一血清型，感染后免疫持久。故同一人可反复患普通感冒"},{"q":"关于EBV与鼻咽癌的叙述，错误的是","o":["鼻咽癌主要发生在东南亚、北非和北美洲北部地区","多发生在40岁以上人群","EBV是致鼻咽癌的唯一因子","所有鼻咽癌组织中均可找到EBV的核酸和抗原","鼻咽癌患者血清EBV抗体效价高于正常人"],"a":2,"e":"EBV与鼻咽癌关系密切：所有鼻咽癌组织均可检出EBV核酸和抗原，病人血清EBV抗体效价升高，治疗好转后抗体效价随之下降。但鼻咽癌发生还涉及遗传易感性和化学致癌物，EBV并非唯一因子，故C项错误；该病多见于东南亚和我国华南，40岁以上高发"},{"q":"与HTLV-1致瘤机制密切相关的病毒蛋白是","o":["Tax","Rex","p12","p13","p30"],"a":0,"e":"Tax由pX区ORF-Ⅲ、Ⅳ编码，可激活病毒LTR转录，并激活NF-κB，促使多种细胞因子产生与抗凋亡，间接引起T细胞异常增殖，是HTLV-1致成人T细胞白血病的关键蛋白。Rex参与病毒mRNA剪接与转运；p12、p13、p30为非结构调节蛋白，与致瘤关系不直接"},{"q":"受病毒感染的宿主细胞被杀伤的机制中错误的是","o":["CTL直接杀伤靶细胞","ADCC机制杀伤靶细胞","中和抗体直接溶解靶细胞","在补体参与下溶解靶细胞","淋巴因子直接或间接作用于靶细胞"],"a":2,"e":"中和抗体与游离病毒结合，阻止其吸附穿入，主要作用于细胞外病毒，不能直接溶解感染细胞。杀伤靶细胞依靠CTL直接识别并杀伤、ADCC、补体参与下的抗体介导溶解，以及淋巴因子直接或间接作用。故“中和抗体直接溶解靶细胞”不成立"},{"q":"细胞受病毒感染后可在胞浆或/和核内形成一种具有诊断意义的物质","o":["质粒","溶酶体","核糖体","中介体","包涵体"],"a":4,"e":"包涵体是病毒感染后在胞质或胞核内形成的特殊结构，可为病毒颗粒的聚集体、病毒的合成原料或细胞反应物，具诊断意义，如狂犬病的内氏小体。质粒是细菌染色体外的DNA；溶酶体与核糖体为细胞固有结构；中介体是细菌细胞膜内褶形成的结构，与病毒无关"},{"q":"具有Vi抗原的沙门菌是","o":["伤寒沙门菌","肠炎沙门菌","鼠伤寒沙门菌","甲型副伤寒沙门菌","肖氏沙门菌"],"a":0,"e":"Vi抗原是新分离伤寒沙门菌和丙型副伤寒沙门菌表面的荚膜样抗原，可阻止O抗原与其抗体凝集，60℃加热或传代培养后易消失。肠炎沙门菌、鼠伤寒沙门菌、甲型副伤寒沙门菌和肖氏沙门菌均无Vi抗原"},{"q":"肠热症所引起的外周血血细胞变化是","o":["嗜酸性粒细胞增多","嗜碱性粒细胞降低","血红蛋白降低","外周白细胞上升","外周白细胞下降"],"a":4,"e":"肠热症时内毒素抑制骨髓造血，并使白细胞黏附于血管壁，外周血白细胞数下降或正常，嗜酸性粒细胞减少甚至消失。血红蛋白多无明显降低，白细胞升高见于化脓性感染。嗜酸性粒细胞增多见于寄生虫感染与过敏性疾病"},{"q":"调查人群对白喉棒状杆菌的免疫力可用","o":["结核菌素（OT）试验","锡克试验","肥达试验","外斐反应","狄克试验"],"a":1,"e":"锡克试验以白喉毒素皮内注射，观察局部反应以判断机体有无抗毒素免疫，用于调查人群对白喉棒状杆菌的免疫力。狄克试验用猩红热毒素检测对猩红热的易感性；结核菌素试验查结核感染；肥达试验诊肠热症；外斐反应用于立克次体病"},{"q":"紧急预防病毒感染最有效的方法是","o":["用化学药物","用免疫血清","用减毒活疫苗","用干扰素","用灭活疫苗"],"a":1,"e":"免疫血清含特异抗体，注射后即刻获得被动免疫，可用于麻疹、狂犬病等暴露后的紧急预防。减毒活疫苗和灭活疫苗属人工主动免疫，需2～4周才产生保护；化学药物和干扰素无即刻中和病原体的作用"},{"q":"下列哪种毒素抑制乙酰胆碱的释放","o":["破伤风溶血素","破伤风痉挛毒素","产气荚膜梭菌β毒素","肉毒毒素","链球菌溶血素"],"a":3,"e":"肉毒毒素为神经毒素，轻链进入外周胆碱能神经末梢，裂解突触小体相关蛋白，阻断乙酰胆碱释放，引起弛缓性麻痹。破伤风痉挛毒素阻止抑制性神经递质释放，导致肌肉强直痉挛；产气荚膜梭菌β毒素致肠壁坏死；链球菌溶血素溶解红细胞和白细胞"},{"q":"病原菌与其传播途径组合错误的是","o":["淋病奈瑟菌——性传播","伤寒沙门菌——消化道传播","肺炎链球菌——呼吸道传播","脑膜炎奈瑟菌——呼吸道传播","引起猩红热的乙型链球菌——血行传播"],"a":4,"e":"猩红热由A群乙型溶血性链球菌引起，经呼吸道飞沫传播，并非血行传播，故该组合错误。淋病奈瑟菌经性接触传播，伤寒沙门菌经消化道传播，肺炎链球菌与脑膜炎奈瑟菌均经呼吸道传播，组合均正确"},{"q":"关于外毒素的特点描述正确的是","o":["耐热","多由革兰阴性菌产生","多为细菌死亡后释放","可制备成类毒素","主要成分是脂多糖"],"a":3,"e":"外毒素为蛋白质，经0.3%～0.4%甲醛处理可脱毒并保留抗原性，制成类毒素用于预防。其不耐热，主要由革兰阳性菌及部分革兰阴性菌产生，在菌体生活状态下合成并分泌，化学本质是蛋白质而非脂多糖。耐热、多在菌体死亡后释放、成分为脂多糖均为内毒素特点"},{"q":"判定致病性葡萄球菌的主要生化反应是","o":["分解乳糖","硫化氢阳性","分解葡萄糖产酸产气","凝固酶阳性","吲哚试验阳性"],"a":3,"e":"血浆凝固酶使纤维蛋白原转变为纤维蛋白并沉积于菌体表面，阻碍吞噬细胞吞噬与胞内消化，是致病性葡萄球菌即金黄色葡萄球菌的关键鉴定指标，表皮与腐生葡萄球菌均为阴性。分解甘露醇、耐热核酸酶同为其特征；乳糖发酵、硫化氢与吲哚试验用于肠道杆菌鉴别"},{"q":"我国最常见的着色真菌病病原体是","o":["卡氏枝孢霉","裴氏丰萨卡菌","疣状瓶霉","链格孢霉","甄氏外瓶霉"],"a":0,"e":"我国着色真菌病以卡氏枝孢霉最为常见，其次为裴氏丰萨卡菌。该菌在沙氏培养基上生长缓慢，菌落呈暗褐色绒毛状，镜检见树枝状分生孢子链。疣状瓶霉、甄氏外瓶霉与链格孢霉亦属着色真菌，但国内分离率较低"},{"q":"不属于原核细胞型微生物的是","o":["细菌","病毒","支原体","立克次体","衣原体"],"a":1,"e":"病毒无细胞结构，只含一种核酸，必需在活细胞内增殖，属非细胞型微生物。细菌、支原体、立克次体与衣原体均有细胞壁或细胞膜，含DNA和RNA两种核酸，以二分裂繁殖，同属原核细胞型微生物；衣原体虽有独特发育周期，仍归原核细胞型"},{"q":"在病毒复制过程中具有逆转录过程的肝炎病毒是","o":["HAV","HBV","HCV","HDV","HEV"],"a":1,"e":"HBV基因组为不完全环状双链DNA，复制时先转录前基因组RNA，再经病毒逆转录酶逆转录为负链DNA，故具逆转录过程。HCV为单正链RNA病毒，复制经负链RNA中间体，无逆转录。HAV与HEV亦为单正链RNA病毒。HDV为环状单负链RNA，需HBV提供包膜"},{"q":"不是正常菌群致病条件的是","o":["寄生部位改变","全身免疫功能低下","局部免疫功能低下","菌群失调","病原菌感染"],"a":4,"e":"正常菌群致病需具备条件：寄居部位改变使细菌进入非正常部位，全身或局部免疫功能低下，以及长期使用广谱抗生素致菌群失调。病原菌感染是外源性致病菌侵入所致，不属正常菌群转为条件致病菌的诱因，故不列为其致病条件"},{"q":"关于细菌核质的描述不正确的是","o":["为细菌的染色体","存在于细胞核内","其核酸无组蛋白包绕","无核膜和核仁，不显示核的形态","具有细菌生命活动所必需的遗传基因"],"a":1,"e":"细菌核质即染色体，为环状双股DNA，无核膜、核仁与组蛋白，不显示完整核的形态，集中于胞质的一定区域，故“存在于细胞核内”错误。它携带细菌生命活动所必需的遗传基因，控制遗传与变异，因无核膜包裹而称拟核"},{"q":"慢性肝炎患者由抗原抗体复合物沉积引起的关节炎症属于","o":["Ⅰ型超敏反应","Ⅱ型超敏反应","Ⅲ型超敏反应","Ⅳ型超敏反应","非超敏反应"],"a":2,"e":"慢性肝炎时HBsAg等与相应抗体形成免疫复合物，随血流沉积于关节滑膜、肾小球基底膜，激活补体并招募中性粒细胞，属Ⅲ型超敏反应。Ⅱ型超敏反应是抗体直接与细胞表面抗原结合致细胞溶解，如抗链球菌M蛋白抗体交叉反应损伤心肌。Ⅳ型由T细胞介导、以单核细胞浸润为主，见于结核与接触性皮炎"},{"q":"关于病原菌致病性的构成因素，叙述最全面的是","o":["毒力＋侵入部位＋细菌数量","毒素＋侵袭力＋侵入部位","侵袭力＋侵入部位＋细菌数量","侵袭酶类＋毒素＋细菌数量","侵入部位＋毒素＋细菌表面结构"],"a":0,"e":"病原菌能否致病取决于毒力、侵入部位和侵入数量三方面，毒力又包含侵袭力与毒素，故毒力加侵入部位加细菌数量最全面。仅列毒素与侵袭力遗漏数量；仅列侵袭力遗漏毒素；细菌表面结构只是侵袭力的一部分"},{"q":"决定流感病毒型特异性的蛋白是","o":["血凝素（HA）","神经氨酸酶（NA）","血凝素（HA）和神经氨酸酶（NA）","核蛋白（NP）和基质蛋白（MP）","核糖核蛋白（RNP）"],"a":3,"e":"流感病毒的型特异性抗原由核蛋白（NP）和基质蛋白（MP）决定，二者抗原性稳定，不同型间无交叉，是分型的依据。血凝素（HA）和神经氨酸酶（NA）是包膜刺突糖蛋白，决定亚型与株特异性，也是抗原漂移和转换的靶点，只答HA或NA均属亚型抗原。核糖核蛋白（RNP）是NP与基因组RNA、聚合酶复合物结合形成的结构，不单独构成分型抗原"},{"q":"一女性患者怀疑有念珠菌性阴道炎，下列描述中最不正确的是","o":["阴道分泌物用革兰染色后，可见芽生酵母型菌","阴道分泌物用沙氏培养基培养，能产生带有分生孢子的气生菌丝体","应检查患者的尿糖情况","应询问患者是否使用过大剂量广谱抗生素","应询问患者是否长期使用过激素类药物"],"a":1,"e":"白念珠菌在沙氏培养基上形成奶油状类酵母型菌落，镜检为芽生孢子与假菌丝，不产生带分生孢子的气生菌丝，故该项最不正确。革兰染色可见芽生酵母与假菌丝；尿糖、广谱抗生素及激素使用均为其诱发因素"},{"q":"在人体肠道正常菌群中，占绝对优势的是","o":["链球菌","大肠埃希菌","变形杆菌","白色念珠菌","无芽孢厌氧菌"],"a":4,"e":"肠道微生物群中厌氧菌占99.9%，无芽胞厌氧菌是需氧及兼性厌氧菌的10～1000倍，占绝对优势。大肠埃希菌等肠杆菌科细菌仅占0.1%，链球菌、变形杆菌更少；白色念珠菌属真菌，占比极微"},{"q":"EBV潜伏感染期表达的抗原不包括","o":["EBNA-1","EBNA-2","LMP-1","LMP-2","VCA"],"a":4,"e":"EBV潜伏感染期仅表达EBNA-1、EBNA-2、LMP-1和LMP-2等潜伏蛋白，不产生完整病毒颗粒。VCA属病毒增殖性感染期表达的衣壳抗原，VCA IgM阳性提示原发感染，故不属于潜伏期抗原"},{"q":"可通过粪-口途径传播的病原体是","o":["EB病毒、埃可病毒、脊髓灰质炎病毒、柯萨奇病毒","冠状病毒、腮腺炎病毒、埃可病毒、柯萨奇病毒","腺病毒、柯萨奇病毒、脊髓灰质炎病毒、埃可病毒","柯萨奇病毒、HIV、麻疹病毒、EB病毒","腺病毒、流感病毒、脊髓灰质炎病毒、埃可病毒"],"a":2,"e":"腺病毒、柯萨奇病毒、脊髓灰质炎病毒与埃可病毒均可经粪-口途径传播，后三者属肠道病毒，在肠道增殖并经粪便排出。EB病毒经唾液与密切接触传播，冠状病毒与腮腺炎病毒经呼吸道传播，HIV经性接触与血液传播"},{"q":"与细菌的运动功能有关的结构是","o":["菌毛","鞭毛","芽孢","荚膜","性菌毛"],"a":1,"e":"鞭毛是细菌的运动器官，单毛菌、双毛菌、丛毛菌、周毛菌借鞭毛在液体中游动，并具趋化性，可向营养物前进、逃离有害物。菌毛为黏附结构，性菌毛介导接合；荚膜抗吞噬；芽孢为休眠体，均与运动无关"},{"q":"关于朊粒的叙述，以下错误的是","o":["主要致病部位是脑组织","可引起库鲁病","具有传染性","可诱导宿主产生特异性免疫应答","可感染人和动物"],"a":3,"e":"朊粒为构象异常的朊蛋白，不含核酸，不诱导机体产生特异性免疫应答，也不引起炎症反应，故D项错误。该病主要累及脑组织，引起神经元空泡变性和海绵状改变，可感染人和多种动物，库鲁病、克雅病均属朊粒病，具传染性"},{"q":"关于疱疹病毒的特点，叙述错误的是","o":["病毒呈球形，核心由双股RNA组成","多数能在人二倍体细胞核内复制，产生明显细胞病变","病毒感染宿主细胞可表现为增殖性感染","潜伏感染时，病毒不增殖","病毒基因组的一部分可整合于宿主细胞DNA中"],"a":0,"e":"疱疹病毒核心为双股线形DNA，而非双股RNA，故该项错误。病毒呈球形，有包膜，能在人二倍体细胞核内复制并产生明显细胞病变；感染可表现为增殖性感染、潜伏感染或整合感染，潜伏时病毒不增殖，部分基因组可整合于宿主细胞DNA"},{"q":"G+菌细胞壁肽聚糖主要成分为","o":["脂多糖、聚糖骨架和四肽侧链","特异性多糖、核心多糖和脂质A","脂蛋白、脂质双层和脂多糖","脂质双层、四肽侧链和五肽交联桥","聚糖骨架、四肽侧链和五肽交联桥"],"a":4,"e":"革兰阳性菌肽聚糖由聚糖骨架、四肽侧链和五肽交联桥三部分构成，层数多、交联致密，占细胞壁干重50%～80%。革兰阴性菌肽聚糖只有聚糖骨架和四肽侧链，无五肽交联桥；脂多糖由特异多糖、核心多糖和脂质A组成；脂蛋白、脂质双层和脂多糖是阴性菌外膜的组成"},{"q":"关于细菌的耐药性基因突变，下列说法错误的是","o":["基因突变是随机发生的","细菌耐药性基因突变与抗菌药物的使用有关","基因突变可发生回复突变","基因突变具有相对稳定性","细菌通过基因突变获得的耐药性可保持很多代"],"a":1,"e":"基因突变是随机、自发发生的，与抗菌药物是否存在无关，药物的作用只是对已存在的耐药突变株进行选择，故该说法错误。突变可发生回复突变，具有相对稳定性，获得的耐药性可遗传多代。耐药突变株在药物选择下成为优势菌群，停药后又可逐渐减少"},{"q":"不符合脑膜炎奈瑟菌标本采集与送检要求的是","o":["采集标本应注意无菌操作","根据该病原菌主要存在部位取材","应在使用抗菌药物之前采集标本","采集的标本要立即送检","标本送检过程中要保持低温和干燥"],"a":4,"e":"脑膜炎奈瑟菌对低温与干燥极敏感，标本采集后须保暖、保湿并立即送检，故保持低温和干燥错误。采集应无菌操作、取脑脊液或瘀斑渗出物，并在使用抗菌药物之前完成；该菌能产生自溶酶，标本不宜冷藏"},{"q":"常见的可引起先天性婴儿畸形的病毒是","o":["麻疹病毒","狂犬病病毒","风疹病毒","脊髓灰质炎病毒","冠状病毒"],"a":2,"e":"风疹病毒经垂直传播感染胎儿，孕20周内感染危害最大，可致先天性心脏病、白内障、耳聋等先天性风疹综合征。麻疹病毒、狂犬病病毒、脊髓灰质炎病毒与冠状病毒一般不通过胎盘致畸；巨细胞病毒亦致畸，但不在选项内"},{"q":"根据霍乱弧菌鞭毛的数量和位置，它属于","o":["周鞭毛菌","丛鞭毛菌","双鞭毛菌","单鞭毛菌","无鞭毛菌"],"a":3,"e":"霍乱弧菌菌体一端只有一根鞭毛，属单毛菌，运动活泼，可穿过小肠黏膜表面的黏液层而黏附定植。双毛菌如空肠弯曲菌两端各一根鞭毛，周毛菌如大肠埃希菌、变形杆菌遍体鞭毛，丛毛菌多见于铜绿假单胞菌"},{"q":"与裸露病毒比较，包膜病毒对下列哪种因素敏感","o":["干燥","热","酸","氧","脂溶剂"],"a":4,"e":"包膜病毒的包膜含脂质双层，乙醚、氯仿、去氧胆酸盐等脂溶剂可溶解包膜，使病毒失去吸附能力而灭活，故常用乙醚试验鉴别有无包膜。裸露病毒无脂质包膜，对脂溶剂耐受；干燥、热、酸对两类病毒均有影响，不能据此区分"},{"q":"做抗生素敏感试验时，应选择","o":["迟缓期","稳定期","衰亡期","对数生长期","衰亡期前期"],"a":3,"e":"对数生长期细菌代谢旺盛、酶活性高、对抗菌药物最敏感，药敏试验须取该期菌液。迟缓期细菌代谢尚未活跃，稳定期与衰亡期死菌增多、结果偏差。接种菌量与培养基厚度均影响抑菌圈大小与判定。临床报告须注明所用方法与判读标准"},{"q":"异染颗粒是下列哪一种细菌的染色特性","o":["麻风分枝杆菌","结核分枝杆菌","炭疽芽孢杆菌","蜡样芽孢杆菌","白喉棒状杆菌"],"a":4,"e":"白喉棒状杆菌菌体着色不均，含大量多偏磷酸盐的浓染颗粒，用Albert染色呈蓝黑色，与菌体染色不同，称异染颗粒，有鉴定价值。麻风分枝杆菌与结核分枝杆菌具抗酸性，用抗酸染色；炭疽芽胞杆菌与蜡样芽胞杆菌的鉴别依赖荚膜、噬菌体裂解与碳酸氢钠培养等"},{"q":"有迁徒性生长现象的细菌是","o":["福氏志贺菌","变形杆菌","痢疾志贺菌","大肠埃希菌","伤寒沙门菌"],"a":1,"e":"变形杆菌有周身鞭毛、运动活跃，在固体培养基上呈波纹状迁徙性生长，可铺满整个平板。福氏志贺菌与痢疾志贺菌无鞭毛、动力阴性；大肠埃希菌、伤寒沙门菌虽有鞭毛，却只形成孤立菌落，不出现迁徙现象。故迁徙生长是变形杆菌的典型特征"},{"q":"鉴别结核分枝杆菌下列哪种染色方法较好","o":["抗酸染色","镀银染色","阿尔培脱染色","革兰染色","荧光染色"],"a":0,"e":"结核分枝杆菌细胞壁富含分枝菌酸，苯酚复红着色后不能被3%盐酸乙醇脱色，呈红色，为抗酸染色阳性，是鉴别分枝杆菌的关键方法。革兰染色不易着色，无鉴别意义；镀银染色用于螺旋体；阿尔培脱染色用于观察白喉棒状杆菌的异染颗粒；荧光染色敏感性高，只宜作筛查"},{"q":"能代表病毒体的一种结构成分是","o":["核酸","衣壳","核衣壳","胞膜","刺突"],"a":2,"e":"核衣壳由核心与衣壳构成，是裸露病毒完整的病毒体，可代表病毒体结构。核酸只是基因组，单独不具感染性；衣壳仅为外壳；包膜与刺突只见于包膜病毒，并非所有病毒共有，不能代表病毒体"},{"q":"感染后机体血清中虽有特异性抗体，但仍可发病的病毒是","o":["脊髓灰质炎病毒","单纯疱疹病毒","乙型肝炎病毒","流感病毒","腮腺炎病毒"],"a":1,"e":"单纯疱疹病毒原发感染后潜伏于感觉神经节，机体虽有中和抗体，但不能清除潜伏病毒，再激活后仍可反复发病，故血清有抗体仍可发病。脊髓灰质炎、麻疹、腮腺炎病后免疫力持久，再次感染少见；乙肝慢性化源于免疫耐受，机制不同"},{"q":"结核分枝杆菌感染机体后，机体发生的抗感染免疫主要是","o":["细胞免疫","Ⅰ型超敏反应","Ⅱ型超敏反应","天然免疫反应","体液免疫"],"a":0,"e":"结核分枝杆菌为兼性胞内寄生菌，抗感染免疫主要依靠细胞免疫，CD4+Th1细胞分泌IFN-γ激活巨噬细胞，增强其杀灭胞内菌的能力，同时伴迟发型超敏反应。体液免疫作用有限，天然免疫不能有效清除，Ⅰ、Ⅱ型超敏反应与本病的保护性免疫无关"},{"q":"欲研发一种新的工具质粒，计划从临床分离菌株中获得原始质粒序列再进行改建，通常不希望该质粒具有的特性是","o":["编码耐药基因","具有松弛复制性","具有紧密复制性","具有与其他质粒的相容性","可经接合和转化等机制在细菌间转移"],"a":2,"e":"工具质粒需具松弛复制特性，才能在宿主菌内以高拷贝存在，便于大量制备与改建。紧密复制质粒拷贝数少，与染色体复制同步，不适合作载体。编码耐药基因可作筛选标记，具相容性可与辅助质粒共存，能经接合或转化转移便于操作"},{"q":"决定病毒吸附易感细胞的因素是","o":["病毒包膜","刺突","核酸","壳粒及排列","病毒表面的配体位点和敏感细胞表面的特异性受体"],"a":4,"e":"病毒吸附取决于病毒表面的配体位点（如HA、gp120）与敏感细胞表面特异性受体的互补结合，二者共同决定病毒的组织亲嗜性和宿主范围。包膜、刺突只是配体的载体，核酸与壳粒排列均不参与吸附识别"},{"q":"细菌合成代谢产物中，细菌内毒素的生物学特性是","o":["抗原性弱","毒性作用强","细菌生活状态下释放","主要由革兰阳性菌产生","60～80℃，30分钟被破坏"],"a":0,"e":"内毒素为革兰阴性菌细胞壁脂多糖，抗原性弱，刺激机体产生的中和抗体作用也弱。其毒性作用相对较弱，只在菌体死亡崩解后释放；耐热，需160℃ 2～4小时才被破坏。毒性作用强、60～80℃ 30分钟即被破坏均为外毒素特点；主要由革兰阳性菌产生应改为革兰阴性菌"},{"q":"关于VZV原发感染引起水痘的描述，错误的是","o":["病毒感染起始于呼吸道黏膜","皮疹呈向心性分布，以躯干较多","儿童水痘一般为自限性，症状较轻","孕妇患水痘有传给胎儿导致流产的可能性","病毒一般不入血，不引起病毒血症"],"a":4,"e":"VZV原发感染经呼吸道黏膜侵入，在局部淋巴结增殖后入血形成第一次病毒血症，再于单核巨噬细胞系统增殖后形成第二次病毒血症，故病毒不入血的说法错误。皮疹呈向心性、以躯干为多，儿童水痘多为自限性，孕妇感染可致胎儿畸形或流产"},{"q":"以内毒素作为主要致病物质的细菌是","o":["布鲁菌","破伤风梭菌","结核分枝杆菌","金黄色葡萄球菌","肺炎链球菌"],"a":0,"e":"布鲁菌为革兰阴性胞内寄生菌，内毒素是其重要致病物质，引起发热与毒血症。破伤风梭菌、金黄色葡萄球菌靠分泌外毒素致病；结核分枝杆菌无内毒素，致病依靠脂质与索状因子；肺炎链球菌主要靠荚膜抗吞噬"},{"q":"下列描述不正确的是","o":["黏附是许多细菌感染的第一步","微菌落是某些细菌在体内一定部位的定植方式之一","生物膜的形成有利于细菌黏附","微菌落和生物膜使细菌增加抵抗免疫物质杀伤的能力","生物膜中的细菌耐药基因不易相互传递"],"a":4,"e":"生物被膜内细菌密集且彼此接触，信号分子、耐药基因和毒力基因的捕获与转移反而更容易，故“不易相互传递”与事实相反。黏附是许多细菌感染的第一步，微菌落是体内定植方式之一，生物被膜还能阻挡抗生素渗入并抵抗免疫杀伤，这三项均成立"},{"q":"结核分枝杆菌引起的疾病中最常见的是","o":["结核性胸膜炎","肺结核","结核性关节炎","结核性脑膜炎","肠结核"],"a":1,"e":"结核分枝杆菌经呼吸道侵入，可侵犯全身各器官，但以肺结核最为常见，占各类结核病的绝大多数，痰中排菌是主要传染来源。结核性胸膜炎、脑膜炎、肠结核和结核性关节炎均为继发或肺外表现，发生率明显较低"},{"q":"对结核菌素试验的叙述，错误的是","o":["属于皮肤迟发型超敏反应","可检测机体对结核分枝杆菌的免疫状况","皮肤反应程度以局部红肿，硬结的直径为标准","可检测肿瘤患者的细胞免疫功能状况","12～18小时观察结果"],"a":4,"e":"结核菌素试验属迟发型Ⅳ型超敏反应，于前臂皮内注射PPD后48～72小时观察局部红肿硬结直径，故12～18小时观察错误。该试验可反映机体对结核分枝杆菌的细胞免疫状态，也用于肿瘤等细胞免疫功能低下的评估"},{"q":"目前已广泛用于治疗病毒感染的药物或制剂是","o":["核苷类药物","反义寡核苷酸","核酶","干扰RNA","治疗性疫苗"],"a":0,"e":"核苷类药物是最早用于临床的抗病毒药物，通过抑制病毒基因转录和复制起效，碘苷、阿昔洛韦、拉米夫定等已广泛用于疱疹病毒、HBV和HIV感染。反义寡核苷酸、核酶与干扰RNA多停留于实验研究或早期临床试验，临床应用有限。治疗性疫苗仍处探索阶段，尚非广泛应用的抗病毒手段"},{"q":"关于获得耐药性描述，错误的是","o":["不是天然耐药性","可由染色体突变引起","可由耐药质粒传播引起","是由于药物的应用引起的","是敏感细菌出现对抗菌药物有耐药性的菌株"],"a":3,"e":"获得耐药性是细菌DNA改变导致敏感菌获得耐药表型，可由染色体突变或获得耐药质粒、转座子引起；抗菌药物的使用只起选择作用，并非耐药性产生的直接原因。其区别于固有耐药性，本质是遗传物质改变而非药物诱导生成"},{"q":"编码细菌对抗菌药物耐药性的质粒是","o":["F质粒","R质粒","Vi质粒","Col质粒","K质粒"],"a":1,"e":"R质粒为接合性耐药质粒，携带多个耐药基因，可经接合在种内甚至种间传递，是耐药性播散的主要原因。F质粒编码性菌毛，Vi质粒编码Vi抗原增强毒力，Col质粒编码大肠菌素，K质粒编码K抗原，均与耐药性无关"},{"q":"最易引起新生儿病毒性心肌炎的病毒是","o":["肠道病毒70型","脊髓灰质炎病毒","柯萨奇病毒A组","埃可病毒","柯萨奇病毒B组"],"a":4,"e":"B组柯萨奇病毒是病毒性心肌炎最常见的病原体，新生儿及婴幼儿感染后可引起原发性心肌病，心肌组织中可检出肠道病毒基因组RNA。柯萨奇A组主要致疱疹性咽峡炎和手足口病；埃可病毒多致无菌性脑膜炎、皮疹和腹泻；脊髓灰质炎病毒侵犯脊髓前角运动神经元，引起弛缓性麻痹"},{"q":"汉坦病毒的主要宿主动物和传染源是","o":["白纹伊蚊","鼠蚤","黑线姬鼠","人虱","亚洲璃眼蜱"],"a":2,"e":"我国汉坦病毒的主要宿主动物和传染源是黑线姬鼠与褐家鼠，分别构成姬鼠型（汉滩型）与家鼠型（汉城型）疫区，鼠类排泄物形成气溶胶经呼吸道传播。白纹伊蚊传播登革病毒，鼠蚤传播鼠疫，人虱传播斑疹伤寒，亚洲璃眼蜱传播克里米亚-刚果出血热"},{"q":"皮肤癣菌引起的最常见的癣病是","o":["头癣","体癣","足癣","手癣","甲癣"],"a":2,"e":"皮肤癣菌病以手足癣最为多见，其中足癣发病率最高，与足部多汗、透气差、共用拖鞋等有关。头癣多见于儿童，随卫生条件改善已明显减少；甲癣多继发于手足癣；体癣、股癣相对少见，临床上以足癣就诊者最多"},{"q":"下列哪种疾病的病原体不侵入血","o":["伤寒","细菌性痢疾","副伤寒","鼠疫","钩端螺旋体病"],"a":1,"e":"志贺菌侵入结肠黏膜后在黏膜层内繁殖，一般不进入血流，故菌痢无菌血症期。伤寒、副伤寒沙门菌经肠淋巴组织入血形成第一次菌血症；鼠疫耶尔森菌经淋巴入血引起败血症；钩端螺旋体亦经血流播散至肝、肾等器官"},{"q":"与革兰氏阳性菌黏附能力有关的结构是","o":["芽孢","菌毛","鞭毛","胞浆膜","膜磷壁酸"],"a":4,"e":"磷壁酸分壁磷壁酸与膜磷壁酸，仅膜磷壁酸即脂磷壁酸穿出细胞壁表面，是革兰阳性菌黏附宿主细胞的主要结构。菌毛也介导黏附但主要见于革兰阴性菌，芽胞为休眠体，鞭毛为运动器官，胞浆膜不直接接触宿主细胞"},{"q":"下列真菌中，芽管形成试验及厚膜孢子形成试验均为阳性的是","o":["白假丝酵母菌","热带假丝酵母菌","克柔假丝酵母菌","类星形假丝酵母菌","近平滑假丝酵母菌"],"a":0,"e":"白念珠菌芽管形成试验阳性，血清中37℃ 1.5～4小时形成芽管；厚膜孢子形成试验亦阳性，两项均阳性可与其他念珠菌鉴别。热带念珠菌芽管阴性、厚膜孢子弱阳性；近平滑、克柔念珠菌两项均不能同时阳性"},{"q":"可用于检测病毒蛋白成分的方法是","o":["PCR技术","Southern印迹法","Western印迹法","Northern印迹法","斑点分子杂交法"],"a":2,"e":"Western印迹法将蛋白电泳分离后转膜，再用特异性抗体检测病毒的结构蛋白或非结构蛋白。PCR扩增核酸；Southern印迹检测DNA；Northern印迹检测RNA；斑点分子杂交检测核酸，均不能直接检测蛋白成分"},{"q":"判断病毒有无包膜的依据是","o":["是否出现细胞病变","对苯酚是否敏感","对脂溶剂是否敏感","超速离心沉降速度不同","对温度抵抗力不同"],"a":2,"e":"包膜含脂质，乙醚、氯仿等脂溶剂可溶解包膜使病毒失去感染性，故对脂溶剂是否敏感是判断有无包膜的经典依据。苯酚等化学消毒剂对包膜病毒与裸露病毒均有灭活作用，不能用于鉴别；细胞病变、超速离心沉降速度和耐热性主要反映病毒种类与颗粒大小，与包膜无必然对应关系"},{"q":"革兰阳性菌特有的细胞壁成分是","o":["荚膜","肽聚糖","磷壁酸","脂多糖","脂蛋白"],"a":2,"e":"磷壁酸是革兰阳性菌细胞壁特有的组分，包括壁磷壁酸和脂磷壁酸，占细胞壁干重可达50%。肽聚糖为革兰阳性菌和阴性菌共有；脂多糖是革兰阴性菌外膜成分；荚膜位于细胞壁外，并非革兰阳性菌特有；脂蛋白见于革兰阴性菌外膜"},{"q":"立克次体与细菌的不同点是","o":["具有细胞壁","有DNA和RNA两种核酸","以二分裂方式繁殖","能在人工培养基上生长","有较复杂的酶系统"],"a":3,"e":"立克次体缺乏独立代谢的酶系统，必须依赖活细胞，属专性细胞内寄生，不能在无生命人工培养基上生长，这是与细菌的根本区别。二者均有细胞壁、含DNA和RNA两类核酸并以二分裂方式繁殖。培养常用鸡胚卵黄囊、细胞培养或动物接种"},{"q":"流行性斑疹伤寒的传播媒介","o":["人虱","鼠蚤","鼠虱","蜱","恙螨"],"a":0,"e":"流行性斑疹伤寒由普氏立克次体引起，传播媒介是人虱，虱粪中的立克次体经叮咬伤口或抓痕侵入。鼠蚤、鼠虱传播地方性斑疹伤寒，蜱传播斑点热与莱姆病，恙螨传播恙虫病，媒介不同是两型斑疹伤寒鉴别的要点"},{"q":"下列哪种立克次体病的传染源是病人","o":["流行性斑疹伤寒","地方性斑疹伤寒","立克次体痘","恙虫病","Q热"],"a":0,"e":"流行性斑疹伤寒由普氏立克次体引起，病人是唯一传染源，人虱为传播媒介，含菌虱粪经抓痕或眼结膜侵入人体。地方性斑疹伤寒的传染源与储存宿主为鼠类，鼠蚤、鼠虱为媒介。恙虫病储存宿主为鼠类，经恙螨幼虫传播。Q热由贝纳柯克斯体引起，传染源为牛、羊等家畜，经呼吸道吸入传播"},{"q":"嗜血杆菌出现“卫星现象”的原因是由于金黄色葡萄球菌能合成大量","o":["生长因子","Ⅴ因子","Ⅹ因子","高铁血红素","维生素B1"],"a":1,"e":"金黄色葡萄球菌可合成大量Ⅴ因子（辅酶Ⅰ），供周围需要Ⅴ因子的流感嗜血杆菌生长，形成卫星现象。Ⅹ因子为高铁血红素，金葡菌不能提供；生长因子表述笼统；维生素B1与血平板中的Ⅴ因子无关"},{"q":"关于血清学诊断方法，下列哪项是错误的","o":["伤寒——肥达试验","风湿热——抗O试验","斑疹伤寒——外斐反应","结核——结核菌素试验","梅毒——螺旋体制动试验"],"a":3,"e":"结核菌素试验是检测机体对结核蛋白的迟发型超敏反应，属皮肤试验，非血清学抗体检测。肥达试验诊断肠热症，抗O试验辅助诊断风湿热，外斐反应诊断斑疹伤寒等立克次体病，螺旋体制动试验检测梅毒抗体，均属血清学方法"},{"q":"处于生长周期中对数生长期的细菌特点是","o":["菌体增大并且代谢活跃","向菌体外释放大量毒素","生物学性状不十分典型","有芽孢的细菌开始形成芽孢","对外界环境因素的作用敏感"],"a":4,"e":"对数期细菌以恒定几何级数增殖，形态、染色性和生理活性典型，代谢旺盛，对外界环境因素的作用敏感，故研究生物学性状与做药敏试验应选此期。菌体增大、代谢活跃见于迟缓期；释放大量外毒素多在稳定期；芽胞形成始于稳定期后期；生物学性状不典型为迟缓期表现"},{"q":"均可用抗毒素进行紧急预防的疾病是","o":["肠热症与波状热","破伤风与结核病","白喉与痢疾","白喉与破伤风","猩红热与风湿热"],"a":3,"e":"白喉棒状杆菌和破伤风梭菌均以外毒素致病，注射白喉抗毒素、破伤风抗毒素可即刻中和游离毒素，用于密切接触者的紧急预防。肠热症、波状热、结核病、痢疾以抗菌治疗为主，无对应抗毒素；猩红热与风湿热亦不用抗毒素预防"},{"q":"既可引起食物中毒，也引起人类严重创伤感染的厌氧菌是","o":["破伤风梭菌","产气荚膜梭菌","艰难梭菌","炭疽杆菌","蜡样芽孢杆菌"],"a":1,"e":"产气荚膜梭菌为厌氧芽胞梭菌，既引起气性坏疽等严重创伤感染，又可因进食被污染食物产生肠毒素而引起食物中毒，还导致坏死性肠炎。破伤风梭菌只引起破伤风；艰难拟梭菌引起抗生素相关性腹泻与伪膜性肠炎；炭疽芽胞杆菌与蜡样芽胞杆菌为需氧芽胞菌，不属厌氧菌"},{"q":"机会致病菌的主要特点不包括","o":["毒力弱或无明显毒力","多为耐药菌或多重耐药菌","新现机会致病菌逐渐增多","新的致病菌逐渐增多","菌种因感染年代、地域及抗生素使用情况等的不同而变化"],"a":3,"e":"机会致病菌的特点是毒力弱或无明显毒力、多为耐药或多重耐药菌、新现机会致病菌逐渐增多，菌种随感染年代、地域及抗生素使用情况而变化。D项称新的致病菌逐渐增多，混淆了新现机会致病菌与真正新发的病原菌"},{"q":"检测细菌能否产生H2S时，应选择的培养基是","o":["SS培养基","庖肉培养基","罗氏培养基","双糖铁培养基","巧克力色培养基"],"a":3,"e":"双糖铁培养基含乳糖、葡萄糖、硫代硫酸钠与硫酸亚铁，细菌分解含硫氨基酸产生H2S时与铁离子生成黑色硫化铁，用于观察H2S产生。SS培养基为选择鉴别培养基，庖肉培养基用于厌氧菌，罗氏培养基用于结核分枝杆菌"},{"q":"HSV分型的特异性抗原决定簇是","o":["gB","gC","gD","gE","gG"],"a":4,"e":"gG分为gG-1与gG-2，是区分HSV-1和HSV-2血清型的型特异性糖蛋白，也是型特异性抗体检测的靶抗原。gB、gD为病毒吸附穿入所必需，gC是补体C3b受体，gE与gI形成IgG Fc受体复合物参与免疫逃逸，均不具型特异性"},{"q":"下列只有一个血清型的病毒是","o":["流感病毒","腺病毒","麻疹病毒","鼻病毒","副流感病毒"],"a":2,"e":"麻疹病毒抗原性稳定，至今只有一个血清型，病后可获持久免疫。流感病毒分甲、乙、丙三型，HA与NA亚型众多；腺病毒有数十个血清型，鼻病毒逾百型，副流感病毒分1～4型。抗原单一使麻疹疫苗只需单一毒株即可奏效"},{"q":"关于金黄色葡萄球菌的叙述错误的是","o":["能产生脂溶性色素","需氧或兼性厌氧","无鞭毛和芽孢","一般不形成荚膜","不可转为革兰阴性"],"a":4,"e":"金黄色葡萄球菌为革兰阳性球菌，但培养日久、菌体衰老或死亡后肽聚糖减少，可染成革兰阴性，故“不可转为革兰阴性”错误。该菌产生金黄色脂溶性色素，A项正确；需氧或兼性厌氧，B项正确；无鞭毛、无芽胞，一般不形成荚膜，C、D项正确"},{"q":"破伤风致病机制是由于","o":["破伤风梭菌侵入中枢神经系统","破伤风痉挛毒素侵入中枢神经系统","破伤风梭菌侵入血流引起败血症","破伤风梭菌产生侵袭性酶","破伤风梭菌产生内毒素"],"a":1,"e":"破伤风梭菌仅在局部厌氧创口繁殖，不入血、无侵袭性酶、不产生内毒素；其破伤风痉挛毒素经神经肌肉接头及血流侵入中枢神经系统，阻止抑制性神经递质释放，引起肌张力增高与阵发性痉挛。A项误为细菌侵入中枢，C、E项与本病不符"},{"q":"诺如病毒感染的预防方法不包括","o":["避免食用未经加热的食品","饭前便后彻底洗手","发生疫情的公共场所环境消毒","呕吐物及污染用品用漂白粉消毒","接种疫苗"],"a":4,"e":"诺如病毒尚无上市疫苗，预防依靠切断传播途径：不食未经加热的食品、饭前便后彻底洗手、疫情场所环境消毒、呕吐物及污染用品用漂白粉等含氯消毒剂处理。该病毒耐酸耐热，酒精效果差，须用含氯消毒剂"},{"q":"关于立克次体生物学性状的描述，错误的是","o":["二分裂方式繁殖","具有革兰阴性菌类似细胞壁","致病物质主要是内毒素","对广谱抗生素和磺胺类敏感","不能在无生命培养基上生长"],"a":3,"e":"立克次体对四环素类和氯霉素敏感，对磺胺类不敏感，磺胺反而可促进其生长，故该项错误。其余均正确：以二分裂方式繁殖，细胞壁似革兰阴性菌，致病物质主要是内毒素，为专性细胞内寄生，不能在无生命培养基上生长"},{"q":"不构成细菌侵袭力的组分是","o":["荚膜","菌毛","芽孢","膜磷壁酸","血浆凝固酶"],"a":2,"e":"侵袭力由菌体表面结构（黏附素、荚膜、鞭毛）、侵袭性物质（侵袭素、侵袭性酶）和生物被膜构成。芽胞是细菌的休眠体，与抵抗外界环境有关，不参与侵袭过程。菌毛与膜磷壁酸均为黏附素，协助细菌黏附定植；血浆凝固酶属侵袭性酶，可凝固血浆、阻碍吞噬"},{"q":"以细胞免疫机制为主实现免疫保护效应的细菌是","o":["结核分枝杆菌","葡萄球菌","流感嗜血杆菌","肺炎链球菌","炭疽芽胞杆菌"],"a":0,"e":"结核分枝杆菌为兼性胞内寄生菌，抗感染以CD4⁺Th1细胞介导的细胞免疫为主，巨噬细胞活化后杀灭胞内菌。葡萄球菌、流感嗜血杆菌、肺炎链球菌、炭疽芽胞杆菌均为胞外菌，机体主要靠抗体和吞噬细胞清除，以体液免疫为主"},{"q":"钩端螺旋体最主要的感染途径是","o":["经呼吸道感染","接触病人或病兽","经节肢动物叮咬","经消化道感染","接触疫水或疫土"],"a":4,"e":"致病性钩端螺旋体随疫鼠、病畜尿液排出，污染水源和土壤形成疫水、疫土，人经皮肤黏膜微小伤口接触而感染，这是最主要的途径。消化道、呼吸道感染少见，节肢动物不是其传播媒介，病人作为传染源的意义也小"},{"q":"预防病毒感染最有效的办法是","o":["用免疫血清","用化学药物","用减毒活疫苗主动免疫","用抗生素","用干扰素"],"a":2,"e":"减毒活疫苗保留免疫原性而失去致病性，可诱导体液和细胞免疫，免疫持久，是预防病毒感染最有效的措施，如麻疹、腮腺炎、乙脑疫苗。免疫血清与干扰素属被动或临时措施，抗生素对病毒无效，化学药物多为治疗用药"},{"q":"干扰素之所以是一种非常有前途的生物制品，最重要的原因是","o":["抗病毒范围广","在抗病毒免疫中发挥重要作用","毒性低","使用时机体不产生耐受性","除具有抗病毒作用外，还具有免疫调节作用"],"a":4,"e":"干扰素不仅具广谱抗病毒作用，还能抗肿瘤、调节免疫，可激活巨噬细胞与NK细胞、促进MHC抗原表达，故被视为有前途的生物制品。抗病毒范围广、毒性低虽为优点，但不及兼具免疫调节作用更具价值"},{"q":"与细菌遗传相关的物质是","o":["染色体、核糖体、质粒、中介体","染色体、质粒、噬菌体、转座子","染色体、转座子、核糖体、质粒","染色体、噬菌体、中介体、核糖体","染色体、噬菌体、中介体、质粒"],"a":1,"e":"细菌遗传物质包括染色体、质粒、噬菌体即前噬菌体与转座子，均可携带并传递遗传信息，其中质粒与转座子可携带耐药基因，前噬菌体可携带毒素基因。核糖体是蛋白质合成场所，中介体与细胞壁合成及呼吸有关"},{"q":"用直接电镜法可做出早期快速诊断的病毒是","o":["疱疹病毒","轮状病毒","流感病毒","巨细胞病毒","脊髓灰质炎病毒"],"a":1,"e":"轮状病毒腹泻时粪便中病毒颗粒可达每克10¹⁰以上，直接电镜即可快速检出，是早期快速诊断的经典方法。疱疹病毒、巨细胞病毒需细胞培养或核酸检测；流感病毒常用免疫荧光或RT-PCR；脊髓灰质炎病毒须分离培养或PCR"},{"q":"流行性腮腺炎的主要传播方式是","o":["飞沫","胎盘","粪-口途径","哺乳","性接触"],"a":0,"e":"腮腺炎病毒以人为唯一宿主，主要经飞沫传播，侵入呼吸道后引起腮腺非化脓性肿胀。胎盘、哺乳、性接触均非其传播方式；粪-口途径是脊髓灰质炎、甲肝等肠道传播疾病的途径，与腮腺炎病毒无关。流行季节以冬春季为主"},{"q":"下列病毒中与肿瘤不相关的是","o":["HBV","HCV","HEV","EBV","HPV"],"a":2,"e":"戊型肝炎病毒经粪-口传播，引起急性自限性肝炎，不整合宿主基因组，与肿瘤无关。HBV、HCV长期感染可致肝硬化与肝细胞癌，EB病毒与鼻咽癌、Burkitt淋巴瘤相关，HPV的E6、E7蛋白与宫颈癌相关"},{"q":"与衣壳功能无关的是","o":["保护病毒核酸","介导病毒体吸附易感细胞受体","构成病毒特异性抗原","本身具有传染性","病毒分类、鉴定的依据"],"a":3,"e":"衣壳本身不具传染性，传染性由其所包裹的核酸决定，核酸进入细胞后才起始感染；单正链RNA病毒基因组本身即可作mRNA并具感染性。衣壳的功能是保护核酸、介导吸附、构成抗原以及作为分类鉴定依据"},{"q":"易破坏病毒包膜的因素是","o":["干扰素","乙醚","青霉素","乙醇","紫外线"],"a":1,"e":"乙醚、氯仿等脂溶剂可溶解包膜中的脂质双层，使包膜病毒失去吸附能力而灭活，故乙醚试验用于鉴别病毒有无包膜。干扰素为抗病毒生物制剂，青霉素针对细菌，紫外线损伤核酸，乙醇主要使蛋白变性，均不是特异性破坏包膜的因素"},{"q":"以下关于克-雅病的描述，错误的是","o":["传染性海绵状脑病","英文缩写为CJD","潜伏期为10～15年","病理学改变与库鲁病类似","可分为散发性和医源性两种类型"],"a":4,"e":"克-雅病分散发型、家族型和医源性三型，散发型约占85%，并非只有散发与医源两型。该病为传染性海绵状脑病，缩写CJD，潜伏期长达10～15年，病理为脑组织海绵状变性、淀粉样斑块，与库鲁病类似"},{"q":"妊娠期最容易引起畸胎的一种病毒是","o":["流感病毒","巨细胞病毒","脊髓灰质炎病毒","轮状病毒","甲型肝炎病毒"],"a":1,"e":"妊娠早期胎盘屏障不完善，HCMV经胎盘感染胎儿，可致小头畸形、智力低下与先天性耳聋，是引起先天性畸形最常见的病原体之一。流感病毒、脊髓灰质炎病毒、轮状病毒与甲型肝炎病毒一般不通过胎盘致畸；风疹病毒亦致畸，但不在选项内"},{"q":"下列能产生志贺毒素的大肠埃希菌是","o":["EIEC","ETEC","EPEC","EHEC","EAEC"],"a":3,"e":"EHEC即产志贺毒素大肠埃希菌，携带Stx基因，表达志贺毒素即Vero毒素，是引起出血性结肠炎和溶血性尿毒综合征的主要菌型。ETEC产不耐热和耐热肠毒素，EPEC以束状黏附致婴儿腹泻，EIEC侵袭结肠上皮，EAEC呈集聚性黏附"},{"q":"细菌涂片后固定的作用不包括","o":["杀死细菌","使染料易与细菌结合","使细菌较牢固黏附于玻片","使细菌失去抗原性","破坏细菌结构"],"a":3,"e":"固定的作用包括杀死细菌、使菌体蛋白凝固而破坏结构、使细菌牢固黏附于玻片、改变细胞膜通透性而利于染料进入。固定并不破坏抗原性，免疫荧光染色正是对固定标本检测特异抗原，故使细菌失去抗原性不属于固定作用"},{"q":"下列关于干扰素的叙述中，不正确的是","o":["是一组具有高活性的多功能糖蛋白","可由病毒及其他干扰素诱生剂诱生","产生后可直接杀伤病毒","产生后对邻近的细胞可发生作用","起作用发生早于抗体"],"a":2,"e":"干扰素不直接杀伤病毒，而是与细胞表面受体结合，诱导产生2′-5′寡腺苷酸合成酶、蛋白激酶R等抗病毒蛋白，抑制病毒蛋白翻译。干扰素为诱生性糖蛋白，可由病毒等诱生剂诱生，作用有种属特异性，且产生早于特异性抗体，C项错误"},{"q":"初步将志贺菌与沙门菌、大肠埃希菌进行区别的生化反应是","o":["培养基中加亚碲酸钾","菊糖发酵试验","尿素分解试验","胆汁溶解试验","双糖铁培养基接种试验"],"a":4,"e":"双糖铁培养基可同时观察葡萄糖和乳糖发酵、产气及硫化氢产生：志贺菌只发酵葡萄糖、不产气、不产硫化氢，沙门菌产硫化氢，大肠埃希菌发酵乳糖并产气，据此可初步区别。尿素酶试验用于鉴别变形杆菌，菊糖发酵与胆汁溶菌用于鉴别肺炎链球菌"},{"q":"引起细菌性痢疾的细菌是","o":["大肠埃希菌","福氏志贺菌","霍乱弧菌","副溶血性弧菌","伤寒沙门菌"],"a":1,"e":"细菌性痢疾由志贺菌属引起，我国以福氏志贺菌多见，属B群，感染易转为慢性、病程迁延。大肠埃希菌引起腹泻与肠道外感染，霍乱弧菌引起霍乱，副溶血性弧菌引起食物中毒，伤寒沙门菌引起肠热症"},{"q":"关于HCMV先天性感染的描述，错误的是","o":["孕期6个月内感染","可引起巨细胞病毒感染","可致先天性畸形","严重者可致流产和死胎","部分亚临床感染数年后才出现智力低下"],"a":0,"e":"先天性HCMV感染主要由孕期3个月内的原发感染或潜伏病毒再激活所致，此期胎儿最易受累，将时间窗扩为6个月内与教材不符，故该项描述错误。宫内感染可致流产、死胎及小头畸形、智力低下、耳聋等先天畸形，部分亚临床感染在出生后数月至数年才出现智力与听力损害。该项所称引起巨细胞病毒感染系同义反复，临床疾病为巨细胞病毒病"},{"q":"在我国，除了下列哪项外均有减毒活疫苗","o":["风疹病毒","麻疹病毒","腮腺炎病毒","狂犬病毒","流行性乙型脑炎病毒"],"a":3,"e":"风疹、麻疹、腮腺炎病毒均有减毒活疫苗，可组成麻腮风联合疫苗；我国乙脑亦有SA14-14-2减毒活疫苗。狂犬病疫苗为地鼠肾细胞或人二倍体细胞培养后经灭活制成，属灭活疫苗，无减毒活疫苗用于人体，故除狂犬病毒外均有减毒活疫苗"},{"q":"吕氏血清斜面采用的灭菌方法是","o":["高压蒸汽灭菌","间歇蒸汽灭菌","流动蒸汽灭菌","煮沸法灭菌","紫外线灭菌"],"a":1,"e":"吕氏血清斜面含糖和血清，不耐高压高热，故采用间歇蒸汽灭菌法，100℃加热15～30分钟杀灭繁殖体，置37℃过夜使芽胞发芽，重复三次达到灭菌。高压蒸汽灭菌适用于耐高温培养基；流动蒸汽、煮沸只能消毒；紫外线穿透力弱，不能灭菌培养基"},{"q":"可以在巨噬细胞内寄生的细菌是","o":["金黄色葡萄球菌","肺炎链球菌","布鲁菌","破伤风梭菌","炭疽芽孢杆菌"],"a":2,"e":"布鲁菌为兼性胞内寄生菌，被巨噬细胞吞噬后可在其内生长繁殖，并随巨噬细胞播散至肝、脾、骨髓与淋巴结。金黄色葡萄球菌、肺炎链球菌为胞外菌，破伤风梭菌在创口厌氧环境繁殖，炭疽芽胞杆菌在局部发芽繁殖后入血致败血症"},{"q":"细菌L型与支原体的共同点不包括","o":["脱离诱导因素后均可回复为原来的细菌型","均能通过滤菌器","具有多态性","在固体培养基上均能形成荷包蛋样菌落","培养时均需10%～20%的动物血清"],"a":0,"e":"支原体无细胞壁，去除诱导因素亦不能回复；L型细菌在无抗生素等诱导因素时可回复为原型菌，这是两者最主要的区别。两者均无细胞壁、呈多形性、能通过滤菌器、形成油煎蛋样菌落，培养均需含血清的培养基"},{"q":"与HHV-8有关的肿瘤是","o":["鼻咽癌","Burkitt淋巴瘤","恶性单克隆B淋巴细胞瘤","宫颈癌","卡波西肉瘤"],"a":4,"e":"HHV-8即卡波西肉瘤相关疱疹病毒，是卡波西肉瘤的病原体，在艾滋病患者中尤为多见。鼻咽癌和Burkitt淋巴瘤与EBV相关；恶性单克隆B淋巴细胞瘤与HTLV-1相关；宫颈癌由高危型HPV引起"},{"q":"白假丝酵母菌所致鹅口疮多见于","o":["初生婴儿","幼儿","儿童","青少年","成年人"],"a":0,"e":"鹅口疮即口腔念珠菌病，白念珠菌为条件致病菌，新生儿经产道时接触带菌分泌物，加之口腔黏膜娇嫩、sIgA水平低，故初生婴儿最易发生。婴幼儿与成人多在长期使用广谱抗生素、激素或免疫功能低下时出现"},{"q":"“流产转导”是指噬菌体携带的外源DNA","o":["未能进入受体菌","进入受体菌后未能增殖","进入受体菌与染色体重组后未能表达其特性","进入受体菌后游离存在而未能与染色体DNA整合在一起","进入受体菌后自身复制"],"a":3,"e":"流产转导指噬菌体将供体菌DNA带入受体菌后，该片段游离于细胞质而未与受体菌染色体整合，不能随染色体复制稳定遗传，仅随分裂进入一个子代菌，故称流产。完全转导是供体片段经同源重组整合于染色体并稳定表达。溶原性转换由前噬菌体基因表达所致。外源DNA确已进入受体菌，故并非未能进入"},{"q":"SPA存在于下列哪种细菌","o":["乙型溶血性链球菌","金黄色葡萄球菌","大肠埃希菌","淋病奈瑟菌","伤寒沙门菌"],"a":1,"e":"SPA即葡萄球菌A蛋白，存在于金黄色葡萄球菌细胞壁，可与IgG的Fc段非特异性结合，用于协同凝集试验和免疫学诊断。乙型溶血性链球菌、大肠埃希菌、淋病奈瑟菌、伤寒沙门菌均无SPA，可借以与金葡菌鉴别"},{"q":"关于噬斑形成单位的叙述，正确的是","o":["可用于任何类型噬菌体的定量检测","只可用于毒性噬菌体的定量检测","只可用于温和噬菌体的定量检测","只可用于丝状噬菌体的定量检测","只可用于溶原性噬菌体的定量检测"],"a":1,"e":"噬斑是毒性噬菌体裂解宿主菌后在菌苔上形成的透明区，一个噬斑源自一个噬菌体，故噬斑形成单位只用于毒性噬菌体的定量。温和噬菌体感染后多整合为前噬菌体，不裂解细菌、不形成噬斑，不能据此定量"},{"q":"关于病毒结构的描述，错误的是","o":["病毒的衣壳蛋白具有保护病毒核酸的作用","病毒包膜的一些成分和宿主细胞膜的成分相似","病毒包膜糖蛋白来源于宿主细胞","病毒衣壳由一定数量的壳粒组成","每种病毒的核酸类型只有一种"],"a":2,"e":"病毒包膜的脂质来自宿主细胞膜，但包膜上的糖蛋白由病毒基因编码，故糖蛋白来源于宿主细胞错误。衣壳由壳粒组成，保护核酸；包膜成分与宿主细胞膜相似利于融合；每种病毒只含一种核酸，为DNA或RNA"},{"q":"影响细菌胞浆膜通透性的抗菌药物有","o":["青霉素","磷霉素","万古霉素","两性霉素","阿莫西林"],"a":3,"e":"两性霉素B与真菌细胞膜上的麦角固醇结合，形成亲水性孔道，使细胞膜通透性增加、内容物和离子外漏而致真菌死亡。青霉素、阿莫西林抑制肽聚糖交联，磷霉素抑制细胞壁早期合成，万古霉素阻断肽聚糖延伸，均作用于细胞壁"},{"q":"细菌因基因突变发生的耐药性的特点是","o":["不是随机发生的","突变频率很高","不稳定","在接触抗菌药物之前出现","不发生回复突变"],"a":3,"e":"耐药突变是自发、随机发生的，在接触抗菌药物之前即已存在，药物只起筛选作用，影印培养实验已证实。突变频率低，性状稳定可遗传，并可发生回复突变。接触药物后诱导产生的是表型适应，不属基因突变，故“非随机”“高频”“不稳定”均与突变耐药不符"},{"q":"一手术室护士正在对外科手术器械及手术敷料等进行高压蒸汽灭菌处理。此方法处理的目的是为了杀灭细菌的","o":["荚膜","菌毛","芽孢","繁殖体","鞭毛"],"a":2,"e":"高压蒸汽灭菌以杀灭包括芽胞在内的全部微生物为目标，故判断灭菌效果以芽胞是否被杀灭为指标，手术器械与敷料必须达到灭菌。荚膜、菌毛、鞭毛均为细菌结构，繁殖体在湿热80℃数分钟内即死亡，不能作为灭菌指标"},{"q":"衣原体在细胞内的繁殖型是","o":["革兰阳性圆形体","革兰阴性圆形体","内基小体","原体","始体"],"a":4,"e":"衣原体发育周期中，原体为感染型，进入细胞后膨大转变为始体即网状体；始体无胞壁、代谢活跃，以二分裂方式增殖，是繁殖型但不具感染性。内基小体是狂犬病病毒在神经元胞质内形成的嗜酸性包涵体，与衣原体无关"},{"q":"与卫星现象有关的细菌是","o":["白喉杆菌","百日咳杆菌","流感嗜血杆菌","军团菌属","炭疽杆菌"],"a":2,"e":"流感嗜血杆菌生长需X因子和V因子，金黄色葡萄球菌溶血时可释放V因子，故在其菌落周围生长的流感嗜血杆菌菌落较大，离得越远越小，称卫星现象，有助于该菌鉴定。百日咳鲍特菌需鲍-金培养基；军团菌需BCYE培养基；白喉棒状杆菌用亚碲酸钾血平板"},{"q":"EBV增殖性感染期表达的抗原不包括","o":["EA-R","EA-D","VCA","MA","EBNA"],"a":4,"e":"EBV增殖性感染期表达早期抗原（EA-R、EA-D）、衣壳抗原VCA和膜抗原MA；EBNA为潜伏感染期表达的核抗原，存在于感染B细胞核内，不属于增殖期抗原。EA为病毒非结构蛋白，标志增殖活跃；VCA与MA为晚期结构蛋白，MA可诱导中和抗体"},{"q":"判断流感病毒接种鸡胚尿囊腔是否生长，应选","o":["红细胞吸附试验","血凝试验","血凝抑制实验","补体结合试验","间接血凝试验"],"a":1,"e":"流感病毒接种鸡胚尿囊腔增殖后不引起明显病变，需取尿囊液作血凝试验，以红细胞凝集判断是否生长并测效价。血凝抑制试验用于鉴定病毒亚型；红细胞吸附试验用于细胞培养；补体结合试验测抗体；间接血凝试验测抗体"},{"q":"抗胞外菌感染的主要免疫因素是","o":["补体","抗体","NK细胞","巨噬细胞","T细胞"],"a":1,"e":"抗胞外菌感染以体液免疫为主，特异性抗体可中和外毒素、调理吞噬并激活补体溶菌。细胞免疫主要针对胞内菌；NK细胞在抗病毒与抗肿瘤中起作用；补体与巨噬细胞属固有免疫，不能替代抗体的特异性保护作用"},{"q":"关于汉坦病毒免疫性的描述，正确的是","o":["正常人群血清抗体阳性率高","隐性感染也可获得持久免疫力","细胞免疫基本不起保护作用","机体主要依赖于IgM、IgG的保护作用","特异性IgG出现迟，但维持时间长"],"a":3,"e":"汉坦病毒感染后以体液免疫为主，特异性IgM和IgG抗体发挥中和与调理作用，是免疫保护的主要因素。人群抗体阳性率低，隐性感染少见，持久免疫主要来自显性感染；细胞免疫也参与清除病毒，特异性IgG并非出现迟"},{"q":"不是克里米亚-刚果出血热主要表现的是","o":["肾功能损害","高热","脏器出血","低血压或休克","皮下出血"],"a":0,"e":"克里米亚-刚果出血热以高热、头痛、肌痛及明显出血为特征，轻者皮肤黏膜点状出血，重者鼻出血、呕血、血尿乃至低血压休克。该病一般无明显肾功能损害，肾功能损害是肾综合征出血热的典型表现，两者常被混淆"},{"q":"下列细菌中，能在pH7.4～9.6范围内生长的是","o":["金黄色葡萄球菌","大肠埃希菌","结核分枝杆菌","霍乱弧菌","白喉棒状杆菌"],"a":3,"e":"霍乱弧菌耐碱不耐酸，在pH8.4～9.2生长最好，可在pH7.4～9.6范围内生长，故初次分离常用碱性蛋白胨水增菌。结核分枝杆菌最适pH6.5～6.8，金葡菌、大肠埃希菌、白喉棒状杆菌最适pH7.2～7.6"},{"q":"人巨细胞病毒感染患者标本中可见","o":["核内嗜碱性包涵体","核内嗜酸性包涵体","核内和胞质嗜碱性包涵体","核内和胞质嗜酸性包涵体","胞质嗜碱性包涵体"],"a":3,"e":"HCMV感染的细胞体积显著增大，核内出现嗜酸性包涵体，胞质内亦可见嗜酸性包涵体，形成典型的猫头鹰眼样巨细胞。麻疹病毒、HSV主要形成核内嗜酸性包涵体；狂犬病病毒的内基小体位于胞质；仅有核内嗜碱性包涵体不符合HCMV"},{"q":"根据产气荚膜梭菌的主要毒素产生情况，可将其分为5个血清型，对人致病的主要为","o":["A型","B型","C型","D型","E型"],"a":0,"e":"产气荚膜梭菌依α、β、ε、ι、肠毒素与NetB可分为A～G七个毒素型，对人致病的主要为A型，引起气性坏疽与食物中毒。C型致坏死性肠炎，F型亦可致食物中毒，B、D型主要引起羔羊痢疾等动物疾病"},{"q":"可经垂直感染导致畸胎的病毒是","o":["麻疹病毒","风疹病毒","流感病毒","乙型脑炎病毒","脊髓灰质炎病毒"],"a":1,"e":"风疹病毒经垂直传播感染胎儿，尤其孕20周内感染危害最大，可致流产、死胎及先天性风疹综合征，表现为先天性心脏病、耳聋、白内障等畸形。麻疹、流感、乙脑、脊髓灰质炎病毒均不以垂直传播致畸为主要特征"},{"q":"检查包涵体可作为","o":["衡量病毒毒力强弱的标准","诊断乙型脑炎病毒感染","测定病毒数量的指标","鉴定病毒的特异性依据","病毒在细胞内增殖的标志之一"],"a":4,"e":"病毒在细胞内增殖后可在胞核或胞质形成包涵体，故包涵体可作为病毒增殖的标志之一，并辅助诊断。但包涵体不具病毒特异性，腺病毒、疱疹病毒、狂犬病毒等均可形成，理化因素也可引起类似结构，不能作为鉴定病毒的依据，也不用于测定毒力或病毒数量"},{"q":"下列哪个病毒不是单个血清型，但感染后可获得持久免疫力","o":["麻疹病毒","风疹病毒","腮腺炎病毒","脊髓灰质炎病毒","甲型肝炎病毒"],"a":3,"e":"脊髓灰质炎病毒分3个血清型，型间无交叉免疫，感染后仅获型特异性牢固免疫，故不是单一血清型。麻疹病毒、风疹病毒、腮腺炎病毒、甲型肝炎病毒均只有一个血清型，感染后同样可获得持久免疫，与本问的限定条件不符"},{"q":"可以用类毒素预防的疾病是","o":["白喉","痢疾","伤寒","结核病","百日咳"],"a":0,"e":"白喉棒状杆菌致病依靠白喉外毒素，甲醛脱毒制成白喉类毒素，为百白破三联疫苗的成分，可用于预防。类毒素须经佐剂吸附，全程接种后抗体可维持数年。痢疾、伤寒与结核病无类毒素疫苗，卡介苗为减毒活疫苗"},{"q":"关于HCMV围生期感染的叙述，错误的是","o":["分娩时新生儿经产道感染","感染后多无明显的临床症状","尿液和分泌物中大量排出病毒","多数患儿预后差","可经母乳感染"],"a":3,"e":"HCMV围生期感染多经产道或母乳获得，病毒在尿液、唾液中大量排出，但多数患儿无临床症状或仅轻度肝脾大、间质性肺炎，预后良好，故多数预后差错误。仅少数发生播散性感染或神经系统损害，预后不良"},{"q":"不能侵害指甲的皮肤癣菌是","o":["红色毛癣菌","须毛癣菌","絮状表皮癣菌","小孢子癣菌属","紫色毛癣菌"],"a":3,"e":"小孢子菌属约有15种，侵犯皮肤和毛发，不侵犯甲板，故不能引起甲癣。毛癣菌属侵犯皮肤、毛发和甲板；絮状表皮癣菌侵犯皮肤和甲板而不侵犯毛发；红色毛癣菌、须毛癣菌、紫色毛癣菌均属毛癣菌属，可致甲癣"},{"q":"参与HIV-1整合过程的病毒基因是","o":["tat","vif","env","pol","vpr"],"a":3,"e":"HIV-1的pol基因编码整合酶，病毒双链DNA进入细胞核后由整合酶催化插入宿主染色体形成前病毒。env编码包膜糖蛋白，tat为反式激活因子，vif、vpr参与病毒复制与致病，均无整合功能"},{"q":"多种病毒通过呼吸道感染，下列病毒中不能通过呼吸道感染的是","o":["腺病毒","冠状病毒","肝炎病毒","副黏病毒","痘病毒"],"a":2,"e":"肝炎病毒中HAV、HEV经消化道传播，HBV、HCV、HDV经血液、母婴及性接触传播，均不经呼吸道感染。腺病毒、冠状病毒、副黏病毒与痘病毒均可经呼吸道飞沫或气溶胶传播，故呼吸道是它们的共同侵入门户"},{"q":"蝌蚪形噬菌体吸附易感细胞的结构是","o":["尾板","尾丝","尾鞘","尾髓","尾领"],"a":1,"e":"蝌蚪形噬菌体的尾丝是吸附器官，能识别宿主菌表面特异性受体并与之结合，完成吸附。尾鞘收缩时将头部核酸经中空的尾髓注入菌体；尾板内含溶菌酶，协助裂解细胞壁；尾领与头部装配有关，均不承担吸附功能"},{"q":"HEV的传播和流行主要方式是","o":["粪-口途径","性接触","日常生活接触","垂直传播","血液和血制品"],"a":0,"e":"戊型肝炎病毒主要经粪-口途径传播，水源或食物被粪便污染可引起暴发流行，经血液或血制品传播较少见。性接触与垂直传播是HBV、HCV的重要途径；日常生活接触传播发生率低，不是HEV的主要方式。HAV同样经消化道传播，两者常并列比较"},{"q":"R质粒决定的耐药性主要是","o":["单一耐药性","多重耐药性","对药物依赖性","稳定的耐药性","不易丢失的耐药性"],"a":1,"e":"R质粒的耐药决定因子可携带多个转座子，同时编码对氨苄西林、链霉素、磺胺、氯霉素等多种药物的耐药性，故主要表现为多重耐药性。单一耐药多由染色体基因突变所致，R质粒决定的耐药性还可随质粒丢失而消失"},{"q":"鉴别肺炎球菌与甲型链球菌的试验是","o":["胆汁溶菌试验和菊糖发酵试验","胆汁溶菌试验和甘露醇发酵试验","血浆凝固酶试验和甘露醇发酵试验","血浆凝固酶试验和菊糖发酵试验","乳糖发酵试验和蔗糖发酵试验"],"a":0,"e":"肺炎链球菌可被胆汁或胆盐激活自溶酶而溶解，且发酵菊糖；甲型溶血性链球菌两项均阴性，故以此鉴别。Optochin敏感试验亦可辅助鉴别，肺炎链球菌抑菌圈直径常大于20mm。血浆凝固酶与甘露醇发酵用于葡萄球菌鉴别"},{"q":"关于转导，下述正确的是","o":["只可转移供体菌染色体上特定的基因","由噬菌体介导","由R质粒介导","由F质粒介导","由性菌毛介导"],"a":1,"e":"转导由噬菌体介导，将供体菌DNA片段转入受体菌并重组；普遍性转导可转移任一片段，并非只限特定基因，局限性转导才转移整合位点两侧的特定基因。R质粒、F质粒经接合传递，由性菌毛介导，与转导机制不同"},{"q":"下列不产生外毒素的细菌是","o":["霍乱弧菌","伤寒沙门菌","痢疾志贺菌","白喉棒状杆菌","肠产毒性大肠埃希菌"],"a":1,"e":"伤寒沙门菌的致病物质为内毒素与侵袭力，不产生外毒素。霍乱弧菌产霍乱肠毒素，痢疾志贺菌产志贺毒素，白喉棒状杆菌产白喉毒素，肠产毒性大肠埃希菌产不耐热与耐热肠毒素。内毒素与其持续发热、中毒症状相关"},{"q":"目前葡萄球菌对青霉素的耐药性已达","o":["10%","30%～40%","50%左右","80%以上","100%"],"a":3,"e":"金黄色葡萄球菌90%以上菌株产生β-内酰胺酶，水解青霉素的β-内酰胺环，使药物失活，故临床耐药率在80%以上。答100%过于绝对，仍有少数敏感株；50%左右明显低于实际流行水平。耐甲氧西林株另由mecA基因编码的PBP2a介导，与产酶机制不同"},{"q":"寨卡病毒的主要传播媒介是","o":["伊蚊","硬蜱","人虱","鼠蚤","白蛉"],"a":0,"e":"寨卡病毒主要经蚊叮咬传播，埃及伊蚊与白纹伊蚊为主要媒介，流行区域与伊蚊分布一致，另有性传播与母婴传播报道。硬蜱传播森林脑炎病毒；人虱传播流行性斑疹伤寒；鼠蚤传播鼠疫；白蛉传播利什曼病与白蛉热，均非寨卡病毒的媒介"},{"q":"脑脊液离心涂片染色，镜检发现白细胞内外均有革兰阴性双球菌，该患者可诊断为","o":["结核性脑膜炎","脱髓鞘脑脊髓膜炎","流行性脑脊髓膜炎","流行性乙型脑炎","新型隐球菌性脑膜炎"],"a":2,"e":"脑脊液涂片见白细胞内外革兰阴性双球菌，是脑膜炎奈瑟菌的典型形态，结合化脓性脑膜炎表现可诊断为流行性脑脊髓膜炎。结核性脑膜炎脑脊液以淋巴细胞为主，需抗酸染色找结核分枝杆菌；乙型脑炎为病毒感染，涂片无细菌；隐球菌性脑膜炎墨汁负染见有荚膜酵母细胞"},{"q":"机体获得人工被动免疫的方式是","o":["隐性感染","疫苗接种","显性感染","注射类毒素","注射抗毒素"],"a":4,"e":"人工被动免疫是直接输入抗体或细胞因子，注射抗毒素即属此类，出现快、维持短，多用于治疗或紧急预防。疫苗接种与注射类毒素属人工主动免疫，需2～4周才产生保护；隐性感染与显性感染属自然感染获得的免疫，非人工方式"},{"q":"在下列各种病毒中病毒粒子直径最大的是","o":["牛痘苗病毒","甲型肝炎病毒","烟草坏死病毒","大肠杆菌f1噬菌体","冠状病毒"],"a":0,"e":"痘病毒呈砖状或卵圆形，直径约200～300nm，是已知最大的病毒，牛痘苗病毒即属此类。冠状病毒约100nm，甲型肝炎病毒与烟草坏死病毒均约27～30nm，大肠埃希菌f1噬菌体为细丝状，直径仅约6nm"},{"q":"当两种病毒感染同一宿主细胞发生基因的交换，产生具有两个亲代特征的子代病毒，并能继续增殖，该变化称为","o":["基因整合","基因交换","基因重组","基因突变","基因变异"],"a":2,"e":"两种不同病毒感染同一细胞时核酸片段互换，产生兼具两亲代特征且能继续增殖的子代，称基因重组。基因整合是病毒核酸插入宿主染色体，基因突变是单个碱基改变，均不涉及两病毒间片段交换。基因重排则见于分节段基因组病毒，如流感病毒"},{"q":"对铜绿假单胞菌致病性的描述，错误的是","o":["可发生于烧伤感染","可发生于医院内感染","可发生于免疫功能低下患者的继发感染","可引起婴儿严重的流行性腹泻","对多种抗生素敏感"],"a":4,"e":"铜绿假单胞菌外膜通透性低，并具主动外排系统与β-内酰胺酶，对多种抗菌药物固有耐药，常呈多重耐药。它是烧伤创面、医院内感染及免疫功能低下者继发感染的重要病原菌，也可引起婴儿流行性腹泻。治疗需依药敏选择，常联合用药"}];
